import os
import struct
import sys
from collections import deque


def trailing_zeros(x):
    if x == 0:
        return 32
    count = 0
    while (x & 1) == 0:
        count += 1
        x >>= 1
    return count


def popcount(x):
    count = 0
    while x:
        count += x & 1
        x >>= 1
    return count


def extract_channel(pixel, mask):
    s = trailing_zeros(mask)
    n = popcount(mask)
    m = (1 << n) - 1
    v = (pixel & mask) >> s
    return (v * 255 + m // 2) // m


def is_ink(r, g, b):
    return (299 * r + 587 * g + 114 * b) // 1000 < 128


def get_pixel(data, row_offset, x, bpp, palette, compression, red_mask, green_mask, blue_mask):
    if bpp == 1:
        byte_idx = x // 8
        bit_idx = 7 - (x % 8)
        idx = (data[row_offset + byte_idx] >> bit_idx) & 1
        return palette[idx]
    elif bpp == 4:
        byte_idx = x // 2
        if x % 2 == 0:
            idx = (data[row_offset + byte_idx] >> 4) & 0xF
        else:
            idx = data[row_offset + byte_idx] & 0xF
        return palette[idx]
    elif bpp == 8:
        idx = data[row_offset + x]
        return palette[idx]
    elif bpp == 24:
        offset = row_offset + x * 3
        b = data[offset]
        g = data[offset + 1]
        r = data[offset + 2]
        return (r, g, b)
    elif bpp == 32:
        offset = row_offset + x * 4
        pixel = struct.unpack_from('<I', data, offset)[0]
        if compression == 0:
            b = data[offset]
            g = data[offset + 1]
            r = data[offset + 2]
            return (r, g, b)
        else:
            r = extract_channel(pixel, red_mask)
            g = extract_channel(pixel, green_mask)
            b = extract_channel(pixel, blue_mask)
            return (r, g, b)


def process_file(path, fname):
    with open(path, 'rb') as f:
        data = f.read()

    if len(data) < 14 or data[:2] != b'BM':
        return

    bfOffBits = struct.unpack_from('<I', data, 10)[0]

    dib_size = struct.unpack_from('<I', data, 14)[0]
    width = struct.unpack_from('<i', data, 18)[0]
    height_signed = struct.unpack_from('<i', data, 22)[0]
    bpp = struct.unpack_from('<H', data, 28)[0]
    compression = struct.unpack_from('<I', data, 30)[0]
    colours_used = struct.unpack_from('<I', data, 46)[0]

    height = abs(height_signed)
    bottom_up = height_signed > 0

    if compression not in (0, 3):
        print(f"== {fname}")
        print(f"error: unsupported compression {compression}")
        return

    red_mask = green_mask = blue_mask = 0
    if compression == 3:
        if dib_size == 40:
            red_mask = struct.unpack_from('<I', data, 54)[0]
            green_mask = struct.unpack_from('<I', data, 58)[0]
            blue_mask = struct.unpack_from('<I', data, 62)[0]
        else:
            red_mask = struct.unpack_from('<I', data, 14 + 40)[0]
            green_mask = struct.unpack_from('<I', data, 14 + 44)[0]
            blue_mask = struct.unpack_from('<I', data, 14 + 48)[0]

    palette = []
    if bpp in (1, 4, 8):
        palette_offset = 14 + dib_size
        num_colors = colours_used if colours_used != 0 else (1 << bpp)
        for i in range(num_colors):
            idx = palette_offset + i * 4
            b = data[idx]
            g = data[idx + 1]
            r = data[idx + 2]
            palette.append((r, g, b))

    row_bytes = ((width * bpp + 31) // 32) * 4

    ink = [[False] * width for _ in range(height)]

    for y in range(height):
        if bottom_up:
            stored_row = height - 1 - y
        else:
            stored_row = y

        row_offset = bfOffBits + stored_row * row_bytes

        for x in range(width):
            r, g, b = get_pixel(data, row_offset, x, bpp, palette, compression, red_mask, green_mask, blue_mask)
            if is_ink(r, g, b):
                ink[y][x] = True

    visited = [[False] * width for _ in range(height)]
    components = []

    for y in range(height):
        for x in range(width):
            if ink[y][x] and not visited[y][x]:
                queue = deque()
                queue.append((x, y))
                visited[y][x] = True
                comp_pixels = []
                min_x = max_x = x
                min_y = max_y = y

                while queue:
                    cx, cy = queue.popleft()
                    comp_pixels.append((cx, cy))
                    if cx < min_x:
                        min_x = cx
                    if cx > max_x:
                        max_x = cx
                    if cy < min_y:
                        min_y = cy
                    if cy > max_y:
                        max_y = cy

                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = cx + dx, cy + dy
                            if 0 <= nx < width and 0 <= ny < height and ink[ny][nx] and not visited[ny][nx]:
                                visited[ny][nx] = True
                                queue.append((nx, ny))

                first = min(comp_pixels, key=lambda p: (p[1], p[0]))
                components.append((first, (min_x, min_y, max_x, max_y), len(comp_pixels)))

    components.sort(key=lambda c: (c[0][1], c[0][0]))

    ink_count = sum(1 for y in range(height) for x in range(width) if ink[y][x])

    orientation = "bottom-up" if bottom_up else "top-down"
    print(f"== {fname}")
    print(f"size {width}x{height} bpp {bpp} header {dib_size} {orientation} ink {ink_count}")
    print(f"components {len(components)}")
    for (fx, fy), (bx0, by0, bx1, by1), cnt in components:
        print(f"{fx},{fy} bbox {bx0},{by0}-{bx1},{by1} pixels {cnt}")


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    directory = sys.argv[1]

    files = sorted(
        [f for f in os.listdir(directory) if f.endswith('.bmp')],
        key=lambda x: x.encode()
    )

    for fname in files:
        process_file(os.path.join(directory, fname), fname)


if __name__ == '__main__':
    main()

