use std::collections::VecDeque;
use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = fs::read_dir(Path::new(dir))
        .unwrap()
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().to_string())
        .filter(|name| name.ends_with(".bmp"))
        .collect();
    files.sort();

    for filename in files {
        let path = Path::new(dir).join(&filename);
        let data = fs::read(&path).unwrap();
        process_bmp(&filename, &data);
    }
}

fn process_bmp(filename: &str, data: &[u8]) {
    let bf_off_bits = read_u32_le(data, 10) as usize;
    let dib_size = read_u32_le(data, 14) as usize;
    let width = read_i32_le(data, 18) as usize;
    let height_raw = read_i32_le(data, 22);
    let bits_per_pixel = read_u16_le(data, 28) as usize;
    let compression = read_u32_le(data, 30);
    let colours_used = read_u32_le(data, 46) as usize;

    let height = if height_raw < 0 { (-height_raw) as usize } else { height_raw as usize };
    let bottom_up = height_raw > 0;

    if compression != 0 && compression != 3 {
        println!("== {}", filename);
        println!("error: unsupported compression {}", compression);
        return;
    }

    // Masks for BI_BITFIELDS
    let (red_mask, green_mask, blue_mask) = if bits_per_pixel == 32 && compression == 3 {
        let r = read_u32_le(data, 54);
        let g = read_u32_le(data, 58);
        let b = read_u32_le(data, 62);
        (r, g, b)
    } else {
        (0u32, 0u32, 0u32)
    };

    // Palette
    let palette_start = 14 + dib_size;
    let palette_entries = if colours_used == 0 {
        1usize << bits_per_pixel
    } else {
        colours_used
    };
    let _ = palette_entries;

    // Row stride in bytes
    let row_stride = match bits_per_pixel {
        1 => ((width + 7) / 8 + 3) / 4 * 4,
        4 => ((width + 1) / 2 + 3) / 4 * 4,
        8 => (width + 3) / 4 * 4,
        24 => (width * 3 + 3) / 4 * 4,
        32 => width * 4,
        _ => width * bits_per_pixel / 8,
    };

    let mut ink = vec![false; width * height];
    let mut ink_count = 0usize;

    for y in 0..height {
        let stored_y = if bottom_up { height - 1 - y } else { y };
        let row_offset = bf_off_bits + stored_y * row_stride;

        for x in 0..width {
            let (r, g, b): (u8, u8, u8) = match bits_per_pixel {
                1 => {
                    let byte_idx = row_offset + x / 8;
                    let bit_idx = 7 - (x % 8);
                    let idx = ((data[byte_idx] >> bit_idx) & 1) as usize;
                    palette_color(data, palette_start, idx)
                }
                4 => {
                    let byte_idx = row_offset + x / 2;
                    let nibble = if x % 2 == 0 {
                        (data[byte_idx] >> 4) & 0xF
                    } else {
                        data[byte_idx] & 0xF
                    };
                    palette_color(data, palette_start, nibble as usize)
                }
                8 => {
                    let idx = data[row_offset + x] as usize;
                    palette_color(data, palette_start, idx)
                }
                24 => {
                    let off = row_offset + x * 3;
                    (data[off + 2], data[off + 1], data[off])
                }
                32 => {
                    let off = row_offset + x * 4;
                    if compression == 0 {
                        (data[off + 2], data[off + 1], data[off])
                    } else {
                        let pixel = read_u32_le(data, off);
                        let rv = extract_channel(pixel, red_mask);
                        let gv = extract_channel(pixel, green_mask);
                        let bv = extract_channel(pixel, blue_mask);
                        (rv, gv, bv)
                    }
                }
                _ => (0, 0, 0),
            };

            let luminance = (299 * r as u32 + 587 * g as u32 + 114 * b as u32) / 1000;
            if luminance < 128 {
                ink[y * width + x] = true;
                ink_count += 1;
            }
        }
    }

    println!("== {}", filename);
    println!(
        "size {}x{} bpp {} header {} {} ink {}",
        width,
        height,
        bits_per_pixel,
        dib_size,
        if bottom_up { "bottom-up" } else { "top-down" },
        ink_count
    );

    // Connected components (8-connectivity)
    let mut visited = vec![false; width * height];
    let mut components: Vec<(usize, usize, usize, usize, usize, usize, usize)> = Vec::new();

    for y in 0..height {
        for x in 0..width {
            if ink[y * width + x] && !visited[y * width + x] {
                let mut queue = VecDeque::new();
                queue.push_back((x, y));
                visited[y * width + x] = true;
                let mut minx = x;
                let mut miny = y;
                let mut maxx = x;
                let mut maxy = y;
                let mut count = 0usize;

                while let Some((cx, cy)) = queue.pop_front() {
                    count += 1;
                    if cx < minx { minx = cx; }
                    if cx > maxx { maxx = cx; }
                    if cy < miny { miny = cy; }
                    if cy > maxy { maxy = cy; }

                    for dy in -1i32..=1 {
                        for dx in -1i32..=1 {
                            if dx == 0 && dy == 0 { continue; }
                            let nx = cx as i32 + dx;
                            let ny = cy as i32 + dy;
                            if nx >= 0 && nx < width as i32 && ny >= 0 && ny < height as i32 {
                                let ni = ny as usize * width + nx as usize;
                                if ink[ni] && !visited[ni] {
                                    visited[ni] = true;
                                    queue.push_back((nx as usize, ny as usize));
                                }
                            }
                        }
                    }
                }

                components.push((x, y, minx, miny, maxx, maxy, count));
            }
        }
    }

    println!("components {}", components.len());
    for (fx, fy, minx, miny, maxx, maxy, count) in &components {
        println!(
            "{},{} bbox {},{}-{},{} pixels {}",
            fx, fy, minx, miny, maxx, maxy, count
        );
    }
}

fn palette_color(data: &[u8], palette_start: usize, idx: usize) -> (u8, u8, u8) {
    let off = palette_start + idx * 4;
    let b = data[off];
    let g = data[off + 1];
    let r = data[off + 2];
    (r, g, b)
}

fn extract_channel(pixel: u32, mask: u32) -> u8 {
    let s = mask.trailing_zeros();
    let n = mask.count_ones();
    let m: u32 = (1u32 << n) - 1;
    let v = (pixel & mask) >> s;
    ((v * 255 + m / 2) / m) as u8
}

fn read_u32_le(data: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_i32_le(data: &[u8], offset: usize) -> i32 {
    i32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_u16_le(data: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([data[offset], data[offset + 1]])
}

