                var comp = Component(firstX: x, firstY: y, minX: x, minY: y, maxX: x, maxY: y, count: 0)
                var queue = [(Int, Int)]()
                queue.append((x, y))
                visited[y][x] = true
                var qi = 0

                while qi < queue.count {
                    let (cx, cy) = queue[qi]
                    qi += 1
                    comp.count += 1
                    if cx < comp.minX { comp.minX = cx }
                    if cy < comp.minY { comp.minY = cy }
                    if cx > comp.maxX { comp.maxX = cx }
                    if cy > comp.maxY { comp.maxY = cy }

                    for d in 0..<8 {
                        let nx = cx + dx[d]
                        let ny = cy + dy[d]
                        if nx >= 0 && nx < width && ny >= 0 && ny < height && ink[ny][nx] && !visited[ny][nx] {
                            visited[ny][nx] = true
                            queue.append((nx, ny))
                        }
                    }
                }

                components.append(comp)
            }
        }
    }

    print("== \(fileName)")
    let orientation = bottomUp ? "bottom-up" : "top-down"
    print("size \(width)x\(height) bpp \(bitsPerPixel) header \(dibSize) \(orientation) ink \(inkCount)")
    print("components \(components.count)")
    for comp in components {
        print("\(comp.firstX),\(comp.firstY) bbox \(comp.minX),\(comp.minY)-\(comp.maxX),\(comp.maxY) pixels \(comp.count)")
    }
}

