                BigInteger[] remainders = new BigInteger[n];
                BigInteger sumFloors = BigInteger.ZERO;

                for (int i = 0; i < n; i++) {
                    BigInteger numerator = aMinor.multiply(BigInteger.valueOf(weights.get(i)));
                    allocations[i] = numerator.divide(W);
                    remainders[i] = numerator.mod(W);
                    sumFloors = sumFloors.add(allocations[i]);
                }

                BigInteger leftover = aMinor.subtract(sumFloors);

                Integer[] indices = new Integer[n];
                for (int i = 0; i < n; i++) indices[i] = i;
                Arrays.sort(indices, (a, b) -> {
                    int cmp = remainders[b].compareTo(remainders[a]);
                    if (cmp != 0) return cmp;
                    return Integer.compare(a, b);
                });

                accFrom.balance = newBalance;
                for (int i = 0; i < n; i++) {
                    int idx = indices[i];
                    BigInteger alloc = allocations[idx];
                    if (i < leftover.intValue()) {
                        alloc = alloc.add(BigInteger.ONE);
                    }
                    BigDecimal allocDecimal = new BigDecimal(alloc, minor);
                    accounts.get(targets.get(idx)).balance = accounts.get(targets.get(idx)).balance.add(allocDecimal);
                }

