                sb.append(Integer.toHexString(groups[i]));
            }
        }
        return sb.toString();
    }

    static String formatTxt(byte[] msg, int offset, int length) {
        StringBuilder sb = new StringBuilder();
        int end = offset + length;
        int pos = offset;
        boolean first = true;

        while (pos < end) {
            int strLen = msg[pos] & 0xFF;
            pos++;

            if (!first) sb.append(' ');
            first = false;

            sb.append('"');
            for (int i = 0; i < strLen; i++) {
                int b = msg[pos + i] & 0xFF;
                if (b == '"') {
                    sb.append("\\\"");
                } else if (b == '\\') {
                    sb.append("\\\\");
                } else if (b >= 0x20 && b <= 0x7E) {
                    sb.append((char) b);
                } else {
                    sb.append(String.format("\\%03d", b));
                }
            }
            sb.append('"');
            pos += strLen;
        }

