function typeToNum(t: string): number {
  switch (t) {
    case 'A': return 1;
    case 'AAAA': return 28;
    case 'MX': return 15;
    case 'TXT': return 16;
    case 'CNAME': return 5;
    default: return 0;
  }
}

function numToType(n: number): string {
  switch (n) {
    case 1: return 'A';
    case 5: return 'CNAME';
    case 15: return 'MX';
    case 16: return 'TXT';
    case 28: return 'AAAA';
    default: return `TYPE${n}`;
  }
}

function rcodeStr(code: number): string {
  switch (code) {
    case 0: return 'NOERROR';
    case 1: return 'FORMERR';
    case 2: return 'SERVFAIL';
    case 3: return 'NXDOMAIN';
    case 4: return 'NOTIMP';
    case 5: return 'REFUSED';
    default: return `RCODE${code}`;
  }
}

function normalizeName(name: string): string {
  let n = name.toLowerCase();
  if (n.endsWith('.')) n = n.slice(0, -1);
  if (n === '') return '.';
  return n;
}

function buildQuery(id: number, name: string, qtype: number): Buffer {
  const parts: Buffer[] = [];
  const header = Buffer.alloc(12);
  header.writeUInt16BE(id, 0);
  header.writeUInt16BE(0x0100, 2);
  header.writeUInt16BE(1, 4);
  header.writeUInt16BE(0, 6);
  header.writeUInt16BE(0, 8);
  header.writeUInt16BE(0, 10);
  parts.push(header);

  let labels = name.split('.');
  if (labels.length > 0 && labels[labels.length - 1] === '') labels.pop();

  for (const label of labels) {
    const lb = Buffer.from(label, 'ascii');
    parts.push(Buffer.from([lb.length]));
    parts.push(lb);
  }
  parts.push(Buffer.from([0]));

  const q = Buffer.alloc(4);
  q.writeUInt16BE(qtype, 0);
  q.writeUInt16BE(1, 2);
  parts.push(q);

  return Buffer.concat(parts);
}

function parseName(buf: Buffer, offset: number): { name: string; newOffset: number } {
  const labels: string[] = [];
  let pos = offset;
  let returnOffset = -1;

  while (pos < buf.length) {
    const len = buf[pos];
    if (len === 0) {
      if (returnOffset === -1) returnOffset = pos + 1;
      break;
    }
    if ((len & 0xC0) === 0xC0) {
      const ptr = ((len & 0x3F) << 8) | buf[pos + 1];
      if (returnOffset === -1) returnOffset = pos + 2;
      pos = ptr;
    } else {
      labels.push(buf.slice(pos + 1, pos + 1 + len).toString('ascii').toLowerCase());
      pos += 1 + len;
      if (returnOffset === -1) returnOffset = pos;
    }
  }

  const name = labels.length === 0 ? '.' : labels.join('.');
  return { name, newOffset: returnOffset };
}

function formatAAAA(buf: Buffer, offset: number): string {
  const groups: number[] = [];
  for (let i = 0; i < 8; i++) {
    groups.push((buf[offset + i * 2] << 8) | buf[offset + i * 2 + 1]);
  }

  const hex = groups.map(g => g.toString(16));

  let bestStart = -1, bestLen = 0;
  let i = 0;
  while (i < 8) {
    if (groups[i] === 0) {
      let j = i;
      while (j < 8 && groups[j] === 0) j++;
      const runLen = j - i;
      if (runLen >= 2 && runLen > bestLen) {
        bestStart = i;
        bestLen = runLen;
      }
      i = j;
    } else {
      i++;
    }
  }

  if (bestLen >= 2) {
    const before = hex.slice(0, bestStart);
    const after = hex.slice(bestStart + bestLen);
    if (before.length === 0 && after.length === 0) return '::';
    if (before.length === 0) return '::' + after.join(':');
    if (after.length === 0) return before.join(':') + '::';
    return before.join(':') + '::' + after.join(':');
  }

  return hex.join(':');
}

function formatTXT(buf: Buffer, offset: number, length: number): string {
  const parts: string[] = [];
  let pos = offset;
  const end = offset + length;
  while (pos < end) {
    const strLen = buf[pos];
    pos++;
    let s = '"';
    for (let i = 0; i < strLen; i++) {
      const b = buf[pos + i];
      if (b === 0x22) s += '\\"';
      else if (b === 0x5C) s += '\\\\';
      else if (b >= 0x20 && b <= 0x7E) s += String.fromCharCode(b);
      else s += '\\' + b.toString().padStart(3, '0');
    }
    s += '"';
    parts.push(s);
    pos += strLen;
  }
  return parts.join(' ');
}

function formatRData(buf: Buffer, type: number, rdataOffset: number, rdlength: number): string {
  switch (type) {
    case 1:
      return `${buf[rdataOffset]}.${buf[rdataOffset + 1]}.${buf[rdataOffset + 2]}.${buf[rdataOffset + 3]}`;
    case 28:
      return formatAAAA(buf, rdataOffset);
    case 5:
      return parseName(buf, rdataOffset).name;
    case 15: {
      const pref = buf.readUInt16BE(rdataOffset);
      const exchange = parseName(buf, rdataOffset + 2).name;
      return `${pref} ${exchange}`;
    }
    case 16:
      return formatTXT(buf, rdataOffset, rdlength);
    default: {
      if (rdlength === 0) return '\\# 0';
      const hex = buf.slice(rdataOffset, rdataOffset + rdlength).toString('hex');
      return `\\# ${rdlength} ${hex}`;
    }
  }
}

function sendUDP(query: Buffer, port: number): Promise<Buffer> {
