        boolean bVal;
        double nVal;
        String sVal;
        List<JVal> aVal;
        LinkedHashMap<String, JVal> oVal;

        static JVal nullVal() { JVal v = new JVal(); v.type = JType.NULL; return v; }
        static JVal boolVal(boolean b) { JVal v = new JVal(); v.type = JType.BOOLEAN; v.bVal = b; return v; }
        static JVal numVal(double d) { JVal v = new JVal(); v.type = JType.NUMBER; v.nVal = d; return v; }
        static JVal strVal(String s) { JVal v = new JVal(); v.type = JType.STRING; v.sVal = s; return v; }
        static JVal arrVal(List<JVal> a) { JVal v = new JVal(); v.type = JType.ARRAY; v.aVal = a; return v; }
        static JVal objVal(LinkedHashMap<String, JVal> o) { JVal v = new JVal(); v.type = JType.OBJECT; v.oVal = o; return v; }
    }

