import Foundation
import CryptoKit

func base64urlDecode(_ s: String) -> Data? {
    if s.isEmpty { return nil }
    for ch in s.unicodeScalars {
        guard (ch >= "A" && ch <= "Z") || (ch >= "a" && ch <= "z") ||
              (ch >= "0" && ch <= "9") || ch == "-" || ch == "_" else {
            return nil
        }
    }
    if s.count % 4 == 1 { return nil }
    var padded = s
    switch s.count % 4 {
    case 2: padded += "=="
    case 3: padded += "="
    default: break
    }
    padded = padded.replacingOccurrences(of: "-", with: "+")
                  .replacingOccurrences(of: "_", with: "/")
    return Data(base64Encoded: padded)
}

func hmacVerify(alg: String, signingInput: String, signature: Data, secret: Data) -> Bool {
    let key = SymmetricKey(data: secret)
    let expected: Data
    switch alg {
    case "HS256":
        expected = Data(HMAC<SHA256>.authentication(for: signingInput, using: key))
    case "HS384":
        expected = Data(HMAC<SHA384>.authentication(for: signingInput, using: key))
    case "HS512":
        expected = Data(HMAC<SHA512>.authentication(for: signingInput, using: key))
    default:
        return false
    }
    return expected == signature
}

