    schema: &JsonValue,
    inst_loc: &str,
    sch_loc: &str,
    root: &JsonValue,
) -> bool {
    let mut tmp = HashSet::new();
    validate(instance, schema, inst_loc, sch_loc, root, &mut tmp);
