    func format(minorUnits: Int) -> String {
        let r = self.round(to: minorUnits)

        let intPart: BigUInt
        let fracPart: BigUInt

        if minorUnits == 0 {
            intPart = r.unscaled
            fracPart = BigUInt()
        } else {
            let divisor = pow10(minorUnits)
            let (q, rem) = BigUInt.divMod(r.unscaled, divisor)
            intPart = q
            fracPart = rem
        }

        var result = ""
        if r.neg { result += "-" }

        let intStr = intPart.toString()
        var groups: [String] = []
        var remaining = intStr
        while remaining.count > 3 {
            groups.insert(String(remaining.suffix(3)), at: 0)
            remaining = String(remaining.dropLast(3))
        }
        if !remaining.isEmpty { groups.insert(remaining, at: 0) }
        if groups.isEmpty { groups = ["0"] }
        result += groups.joined(separator: ",")

        if minorUnits > 0 {
            let fracStr = fracPart.toString()
            let padded = String(repeating: "0", count: minorUnits - fracStr.count) + fracStr
            result += "." + padded
        }

        return result
    }
}

