fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut p = JsonParser::new(s);
    p.parse_full()
}

fn base64url_decode(s: &str) -> Option<Vec<u8>> {
    let bytes = s.as_bytes();
    let n = bytes.len();
    for &b in bytes {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' => {}
            _ => return None,
        }
    }
    if n % 4 == 1 { return None; }
    let mut bits: u64 = 0;
    let mut nbits = 0usize;
    let mut out = Vec::new();
    for &b in bytes {
        let val: u64 = match b {
            b'A'..=b'Z' => (b - b'A') as u64,
            b'a'..=b'z' => (b - b'a' + 26) as u64,
            b'0'..=b'9' => (b - b'0' + 52) as u64,
            b'-' => 62,
            b'_' => 63,
            _ => return None,
        };
        bits = (bits << 6) | val;
        nbits += 6;
        if nbits >= 8 {
            nbits -= 8;
            out.push((bits >> nbits) as u8);
            bits &= (1u64 << nbits) - 1;
        }
    }
    Some(out)
}

fn hmac_sha(alg: &str, key: &[u8], data: &[u8]) -> Vec<u8> {
    let (cc_alg, out_len) = match alg {
        "HS256" => (CC_SHA256, 32usize),
        "HS384" => (CC_SHA384, 48usize),
        "HS512" => (CC_SHA512, 64usize),
        _ => (CC_SHA256, 32usize),
    };
    let mut mac = vec![0u8; out_len];
    unsafe {
        CCHmac(cc_alg, key.as_ptr(), key.len(), data.as_ptr(), data.len(), mac.as_mut_ptr());
    }
    mac
}

fn validate_token(
    token: &str,
    keys: &HashMap<String, (String, Vec<u8>)>,
    now: f64,
    leeway: f64,
    issuer: &str,
    audience: &str,
) -> Result<(String, String), String> {
    // Rule 1: MALFORMED
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 { return Err("MALFORMED".into()); }
    for &part in &parts {
        if part.is_empty() { return Err("MALFORMED".into()); }
        for &b in part.as_bytes() {
            match b {
                b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' => {}
                _ => return Err("MALFORMED".into()),
            }
        }
        if part.len() % 4 == 1 { return Err("MALFORMED".into()); }
    }
    let header_bytes = base64url_decode(parts[0]).ok_or("MALFORMED")?;
    let payload_bytes = base64url_decode(parts[1]).ok_or("MALFORMED")?;
    let header_str = std::str::from_utf8(&header_bytes).map_err(|_| "MALFORMED")?;
    let payload_str = std::str::from_utf8(&payload_bytes).map_err(|_| "MALFORMED")?;
    let header = parse_json(header_str).map_err(|_| "MALFORMED")?;
    let payload = parse_json(payload_str).map_err(|_| "MALFORMED")?;
    if !matches!(header, JsonValue::Object(_)) { return Err("MALFORMED".into()); }
    if !matches!(payload, JsonValue::Object(_)) { return Err("MALFORMED".into()); }

    // Rule 2: UNSUPPORTED_ALG
    let alg = match header.get("alg") {
        Some(JsonValue::Str(s)) => s.clone(),
        _ => return Err("UNSUPPORTED_ALG".into()),
    };
    if alg != "HS256" && alg != "HS384" && alg != "HS512" {
        return Err("UNSUPPORTED_ALG".into());
    }

    // Rule 3: UNKNOWN_KEY
    let kid = match header.get("kid") {
        Some(JsonValue::Str(s)) => s.clone(),
        _ => return Err("UNKNOWN_KEY".into()),
    };
    let (key_alg, secret) = match keys.get(&kid) {
        Some(k) => k,
        None => return Err("UNKNOWN_KEY".into()),
    };

    // Rule 4: ALG_MISMATCH
    if key_alg != &alg { return Err("ALG_MISMATCH".into()); }

    // Rule 5: BAD_SIGNATURE
    let signing_input = format!("{}.{}", parts[0], parts[1]);
    let sig_bytes = base64url_decode(parts[2]).ok_or("BAD_SIGNATURE")?;
    let expected_sig = hmac_sha(&alg, secret, signing_input.as_bytes());
    if sig_bytes != expected_sig { return Err("BAD_SIGNATURE".into()); }

    // Rule 6: EXPIRED
    if let Some(exp_val) = payload.get("exp") {
        if let Some(exp) = exp_val.as_f64() {
            if now >= exp + leeway { return Err("EXPIRED".into()); }
        }
    }

    // Rule 7: NOT_YET_VALID
    if let Some(nbf_val) = payload.get("nbf") {
        if let Some(nbf) = nbf_val.as_f64() {
            if now + leeway < nbf { return Err("NOT_YET_VALID".into()); }
        }
    }

    // Rule 8: BAD_ISSUER
    match payload.get("iss") {
        Some(JsonValue::Str(s)) if s == issuer => {}
        _ => return Err("BAD_ISSUER".into()),
    }

    // Rule 9: BAD_AUDIENCE
    match payload.get("aud") {
        Some(JsonValue::Str(s)) => {
            if s != audience { return Err("BAD_AUDIENCE".into()); }
        }
        Some(JsonValue::Array(arr)) => {
            let found = arr.iter().any(|v| matches!(v, JsonValue::Str(s) if s == audience));
            if !found { return Err("BAD_AUDIENCE".into()); }
        }
        _ => return Err("BAD_AUDIENCE".into()),
    }

    // VALID
    let sub = payload.get("sub").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let scope_str = payload.get("scope").and_then(|v| v.as_str()).unwrap_or("");
    let scopes = format_scopes(scope_str);
    Ok((sub, scopes))
}

fn format_scopes(scope_str: &str) -> String {
    if scope_str.is_empty() { return String::new(); }
    let mut parts: Vec<&str> = scope_str.split(' ').filter(|s| !s.is_empty()).collect();
    parts.sort();
    parts.dedup();
    parts.join(",")
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let config_str = fs::read_to_string(format!("{}/config.json", dir)).expect("cannot read config.json");
    let config = parse_json(&config_str).expect("cannot parse config.json");

    let now = config.get("now").and_then(|v| v.as_f64()).expect("missing now");
    let leeway = config.get("leeway").and_then(|v| v.as_f64()).unwrap_or(0.0);
    let issuer = config.get("issuer").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let audience = config.get("audience").and_then(|v| v.as_str()).unwrap_or("").to_string();

    let keys_json = config.get("keys").and_then(|v| v.as_array()).expect("missing keys");
    let mut keys: HashMap<String, (String, Vec<u8>)> = HashMap::new();
    for key_obj in keys_json {
        let kid = key_obj.get("kid").and_then(|v| v.as_str()).unwrap_or("").to_string();
        let alg = key_obj.get("alg").and_then(|v| v.as_str()).unwrap_or("").to_string();
        let k_str = key_obj.get("k").and_then(|v| v.as_str()).unwrap_or("");
        let k_bytes = base64url_decode(k_str).unwrap_or_default();
        keys.insert(kid, (alg, k_bytes));
    }

    let tokens_str = fs::read_to_string(format!("{}/tokens.txt", dir)).expect("cannot read tokens.txt");
    let token_lines: Vec<&str> = tokens_str.lines().map(|l| l.trim()).filter(|l| !l.is_empty()).collect();

    let mut valid_count = 0usize;
    let mut invalid_count = 0usize;
    let mut output = String::new();

    for (idx, token) in token_lines.iter().enumerate() {
        let n = idx + 1;
        match validate_token(token, &keys, now, leeway, &issuer, &audience) {
            Ok((sub, scopes)) => {
                output.push_str(&format!("{}: VALID sub={} scope={}\n", n, sub, scopes));
                valid_count += 1;
            }
            Err(err) => {
                output.push_str(&format!("{}: {}\n", n, err));
                invalid_count += 1;
            }
        }
    }

    output.push_str(&format!("\nvalid={} invalid={}\n", valid_count, invalid_count));
    print!("{}", output);
}
