struct PropDef {
    name: &'static str,
    ptype: &'static str, // "string" or "array"
    min_len: Option<usize>,
}

struct ToolDef {
    name: &'static str,
    props: Vec<PropDef>,
    required: Vec<&'static str>,
    has_output: bool,
}

