struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self { Parser { s: s.as_bytes(), pos: 0 } }

    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            match self.s[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> Result<JsonVal, ()> {
        self.skip_ws();
        if self.pos >= self.s.len() { return Err(()); }
        match self.s[self.pos] {
            b'n' => self.parse_lit(b"null", JsonVal::Null),
            b't' => self.parse_lit(b"true", JsonVal::Bool(true)),
            b'f' => self.parse_lit(b"false", JsonVal::Bool(false)),
            b'"' => self.parse_string().map(JsonVal::Str),
            b'[' => self.parse_array(),
            b'{' => self.parse_object(),
            b'-' | b'0'..=b'9' => self.parse_number(),
            _ => Err(()),
        }
    }

    fn parse_lit(&mut self, lit: &[u8], val: JsonVal) -> Result<JsonVal, ()> {
        if self.s.len() - self.pos >= lit.len() && &self.s[self.pos..self.pos+lit.len()] == lit {
            self.pos += lit.len();
            Ok(val)
        } else { Err(()) }
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.pos += 1; // skip opening "
        let mut result = String::new();
        while self.pos < self.s.len() {
            let c = self.s[self.pos];
            if c == b'"' { self.pos += 1; return Ok(result); }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.s.len() { return Err(()); }
                match self.s[self.pos] {
                    b'"' => { result.push('"'); self.pos += 1; }
                    b'\\' => { result.push('\\'); self.pos += 1; }
                    b'/' => { result.push('/'); self.pos += 1; }
                    b'b' => { result.push('\u{0008}'); self.pos += 1; }
                    b'f' => { result.push('\u{000C}'); self.pos += 1; }
                    b'n' => { result.push('\n'); self.pos += 1; }
                    b'r' => { result.push('\r'); self.pos += 1; }
                    b't' => { result.push('\t'); self.pos += 1; }
                    b'u' => {
                        self.pos += 1;
                        let cp = self.parse_hex4()?;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if self.pos + 1 < self.s.len() && self.s[self.pos] == b'\\' && self.s[self.pos+1] == b'u' {
                                self.pos += 2;
                                let lo = self.parse_hex4()?;
                                if lo >= 0xDC00 && lo <= 0xDFFF {
                                    let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                    result.push(char::from_u32(combined).ok_or(())?);
                                } else { return Err(()); }
                            } else { return Err(()); }
                        } else if cp >= 0xDC00 && cp <= 0xDFFF {
                            return Err(());
                        } else {
                            result.push(char::from_u32(cp).ok_or(())?);
                        }
                    }
                    _ => return Err(()),
                }
            } else {
                let start = self.pos;
                let byte = self.s[self.pos];
                let len = if byte < 0x80 { 1usize }
                          else if byte < 0xE0 { 2 }
                          else if byte < 0xF0 { 3 }
                          else { 4 };
                if self.pos + len > self.s.len() { return Err(()); }
                let sub = std::str::from_utf8(&self.s[start..start+len]).map_err(|_| ())?;
                result.push_str(sub);
                self.pos += len;
            }
        }
        Err(())
    }

    fn parse_hex4(&mut self) -> Result<u32, ()> {
        if self.pos + 4 > self.s.len() { return Err(()); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.s[self.pos + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => return Err(()),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_number(&mut self) -> Result<JsonVal, ()> {
        let start = self.pos;
        let mut is_int = true;
        if self.pos < self.s.len() && self.s[self.pos] == b'-' { self.pos += 1; }
        if self.pos >= self.s.len() { return Err(()); }
        if self.s[self.pos] == b'0' {
            self.pos += 1;
        } else if self.s[self.pos] >= b'1' && self.s[self.pos] <= b'9' {
            while self.pos < self.s.len() && self.s[self.pos] >= b'0' && self.s[self.pos] <= b'9' { self.pos += 1; }
        } else { return Err(()); }
        if self.pos < self.s.len() && self.s[self.pos] == b'.' {
            is_int = false; self.pos += 1;
            if self.pos >= self.s.len() || self.s[self.pos] < b'0' || self.s[self.pos] > b'9' { return Err(()); }
            while self.pos < self.s.len() && self.s[self.pos] >= b'0' && self.s[self.pos] <= b'9' { self.pos += 1; }
        }
        if self.pos < self.s.len() && (self.s[self.pos] == b'e' || self.s[self.pos] == b'E') {
            is_int = false; self.pos += 1;
            if self.pos < self.s.len() && (self.s[self.pos] == b'+' || self.s[self.pos] == b'-') { self.pos += 1; }
            if self.pos >= self.s.len() || self.s[self.pos] < b'0' || self.s[self.pos] > b'9' { return Err(()); }
            while self.pos < self.s.len() && self.s[self.pos] >= b'0' && self.s[self.pos] <= b'9' { self.pos += 1; }
        }
        let txt = std::str::from_utf8(&self.s[start..self.pos]).map_err(|_| ())?;
        let val: f64 = txt.parse().map_err(|_| ())?;
        Ok(JsonVal::Num(val, is_int))
    }

    fn parse_array(&mut self) -> Result<JsonVal, ()> {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.pos < self.s.len() && self.s[self.pos] == b']' { self.pos += 1; return Ok(JsonVal::Arr(items)); }
        loop {
            items.push(self.parse_value()?);
            self.skip_ws();
            if self.pos >= self.s.len() { return Err(()); }
            match self.s[self.pos] {
                b',' => { self.pos += 1; }
                b']' => { self.pos += 1; return Ok(JsonVal::Arr(items)); }
                _ => return Err(()),
            }
        }
    }

    fn parse_object(&mut self) -> Result<JsonVal, ()> {
        self.pos += 1;
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.pos < self.s.len() && self.s[self.pos] == b'}' { self.pos += 1; return Ok(JsonVal::Obj(pairs)); }
