fn validate_and_call(tool: &ToolDef, args: &JsonVal, store: &mut HashMap<String, String>) -> JsonVal {
    // 1. arguments present but not object
    if !args.is_object() {
        return tool_failure("arguments must be an object");
    }
    let args_pairs = if let JsonVal::Obj(ref pairs) = args { pairs } else { unreachable!() };

    // 2. unknown arguments
    let valid_names: Vec<&str> = tool.props.iter().map(|p| p.name).collect();
    let mut unknowns: Vec<&str> = Vec::new();
    for (k, _) in args_pairs {
        if !valid_names.contains(&k.as_str()) {
            unknowns.push(k.as_str());
        }
    }
    if !unknowns.is_empty() {
        unknowns.sort();
        return tool_failure(&format!("unknown argument: {}", unknowns[0]));
    }

    // 3. check each property in schema order
    for prop in &tool.props {
        let val = args.get(prop.name);
        if val.is_none() {
            if tool.required.contains(&prop.name) {
                return tool_failure(&format!("missing required argument: {}", prop.name));
            }
            continue;
        }
        let val = val.unwrap();
        // type check
        match prop.ptype {
            "string" => {
                if !val.is_string() {
                    return tool_failure(&format!("argument {} must be a string", prop.name));
                }
            }
            "array" => {
                let items = if let JsonVal::Arr(ref items) = *val { items } else {
                    return tool_failure(&format!("argument {} must be an array of integers", prop.name));
                };
                for item in items {
                    if !item.is_integer() {
                        return tool_failure(&format!("argument {} must be an array of integers", prop.name));
                    }
                }
            }
            _ => {}
        }
        // minLength / minItems
        if let Some(ml) = prop.min_len {
            match prop.ptype {
                "string" => {
                    if let JsonVal::Str(ref s) = *val {
                        if s.chars().count() < ml {
                            return tool_failure(&format!("argument {} must not be empty", prop.name));
                        }
                    }
                }
                "array" => {
                    if let JsonVal::Arr(ref items) = *val {
                        if items.len() < ml {
                            return tool_failure(&format!("argument {} must not be empty", prop.name));
                        }
                    }
                }
                _ => {}
            }
        }
    }

    // Execute tool
    match tool.name {
        "kv_set" => {
            let key = args.get("key").unwrap().as_str().unwrap().to_string();
            let value = args.get("value").unwrap().as_str().unwrap().to_string();
            let existed = store.contains_key(&key);
            store.insert(key.clone(), value);
            if existed {
                tool_success_text(&format!("updated {}", key))
            } else {
                tool_success_text(&format!("created {}", key))
            }
        }
        "kv_get" => {
            let key = args.get("key").unwrap().as_str().unwrap().to_string();
            match store.get(&key) {
                Some(v) => tool_success_text(v),
                None => tool_failure(&format!("key not found: {}", key)),
            }
        }
        "kv_list" => {
            let prefix = args.get("prefix").and_then(|v| v.as_str()).unwrap_or("");
            let mut keys: Vec<String> = store.keys().filter(|k| k.starts_with(prefix)).cloned().collect();
            keys.sort();
            let count = keys.len() as i64;
            let s = make_obj(vec![
                ("keys", JsonVal::Arr(keys.into_iter().map(JsonVal::Str).collect())),
                ("count", JsonVal::Num(count as f64, true)),
            ]);
            tool_success_structured(s)
        }
        "sum" => {
            let items = args.get("numbers").unwrap();
            let nums = if let JsonVal::Arr(ref items) = *items { items } else { unreachable!() };
            let sum: i64 = nums.iter().map(|v| v.as_int().unwrap_or(0)).sum();
            let count = nums.len() as i64;
            let s = make_obj(vec![
                ("sum", JsonVal::Num(sum as f64, true)),
                ("count", JsonVal::Num(count as f64, true)),
            ]);
            tool_success_structured(s)
        }
        "text_stats" => {
            let text = args.get("text").unwrap().as_str().unwrap();
            let codepoints = text.chars().count() as i64;
            let utf8_bytes = text.len() as i64;
            let mut words: i64 = 0;
            let mut in_word = false;
            for c in text.chars() {
                if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                    in_word = false;
                } else {
                    if !in_word { words += 1; in_word = true; }
                }
            }
            let s = make_obj(vec![
                ("words", JsonVal::Num(words as f64, true)),
                ("codepoints", JsonVal::Num(codepoints as f64, true)),
                ("utf8_bytes", JsonVal::Num(utf8_bytes as f64, true)),
            ]);
            tool_success_structured(s)
        }
        _ => unreachable!(),
    }
}

fn extract_id(msg: &JsonVal) -> Option<IdEcho> {
    // Returns None if no id member at all
    if !msg.has("id") { return None; }
    let id_val = msg.get("id").unwrap();
    match id_val {
        JsonVal::Str(s) => Some(IdEcho::Str(s.clone())),
        JsonVal::Num(_, true) => Some(IdEcho::Int(id_val.as_int().unwrap())),
        _ => Some(IdEcho::Null),
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();

    let mut initialized = false;
    let mut store: HashMap<String, String> = HashMap::new();
    let tool_defs = get_tool_defs();

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        // strip trailing \r
        let line = if line.ends_with('\r') { &line[..line.len()-1] } else { &line[..] };
        // check if line is empty or whitespace only
        if line.is_empty() || line.bytes().all(|b| b == b' ' || b == b'\t' || b == b'\r') {
            continue;
        }

        // Rule 1: parse JSON
        let parsed = {
            let mut p = Parser::new(line);
            p.parse_full()
        };
        let msg = match parsed {
            Ok(v) => v,
            Err(_) => {
                let resp = err_response(&IdEcho::Null, -32700, "Parse error");
                let _ = writeln!(out, "{}", resp);
                continue;
            }
        };

        // Rule 2: not an object
        if !msg.is_object() {
            let resp = err_response(&IdEcho::Null, -32600, "Invalid Request");
            let _ = writeln!(out, "{}", resp);
            continue;
        }

        // Rule 3: has result or error but no method → ignore
        if !msg.has("method") && (msg.has("result") || msg.has("error")) {
            continue;
        }

        // Rule 4: invalid request checks
        let jsonrpc_ok = msg.get("jsonrpc").map(|v| v.as_str() == Some("2.0")).unwrap_or(false);
        let method_ok = msg.get("method").map(|v| v.is_string()).unwrap_or(false);
        let id_present = msg.has("id");
        let id_valid = if id_present {
            let iv = msg.get("id").unwrap();
            matches!(iv, JsonVal::Str(_) | JsonVal::Num(_, true))
        } else { true };

        if !jsonrpc_ok || !method_ok || !id_valid {
            let id = if id_present && id_valid {
                extract_id(&msg).unwrap()
            } else {
                IdEcho::Null
            };
            let resp = err_response(&id, -32600, "Invalid Request");
            let _ = writeln!(out, "{}", resp);
            continue;
        }

        // Rule 5: notification (no id)
        if !id_present {
            continue;
        }

        // Rule 6: request
        let id = extract_id(&msg).unwrap();
        let method = msg.get("method").unwrap().as_str().unwrap();

        // 6a: method not found
        if method != "initialize" && method != "ping" && method != "tools/list" && method != "tools/call" {
            let resp = err_response(&id, -32601, "Method not found");
            let _ = writeln!(out, "{}", resp);
            continue;
        }

        // 6b: params present but not object
        if msg.has("params") && !msg.get("params").unwrap().is_object() {
            let resp = err_response(&id, -32602, "Invalid params");
            let _ = writeln!(out, "{}", resp);
            continue;
        }

        // 6c: not initialized
        if !initialized && method != "initialize" && method != "ping" {
            let resp = err_response(&id, -32002, "Server not initialized");
            let _ = writeln!(out, "{}", resp);
            continue;
        }

        // 6d: dispatch
        let result: Result<JsonVal, (i64, String)> = match method {
            "initialize" => {
                if initialized {
                    Err((-32600, "Already initialized".to_string()))
                } else {
                    let params = msg.get("params");
                    let pv = params.and_then(|p| p.get("protocolVersion")).and_then(|v| v.as_str());
                    match pv {
                        Some(v) => {
                            let version = match v {
                                "2025-06-18" | "2025-03-26" | "2024-11-05" => v.to_string(),
                                _ => "2025-06-18".to_string(),
                            };
                            initialized = true;
                            Ok(make_obj(vec![
                                ("protocolVersion", JsonVal::Str(version)),
                                ("capabilities", make_obj(vec![
                                    ("tools", make_obj(vec![("listChanged", JsonVal::Bool(false))])),
                                ])),
                                ("serverInfo", make_obj(vec![
                                    ("name", JsonVal::Str("cb2-kv".to_string())),
                                    ("title", JsonVal::Str("CB2 key-value server".to_string())),
                                    ("version", JsonVal::Str("1.4.2".to_string())),
                                ])),
                            ]))
                        }
                        None => Err((-32602, "Invalid params".to_string())),
                    }
                }
            }
            "ping" => Ok(make_obj(vec![])),
            "tools/list" => Ok(build_tools_list()),
            "tools/call" => {
                let params = msg.get("params");
                let name_val = params.and_then(|p| p.get("name"));
                let name = match name_val {
                    Some(v) => match v.as_str() {
                        Some(s) => s,
                        None => return { let resp = err_response(&id, -32602, "Invalid params"); let _ = writeln!(out, "{}", resp); continue; },
                    },
                    None => return { let resp = err_response(&id, -32602, "Invalid params"); let _ = writeln!(out, "{}", resp); continue; },
                };
                let tool_def = tool_defs.iter().find(|t| t.name == name);
                match tool_def {
                    Some(td) => {
                        let args = params.unwrap().get("arguments");
                        let args_val = match args {
                            Some(a) => a,
                            None => &JsonVal::Obj(vec![]),
                        };
                        Ok(validate_and_call(td, args_val, &mut store))
                    }
                    None => Err((-32602, format!("Unknown tool: {}", name))),
                }
            }
            _ => unreachable!(),
        };

        match result {
            Ok(r) => {
                let resp = ok_response(&id, r);
                let _ = writeln!(out, "{}", resp);
            }
            Err((code, msg)) => {
                let resp = err_response(&id, code, &msg);
                let _ = writeln!(out, "{}", resp);
            }
        }
    }

    let _ = out.flush();
    std::process::exit(0);
}
