#include <string.h>
#include <stdint.h>
#include <math.h>

/* ==================== JSON Value ==================== */
typedef enum { J_NULL, J_BOOL, J_INT, J_FLOAT, J_STRING, J_ARRAY, J_OBJECT } JType;

typedef struct JVal {
    JType type;
    union {
        int b;
        long long i;
        double f;
        char *s;
        struct { struct JVal **items; int n; } arr;
        struct { char **keys; struct JVal **vals; int n; } obj;
    };
} JVal;

static void jval_free(JVal *v) {
    if (!v) return;
    switch (v->type) {
        case J_STRING: free(v->s); break;
        case J_ARRAY:
            for (int i = 0; i < v->arr.n; i++) jval_free(v->arr.items[i]);
            free(v->arr.items);
            break;
        case J_OBJECT:
            for (int i = 0; i < v->obj.n; i++) { free(v->obj.keys[i]); jval_free(v->obj.vals[i]); }
            free(v->obj.keys); free(v->obj.vals);
            break;
        default: break;
    }
    free(v);
}

/* ==================== JSON Parser ==================== */
typedef struct { const char *src; int pos, len; } P;

static void skip_ws(P *p) {
    while (p->pos < p->len) {
        char c = p->src[p->pos];
        if (c==' '||c=='\t'||c=='\n'||c=='\r') p->pos++; else break;
    }
}

static int hexval(char c) {
    if(c>='0'&&c<='9')return c-'0';
    if(c>='a'&&c<='f')return c-'a'+10;
    if(c>='A'&&c<='F')return c-'A'+10;
    return -1;
}

static JVal *parse_value(P *p);

static char *parse_str(P *p) {
    p->pos++; /* skip " */
    int cap=128,n=0; char *buf=malloc(cap);
    while(p->pos<p->len){
        char c=p->src[p->pos];
        if(c=='"'){p->pos++;buf[n]='\0';return buf;}
        if(c=='\\'){
            p->pos++;
            if(p->pos>=p->len){free(buf);return NULL;}
            c=p->src[p->pos];
            char out=0;
            int skip_out=0;
            switch(c){
                case '"':out='"';break;case '\\':out='\\';break;case '/':out='/';break;
                case 'b':out='\b';break;case 'f':out='\f';break;case 'n':out='\n';break;
                case 'r':out='\r';break;case 't':out='\t';break;
                case 'u':{
                    skip_out=1;
                    if(p->pos+4>=p->len){free(buf);return NULL;}
                    int cp=0;
                    for(int i=1;i<=4;i++){int h=hexval(p->src[p->pos+i]);if(h<0){free(buf);return NULL;}cp=(cp<<4)|h;}
                    p->pos+=4;
                    if(cp>=0xD800&&cp<=0xDBFF){
                        if(p->pos+1<p->len&&p->src[p->pos+1]=='\\'&&p->src[p->pos+2]=='u'){
                            if(p->pos+6>=p->len){free(buf);return NULL;}
                            int cp2=0;
                            for(int i=3;i<=6;i++){int h=hexval(p->src[p->pos+i]);if(h<0){free(buf);return NULL;}cp2=(cp2<<4)|h;}
                            if(cp2>=0xDC00&&cp2<=0xDFFF){cp=0x10000+((cp-0xD800)<<10)+(cp2-0xDC00);p->pos+=6;}
                            else{free(buf);return NULL;}
                        }else{free(buf);return NULL;}
                    }else if(cp>=0xDC00&&cp<=0xDFFF){free(buf);return NULL;}
                    if(n>=cap-4){cap*=2;buf=realloc(buf,cap);}
                    if(cp<0x80){buf[n++]=(char)cp;}
                    else if(cp<0x800){buf[n++]=(char)(0xC0|(cp>>6));buf[n++]=(char)(0x80|(cp&0x3F));}
                    else if(cp<0x10000){buf[n++]=(char)(0xE0|(cp>>12));buf[n++]=(char)(0x80|((cp>>6)&0x3F));buf[n++]=(char)(0x80|(cp&0x3F));}
                    else{buf[n++]=(char)(0xF0|(cp>>18));buf[n++]=(char)(0x80|((cp>>12)&0x3F));buf[n++]=(char)(0x80|((cp>>6)&0x3F));buf[n++]=(char)(0x80|(cp&0x3F));}
                    break;
                }
                default:free(buf);return NULL;
            }
            if(!skip_out) buf[n++]=out;
            p->pos++;
        }else if((unsigned char)c<0x20){free(buf);return NULL;}
        else{buf[n++]=c;p->pos++;}
        if(n>=cap-8){cap*=2;buf=realloc(buf,cap);}
    }
    free(buf);return NULL;
}

static JVal *mk_null(){JVal*v=calloc(1,sizeof(JVal));v->type=J_NULL;return v;}
static JVal *mk_bool(int b){JVal*v=calloc(1,sizeof(JVal));v->type=J_BOOL;v->b=b;return v;}
static JVal *mk_int(long long i){JVal*v=calloc(1,sizeof(JVal));v->type=J_INT;v->i=i;return v;}
static JVal *mk_float(double f){JVal*v=calloc(1,sizeof(JVal));v->type=J_FLOAT;v->f=f;return v;}
static JVal *mk_str(char *s){JVal*v=calloc(1,sizeof(JVal));v->type=J_STRING;v->s=s;return v;}

static JVal *parse_number(P *p){
    int start=p->pos;
    int is_int=1;
    if(p->pos<p->len&&p->src[p->pos]=='-')p->pos++;
    while(p->pos<p->len&&p->src[p->pos]>='0'&&p->src[p->pos]<='9')p->pos++;
    if(p->pos<p->len&&p->src[p->pos]=='.'){is_int=0;p->pos++;while(p->pos<p->len&&p->src[p->pos]>='0'&&p->src[p->pos]<='9')p->pos++;}
    if(p->pos<p->len&&(p->src[p->pos]=='e'||p->src[p->pos]=='E')){is_int=0;p->pos++;if(p->pos<p->len&&(p->src[p->pos]=='+'||p->src[p->pos]=='-'))p->pos++;while(p->pos<p->len&&p->src[p->pos]>='0'&&p->src[p->pos]<='9')p->pos++;}
    int n=p->pos-start;
    char tmp[64];if(n>63)n=63;
    memcpy(tmp,p->src+start,n);tmp[n]='\0';
    if(is_int){return mk_int(strtoll(tmp,NULL,10));}
    else{return mk_float(strtod(tmp,NULL));}
}

static JVal *parse_value(P *p){
    skip_ws(p);
    if(p->pos>=p->len)return NULL;
    char c=p->src[p->pos];
    if(c=='"'){char *s=parse_str(p);if(!s)return NULL;return mk_str(s);}
    if(c=='{'){
        p->pos++;
        int cap=8,n=0;char **keys=malloc(cap*sizeof(char*));JVal **vals=malloc(cap*sizeof(JVal*));
        skip_ws(p);
        if(p->pos<p->len&&p->src[p->pos]=='}'){p->pos++;JVal*v=calloc(1,sizeof(JVal));v->type=J_OBJECT;v->obj.keys=keys;v->obj.vals=vals;v->obj.n=0;return v;}
        while(1){
            skip_ws(p);
            if(p->pos>=p->len||p->src[p->pos]!='"'){for(int i=0;i<n;i++){free(keys[i]);jval_free(vals[i]);}free(keys);free(vals);return NULL;}
            char *k=parse_str(p);if(!k){for(int i=0;i<n;i++){free(keys[i]);jval_free(vals[i]);}free(keys);free(vals);return NULL;}
            skip_ws(p);
            if(p->pos>=p->len||p->src[p->pos]!=':'){free(k);for(int i=0;i<n;i++){free(keys[i]);jval_free(vals[i]);}free(keys);free(vals);return NULL;}
            p->pos++;
            JVal *val=parse_value(p);
            if(!val){free(k);for(int i=0;i<n;i++){free(keys[i]);jval_free(vals[i]);}free(keys);free(vals);return NULL;}
            if(n>=cap){cap*=2;keys=realloc(keys,cap*sizeof(char*));vals=realloc(vals,cap*sizeof(JVal*));}
            keys[n]=k;vals[n]=val;n++;
            skip_ws(p);
            if(p->pos>=p->len){for(int i=0;i<n;i++){free(keys[i]);jval_free(vals[i]);}free(keys);free(vals);return NULL;}
            if(p->src[p->pos]=='}'){p->pos++;break;}
            if(p->src[p->pos]!=','){for(int i=0;i<n;i++){free(keys[i]);jval_free(vals[i]);}free(keys);free(vals);return NULL;}
            p->pos++;
        }
        JVal*v=calloc(1,sizeof(JVal));v->type=J_OBJECT;v->obj.keys=keys;v->obj.vals=vals;v->obj.n=n;return v;
    }
    if(c=='['){
        p->pos++;
        int cap=8,n=0;JVal **items=malloc(cap*sizeof(JVal*));
        skip_ws(p);
        if(p->pos<p->len&&p->src[p->pos]==']'){p->pos++;JVal*v=calloc(1,sizeof(JVal));v->type=J_ARRAY;v->arr.items=items;v->arr.n=0;return v;}
        while(1){
            JVal *val=parse_value(p);
            if(!val){for(int i=0;i<n;i++)jval_free(items[i]);free(items);return NULL;}
            if(n>=cap){cap*=2;items=realloc(items,cap*sizeof(JVal*));}
            items[n++]=val;
            skip_ws(p);
            if(p->pos>=p->len){for(int i=0;i<n;i++)jval_free(items[i]);free(items);return NULL;}
            if(p->src[p->pos]==']'){p->pos++;break;}
            if(p->src[p->pos]!=','){for(int i=0;i<n;i++)jval_free(items[i]);free(items);return NULL;}
            p->pos++;
        }
        JVal*v=calloc(1,sizeof(JVal));v->type=J_ARRAY;v->arr.items=items;v->arr.n=n;return v;
    }
    if(c=='t'){if(p->pos+4<=p->len&&memcmp(p->src+p->pos,"true",4)==0){p->pos+=4;return mk_bool(1);}return NULL;}
    if(c=='f'){if(p->pos+5<=p->len&&memcmp(p->src+p->pos,"false",5)==0){p->pos+=5;return mk_bool(0);}return NULL;}
    if(c=='n'){if(p->pos+4<=p->len&&memcmp(p->src+p->pos,"null",4)==0){p->pos+=4;return mk_null();}return NULL;}
    if(c=='-'||(c>='0'&&c<='9'))return parse_number(p);
    return NULL;
}

static JVal *parse_json(const char *line){
    P p={line,0,(int)strlen(line)};
    skip_ws(&p);
    if(p.pos>=p.len)return NULL;
    JVal *v=parse_value(&p);
    if(!v)return NULL;
    skip_ws(&p);
    if(p.pos<p.len){jval_free(v);return NULL;}
    return v;
}

/* ==================== JSON Output ==================== */
static void out_str(FILE *f,const char *s){
    fputc('"',f);
    for(const char *p=s;*p;p++){
        unsigned char c=(unsigned char)*p;
        if(c=='"')fputs("\\\"",f);
        else if(c=='\\')fputs("\\\\",f);
        else if(c=='\n')fputs("\\n",f);
        else if(c=='\r')fputs("\\r",f);
        else if(c=='\t')fputs("\\t",f);
        else if(c=='\b')fputs("\\b",f);
        else if(c=='\f')fputs("\\f",f);
        else if(c<0x20){fprintf(f,"\\u%04x",c);}
        else fputc(c,f);
    }
    fputc('"',f);
}

static void out_id(FILE *f,JVal *id){
    if(!id||id->type==J_NULL){fputs("null",f);}
    else if(id->type==J_INT){fprintf(f,"%lld",id->i);}
    else if(id->type==J_STRING){out_str(f,id->s);}
    else{fputs("null",f);}
}

static void out_json(FILE *f,JVal *v);

static void out_json(FILE *f,JVal *v){
    if(!v){fputs("null",f);return;}
    switch(v->type){
        case J_NULL:fputs("null",f);break;
        case J_BOOL:fputs(v->b?"true":"false",f);break;
        case J_INT:fprintf(f,"%lld",v->i);break;
        case J_FLOAT:{
            double d=v->f;
            if(d==(long long)d&&fabs(d)<1e15)fprintf(f,"%lld",(long long)d);
            else fprintf(f,"%g",d);
            break;
        }
        case J_STRING:out_str(f,v->s);break;
        case J_ARRAY:
            fputc('[',f);
            for(int i=0;i<v->arr.n;i++){if(i)fputc(',',f);out_json(f,v->arr.items[i]);}
            fputc(']',f);break;
        case J_OBJECT:
            fputc('{',f);
            for(int i=0;i<v->obj.n;i++){if(i)fputc(',',f);out_str(f,v->obj.keys[i]);fputc(':',f);out_json(f,v->obj.vals[i]);}
            fputc('}',f);break;
    }
}

/* ==================== KV Store ==================== */
typedef struct KV{char *k;char *v;struct KV *next;}KV;
static KV *kv_head=NULL;

static void kv_set(const char *k,const char *v){
    for(KV *p=kv_head;p;p=p->next){
        if(strcmp(p->k,k)==0){free(p->v);p->v=strdup(v);return;}
    }
    KV *n=malloc(sizeof(KV));n->k=strdup(k);n->v=strdup(v);n->next=kv_head;kv_head=n;
}

static int kv_get(const char *k,char **out){
    for(KV *p=kv_head;p;p=p->next){if(strcmp(p->k,k)==0){*out=p->v;return 1;}}
    return 0;
}

static int kv_list(const char *prefix,char ***out_keys,int *out_n){
    int cap=16,n=0;char **keys=malloc(cap*sizeof(char*));
    int plen=prefix?(int)strlen(prefix):0;
    for(KV *p=kv_head;p;p=p->next){
        if(plen==0||strncmp(p->k,prefix,plen)==0){
            if(n>=cap){cap*=2;keys=realloc(keys,cap*sizeof(char*));}
            keys[n++]=p->k;
        }
    }
    /* sort by strcmp (valid UTF-8 byte order == code point order) */
    for(int i=0;i<n-1;i++)for(int j=0;j<n-1-i;j++){
        if(strcmp(keys[j],keys[j+1])>0){char *t=keys[j];keys[j]=keys[j+1];keys[j+1]=t;}
    }
    *out_keys=keys;*out_n=n;
}

/* ==================== Helpers ==================== */
static JVal *obj_get(JVal *obj,const char *key){
    if(!obj||obj->type!=J_OBJECT)return NULL;
    for(int i=0;i<obj->obj.n;i++)if(strcmp(obj->obj.keys[i],key)==0)return obj->obj.vals[i];
    return NULL;
}

static int obj_has(JVal *obj,const char *key){
    if(!obj||obj->type!=J_OBJECT)return 0;
    for(int i=0;i<obj->obj.n;i++)if(strcmp(obj->obj.keys[i],key)==0)return 1;
    return 0;
}

/* ==================== Tools ==================== */
static const char *tool_names[]={"kv_set","kv_get","kv_list","sum","text_stats"};

typedef struct{const char *name;int type; /* 0=string,1=array_int */int required;int minlen;int minitems;}PropInfo;

static PropInfo props_kv_set[]={{"key",0,1,1,0},{"value",0,1,0,0}};
static PropInfo props_kv_get[]={{"key",0,1,1,0}};
static PropInfo props_kv_list[]={{"prefix",0,0,0,0}};
static PropInfo props_sum[]={{"numbers",1,1,0,1}};
static PropInfo props_text_stats[]={{"text",0,1,0,0}};

typedef struct{const char *name;PropInfo *props;int nprops;int has_output_schema;}ToolDef;
static ToolDef tools[]={
    {"kv_set",props_kv_set,2,0},
    {"kv_get",props_kv_get,1,0},
    {"kv_list",props_kv_list,1,1},
    {"sum",props_sum,1,1},
    {"text_stats",props_text_stats,1,1},
};

static int find_tool(const char *name){
    for(int i=0;i<5;i++)if(strcmp(tools[i].name,name)==0)return i;
    return -1;
}

static int is_jint(JVal *v){return v&&v->type==J_INT;}

static char *validate_args(int ti,JVal *args){
    ToolDef *td=&tools[ti];
    const char *first_unknown=NULL;
    for(int i=0;i<args->obj.n;i++){
        int found=0;
        for(int j=0;j<td->nprops;j++){
            if(strcmp(args->obj.keys[i],td->props[j].name)==0){found=1;break;}
        }
        if(!found){
            if(!first_unknown||strcmp(args->obj.keys[i],first_unknown)<0)
                first_unknown=args->obj.keys[i];
        }
    }
    if(first_unknown){
        char *msg=malloc(256);sprintf(msg,"unknown argument: %s",first_unknown);return msg;
    }
    for(int j=0;j<td->nprops;j++){
        PropInfo *pi=&td->props[j];
        JVal *av=obj_get(args,pi->name);
        if(!av){
            if(pi->required){
                char *msg=malloc(256);sprintf(msg,"missing required argument: %s",pi->name);return msg;
            }
            continue;
        }
        if(pi->type==0){
            if(av->type!=J_STRING){
                char *msg=malloc(256);sprintf(msg,"argument %s must be a string",pi->name);return msg;
            }
            if(pi->minlen&&(int)strlen(av->s)==0){
                char *msg=malloc(256);sprintf(msg,"argument %s must not be empty",pi->name);return msg;
            }
        }else if(pi->type==1){
            if(av->type!=J_ARRAY){
                char *msg=malloc(256);sprintf(msg,"argument %s must be an array of integers",pi->name);return msg;
            }
            if(pi->minitems&&av->arr.n==0){
                char *msg=malloc(256);sprintf(msg,"argument %s must not be empty",pi->name);return msg;
            }
            for(int k=0;k<av->arr.n;k++){
                if(av->arr.items[k]->type!=J_INT){
                    char *msg=malloc(256);sprintf(msg,"argument %s must be an array of integers",pi->name);return msg;
                }
            }
        }
    }
    return NULL;
}

/* ==================== Message Processing ==================== */
static int initialized=0;

static void process_line(FILE *f,const char *line){
    int empty=1;
    for(const char *p=line;*p;p++){
        if(*p!=' '&&*p!='\t'&&*p!='\r'&&*p!='\n'){empty=0;break;}
    }
    if(empty)return;

    JVal *msg=parse_json(line);
    if(!msg){
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":null,\"error\":{\"code\":-32700,\"message\":\"Parse error\"}}\n");
        return;
    }
    if(msg->type!=J_OBJECT){
        jval_free(msg);
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":null,\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}\n");
        return;
    }
    /* Rule 3: response from client */
    if(!obj_has(msg,"method")&&(obj_has(msg,"result")||obj_has(msg,"error"))){
        jval_free(msg);return;
    }
    /* Rule 4: invalid request checks */
    JVal *jrpc=obj_get(msg,"jsonrpc");
    JVal *method=obj_get(msg,"method");
    JVal *id=obj_get(msg,"id");
    int has_id=obj_has(msg,"id");

    int invalid=0;
    if(!jrpc||jrpc->type!=J_STRING||strcmp(jrpc->s,"2.0")!=0)invalid=1;
    if(!method||method->type!=J_STRING)invalid=1;
    if(has_id){
        if(!(id->type==J_STRING||id->type==J_INT))invalid=1;
    }
    if(invalid){
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");
        if(has_id&&(id->type==J_STRING||id->type==J_INT))out_id(f,id);
        else fputs("null",f);
        fprintf(f,",\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}\n");
        jval_free(msg);return;
    }
    /* Rule 5: notification */
    if(!has_id){jval_free(msg);return;}

    /* Rule 6: request */
    const char *m=method->s;

    /* 6a: method not found */
    if(strcmp(m,"initialize")!=0&&strcmp(m,"ping")!=0&&strcmp(m,"tools/list")!=0&&strcmp(m,"tools/call")!=0){
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
        fprintf(f,",\"error\":{\"code\":-32601,\"message\":\"Method not found\"}}\n");
        jval_free(msg);return;
    }
    /* 6b: params present but not object */
    JVal *params=obj_get(msg,"params");
    if(params&&params->type!=J_OBJECT){
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
        fprintf(f,",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}\n");
        jval_free(msg);return;
    }
    /* 6c: not initialized */
    if(!initialized&&strcmp(m,"initialize")!=0&&strcmp(m,"ping")!=0){
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
        fprintf(f,",\"error\":{\"code\":-32002,\"message\":\"Server not initialized\"}}\n");
        jval_free(msg);return;
    }

    /* 6d: dispatch */
    if(strcmp(m,"initialize")==0){
        if(initialized){
            fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
            fprintf(f,",\"error\":{\"code\":-32600,\"message\":\"Already initialized\"}}\n");
            jval_free(msg);return;
        }
        if(!params||!obj_has(params,"protocolVersion")){
            fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
            fprintf(f,",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}\n");
            jval_free(msg);return;
        }
        JVal *pv=obj_get(params,"protocolVersion");
        if(pv->type!=J_STRING){
            fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
            fprintf(f,",\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}\n");
            jval_free(msg);return;
        }
        const char *ver=pv->s;
        const char *out_ver="2025-06-18";
        if(strcmp(ver,"2025-06-18")==0||strcmp(ver,"2025-03-26")==0||strcmp(ver,"2024-11-05")==0)
            out_ver=ver;
        initialized=1;
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
        fprintf(f,",\"result\":{\"protocolVersion\":");out_str(f,out_ver);
        fprintf(f,",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}\n");
        jval_free(msg);return;
    }
    if(strcmp(m,"ping")==0){
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
        fprintf(f,",\"result\":{}}\n");
        jval_free(msg);return;
    }
    if(strcmp(m,"tools/list")==0){
        fprintf(f,"{\"jsonrpc\":\"2.0\",\"id\":");out_id(f,id);
        fprintf(f,",\"result\":{\"tools\":[");
        fprintf(f,"{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}}");
