    // ---- Main processing ----
    static String processLine(String line){
        // Rule 1: parse JSON
        JVal msg;
        try{
            JP p=new JP(line);
            msg=p.parse();
        }catch(Exception e){
            return respError(JVal.ofNull(),-32700,"Parse error");
        }
        // Rule 2: must be object
        if(msg.type!=5){
            return respError(JVal.ofNull(),-32600,"Invalid Request");
        }
        // Rule 3: response from client (has result or error, no method)
        JVal methodVal=getMember(msg,"method");
        JVal resultVal=getMember(msg,"result");
        JVal errorVal=getMember(msg,"error");
        if(methodVal==null&&(resultVal!=null||errorVal!=null)){
            return null; // ignore
        }
        // Rule 4: invalid request checks
        JVal jsonrpcVal=getMember(msg,"jsonrpc");
        JVal idVal=getMember(msg,"id");
        boolean hasId=msg.obj.containsKey("id");

        boolean badReq=false;
        if(jsonrpcVal==null||jsonrpcVal.type!=2||!jsonrpcVal.sval.equals("2.0"))badReq=true;
        else if(methodVal==null||methodVal.type!=2)badReq=true;
        else if(hasId&&!isValidId(idVal))badReq=true;

        if(badReq){
            return respError(idForOutput(hasId?idVal:null),-32600,"Invalid Request");
        }
        // Rule 5: notification (no id member)
        if(!hasId){
            return null;
        }
        // Rule 6: request
        JVal outId=idVal; // valid id, echo exactly
        String method=methodVal.sval;

        // 6a: method not found
        if(!method.equals("initialize")&&!method.equals("ping")&&!method.equals("tools/list")&&!method.equals("tools/call")){
            return respError(outId,-32601,"Method not found");
        }
        // 6b: params present but not object
        JVal params=getMember(msg,"params");
        boolean hasParams=msg.obj.containsKey("params");
        if(hasParams&&(params==null||params.type!=5)){
            return respError(outId,-32602,"Invalid params");
        }
        // 6c: not initialized
        if(!initialized&&!method.equals("initialize")&&!method.equals("ping")){
            return respError(outId,-32002,"Server not initialized");
        }
        // 6d: dispatch
        switch(method){
            case "initialize":{
                if(initialized)return respError(outId,-32600,"Already initialized");
                if(!hasParams||params==null||params.type!=5)return respError(outId,-32602,"Invalid params");
                JVal pv=getMember(params,"protocolVersion");
                if(pv==null||pv.type!=2)return respError(outId,-32602,"Invalid params");
                String ver=pv.sval;
                String outVer;
                if(ver.equals("2025-06-18")||ver.equals("2025-03-26")||ver.equals("2024-11-05"))outVer=ver;
                else outVer="2025-06-18";
                initialized=true;
                LinkedHashMap<String,JVal> res=new LinkedHashMap<>();
                res.put("protocolVersion",JVal.ofStr(outVer));
                LinkedHashMap<String,JVal> caps=new LinkedHashMap<>();
                LinkedHashMap<String,JVal> toolsCap=new LinkedHashMap<>();
                toolsCap.put("listChanged",JVal.ofBool(false));
                caps.put("tools",JVal.ofObj(toolsCap));
                res.put("capabilities",JVal.ofObj(caps));
                LinkedHashMap<String,JVal> si=new LinkedHashMap<>();
                si.put("name",JVal.ofStr("cb2-kv"));si.put("title",JVal.ofStr("CB2 key-value server"));si.put("version",JVal.ofStr("1.4.2"));
                res.put("serverInfo",JVal.ofObj(si));
                return respResult(outId,JVal.ofObj(res));
            }
            case "ping":{
                return respResult(outId,JVal.ofObj(new LinkedHashMap<>()));
            }
            case "tools/list":{
                return respResult(outId,buildToolsList());
            }
            case "tools/call":{
                if(!hasParams||params==null||params.type!=5)return respError(outId,-32602,"Invalid params");
                JVal nameVal=getMember(params,"name");
                if(nameVal==null||nameVal.type!=2)return respError(outId,-32602,"Invalid params");
                String tName=nameVal.sval;
                boolean found=false;
                for(String tn:TOOL_NAMES)if(tn.equals(tName)){found=true;break;}
                if(!found)return respError(outId,-32602,"Unknown tool: "+tName);
                JVal arguments=getMember(params,"arguments");
                boolean hasArgs=params.obj.containsKey("arguments");
                // validate
                String err=validateArgs(tName,hasArgs?arguments:null);
                if(err!=null){
                    return respResult(outId,makeToolResult(err,true,null));
                }
                JVal toolRes=execTool(tName,hasArgs?arguments:null);
                return respResult(outId,toolRes);
            }
        }
        return null;
    }

    public static void main(String[] args)throws Exception{
        BufferedReader reader=new BufferedReader(new InputStreamReader(System.in,"UTF-8"));
        PrintWriter writer=new PrintWriter(new OutputStreamWriter(System.out,"UTF-8"));
        String line;
