    // ---- Tool argument validation ----
    static String validateArgs(String toolName, JVal args){
        if(args!=null&&args.type!=5) return "arguments must be an object";
        LinkedHashMap<String,JVal> aMap=(args==null)?new LinkedHashMap<>():args.obj;

        List<String> propOrder;
        Set<String> propSet;
        List<String> reqList;
        Map<String,String> propType=new LinkedHashMap<>();
        Map<String,Integer> propMinLen=new HashMap<>();
        Map<String,Integer> propMinItems=new HashMap<>();

        switch(toolName){
            case "kv_set":
                propOrder=Arrays.asList("key","value");propSet=new HashSet<>(propOrder);
                reqList=Arrays.asList("key","value");
                propType.put("key","string");propMinLen.put("key",1);
                propType.put("value","string");
                break;
            case "kv_get":
                propOrder=Arrays.asList("key");propSet=new HashSet<>(propOrder);
                reqList=Arrays.asList("key");
                propType.put("key","string");propMinLen.put("key",1);
                break;
            case "kv_list":
                propOrder=Arrays.asList("prefix");propSet=new HashSet<>(propOrder);
                reqList=Collections.emptyList();
                propType.put("prefix","string");
                break;
            case "sum":
                propOrder=Arrays.asList("numbers");propSet=new HashSet<>(propOrder);
                reqList=Arrays.asList("numbers");
                propType.put("numbers","array_int");propMinItems.put("numbers",1);
                break;
            case "text_stats":
                propOrder=Arrays.asList("text");propSet=new HashSet<>(propOrder);
                reqList=Arrays.asList("text");
                propType.put("text","string");
                break;
            default:return null;
        }

        List<String> unknown=new ArrayList<>();
        for(String k:aMap.keySet()){
            if(!propSet.contains(k))unknown.add(k);
        }
        if(!unknown.isEmpty()){
            unknown.sort(Main::cmpCP);
            return "unknown argument: "+unknown.get(0);
        }

        for(String p:propOrder){
            JVal v=aMap.get(p);
            boolean present=(v!=null);
            if(!present){
                if(reqList.contains(p))return "missing required argument: "+p;
                continue;
            }
            String pt=propType.get(p);
            if(pt.equals("string")){
                if(v.type!=2)return "argument "+p+" must be a string";
                if(propMinLen.containsKey(p)&&v.sval.length()<propMinLen.get(p))return "argument "+p+" must not be empty";
            } else if(pt.equals("array_int")){
                if(v.type!=4)return "argument "+p+" must be an array of integers";
                for(JVal el:v.arr){
                    if(el.type!=3||!el.isInt)return "argument "+p+" must be an array of integers";
                }
                if(propMinItems.containsKey(p)&&v.arr.size()<propMinItems.get(p))return "argument "+p+" must not be empty";
            }
        }
        return null;
    }

    // ---- Tool execution ----
    static JVal execTool(String toolName, JVal args){
        LinkedHashMap<String,JVal> aMap=(args==null||args.type!=5)?new LinkedHashMap<>():args.obj;

        switch(toolName){
            case "kv_set":{
                String key=aMap.get("key").sval;
                String val=aMap.get("value").sval;
                boolean existed=store.containsKey(key);
                store.put(key,val);
                String text=existed?"updated "+key:"created "+key;
                return makeToolResult(text,false,null);
            }
            case "kv_get":{
                String key=aMap.get("key").sval;
                if(!store.containsKey(key)){
                    return makeToolResult("key not found: "+key,true,null);
                }
                return makeToolResult(store.get(key),false,null);
            }
            case "kv_list":{
                JVal pv=aMap.get("prefix");
                String prefix=(pv!=null&&pv.type==2)?pv.sval:"";
                List<String> keys=new ArrayList<>();
                for(String k:store.keySet()){
                    if(k.startsWith(prefix))keys.add(k);
                }
                keys.sort(Main::cmpCP);
                LinkedHashMap<String,JVal> sc=new LinkedHashMap<>();
                ArrayList<JVal> kArr=new ArrayList<>();
                for(String k:keys)kArr.add(JVal.ofStr(k));
                sc.put("keys",JVal.ofArr(kArr));
                sc.put("count",JVal.ofInt(keys.size()));
                return makeToolResult(toJson(JVal.ofObj(sc)),false,JVal.ofObj(sc));
            }
            case "sum":{
                JVal nv=aMap.get("numbers");
                long sum=0;
                for(JVal el:nv.arr){sum+=el.lval;}
                LinkedHashMap<String,JVal> sc=new LinkedHashMap<>();
                sc.put("sum",JVal.ofInt(sum));
                sc.put("count",JVal.ofInt(nv.arr.size()));
                return makeToolResult(toJson(JVal.ofObj(sc)),false,JVal.ofObj(sc));
            }
            case "text_stats":{
                String text=aMap.get("text").sval;
                int words=0;boolean inWord=false;
                int i=0;
                while(i<text.length()){
                    int cp=text.codePointAt(i);
                    boolean sep=(cp==0x20||cp==0x09||cp==0x0A||cp==0x0D);
                    if(!sep&&!inWord){words++;inWord=true;}
                    else if(sep)inWord=false;
                    i+=Character.charCount(cp);
                }
                int cpts=text.codePointCount(0,text.length());
                int utf8=text.getBytes(StandardCharsets.UTF_8).length;
                LinkedHashMap<String,JVal> sc=new LinkedHashMap<>();
                sc.put("words",JVal.ofInt(words));
                sc.put("codepoints",JVal.ofInt(cpts));
                sc.put("utf8_bytes",JVal.ofInt(utf8));
                return makeToolResult(toJson(JVal.ofObj(sc)),false,JVal.ofObj(sc));
            }
        }
        return null;
    }

    static JVal makeToolResult(String text,boolean isError,JVal structured){
        LinkedHashMap<String,JVal> r=new LinkedHashMap<>();
        LinkedHashMap<String,JVal> cb=new LinkedHashMap<>();
        cb.put("type",JVal.ofStr("text"));cb.put("text",JVal.ofStr(text));
        r.put("content",JVal.ofArr(new ArrayList<>(Arrays.asList(JVal.ofObj(cb)))));
        if(structured!=null)r.put("structuredContent",structured);
        r.put("isError",JVal.ofBool(isError));
        return JVal.ofObj(r);
    }

    // ---- Response builders ----
    static String respError(JVal id,int code,String msg){
        LinkedHashMap<String,JVal> r=new LinkedHashMap<>();
        r.put("jsonrpc",JVal.ofStr("2.0"));
        r.put("id",id);
        LinkedHashMap<String,JVal> err=new LinkedHashMap<>();
        err.put("code",JVal.ofInt(code));err.put("message",JVal.ofStr(msg));
        r.put("error",JVal.ofObj(err));
        return toJson(JVal.ofObj(r));
    }
    static String respResult(JVal id,JVal result){
        LinkedHashMap<String,JVal> r=new LinkedHashMap<>();
        r.put("jsonrpc",JVal.ofStr("2.0"));
        r.put("id",id);
        r.put("result",result);
        return toJson(JVal.ofObj(r));
    }

    // ---- Main processing ----
    static String processLine(String line){
        JVal msg;
        try{
            JP p=new JP(line);
            msg=p.parse();
        }catch(Exception e){
            return respError(JVal.ofNull(),-32700,"Parse error");
        }
        if(msg.type!=5){
            return respError(JVal.ofNull(),-32600,"Invalid Request");
        }
        JVal methodVal=getMember(msg,"method");
        JVal resultVal=getMember(msg,"result");
        JVal errorVal=getMember(msg,"error");
        if(methodVal==null&&(resultVal!=null||errorVal!=null)){
            return null;
        }
        JVal jsonrpcVal=getMember(msg,"jsonrpc");
        JVal idVal=getMember(msg,"id");
        boolean hasId=msg.obj.containsKey("id");

        boolean badReq=false;
        if(jsonrpcVal==null||jsonrpcVal.type!=2||!jsonrpcVal.sval.equals("2.0"))badReq=true;
        else if(methodVal==null||methodVal.type!=2)badReq=true;
        else if(hasId&&!isValidId(idVal))badReq=true;

        if(badReq){
            return respError(idForOutput(hasId?idVal:null),-32600,"Invalid Request");
        }
