fn format_ipv6(bytes: &[u8]) -> String {
    let groups: Vec<u16> = (0..8)
        .map(|i| u16::from_be_bytes([bytes[i * 2], bytes[i * 2 + 1]]))
        .collect();

    let mut best_start = usize::MAX;
    let mut best_len = 0usize;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let start = i;
            while i < 8 && groups[i] == 0 {
                i += 1;
            }
            let len = i - start;
            if len >= 2 && len > best_len {
                best_start = start;
                best_len = len;
            }
        } else {
            i += 1;
        }
    }

    if best_len >= 2 {
        let left: Vec<String> = groups[..best_start]
            .iter()
            .map(|g| format!("{:x}", g))
            .collect();
        let right: Vec<String> = groups[best_start + best_len..]
            .iter()
            .map(|g| format!("{:x}", g))
            .collect();
        format!("{}::{}", left.join(":"), right.join(":"))
    } else {
        groups
            .iter()
            .map(|g| format!("{:x}", g))
            .collect::<Vec<_>>()
            .join(":")
    }
}

fn format_txt(msg: &[u8], offset: usize, length: usize) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut pos = offset;
    let end = offset + length;

    while pos < end {
        let mut slen = msg[pos] as usize;
        pos += 1;
        if pos + slen > end {
            slen = end - pos;
        }
        let s = &msg[pos..pos + slen];
        pos += slen;

        let mut quoted = String::from("\"");
        for &b in s {
            match b {
                b'"' => quoted.push_str("\\\""),
                b'\\' => quoted.push_str("\\\\"),
                0x20..=0x7E => quoted.push(b as char),
                _ => quoted.push_str(&format!("\\{:03}", b)),
            }
        }
        quoted.push('"');
        parts.push(quoted);
    }

    parts.join(" ")
}

