        let rdlength = u16::from_be_bytes([msg[next + 6], msg[next + 7]]) as usize;
        let rdata_offset = next + 8;
        pos = rdata_offset + rdlength;

        let data_str = match rtype {
            1 => format!(
                "{}.{}.{}.{}",
                msg[rdata_offset],
                msg[rdata_offset + 1],
                msg[rdata_offset + 2],
                msg[rdata_offset + 3]
            ),
            28 => format_ipv6(&msg[rdata_offset..rdata_offset + 16]),
            5 => {
                let (target, _) = parse_name(msg, rdata_offset);
                target
            }
            15 => {
                let pref = u16::from_be_bytes([msg[rdata_offset], msg[rdata_offset + 1]]);
                let (exchange, _) = parse_name(msg, rdata_offset + 2);
                format!("{} {}", pref, exchange)
            }
            16 => format_txt(msg, rdata_offset, rdlength),
            _ => {
                if rdlength == 0 {
                    "\\# 0".to_string()
                } else {
                    let hex: String = msg[rdata_offset..rdata_offset + rdlength]
                        .iter()
                        .map(|b| format!("{:02x}", b))
                        .collect();
                    format!("\\# {} {}", rdlength, hex)
                }
            }
        };

        let tl = match type_name(rtype) {
            Some(s) => s.to_string(),
            None => format!("TYPE{}", rtype),
        };

        println!("  {} {} {} {}", owner, ttl, tl, data_str);
    }
