        1 => "FORMERR".to_string(),
        2 => "SERVFAIL".to_string(),
        3 => "NXDOMAIN".to_string(),
        4 => "NOTIMP".to_string(),
        5 => "REFUSED".to_string(),
        _ => format!("RCODE{}", code),
    }
}

fn type_name(t: u16) -> Option<&'static str> {
    match t {
        1 => Some("A"),
        5 => Some("CNAME"),
        15 => Some("MX"),
        16 => Some("TXT"),
        28 => Some("AAAA"),
        _ => None,
    }
}

fn print_response(name: &str, qtype_str: &str, msg: &[u8]) {
    let flags = u16::from_be_bytes([msg[2], msg[3]]);
    let rcode = flags & 0x0F;

    let display_name = {
        let n = name.trim_end_matches('.').to_lowercase();
        if n.is_empty() {
            ".".to_string()
        } else {
            n
        }
    };

    println!("{} {} {}", display_name, qtype_str, rcode_str(rcode));

    let qdcount = u16::from_be_bytes([msg[4], msg[5]]) as usize;
    let ancount = u16::from_be_bytes([msg[6], msg[7]]) as usize;

    let mut pos = 12;
    for _ in 0..qdcount {
        let (_, next) = parse_name(msg, pos);
        pos = next + 4; // skip QTYPE(2) + QCLASS(2)
    }

    for _ in 0..ancount {
        let (owner, next) = parse_name(msg, pos);
        // RR layout: TYPE(2) + CLASS(2) + TTL(4) + RDLENGTH(2) + RDATA
        let rtype = u16::from_be_bytes([msg[next], msg[next + 1]]);
        // CLASS at next+2, next+3 (skip)
        let ttl = u32::from_be_bytes([msg[next + 4], msg[next + 5], msg[next + 6], msg[next + 7]]);
        let rdlength = u16::from_be_bytes([msg[next + 8], msg[next + 9]]) as usize;
        let rdata_offset = next + 10;
        pos = rdata_offset + rdlength;

        let data_str = match rtype {
            1 => format!(
                "{}.{}.{}.{}",
                msg[rdata_offset],
                msg[rdata_offset + 1],
                msg[rdata_offset + 2],
                msg[rdata_offset + 3]
            ),
            28 => format_ipv6(&msg[rdata_offset..rdata_offset + 16]),
            5 => {
                let (target, _) = parse_name(msg, rdata_offset);
                target
            }
            15 => {
                let pref = u16::from_be_bytes([msg[rdata_offset], msg[rdata_offset + 1]]);
                let (exchange, _) = parse_name(msg, rdata_offset + 2);
                format!("{} {}", pref, exchange)
            }
            16 => format_txt(msg, rdata_offset, rdlength),
            _ => {
                if rdlength == 0 {
                    "\\# 0".to_string()
                } else {
                    let hex: String = msg[rdata_offset..rdata_offset + rdlength]
                        .iter()
                        .map(|b| format!("{:02x}", b))
                        .collect();
                    format!("\\# {} {}", rdlength, hex)
                }
            }
        };

        let tl = match type_name(rtype) {
            Some(s) => s.to_string(),
            None => format!("TYPE{}", rtype),
        };

        println!("  {} {} {} {}", owner, ttl, tl, data_str);
    }
}
