func handleInitialize(id: Any, params: [String: Any]?) -> String {
    if serverInitialized {
        return makeError(id: id, code: -32600, message: "Already initialized")
    }
    guard let p = params,
          p.keys.contains("protocolVersion"),
          isJSONString(p["protocolVersion"]!) else {
        return makeError(id: id, code: -32602, message: "Invalid params")
    }
    let clientVersion = p["protocolVersion"] as! String
    let supported: Set<String> = ["2025-06-18", "2025-03-26", "2024-11-05"]
    let version = supported.contains(clientVersion) ? clientVersion : "2025-06-18"
    serverInitialized = true
    let result: [String: Any] = [
        "protocolVersion": version,
        "capabilities": ["tools": ["listChanged": false]],
        "serverInfo": ["name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"]
    ]
    return makeResponse(id: id, result: result)
}

func handleToolsCall(id: Any, params: [String: Any]?) -> String {
    guard let p = params,
          p.keys.contains("name"),
          isJSONString(p["name"]!) else {
        return makeError(id: id, code: -32602, message: "Invalid params")
    }
    let name = p["name"] as! String
    guard let toolDef = toolDefs[name] else {
        return makeError(id: id, code: -32602, message: "Unknown tool: \(name)")
    }

    var arguments: [String: Any] = [:]
    if p.keys.contains("arguments") {
        let args = p["arguments"]!
        if !isJSONObject(args) {
            return makeResponse(id: id, result: toolFailure(message: "arguments must be an object"))
        }
        arguments = args as! [String: Any]
    }

    // Check unknown arguments
    let knownProps = Set(toolDef.propOrder)
    let unknownArgs = arguments.keys.filter { !knownProps.contains($0) }
    if !unknownArgs.isEmpty {
        let smallest = unknownArgs.min(by: cpLess)!
        return makeResponse(id: id, result: toolFailure(message: "unknown argument: \(smallest)"))
    }

    // Validate required and types in property order
    for propName in toolDef.propOrder {
        if !arguments.keys.contains(propName) {
            if toolDef.required.contains(propName) {
                return makeResponse(id: id, result: toolFailure(message: "missing required argument: \(propName)"))
            }
            continue
        }
        let value = arguments[propName]!
        let type = toolDef.propTypes[propName]!

        if type == "string" {
            if !isJSONString(value) {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must be a string"))
            }
            if toolDef.minLength[propName] == 1 && (value as! String).isEmpty {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must not be empty"))
            }
        } else if type == "array_int" {
            if !isJSONArray(value) {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must be an array of integers"))
            }
            let arr = value as! [Any]
            for elem in arr {
                if !isJSONInteger(elem) {
                    return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must be an array of integers"))
                }
            }
            if toolDef.minItems[propName] == 1 && arr.isEmpty {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must not be empty"))
            }
        }
    }

    let result = executeTool(name: name, args: arguments)
    return makeResponse(id: id, result: result)
}

// ============ Line Processing ============
func processLine(_ rawLine: String) -> String? {
    var line = rawLine
    if line.hasSuffix("\r") {
        line = String(line.dropLast())
    }

    // Ignore empty/whitespace-only lines
    if line.allSatisfy({ $0 == " " || $0 == "\t" || $0 == "\r" }) {
        return nil
    }

    // Rule 1: Parse JSON
    guard let data = line.data(using: .utf8),
          let parsed = try? JSONSerialization.jsonObject(with: data, options: [.allowFragments]) else {
        return makeError(id: NSNull(), code: -32700, message: "Parse error")
    }

    // Rule 2: Must be an object
    guard let obj = parsed as? [String: Any] else {
        return makeError(id: NSNull(), code: -32600, message: "Invalid Request")
    }

    // Rule 3: Client response (no method, has result or error)
    if !obj.keys.contains("method") && (obj.keys.contains("result") || obj.keys.contains("error")) {
        return nil
    }

    // Rule 4: Invalid request checks
    let jsonrpcOk: Bool
    if let j = obj["jsonrpc"], isJSONString(j), (j as! String) == "2.0" {
        jsonrpcOk = true
    } else {
        jsonrpcOk = false
    }

    let methodOk: Bool
    if let m = obj["method"], isJSONString(m) {
        methodOk = true
    } else {
        methodOk = false
    }

    let hasId = obj.keys.contains("id")
    var idValid = false
    var idForResponse: Any = NSNull()

    if hasId {
        let idObj = obj["id"]!
        if isJSONString(idObj) {
            idValid = true
            idForResponse = idObj
        } else if isJSONInteger(idObj) {
            idValid = true
            idForResponse = (idObj as! NSNumber).int64Value
        } else {
            idValid = false
            idForResponse = NSNull()
        }
    }

    if !jsonrpcOk || !methodOk || (hasId && !idValid) {
        return makeError(id: idForResponse, code: -32600, message: "Invalid Request")
    }

    // Rule 5: Notification (valid, no id)
    if !hasId {
        return nil
    }

    // Rule 6: Request
    let method = obj["method"] as! String
    let id = idForResponse

    // 6a: Method not found
    let validMethods: Set<String> = ["initialize", "ping", "tools/list", "tools/call"]
    if !validMethods.contains(method) {
        return makeError(id: id, code: -32601, message: "Method not found")
    }

    // 6b: params present but not an object
    var params: [String: Any]? = nil
    if obj.keys.contains("params") {
        let p = obj["params"]!
        if !isJSONObject(p) {
            return makeError(id: id, code: -32602, message: "Invalid params")
        }
        params = p as? [String: Any]
    }

    // 6c: Server not initialized check
    if !serverInitialized && method != "initialize" && method != "ping" {
        return makeError(id: id, code: -32002, message: "Server not initialized")
    }

    // 6d: Dispatch
    switch method {
    case "initialize":
        return handleInitialize(id: id, params: params)
    case "ping":
        return makeResponse(id: id, result: [:] as [String: Any])
    case "tools/list":
        return makeResponse(id: id, result: toolsListResult())
    case "tools/call":
        return handleToolsCall(id: id, params: params)
    default:
        return makeError(id: id, code: -32601, message: "Method not found")
    }
}

// ============ Main ============
var outputLines: [String] = []
while let line = readLine() {
    if let resp = processLine(line) {
        outputLines.append(resp)
    }
}
for line in outputLines {
    print(line)
}
