Looking at the failing test case, the issue is with `id: 0`. In Swift, `NSNumber(value: 0) is Bool` returns `true` due to Foundation's bridging behavior (0 is treated as `false`). This causes my `isJSONInteger` function to incorrectly return `false` for integer id `0`.

The fix is to use `CFGetTypeID` to check for boolean instead of the Swift `is Bool` check:

```swift
import Foundation

// ============ Global State ============
var serverInitialized = false
var kvStore: [String: String] = [:]

// ============ JSON Type Helpers ============
func isJSONString(_ v: Any) -> Bool {
    return CFGetTypeID(v as CFTypeRef) == CFStringGetTypeID()
}

func isJSONBool(_ v: Any) -> Bool {
    return CFGetTypeID(v as CFTypeRef) == CFBooleanGetTypeID()
}

func isJSONInteger(_ v: Any) -> Bool {
    let cf = v as CFTypeRef
    let tid = CFGetTypeID(cf)
    if tid == CFBooleanGetTypeID() { return false }
    if tid == CFNumberGetTypeID() {
        return !CFNumberIsFloatType(cf as! CFNumber)
    }
    return false
}

func isJSONNull(_ v: Any) -> Bool {
    return CFGetTypeID(v as CFTypeRef) == CFNullGetTypeID()
}

func isJSONObject(_ v: Any) -> Bool {
    return CFGetTypeID(v as CFTypeRef) == CFDictionaryGetTypeID()
}

func isJSONArray(_ v: Any) -> Bool {
    return CFGetTypeID(v as CFTypeRef) == CFArrayGetTypeID()
}

// ============ JSON Serialization ============
func jsonStr(_ obj: Any) -> String {
    let data = try! JSONSerialization.data(withJSONObject: obj, options: [])
    return String(data: data, encoding: .utf8)!
}

// ============ Response Builders ============
func makeResponse(id: Any, result: Any) -> String {
    return jsonStr(["jsonrpc": "2.0", "id": id, "result": result])
}

func makeError(id: Any, code: Int, message: String) -> String {
    return jsonStr(["jsonrpc": "2.0", "id": id, "error": ["code": code, "message": message]])
}

// ============ Code Point Comparison ============
func cpLess(_ a: String, _ b: String) -> Bool {
    let ua = Array(a.unicodeScalars)
    let ub = Array(b.unicodeScalars)
    return ua.lexicographicallyPrecedes(ub)
}

// ============ Tool Definitions ============
struct ToolDef {
    let name: String
    let propOrder: [String]
    let propTypes: [String: String]
    let required: [String]
    let minLength: [String: Int]
    let minItems: [String: Int]
    let hasOutputSchema: Bool
}

let toolDefs: [String: ToolDef] = [
    "kv_set": ToolDef(
        name: "kv_set",
        propOrder: ["key", "value"],
        propTypes: ["key": "string", "value": "string"],
        required: ["key", "value"],
        minLength: ["key": 1],
        minItems: [:],
        hasOutputSchema: false
    ),
    "kv_get": ToolDef(
        name: "kv_get",
        propOrder: ["key"],
        propTypes: ["key": "string"],
        required: ["key"],
        minLength: ["key": 1],
        minItems: [:],
        hasOutputSchema: false
    ),
    "kv_list": ToolDef(
        name: "kv_list",
        propOrder: ["prefix"],
        propTypes: ["prefix": "string"],
        required: [],
        minLength: [:],
        minItems: [:],
        hasOutputSchema: true
    ),
    "sum": ToolDef(
        name: "sum",
        propOrder: ["numbers"],
        propTypes: ["numbers": "array_int"],
        required: ["numbers"],
        minLength: [:],
        minItems: ["numbers": 1],
        hasOutputSchema: true
    ),
    "text_stats": ToolDef(
        name: "text_stats",
        propOrder: ["text"],
        propTypes: ["text": "string"],
        required: ["text"],
        minLength: [:],
        minItems: [:],
        hasOutputSchema: true
    ),
]

// ============ Tool Result Helpers ============
func toolSuccess(text: String) -> [String: Any] {
    return ["content": [["type": "text", "text": text]], "isError": false]
}

func toolSuccessStructured(structured: [String: Any]) -> [String: Any] {
    let text = jsonStr(structured)
    return ["content": [["type": "text", "text": text]], "structuredContent": structured, "isError": false]
}

func toolFailure(message: String) -> [String: Any] {
    return ["content": [["type": "text", "text": message]], "isError": true]
}

// ============ Word Counting ============
func countWords(_ text: String) -> Int {
    var count = 0
    var inWord = false
    for c in text.unicodeScalars {
        if c == " " || c == "\t" || c == "\n" || c == "\r" {
            inWord = false
        } else {
            if !inWord {
                count += 1
                inWord = true
            }
        }
    }
    return count
}

// ============ Tool Execution ============
func executeTool(name: String, args: [String: Any]) -> [String: Any] {
    switch name {
    case "kv_set":
        let key = args["key"] as! String
        let value = args["value"] as! String
        let existed = kvStore.keys.contains(key)
        kvStore[key] = value
        let text = existed ? "updated \(key)" : "created \(key)"
        return toolSuccess(text: text)
    case "kv_get":
        let key = args["key"] as! String
        if let value = kvStore[key] {
            return toolSuccess(text: value)
        } else {
            return toolFailure(message: "key not found: \(key)")
        }
    case "kv_list":
        let prefix = (args["prefix"] as? String) ?? ""
        let matchingKeys = kvStore.keys.filter { $0.hasPrefix(prefix) }
        let sortedKeys = matchingKeys.sorted(by: cpLess)
        let structured: [String: Any] = ["keys": sortedKeys, "count": sortedKeys.count]
        return toolSuccessStructured(structured: structured)
    case "sum":
        let numbers = args["numbers"] as! [Any]
        var total: Int64 = 0
        for n in numbers {
            total += (n as! NSNumber).int64Value
        }
        let structured: [String: Any] = ["sum": total, "count": numbers.count]
        return toolSuccessStructured(structured: structured)
    case "text_stats":
        let text = args["text"] as! String
        let words = countWords(text)
        let codepoints = text.unicodeScalars.count
        let utf8Bytes = text.utf8.count
        let structured: [String: Any] = ["words": words, "codepoints": codepoints, "utf8_bytes": utf8Bytes]
        return toolSuccessStructured(structured: structured)
    default:
        return toolFailure(message: "Unknown tool")
    }
}

// ============ Tools List ============
func toolsListResult() -> [String: Any] {
    let tools: [[String: Any]] = [
        [
            "name": "kv_set",
            "title": "Set a value",
            "description": "Store a string value under a key, replacing any previous value.",
            "inputSchema": [
                "type": "object",
                "properties": [
                    "key": ["type": "string", "minLength": 1],
                    "value": ["type": "string"]
                ],
                "required": ["key", "value"],
                "additionalProperties": false
            ]
        ],
        [
            "name": "kv_get",
            "title": "Get a value",
            "description": "Return the value stored under a key.",
            "inputSchema": [
                "type": "object",
                "properties": [
                    "key": ["type": "string", "minLength": 1]
                ],
                "required": ["key"],
                "additionalProperties": false
            ]
        ],
        [
            "name": "kv_list",
            "title": "List keys",
            "description": "List the stored keys that start with a prefix, sorted by Unicode code point.",
            "inputSchema": [
                "type": "object",
                "properties": [
                    "prefix": ["type": "string"]
                ],
                "additionalProperties": false
            ],
            "outputSchema": [
                "type": "object",
                "properties": [
                    "keys": ["type": "array", "items": ["type": "string"]],
                    "count": ["type": "integer"]
                ],
                "required": ["keys", "count"]
            ]
        ],
        [
            "name": "sum",
            "title": "Sum integers",
            "description": "Add up a non-empty list of integers.",
            "inputSchema": [
                "type": "object",
                "properties": [
                    "numbers": ["type": "array", "items": ["type": "integer"], "minItems": 1]
                ],
                "required": ["numbers"],
                "additionalProperties": false
            ],
            "outputSchema": [
                "type": "object",
                "properties": [
                    "sum": ["type": "integer"],
                    "count": ["type": "integer"]
                ],
                "required": ["sum", "count"]
            ],
            "annotations": ["readOnlyHint": true, "idempotentHint": true]
        ],
        [
            "name": "text_stats",
            "title": "Text statistics",
            "description": "Count the words, Unicode code points and UTF-8 bytes of a text.",
            "inputSchema": [
                "type": "object",
                "properties": [
                    "text": ["type": "string"]
                ],
                "required": ["text"],
                "additionalProperties": false
            ],
            "outputSchema": [
                "type": "object",
                "properties": [
                    "words": ["type": "integer"],
                    "codepoints": ["type": "integer"],
                    "utf8_bytes": ["type": "integer"]
                ],
                "required": ["words", "codepoints", "utf8_bytes"]
            ],
            "annotations": ["readOnlyHint": true]
        ]
    ]
    return ["tools": tools]
}

// ============ Method Handlers ============
func handleInitialize(id: Any, params: [String: Any]?) -> String {
    if serverInitialized {
        return makeError(id: id, code: -32600, message: "Already initialized")
    }
    guard let p = params,
          p.keys.contains("protocolVersion"),
          isJSONString(p["protocolVersion"]!) else {
        return makeError(id: id, code: -32602, message: "Invalid params")
    }
    let clientVersion = p["protocolVersion"] as! String
    let supported: Set<String> = ["2025-06-18", "2025-03-26", "2024-11-05"]
    let version = supported.contains(clientVersion) ? clientVersion : "2025-06-18"
    serverInitialized = true
    let result: [String: Any] = [
        "protocolVersion": version,
        "capabilities": ["tools": ["listChanged": false]],
        "serverInfo": ["name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"]
    ]
    return makeResponse(id: id, result: result)
}

func handleToolsCall(id: Any, params: [String: Any]?) -> String {
    guard let p = params,
          p.keys.contains("name"),
          isJSONString(p["name"]!) else {
        return makeError(id: id, code: -32602, message: "Invalid params")
    }
    let name = p["name"] as! String
    guard let toolDef = toolDefs[name] else {
        return makeError(id: id, code: -32602, message: "Unknown tool: \(name)")
    }

    var arguments: [String: Any] = [:]
    if p.keys.contains("arguments") {
        let args = p["arguments"]!
        if !isJSONObject(args) {
            return makeResponse(id: id, result: toolFailure(message: "arguments must be an object"))
        }
        arguments = args as! [String: Any]
    }

    // Check unknown arguments
    let knownProps = Set(toolDef.propOrder)
    let unknownArgs = arguments.keys.filter { !knownProps.contains($0) }
    if !unknownArgs.isEmpty {
        let smallest = unknownArgs.min(by: cpLess)!
        return makeResponse(id: id, result: toolFailure(message: "unknown argument: \(smallest)"))
    }

    // Validate required and types in property order
    for propName in toolDef.propOrder {
        if !arguments.keys.contains(propName) {
            if toolDef.required.contains(propName) {
                return makeResponse(id: id, result: toolFailure(message: "missing required argument: \(propName)"))
            }
            continue
        }
        let value = arguments[propName]!
        let type = toolDef.propTypes[propName]!

        if type == "string" {
            if !isJSONString(value) {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must be a string"))
            }
            if toolDef.minLength[propName] == 1 && (value as! String).isEmpty {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must not be empty"))
            }
        } else if type == "array_int" {
            if !isJSONArray(value) {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must be an array of integers"))
            }
            let arr = value as! [Any]
            for elem in arr {
                if !isJSONInteger(elem) {
                    return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must be an array of integers"))
                }
            }
            if toolDef.minItems[propName] == 1 && arr.isEmpty {
                return makeResponse(id: id, result: toolFailure(message: "argument \(propName) must not be empty"))
            }
        }
    }

    let result = executeTool(name: name, args: arguments)
    return makeResponse(id: id, result: result)
}

// ============ Line Processing ============
func processLine(_ rawLine: String) -> String? {
    var line = rawLine
    if line.hasSuffix("\r") {
        line = String(line.dropLast())
    }

    // Ignore empty/whitespace-only lines
    if line.allSatisfy({ $0 == " " || $0 == "\t" || $0 == "\r" }) {
        return nil
    }

    // Rule 1: Parse JSON
    guard let data = line.data(using: .utf8),
          let parsed = try? JSONSerialization.jsonObject(with: data, options: [.allowFragments]) else {
        return makeError(id: NSNull(), code: -32700, message: "Parse error")
    }

    // Rule 2: Must be an object
    guard let obj = parsed as? [String: Any] else {
        return makeError(id: NSNull(), code: -32600, message: "Invalid Request")
    }

    // Rule 3: Client response (no method, has result or error)
    if !obj.keys.contains("method") && (obj.keys.contains("result") || obj.keys.contains("error")) {
        return nil
    }

    // Rule 4: Invalid request checks
    let jsonrpcOk: Bool
    if let j = obj["jsonrpc"], isJSONString(j), (j as! String) == "2.0" {
        jsonrpcOk = true
    } else {
        jsonrpcOk = false
    }

    let methodOk: Bool
    if let m = obj["method"], isJSONString(m) {
        methodOk = true
    } else {
        methodOk = false
    }

    let hasId = obj.keys.contains("id")
    var idValid = false
    var idForResponse: Any = NSNull()

    if hasId {
        let idObj = obj["id"]!
        if isJSONString(idObj) {
            idValid = true
            idForResponse = idObj
        } else if isJSONInteger(idObj) {
            idValid = true
            idForResponse = (idObj as! NSNumber).int64Value
        } else {
            idValid = false
            idForResponse = NSNull()
        }
    }

    if !jsonrpcOk || !methodOk || (hasId && !idValid) {
        return makeError(id: idForResponse, code: -32600, message: "Invalid Request")
    }

    // Rule 5: Notification (valid, no id)
    if !hasId {
        return nil
    }

    // Rule 6: Request
    let method = obj["method"] as! String
    let id = idForResponse

    // 6a: Method not found
    let validMethods: Set<String> = ["initialize", "ping", "tools/list", "tools/call"]
    if !validMethods.contains(method) {
        return makeError(id: id, code: -32601, message: "Method not found")
    }

    // 6b: params present but not an object
    var params: [String: Any]? = nil
    if obj.keys.contains("params") {
        let p = obj["params"]!
        if !isJSONObject(p) {
            return makeError(id: id, code: -32602, message: "Invalid params")
        }
        params = p as? [String: Any]
    }

    // 6c: Server not initialized check
    if !serverInitialized && method != "initialize" && method != "ping" {
        return makeError(id: id, code: -32002, message: "Server not initialized")
    }

    // 6d: Dispatch
    switch method {
    case "initialize":
        return handleInitialize(id: id, params: params)
    case "ping":
        return makeResponse(id: id, result: [:] as [String: Any])
    case "tools/list":
        return makeResponse(id: id, result: toolsListResult())
    case "tools/call":
        return handleToolsCall(id: id, params: params)
    default:
        return makeError(id: id, code: -32601, message: "Method not found")
    }
}

// ============ Main ============
var outputLines: [String] = []
while let line = readLine() {
    if let resp = processLine(line) {
        outputLines.append(resp)
    }
}
for line in outputLines {
    print(line)
}
exit(0)
