        let a = Big { neg: self.neg, limbs: self.align(ts) };
        let b = Big { neg: o.neg, limbs: o.align(ts) };
        let r = a.add(&b);
        Dec { neg: r.neg, limbs: r.limbs, scale: ts }.norm()
    }

    fn mul(&self, o: &Dec) -> Dec {
        let a = Big { neg: false, limbs: self.limbs.clone() };
        let b = Big { neg: false, limbs: o.limbs.clone() };
        let r = a.mul(&b);
        Dec { neg: self.neg != o.neg, limbs: r.limbs, scale: self.scale + o.scale }.norm()
    }

    fn round_to(&self, ts: usize) -> Dec {
        if self.scale <= ts {
            return Dec { neg: self.neg, limbs: self.align(ts), scale: ts };
        }
        let excess = self.scale - ts;
