            }
        }
        Dec { neg: result.neg, limbs: result.limbs, scale: ts }.norm()
    }

    fn to_minor(&self, minor: usize) -> Big {
        let r = self.round_to(minor);
        Big { neg: r.neg, limbs: r.limbs }.normalize()
    }
}

fn fmt_money(val: &Big, minor: usize) -> String {
    if val.is_zero() {
        if minor == 0 { return "0".to_string(); }
        return format!("0.{}", "0".repeat(minor));
    }
    let sign = if val.neg { "-" } else { "" };
    let ds = val.to_dec_str();
    if minor == 0 {
        return format!("{}{}", sign, commas(&ds));
    }
    let padded = if ds.len() <= minor {
        format!("{}{}", "0".repeat(minor + 1 - ds.len()), ds)
    } else {
        ds.clone()
    };
    let ip = &padded[..padded.len() - minor];
    let fp = &padded[padded.len() - minor..];
    format!("{}{}.{}", sign, commas(ip), fp)
}

fn commas(s: &str) -> String {
    let mut r = String::new();
    let len = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 { r.push(','); }
        r.push(c);
    }
    r
}

fn big_div(a: &Big, b: &Big) -> (Big, Big) {
    if b.is_zero() { panic!("div0"); }
    if a.is_zero() { return (Big::zero(), Big::zero()); }
    let a_s = a.to_dec_str();
    let b_s = b.to_dec_str();
    dec_long_div(&a_s, &b_s)
}

fn dec_long_div(a: &str, b: &str) -> (String, String) {
    let bd: Vec<u8> = b.bytes().map(|c| c - b'0').collect();
    let mut q: Vec<u8> = Vec::new();
    let mut rem: Vec<u8> = Vec::new();
    for &ch in a.bytes() {
        rem.push(ch - b'0');
        while rem.len() > 1 && rem[0] == 0 { rem.remove(0); }
        if rem.len() == 1 && rem[0] == 0 {
            q.push(b'0');
            continue;
        }
        let mut cnt: u8 = 0;
        while cmp_darr(&rem, &bd) != Ordering::Less {
            rem = sub_darr(&rem, &bd);
            cnt += 1;
        }
        q.push(b'0' + cnt);
    }
    while q.len() > 1 && q[0] == b'0' { q.remove(0); }
    if q.is_empty() { q.push(b'0'); }
    while rem.len() > 1 && rem[0] == 0 { rem.remove(0); }
    if rem.is_empty() { rem.push(b'0'); }
    (String::from_utf8(q).unwrap(), String::from_utf8(rem).unwrap())
}

fn cmp_darr(a: &[u8], b: &[u8]) -> Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in 0..a.len() { if a[i] != b[i] { return a[i].cmp(&b[i]); } }
    Ordering::Equal
}

fn sub_darr(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut r = vec![0u8; a.len()];
    let mut borrow: i32 = 0;
    for i in (0..a.len()).rev() {
        let av = a[i] as i32;
        let bv = if i < b.len() { b[i] as i32 } else { 0 };
        let d = av - bv - borrow;
        if d < 0 { r[i] = (d + 10) as u8; borrow = 1; }
        else { r[i] = d as u8; borrow = 0; }
    }
    while r.len() > 1 && r[0] == 0 { r.remove(0); }
    r
}

