    }
    while q.len() > 1 && q[0] == b'0' { q.remove(0); }
    if q.is_empty() { q.push(b'0'); }
    while rem.len() > 1 && rem[0] == 0 { rem.remove(0); }
    if rem.is_empty() { rem.push(b'0'); }
    (String::from_utf8(q).unwrap(), String::from_utf8(rem).unwrap())
}

fn cmp_darr(a: &[u8], b: &[u8]) -> Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in 0..a.len() { if a[i] != b[i] { return a[i].cmp(&b[i]); } }
    Ordering::Equal
}

fn sub_darr(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut r = vec![0u8; a.len()];
    let mut borrow: i32 = 0;
    for i in (0..a.len()).rev() {
        let av = a[i] as i32;
        let bv = if i < b.len() { b[i] as i32 } else { 0 };
        let d = av - bv - borrow;
        if d < 0 { r[i] = (d + 10) as u8; borrow = 1; }
        else { r[i] = d as u8; borrow = 0; }
    }
    while r.len() > 1 && r[0] == 0 { r.remove(0); }
    r
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();
    let lines: Vec<&str> = content.lines().collect();

    let mut curr: BTreeMap<String, usize> = BTreeMap::new();
    let mut accts: BTreeMap<String, (String, Big, Big)> = BTreeMap::new();
    let mut rejects: Vec<(usize, String)> = vec![];

    for (idx, line) in lines.iter().enumerate() {
        let ln = idx + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let f: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = f[0];

        match cmd {
            "currency" => {
                curr.insert(f[1].to_string(), f[2].parse::<usize>().unwrap());
            }
