    while r.len() > 1 && r[0] == 0 { r.remove(0); }
    r
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();
    let lines: Vec<&str> = content.lines().collect();

    let mut curr: BTreeMap<String, usize> = BTreeMap::new();
    let mut accts: BTreeMap<String, (String, Big, Big)> = BTreeMap::new();
    let mut rejects: Vec<(usize, String)> = vec![];

    for (idx, line) in lines.iter().enumerate() {
        let ln = idx + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let f: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = f[0];

        match cmd {
            "currency" => {
                curr.insert(f[1].to_string(), f[2].parse::<usize>().unwrap());
            }
            "open" => {
                let name = f[1].to_string();
                let code = f[2].to_string();
                if accts.contains_key(&name) {
                    rejects.push((ln, format!("account exists {}", name)));
                    continue;
                }
                let minor = curr[&code];
                let limit = if f.len() > 3 {
                    Dec::parse(f[3]).to_minor(minor)
                } else {
                    Big::zero()
                };
                accts.insert(name, (code, Big::zero(), limit));
            }
            "deposit" => {
                let name = f[1].to_string();
                if !accts.contains_key(&name) {
                    rejects.push((ln, format!("unknown account {}", name)));
                    continue;
                }
                let code = accts[&name].0.clone();
                let minor = curr[&code];
                let amt = Dec::parse(f[2]).to_minor(minor);
                if amt.is_zero() || amt.neg {
                    rejects.push((ln, "non-positive amount".to_string()));
                    continue;
                }
                let new_bal = accts[&name].1.add(&amt);
                accts.get_mut(&name).unwrap().1 = new_bal;
            }
            "withdraw" => {
                let name = f[1].to_string();
                if !accts.contains_key(&name) {
                    rejects.push((ln, format!("unknown account {}", name)));
                    continue;
                }
                let code = accts[&name].0.clone();
                let minor = curr[&code];
                let amt = Dec::parse(f[2]).to_minor(minor);
                if amt.is_zero() || amt.neg {
                    rejects.push((ln, "non-positive amount".to_string()));
                    continue;
                }
                let bal = accts[&name].1.clone();
                let limit = accts[&name].2.clone();
                let new_bal = bal.sub(&amt);
                let neg_limit = limit.neg();
                if new_bal.cmp(&neg_limit) == Ordering::Less {
                    rejects.push((ln, format!("insufficient funds {}", name)));
                    continue;
                }
                accts.get_mut(&name).unwrap().1 = new_bal;
            }
            "transfer" => {
                let from = f[1].to_string();
                let to = f[2].to_string();
                if !accts.contains_key(&from) {
                    rejects.push((ln, format!("unknown account {}", from)));
                    continue;
                }
                if !accts.contains_key(&to) {
                    rejects.push((ln, format!("unknown account {}", to)));
                    continue;
                }
                let cf = accts[&from].0.clone();
                let ct = accts[&to].0.clone();
                if cf != ct {
                    rejects.push((ln, "currency mismatch".to_string()));
                    continue;
                }
                let minor = curr[&cf];
                let amt = Dec::parse(f[3]).to_minor(minor);
                if amt.is_zero() || amt.neg {
                    rejects.push((ln, "non-positive amount".to_string()));
                    continue;
                }
                let bal = accts[&from].1.clone();
                let limit = accts[&from].2.clone();
                let new_bal = bal.sub(&amt);
                let neg_limit = limit.neg();
                if new_bal.cmp(&neg_limit) == Ordering::Less {
                    rejects.push((ln, format!("insufficient funds {}", from)));
                    continue;
                }
                accts.get_mut(&from).unwrap().1 = new_bal;
                let new_to = accts[&to].1.add(&amt);
                accts.get_mut(&to).unwrap().1 = new_to;
            }
            "convert" => {
                let from = f[1].to_string();
                let to = f[2].to_string();
                if !accts.contains_key(&from) {
                    rejects.push((ln, format!("unknown account {}", from)));
                    continue;
                }
                if !accts.contains_key(&to) {
                    rejects.push((ln, format!("unknown account {}", to)));
                    continue;
                }
                let cf = accts[&from].0.clone();
                let ct = accts[&to].0.clone();
                let minor_f = curr[&cf];
                let minor_t = curr[&ct];
                let amt = Dec::parse(f[3]).to_minor(minor_f);
                if amt.is_zero() || amt.neg {
                    rejects.push((ln, "non-positive amount".to_string()));
                    continue;
                }
                let bal = accts[&from].1.clone();
                let limit = accts[&from].2.clone();
                let new_bal = bal.sub(&amt);
                let neg_limit = limit.neg();
                if new_bal.cmp(&neg_limit) == Ordering::Less {
                    rejects.push((ln, format!("insufficient funds {}", from)));
                    continue;
                }
                accts.get_mut(&from).unwrap().1 = new_bal;
                let amt_dec = Dec { neg: false, limbs: amt.limbs.clone(), scale: minor_f };
                let rate = Dec::parse(f[4]);
                let product = amt_dec.mul(&rate);
                let received = product.to_minor(minor_t);
                let new_to = accts[&to].1.add(&received);
                accts.get_mut(&to).unwrap().1 = new_to;
            }
            "interest" => {
                let name = f[1].to_string();
                if !accts.contains_key(&name) {
                    rejects.push((ln, format!("unknown account {}", name)));
                    continue;
                }
                let code = accts[&name].0.clone();
                let minor = curr[&code];
                let rate = Dec::parse(f[2]);
                let bal = &accts[&name].1;
                let bal_dec = Dec { neg: bal.neg, limbs: bal.limbs.clone(), scale: minor };
                let interest = bal_dec.mul(&rate);
                let interest_minor = interest.to_minor(minor);
                let new_bal = accts[&name].1.add(&interest_minor);
                accts.get_mut(&name).unwrap().1 = new_bal;
            }
            "split" => {
                let from = f[1].to_string();
                let mut targets: Vec<(String, Big)> = vec![];
                for i in 3..f.len() {
                    let colon = f[i].find(':').unwrap();
                    let tname = f[i][..colon].to_string();
                    let w = Big::from_dec_str(&f[i][colon + 1..]);
                    targets.push((tname, w));
                }
                // Check unknown accounts in order of appearance
                let mut rejected = false;
                if !accts.contains_key(&from) {
                    rejects.push((ln, format!("unknown account {}", from)));
                    rejected = true;
                }
                if !rejected {
                    for (tn, _) in &targets {
                        if !accts.contains_key(tn) {
                            rejects.push((ln, format!("unknown account {}", tn)));
                            rejected = true;
                            break;
                        }
                    }
                }
                if rejected { continue; }
                // Currency mismatch
                let cf = accts[&from].0.clone();
                let mut mismatch = false;
                for (tn, _) in &targets {
                    if accts[tn].0 != cf { mismatch = true; break; }
                }
                if mismatch {
                    rejects.push((ln, "currency mismatch".to_string()));
                    continue;
                }
                let minor = curr[&cf];
                let amt = Dec::parse(f[2]).to_minor(minor);
                if amt.is_zero() || amt.neg {
                    rejects.push((ln, "non-positive amount".to_string()));
                    continue;
                }
                let bal = accts[&from].1.clone();
                let limit = accts[&from].2.clone();
                let new_bal = bal.sub(&amt);
                let neg_limit = limit.neg();
                if new_bal.cmp(&neg_limit) == Ordering::Less {
                    rejects.push((ln, format!("insufficient funds {}", from)));
                    continue;
                }
                accts.get_mut(&from).unwrap().1 = new_bal;
                // Distribute
                let mut w_sum = Big::zero();
                for (_, w) in &targets { w_sum = w_sum.add(w); }
                let mut bases: Vec<Big> = vec![];
                let mut rems: Vec<Big> = vec![];
                for (_, w) in &targets {
                    let prod = amt.mul(w);
                    let (q, r) = big_div(&prod, &w_sum);
                    bases.push(q);
                    rems.push(r);
                }
                let total_base: Big = bases.iter().fold(Big::zero(), |acc, b| acc.add(b));
                let leftover = amt.sub(&total_base);
                let n = targets.len();
                let mut indices: Vec<usize> = (0..n).collect();
                indices.sort_by(|&a, &b| {
                    let c = rems[b].cmp_abs(&rems[a]);
                    if c != Ordering::Equal { c } else { a.cmp(&b) }
                });
                let lo: usize = leftover.to_dec_str().parse().unwrap();
                for &idx in &indices[..lo] {
                    bases[idx] = bases[idx].add(&Big::from_u64(1));
                }
                for (i, (tn, _)) in targets.iter().enumerate() {
                    let new_tb = accts[tn].1.add(&bases[i]);
                    accts.get_mut(tn).unwrap().1 = new_tb;
                }
            }
            _ => {}
        }
    }

    // Output rejections
    for (n, reason) in &rejects {
        println!("line {}: REJECT {}", n, reason);
    }
    println!();
    // Output accounts
    for (name, (code, bal, _)) in &accts {
        let minor = curr[code];
        println!("{} {} {}", name, code, fmt_money(bal, minor));
    }
    println!();
    // Output totals
    let mut totals: BTreeMap<String, (Big, usize)> = BTreeMap::new();
    for (_, (code, bal, _)) in &accts {
        let e = totals.entry(code.clone()).or_insert((Big::zero(), 0));
        e.0 = e.0.add(bal);
        e.1 += 1;
    }
    for (code, (sum, cnt)) in &totals {
        let minor = curr[code];
        println!("total {} {} ({} accounts)", code, fmt_money(sum, minor), cnt);
    }
}
