        if c == "n" { pos += 4; return .null }
        if c == "t" { pos += 4; return .bool(true) }
        if c == "f" { pos += 5; return .bool(false) }
        if c == "\"" { return .string(parseString()) }
        if c == "[" { return parseArray() }
        if c == "{" { return parseObject() }
        return parseNumber()
    }

    func parseString() -> String {
        pos += 1
        var result = ""
        while pos < chars.count && chars[pos] != "\"" {
            if chars[pos] == "\\" {
                pos += 1
                let e = chars[pos]
                switch e {
                case "\"": result.append("\""); pos += 1
                case "\\": result.append("\\"); pos += 1
                case "/": result.append("/"); pos += 1
                case "b": result.append("\u{08}"); pos += 1
                case "f": result.append("\u{0C}"); pos += 1
                case "n": result.append("\n"); pos += 1
                case "r": result.append("\r"); pos += 1
                case "t": result.append("\t"); pos += 1
                case "u":
                    pos += 1
                    let cp = parseHex4()
                    if cp >= 0xD800 && cp <= 0xDBFF {
                        pos += 1 // backslash
                        pos += 1 // u
                        let lo = parseHex4()
                        let combined = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
                        result.append(Character(UnicodeScalar(combined)!))
                    } else {
                        result.append(Character(UnicodeScalar(cp)!))
                    }
                default: result.append(e); pos += 1
                }
            } else {
                result.append(chars[pos]); pos += 1
            }
        }
        pos += 1
        return result
    }

    func parseHex4() -> UInt32 {
        var v: UInt32 = 0
        for _ in 0..<4 {
            let c = chars[pos]
            v <<= 4
            if c >= "0" && c <= "9" { v |= UInt32(c.asciiValue! - 48) }
            else if c >= "a" && c <= "f" { v |= UInt32(c.asciiValue! - 87) }
            else { v |= UInt32(c.asciiValue! - 55) }
            pos += 1
        }
        return v
    }

    func parseNumber() -> JSONValue {
        let start = pos
