// MARK: - JSON Pointer helpers

func ptrEscape(_ token: String) -> String {
    var r = ""
    for c in token {
        if c == "~" { r += "~0" }
        else if c == "/" { r += "~1" }
        else { r.append(c) }
    }
    return r
}

func ptrUnescape(_ token: String) -> String {
    var r = ""
    let cs = Array(token)
    var i = 0
    while i < cs.count {
        if cs[i] == "~" && i + 1 < cs.count {
            if cs[i+1] == "0" { r.append("~"); i += 2 }
            else if cs[i+1] == "1" { r.append("/"); i += 2 }
            else { r.append(cs[i]); i += 1 }
        } else { r.append(cs[i]); i += 1 }
    }
    return r
}

// MARK: - Type helpers

func typeName(_ v: JSONValue) -> String {
    switch v {
    case .null: return "null"
    case .bool: return "boolean"
    case .number: return "number"
    case .string: return "string"
    case .array: return "array"
    case .object: return "object"
    }
}

func matchesType(_ v: JSONValue, _ t: String) -> Bool {
    switch t {
    case "null": return typeName(v) == "null"
    case "boolean": return typeName(v) == "boolean"
    case "number": return typeName(v) == "number"
    case "integer":
        if case .number(let d) = v { return d == d.rounded() }
        return false
    case "string": return typeName(v) == "string"
    case "array": return typeName(v) == "array"
    case "object": return typeName(v) == "object"
    default: return true
    }
}

// MARK: - Deep equality

func deepEqual(_ a: JSONValue, _ b: JSONValue) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.number(let x), .number(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.array(let x), .array(let y)):
        if x.count != y.count { return false }
        for i in 0..<x.count { if !deepEqual(x[i], y[i]) { return false } }
        return true
    case (.object(let x), .object(let y)):
        if x.count != y.count { return false }
        for (k, v) in x { guard let w = y[k] else { return false }; if !deepEqual(v, w) { return false } }
