func resolveRef(_ ref: String, _ root: JSONValue) -> (JSONValue, String) {
    if ref == "#" { return (root, "#") }
    let body = String(ref.dropFirst(2)) // remove "#/"
    var tokens: [String] = []
    var cur = ""
    for c in body {
        if c == "/" { tokens.append(cur); cur = "" }
        else { cur.append(c) }
    }
    tokens.append(cur)
    var current = root
    var path = "#"
    for tok in tokens {
