    if case .number(let n) = inst {
        if case .number(let v) = obj["minimum"] { if !(n >= v) { errs.insert(ValidationError(ip: ip, sp: sp + "/minimum")) } }
        if case .number(let v) = obj["maximum"] { if !(n <= v) { errs.insert(ValidationError(ip: ip, sp: sp + "/maximum")) } }
        if case .number(let v) = obj["exclusiveMinimum"] { if !(n > v) { errs.insert(ValidationError(ip: ip, sp: sp + "/exclusiveMinimum")) } }
        if case .number(let v) = obj["exclusiveMaximum"] { if !(n < v) { errs.insert(ValidationError(ip: ip, sp: sp + "/exclusiveMaximum")) } }
