        if case .number(let v) = obj["minItems"] { if !(cnt >= v) { errs.insert(ValidationError(ip: ip, sp: sp + "/minItems")) } }
        if case .number(let v) = obj["maxItems"] { if !(cnt <= v) { errs.insert(ValidationError(ip: ip, sp: sp + "/maxItems")) } }

        if case .bool(let u) = obj["uniqueItems"], u {
            var dup = false
            for i in 0..<arr.count {
                if dup { break }
                for j in (i+1)..<arr.count {
                    if deepEqual(arr[i], arr[j]) { dup = true; break }
                }
            }
            if dup { errs.insert(ValidationError(ip: ip, sp: sp + "/uniqueItems")) }
        }

        // prefixItems
        var pfxLen = 0
        if case .array(let pfx) = obj["prefixItems"] {
            pfxLen = pfx.count
            for i in 0..<min(arr.count, pfx.count) {
                errs.formUnion(validate(arr[i], pfx[i], ip: ip + "/" + String(i), sp: sp + "/prefixItems/" + String(i), root: root))
            }
        }

        // items
        if let isv = obj["items"] {
            for i in pfxLen..<arr.count {
                errs.formUnion(validate(arr[i], isv, ip: ip + "/" + String(i), sp: sp + "/items", root: root))
            }
        }
    }

    // Object assertions
    if case .object(let io) = inst {
        var propKeys: Set<String> = []
        if case .object(let props) = obj["properties"] {
            propKeys = Set(props.keys)
            for (k, ps) in props {
                if let mv = io[k] {
                    errs.formUnion(validate(mv, ps, ip: ip + "/" + ptrEscape(k), sp: sp + "/properties/" + ptrEscape(k), root: root))
                }
            }
        }

        if case .array(let reqs) = obj["required"] {
            for (j, rv) in reqs.enumerated() {
                if case .string(let name) = rv {
                    if io[name] == nil {
                        errs.insert(ValidationError(ip: ip, sp: sp + "/required/" + String(j)))
                    }
                }
            }
        }

        if let aps = obj["additionalProperties"] {
            for (k, v) in io {
                if !propKeys.contains(k) {
                    errs.formUnion(validate(v, aps, ip: ip + "/" + ptrEscape(k), sp: sp + "/additionalProperties", root: root))
                }
            }
        }

        let mcnt = Double(io.count)
        if case .number(let v) = obj["minProperties"] { if !(mcnt >= v) { errs.insert(ValidationError(ip: ip, sp: sp + "/minProperties")) } }
        if case .number(let v) = obj["maxProperties"] { if !(mcnt <= v) { errs.insert(ValidationError(ip: ip, sp: sp + "/maxProperties")) } }
    }

    // allOf
    if case .array(let subs) = obj["allOf"] {
        for (i, s) in subs.enumerated() {
            errs.formUnion(validate(inst, s, ip: ip, sp: sp + "/allOf/" + String(i), root: root))
        }
    }

    // anyOf
    if case .array(let subs) = obj["anyOf"] {
        var any = false
        for s in subs {
            if validate(inst, s, ip: ip, sp: sp + "/anyOf", root: root).isEmpty { any = true; break }
        }
        if !any { errs.insert(ValidationError(ip: ip, sp: sp + "/anyOf")) }
    }

    // oneOf
    if case .array(let subs) = obj["oneOf"] {
        var cnt = 0
        for s in subs {
            if validate(inst, s, ip: ip, sp: sp + "/oneOf", root: root).isEmpty { cnt += 1 }
        }
        if cnt != 1 { errs.insert(ValidationError(ip: ip, sp: sp + "/oneOf")) }
    }

    // not
    if let ns = obj["not"] {
        if validate(inst, ns, ip: ip, sp: sp + "/not", root: root).isEmpty {
            errs.insert(ValidationError(ip: ip, sp: sp + "/not"))
        }
    }

    // if/then/else
    if let ifS = obj["if"] {
        let ifErrs = validate(inst, ifS, ip: ip, sp: sp + "/if", root: root)
        if ifErrs.isEmpty {
            if let thenS = obj["then"] {
