    static Object eval(Expr e,Scope sc){
        if(e instanceof EInt)return((EInt)e).v;
        if(e instanceof EStr)return((EStr)e).v;
        if(e instanceof EBool)return((EBool)e).v;
        if(e instanceof ENil)return NIL;
        if(e instanceof EIdent){
            String n=((EIdent)e).name;
            if(!sc.has(n))throw new TErr(e.ln,"undefined variable "+n);
            return sc.lookup(n);
        }
        if(e instanceof EBin)return evalBin((EBin)e,sc);
        if(e instanceof EUn){
            EUn u=(EUn)e;
            if(u.op.equals("not")){Object v=eval(u.e,sc);return!truthy(v);}
