    }

    static Object callBuiltin(TernFn f,List<Object>args,int ln){
        int need=f.arity;
        if(need>=0&&args.size()!=need)throw new TErr(ln,"expected "+need+" arguments, got "+args.size());
        switch(f.bname){
            case"print":{
                for(int i=0;i<args.size();i++){
                    if(i>0)emit(" ");
                    emit(display(args.get(i),new HashSet<>()));
