                if(!(v instanceof ArrayList))throw new TErr(ln,"bad argument to push");
                ((ArrayList<Object>)v).add(args.get(1));return NIL;
            }
            case"pop":{
                Object v=args.get(0);
                if(!(v instanceof ArrayList))throw new TErr(ln,"bad argument to pop");
