                    if(lo<0||hi>lst.size()||lo>hi)throw new TErr(ln,"bad argument to slice");
                    return new ArrayList<Object>(lst.subList((int)lo,(int)hi));
                }
                throw new TErr(ln,"bad argument to slice");
            }
        }
        return NIL;
    }

    static void execBlock(List<Stmt>body,Scope sc){
        for(Stmt s:body)execStmt(s,sc);
    }

    static void execStmt(Stmt s,Scope sc){
        if(s instanceof SLet){
            SLet st=(SLet)s;Object v=eval(st.val,sc);sc.vars.put(st.name,v);return;
        }
        if(s instanceof SFn){
            SFn st=(SFn)s;TernFn fn=new TernFn(st.params,st.body,sc);sc.vars.put(st.name,fn);return;
        }
        if(s instanceof SIf){
            SIf st=(SIf)s;
            if(truthy(eval(st.cond,sc))){execBlock(st.thenB,new Scope(sc));}
            else if(st.elseB!=null){execBlock(st.elseB,new Scope(sc));}
            else if(st.elseIf!=null){execStmt(st.elseIf,sc);}
            return;
        }
        if(s instanceof SWhile){
            SWhile st=(SWhile)s;
            while(truthy(eval(st.cond,sc))){
                try{execBlock(st.body,new Scope(sc));}
                catch(Brk br){break;}catch(Cnt cn){continue;}
            }
            return;
        }
        if(s instanceof SFor){
            SFor st=(SFor)s;
            Object iter=eval(st.iter,sc);
            if(!(iter instanceof ArrayList))throw new TErr(st.ln,"cannot iterate "+typeName(iter));
            ArrayList<Object>lst=(ArrayList<Object>)iter;
            int i=0;
            while(i<lst.size()){
                Scope isc=new Scope(sc);
                isc.vars.put(st.var,lst.get(i));
                try{execBlock(st.body,isc);}
                catch(Brk br){break;}catch(Cnt cn){/* fall through */}
                i++;
            }
            return;
        }
        if(s instanceof SReturn){
            SReturn st=(SReturn)s;
            throw new Ret(st.val!=null?eval(st.val,sc):NIL);
        }
        if(s instanceof SBreak)throw new Brk();
        if(s instanceof SCont)throw new Cnt();
        if(s instanceof SAssign){
            SAssign st=(SAssign)s;Object v=eval(st.val,sc);
            if(!sc.has(st.name))throw new TErr(st.ln,"undefined variable "+st.name);
            sc.set(st.name,v);return;
        }
        if(s instanceof SIdxAssign){
            SIdxAssign st=(SIdxAssign)s;
            Object obj=eval(st.obj,sc);
            Object idx=eval(st.idx,sc);
            Object val=eval(st.val,sc);
            if(!(obj instanceof ArrayList)){
                throw new TErr(st.ln,"cannot assign into "+typeName(obj));
            }
            if(!(idx instanceof Long)){
                throw new TErr(st.ln,"cannot index list with "+typeName(idx));
            }
            long i=(Long)idx;ArrayList<Object>lst=(ArrayList<Object>)obj;
            if(i<0||i>=lst.size())throw new TErr(st.ln,"index "+i+" out of range for length "+lst.size());
            lst.set((int)i,val);return;
        }
        if(s instanceof SExpr){eval(((SExpr)s).e,sc);return;}
    }

    static Scope makeGlobals(){
        Scope b=new Scope(null);
        b.vars.put("print",new TernFn("print",-1));
        b.vars.put("str",new TernFn("str",1));
        b.vars.put("type",new TernFn("type",1));
        b.vars.put("len",new TernFn("len",1));
        b.vars.put("push",new TernFn("push",2));
        b.vars.put("pop",new TernFn("pop",1));
        b.vars.put("range",new TernFn("range",2));
        b.vars.put("slice",new TernFn("slice",3));
        return b;
    }

