    static class EFn implements Expr{List<String>params;List<Stmt>body;int ln;EFn(List<String>p,List<Stmt>b,int l){params=p;body=b;ln=l;}}
    static class ECall implements Expr{Expr callee;List<Expr>args;int ln;ECall(Expr c,List<Expr>a,int l){callee=c;args=a;ln=l;}}
    static class EIdx implements Expr{Expr obj;Expr idx;int ln;EIdx(Expr o,Expr i,int l){obj=o;idx=i;ln=l;}}

    static class Scope{
        HashMap<String,Object>vars;Scope parent;
        Scope(Scope p){vars=new HashMap<>();parent=p;}
        Object lookup(String n){Scope s=this;while(s!=null){if(s.vars.containsKey(n))return s.vars.get(n);s=s.parent;}return null;}
        boolean has(String n){Scope s=this;while(s!=null){if(s.vars.containsKey(n))return true;s=s.parent;}return false;}
        void set(String n,Object v){Scope s=this;while(s!=null){if(s.vars.containsKey(n)){s.vars.put(n,v);return;}s=s.parent;}}
    }

    static class TernFn{
        List<String>params;List<Stmt>body;Scope captured;
        String bname;int arity;
        TernFn(List<String>p,List<Stmt>b,Scope c){params=p;body=b;captured=c;bname=null;arity=-2;}
        TernFn(String bn,int ar){bname=bn;arity=ar;}
    }

    static class Brk extends RuntimeException{}
    static class Cnt extends RuntimeException{}
    static class Ret extends RuntimeException{Object v;Ret(Object v){this.v=v;}}
    static class TErr extends RuntimeException{int ln;String msg;TErr(int l,String m){ln=l;msg=m;}}

    // Lexer
    static List<Tok> lex(String src){
        List<Tok> toks=new ArrayList<>();int pos=0,line=1,len=src.length();
        while(pos<len){
            char c=src.charAt(pos);
            if(c=='\n'){line++;pos++;continue;}
            if(c==' '||c=='\t'||c=='\r'){pos++;continue;}
            if(c=='#'){while(pos<len&&src.charAt(pos)!='\n')pos++;continue;}
            if(c>='0'&&c<='9'){
                int st=pos;while(pos<len&&src.charAt(pos)>='0'&&src.charAt(pos)<='9')pos++;
                toks.add(new Tok(T_INT,src.substring(st,pos),Long.parseLong(src.substring(st,pos)),line));continue;
            }
            if(c=='"'){
                pos++;StringBuilder sb=new StringBuilder();
                while(pos<len&&src.charAt(pos)!='"'){
                    if(src.charAt(pos)=='\\'){pos++;char e=src.charAt(pos);
                        if(e=='n')sb.append('\n');else if(e=='t')sb.append('\t');
                        else if(e=='"')sb.append('"');else sb.append('\\');
                    }else sb.append(src.charAt(pos));pos++;
                }pos++;
                toks.add(new Tok(T_STR,sb.toString(),0,line));continue;
            }
            if(Character.isLetter(c)||c=='_'){
                int st=pos;while(pos<len&&(Character.isLetterOrDigit(src.charAt(pos))||src.charAt(pos)=='_'))pos++;
                String w=src.substring(st,pos);
                toks.add(new Tok(KWS.contains(w)?T_KW:T_ID,w,0,line));continue;
            }
            if(pos+1<len){
                String two=src.substring(pos,pos+2);
                if(two.equals("==")){toks.add(new Tok(T_EQ,"==",0,line));pos+=2;continue;}
                if(two.equals("!=")){toks.add(new Tok(T_NEQ,"!=",0,line));pos+=2;continue;}
                if(two.equals("<=")){toks.add(new Tok(T_LE,"<=",0,line));pos+=2;continue;}
                if(two.equals(">=")){toks.add(new Tok(T_GE,">=",0,line));pos+=2;continue;}
            }
            switch(c){
                case'<':toks.add(new Tok(T_LT,"<",0,line));pos++;break;
                case'>':toks.add(new Tok(T_GT,">",0,line));pos++;break;
                case'=':toks.add(new Tok(T_ASSIGN,"=",0,line));pos++;break;
                case'+':toks.add(new Tok(T_PLUS,"+",0,line));pos++;break;
                case'-':toks.add(new Tok(T_MINUS,"-",0,line));pos++;break;
                case'*':toks.add(new Tok(T_STAR,"*",0,line));pos++;break;
                case'/':toks.add(new Tok(T_SLASH,"/",0,line));pos++;break;
                case'%':toks.add(new Tok(T_PCT,"%",0,line));pos++;break;
                case'(':toks.add(new Tok(T_LP,"(",0,line));pos++;break;
                case')':toks.add(new Tok(T_RP,")",0,line));pos++;break;
                case'[':toks.add(new Tok(T_LB,"[",0,line));pos++;break;
                case']':toks.add(new Tok(T_RB,"]",0,line));pos++;break;
                case'{':toks.add(new Tok(T_LC,"{",0,line));pos++;break;
                case'}':toks.add(new Tok(T_RC,"}",0,line));pos++;break;
                case',':toks.add(new Tok(T_COMMA,",",0,line));pos++;break;
                case';':toks.add(new Tok(T_SEMI,";",0,line));pos++;break;
                default:pos++;
            }
        }
        return toks;
    }

    // Parser
    static List<Tok> toks;static int tp;
    static Tok peek(){return tp<toks.size()?toks.get(tp):null;}
    static Tok next(){return toks.get(tp++);}
    static boolean chk(int t){return tp<toks.size()&&toks.get(tp).t==t;}
    static boolean chkKw(String k){return tp<toks.size()&&toks.get(tp).t==T_KW&&toks.get(tp).s.equals(k);}
    static void eat(int t){tp++;}
    static void eatKw(String k){tp++;}

    static List<Stmt> parseProgram(){List<Stmt>ss=new ArrayList<>();while(tp<toks.size())ss.add(parseStmt());return ss;}

    static Stmt parseStmt(){
        if(chkKw("let")){tp++;String n=next().s;eat(T_ASSIGN);Expr v=parseExpr();eat(T_SEMI);return new SLet(n,v);}
        if(chkKw("fn")){tp++;String n=next().s;eat(T_LP);List<String>ps=parseParams();eat(T_RP);List<Stmt>b=parseBlock();return new SFn(n,ps,b);}
        if(chkKw("if"))return parseIf();
        if(chkKw("while")){int ln=peek().ln;tp++;Expr c=parseExpr();List<Stmt>b=parseBlock();return new SWhile(c,b,ln);}
        if(chkKw("for")){int ln=peek().ln;tp++;String v=next().s;eatKw("in");Expr it=parseExpr();List<Stmt>b=parseBlock();return new SFor(v,it,b,ln);}
        if(chkKw("return")){int ln=peek().ln;tp++;Expr v=null;if(!chk(T_SEMI))v=parseExpr();eat(T_SEMI);return new SReturn(v,ln);}
        if(chkKw("break")){tp++;eat(T_SEMI);return new SBreak();}
        if(chkKw("continue")){tp++;eat(T_SEMI);return new SCont();}
        // expression or assignment
        Expr e=parseExpr();
        if(chk(T_ASSIGN)){
            tp++;Expr v=parseExpr();eat(T_SEMI);
            if(e instanceof EIdent)return new SAssign(((EIdent)e).name,v,((EIdent)e).ln);
            if(e instanceof EIdx)return new SIdxAssign(((EIdx)e).obj,((EIdx)e).idx,v,((EIdx)e).ln);
            return new SExpr(e);
        }
        eat(T_SEMI);return new SExpr(e);
    }

    static SIf parseIf(){
        int ln=peek().ln;eatKw("if");Expr c=parseExpr();List<Stmt>tb=parseBlock();
        List<Stmt>eb=null;SIf ei=null;
        if(tp<toks.size()&&chkKw("else")){
            tp++;
            if(chkKw("if")){ei=parseIf();}
            else{eb=parseBlock();}
        }
        return new SIf(c,tb,eb,ei,ln);
    }

    static List<Stmt> parseBlock(){eat(T_LC);List<Stmt>ss=new ArrayList<>();while(!chk(T_RC))ss.add(parseStmt());eat(T_RC);return ss;}
    static List<String> parseParams(){List<String>ps=new ArrayList<>();if(chk(T_RP))return ps;ps.add(next().s);while(chk(T_COMMA)){tp++;ps.add(next().s);}return ps;}

    static Expr parseExpr(){return parseOr();}
    static Expr parseOr(){
        Expr l=parseAnd();
        while(chkKw("or")){int ln=peek().ln;tp++;Expr r=parseAnd();l=new EBin("or",l,r,ln);}
        return l;
    }
    static Expr parseAnd(){
        Expr l=parseNot();
        while(chkKw("and")){int ln=peek().ln;tp++;Expr r=parseNot();l=new EBin("and",l,r,ln);}
        return l;
    }
    static Expr parseNot(){
        if(chkKw("not")){int ln=peek().ln;tp++;return new EUn("not",parseNot(),ln);}
        return parseCmp();
    }
    static Expr parseCmp(){
        Expr l=parseAdd();
        while(tp<toks.size()){Tok t=peek();
            if(t.t==T_EQ||t.t==T_NEQ||t.t==T_LT||t.t==T_LE||t.t==T_GT||t.t==T_GE){
                tp++;Expr r=parseAdd();l=new EBin(t.s,l,r,t.ln);
            }else break;
        }
        return l;
    }
    static Expr parseAdd(){
        Expr l=parseMul();
        while(tp<toks.size()){Tok t=peek();
            if(t.t==T_PLUS||t.t==T_MINUS){tp++;Expr r=parseMul();l=new EBin(t.s,l,r,t.ln);}
            else break;
        }
        return l;
    }
    static Expr parseMul(){
        Expr l=parseUnary();
        while(tp<toks.size()){Tok t=peek();
            if(t.t==T_STAR||t.t==T_SLASH||t.t==T_PCT){tp++;Expr r=parseUnary();l=new EBin(t.s,l,r,t.ln);}
            else break;
        }
        return l;
    }
    static Expr parseUnary(){
        if(chk(T_MINUS)){int ln=peek().ln;tp++;return new EUn("-",parseUnary(),ln);}
        return parsePostfix();
    }
    static Expr parsePostfix(){
        Expr e=parsePrimary();
        while(tp<toks.size()){
            if(chk(T_LP)){int ln=peek().ln;tp++;List<Expr>args=new ArrayList<>();if(!chk(T_RP)){args.add(parseExpr());while(chk(T_COMMA)){tp++;args.add(parseExpr());}}eat(T_RP);e=new ECall(e,args,ln);}
            else if(chk(T_LB)){int ln=peek().ln;tp++;Expr idx=parseExpr();eat(T_RB);e=new EIdx(e,idx,ln);}
            else break;
        }
        return e;
    }
    static Expr parsePrimary(){
        Tok t=next();
        if(t.t==T_INT)return new EInt(t.v,t.ln);
        if(t.t==T_STR)return new EStr(t.s,t.ln);
        if(t.t==T_KW){
            if(t.s.equals("true"))return new EBool(true,t.ln);
            if(t.s.equals("false"))return new EBool(false,t.ln);
            if(t.s.equals("nil"))return new ENil(t.ln);
            if(t.s.equals("fn")){eat(T_LP);List<String>ps=parseParams();eat(T_RP);List<Stmt>b=parseBlock();return new EFn(ps,b,t.ln);}
        }
        if(t.t==T_ID)return new EIdent(t.s,t.ln);
        if(t.t==T_LP){Expr e=parseExpr();eat(T_RP);return e;}
        if(t.t==T_LB){List<Expr>elems=new ArrayList<>();if(!chk(T_RB)){elems.add(parseExpr());while(chk(T_COMMA)){tp++;elems.add(parseExpr());}}eat(T_RB);return new EList(elems,t.ln);}
        return new ENil(t.ln);
    }

    // Interpreter
    static StringBuilder out;
    static void emit(String s){out.append(s);}

    static boolean truthy(Object v){
        if(v==NIL)return false;
        if(v instanceof Boolean)return (Boolean)v;
        if(v instanceof Long)return (Long)v!=0;
        if(v instanceof String)return !((String)v).isEmpty();
        if(v instanceof ArrayList)return !((ArrayList<?>)v).isEmpty();
        return true;
    }

    static String typeName(Object v){
        if(v==NIL)return"nil";
        if(v instanceof Long)return"int";
        if(v instanceof Boolean)return"bool";
        if(v instanceof String)return"string";
        if(v instanceof ArrayList)return"list";
        if(v instanceof TernFn)return"function";
        return"unknown";
    }

    static boolean ternEq(Object a,Object b){
        if(a==NIL&&b==NIL)return true;
        if(a==NIL||b==NIL)return false;
        if(a instanceof Long&&b instanceof Long)return((Long)a)==((Long)b);
        if(a instanceof Boolean&&b instanceof Boolean)return a.equals(b);
        if(a instanceof String&&b instanceof String)return a.equals(b);
        if(a instanceof ArrayList&&b instanceof ArrayList){
            ArrayList<?>la=(ArrayList<?>)a,lb=(ArrayList<?>)b;
            if(la.size()!=lb.size())return false;
            for(int i=0;i<la.size();i++)if(!ternEq(la.get(i),lb.get(i)))return false;
            return true;
        }
        if(a instanceof TernFn&&b instanceof TernFn)return a==b;
        return false;
    }

    static String display(Object v,Set<Object>anc){
        if(v==NIL)return"nil";
        if(v instanceof Long)return Long.toString((Long)v);
        if(v instanceof Boolean)return(Boolean)v?"true":"false";
        if(v instanceof String)return(String)v;
        if(v instanceof TernFn)return"<fn>";
        if(v instanceof ArrayList)return dispList((ArrayList<?>)v,anc);
        return"?";
    }
    static String dispList(ArrayList<?>list,Set<Object>anc){
        if(anc.contains(list))return"[...]";
        anc.add(list);
        StringBuilder sb=new StringBuilder("[");
        for(int i=0;i<list.size();i++){
            if(i>0)sb.append(", ");
            Object el=list.get(i);
            if(el instanceof String)sb.append(quoteStr((String)el));
            else sb.append(display(el,anc));
        }
        sb.append("]");anc.remove(list);return sb.toString();
    }
    static String quoteStr(String s){
        StringBuilder sb=new StringBuilder("\"");
        for(int i=0;i<s.length();i++){char c=s.charAt(i);
            if(c=='\\')sb.append("\\\\");
            else if(c=='"')sb.append("\\\"");
            else if(c=='\n')sb.append("\\n");
            else if(c=='\t')sb.append("\\t");
            else sb.append(c);
        }
        sb.append("\"");return sb.toString();
    }

    static Object eval(Expr e,Scope sc){
        if(e instanceof EInt)return((EInt)e).v;
        if(e instanceof EStr)return((EStr)e).v;
        if(e instanceof EBool)return((EBool)e).v;
        if(e instanceof ENil)return NIL;
        if(e instanceof EIdent){
            EIdent id=(EIdent)e;
            String n=id.name;
            if(!sc.has(n))throw new TErr(id.ln,"undefined variable "+n);
            return sc.lookup(n);
        }
        if(e instanceof EBin)return evalBin((EBin)e,sc);
        if(e instanceof EUn){
            EUn u=(EUn)e;
            if(u.op.equals("not")){Object v=eval(u.e,sc);return!truthy(v);}
            Object v=eval(u.e,sc);
            if(!(v instanceof Long))throw new TErr(u.ln,"cannot apply - to "+typeName(v));
            long x=(Long)v;
            if(x==Long.MIN_VALUE)throw new TErr(u.ln,"integer overflow");
            return-x;
        }
        if(e instanceof EList){
            EList el=(EList)e;ArrayList<Object>lst=new ArrayList<>(el.elems.size());
            for(Expr ex:el.elems)lst.add(eval(ex,sc));
            return lst;
        }
        if(e instanceof EFn){
            EFn f=(EFn)e;return new TernFn(f.params,f.body,sc);
        }
        if(e instanceof ECall)return evalCall((ECall)e,sc);
        if(e instanceof EIdx){
            EIdx ix=(EIdx)e;
            Object obj=eval(ix.obj,sc);
            Object idx=eval(ix.idx,sc);
            if(!(obj instanceof ArrayList)&&!(obj instanceof String))
                throw new TErr(ix.ln,"cannot index "+typeName(obj)+" with "+typeName(idx));
            if(!(idx instanceof Long)){
                if(obj instanceof ArrayList)throw new TErr(ix.ln,"cannot index list with "+typeName(idx));
                throw new TErr(ix.ln,"cannot index string with "+typeName(idx));
            }
            long i=(Long)idx;
            int len;
            if(obj instanceof ArrayList)len=((ArrayList<?>)obj).size();
            else len=((String)obj).length();
            if(i<0||i>=len)throw new TErr(ix.ln,"index "+i+" out of range for length "+len);
            if(obj instanceof ArrayList)return((ArrayList<?>)obj).get((int)i);
            return String.valueOf(((String)obj).charAt((int)i));
        }
        return NIL;
    }

    static Object evalBin(EBin b,Scope sc){
        if(b.op.equals("and")){
            Object l=eval(b.l,sc);
            if(!truthy(l))return l;
            return eval(b.r,sc);
        }
        if(b.op.equals("or")){
            Object l=eval(b.l,sc);
            if(truthy(l))return l;
            return eval(b.r,sc);
        }
        Object l=eval(b.l,sc);
        Object r=eval(b.r,sc);
        switch(b.op){
            case"+":
                if(l instanceof Long&&r instanceof Long){
                    long a=(Long)l,c=(Long)r;
                    try{return Math.addExact(a,c);}catch(ArithmeticException ex){throw new TErr(b.ln,"integer overflow");}
                }
                if(l instanceof String&&r instanceof String)return((String)l)+(String)r;
                if(l instanceof ArrayList&&r instanceof ArrayList){
                    ArrayList<Object>res=new ArrayList<>((ArrayList<?>)l);res.addAll((ArrayList<?>)r);return res;
                }
                throw new TErr(b.ln,"cannot apply + to "+typeName(l)+" and "+typeName(r));
            case"-":
                if(l instanceof Long&&r instanceof Long){
                    long a=(Long)l,c=(Long)r;
                    try{return Math.subtractExact(a,c);}catch(ArithmeticException ex){throw new TErr(b.ln,"integer overflow");}
                }
                throw new TErr(b.ln,"cannot apply - to "+typeName(l)+" and "+typeName(r));
            case"*":
                if(l instanceof Long&&r instanceof Long){
                    long a=(Long)l,c=(Long)r;
                    try{return Math.multiplyExact(a,c);}catch(ArithmeticException ex){throw new TErr(b.ln,"integer overflow");}
                }
                throw new TErr(b.ln,"cannot apply * to "+typeName(l)+" and "+typeName(r));
            case"/":
                if(l instanceof Long&&r instanceof Long){
                    long a=(Long)l,c=(Long)r;
                    if(c==0)throw new TErr(b.ln,"division by zero");
                    if(a==Long.MIN_VALUE&&c==-1)throw new TErr(b.ln,"integer overflow");
                    return a/c;
                }
                throw new TErr(b.ln,"cannot apply / to "+typeName(l)+" and "+typeName(r));
            case"%":
                if(l instanceof Long&&r instanceof Long){
                    long a=(Long)l,c=(Long)r;
                    if(c==0)throw new TErr(b.ln,"division by zero");
                    return a%c;
                }
                throw new TErr(b.ln,"cannot apply % to "+typeName(l)+" and "+typeName(r));
            case"==":return ternEq(l,r);
            case"!=":return!ternEq(l,r);
            case"<":
                if(l instanceof Long&&r instanceof Long)return(Long)l<(Long)r;
                if(l instanceof String&&r instanceof String)return((String)l).compareTo((String)r)<0;
                throw new TErr(b.ln,"cannot apply < to "+typeName(l)+" and "+typeName(r));
            case"<=":
                if(l instanceof Long&&r instanceof Long)return(Long)l<=(Long)r;
                if(l instanceof String&&r instanceof String)return((String)l).compareTo((String)r)<=0;
                throw new TErr(b.ln,"cannot apply <= to "+typeName(l)+" and "+typeName(r));
            case">":
                if(l instanceof Long&&r instanceof Long)return(Long)l>(Long)r;
                if(l instanceof String&&r instanceof String)return((String)l).compareTo((String)r)>0;
                throw new TErr(b.ln,"cannot apply > to "+typeName(l)+" and "+typeName(r));
            case">=":
                if(l instanceof Long&&r instanceof Long)return(Long)l>=(Long)r;
                if(l instanceof String&&r instanceof String)return((String)l).compareTo((String)r)>=0;
                throw new TErr(b.ln,"cannot apply >= to "+typeName(l)+" and "+typeName(r));
        }
        return NIL;
    }

    static Object evalCall(ECall call,Scope sc){
        Object fn=eval(call.callee,sc);
        List<Object>args=new ArrayList<>(call.args.size());
        for(Expr a:call.args)args.add(eval(a,sc));
        if(!(fn instanceof TernFn))throw new TErr(call.ln,"cannot call "+typeName(fn));
        TernFn f=(TernFn)fn;
        if(f.bname!=null)return callBuiltin(f,args,call.ln);
        if(f.params.size()!=args.size())
            throw new TErr(call.ln,"expected "+f.params.size()+" arguments, got "+args.size());
        Scope fsc=new Scope(f.captured);
        for(int i=0;i<f.params.size();i++)fsc.vars.put(f.params.get(i),args.get(i));
        try{execBlock(f.body,fsc);}catch(Ret r){return r.v;}
        return NIL;
    }

    @SuppressWarnings("unchecked")
    static Object callBuiltin(TernFn f,List<Object>args,int ln){
        int need=f.arity;
        if(need>=0&&args.size()!=need)throw new TErr(ln,"expected "+need+" arguments, got "+args.size());
        switch(f.bname){
            case"print":{
                for(int i=0;i<args.size();i++){
                    if(i>0)emit(" ");
                    emit(display(args.get(i),new HashSet<>()));
                }
                emit("\n");return NIL;
            }
            case"str":return display(args.get(0),new HashSet<>());
            case"type":return typeName(args.get(0));
            case"len":{
                Object v=args.get(0);
                if(v instanceof String)return(long)((String)v).length();
                if(v instanceof ArrayList)return(long)((ArrayList<?>)v).size();
                throw new TErr(ln,"bad argument to len");
            }
            case"push":{
                Object v=args.get(0);
                if(!(v instanceof ArrayList))throw new TErr(ln,"bad argument to push");
                ((ArrayList<Object>)v).add(args.get(1));return NIL;
            }
            case"pop":{
                Object v=args.get(0);
                if(!(v instanceof ArrayList))throw new TErr(ln,"bad argument to pop");
                ArrayList<Object>lst=(ArrayList<Object>)v;
                if(lst.isEmpty())throw new TErr(ln,"bad argument to pop");
                return lst.remove(lst.size()-1);
            }
            case"range":{
                Object a=args.get(0),b=args.get(1);
                if(!(a instanceof Long)||!(b instanceof Long))throw new TErr(ln,"bad argument to range");
                long lo=(Long)a,hi=(Long)b;ArrayList<Object>res=new ArrayList<>();
                for(long i=lo;i<hi;i++)res.add(i);
                return res;
            }
            case"slice":{
                Object x=args.get(0),a=args.get(1),b=args.get(2);
                if(!(a instanceof Long)||!(b instanceof Long))throw new TErr(ln,"bad argument to slice");
                long lo=(Long)a,hi=(Long)b;
                if(x instanceof String){
                    String s=(String)x;
                    if(lo<0||hi>s.length()||lo>hi)throw new TErr(ln,"bad argument to slice");
                    return s.substring((int)lo,(int)hi);
                }
                if(x instanceof ArrayList){
                    ArrayList<?>lst=(ArrayList<?>)x;
                    if(lo<0||hi>lst.size()||lo>hi)throw new TErr(ln,"bad argument to slice");
                    return new ArrayList<Object>(lst.subList((int)lo,(int)hi));
                }
                throw new TErr(ln,"bad argument to slice");
            }
        }
        return NIL;
    }

    static void execBlock(List<Stmt>body,Scope sc){
        for(Stmt s:body)execStmt(s,sc);
    }

    @SuppressWarnings("unchecked")
    static void execStmt(Stmt s,Scope sc){
        if(s instanceof SLet){
            SLet st=(SLet)s;Object v=eval(st.val,sc);sc.vars.put(st.name,v);return;
        }
        if(s instanceof SFn){
            SFn st=(SFn)s;TernFn fn=new TernFn(st.params,st.body,sc);sc.vars.put(st.name,fn);return;
        }
        if(s instanceof SIf){
            SIf st=(SIf)s;
            if(truthy(eval(st.cond,sc))){execBlock(st.thenB,new Scope(sc));}
            else if(st.elseB!=null){execBlock(st.elseB,new Scope(sc));}
