interface Token { type: string; value: string; line: number; }

const KEYWORDS = new Set(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil']);

function lex(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0, line = 1;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === ' ' || c === '\t' || c === '\r') { i++; continue; }
    if (c === '\n') { line++; i++; continue; }
    if (c === '#') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c >= '0' && c <= '9') {
      let j = i; while (j < n && src[j] >= '0' && src[j] <= '9') j++;
      tokens.push({ type: 'INT', value: src.slice(i, j), line }); i = j; continue;
    }
    if (c === '"') {
      i++; let s = '';
      while (i < n && src[i] !== '"') {
        if (src[i] === '\\') { i++; const e = src[i];
