      }
      i++; tokens.push({ type: 'STR', value: s, line }); continue;
    }
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_') {
      let j = i;
      while (j < n && ((src[j] >= 'a' && src[j] <= 'z') || (src[j] >= 'A' && src[j] <= 'Z') || (src[j] >= '0' && src[j] <= '9') || src[j] === '_')) j++;
      const w = src.slice(i, j);
      tokens.push({ type: KEYWORDS.has(w) ? 'KW' : 'IDENT', value: w, line }); i = j; continue;
    }
    if (i + 1 < n) {
      const two = src[i] + src[i+1];
      if (two === '==' || two === '!=' || two === '<=' || two === '>=') {
        tokens.push({ type: 'OP', value: two, line }); i += 2; continue;
      }
    }
    if (c === '(') { tokens.push({type:'LPAREN',value:c,line}); i++; continue; }
    if (c === ')') { tokens.push({type:'RPAREN',value:c,line}); i++; continue; }
    if (c === '[') { tokens.push({type:'LBRACKET',value:c,line}); i++; continue; }
    if (c === ']') { tokens.push({type:'RBRACKET',value:c,line}); i++; continue; }
    if (c === '{') { tokens.push({type:'LBRACE',value:c,line}); i++; continue; }
    if (c === '}') { tokens.push({type:'RBRACE',value:c,line}); i++; continue; }
    if (c === ',') { tokens.push({type:'COMMA',value:c,line}); i++; continue; }
    if (c === ';') { tokens.push({type:'SEMI',value:c,line}); i++; continue; }
    tokens.push({type:'OP',value:c,line}); i++;
