                        case "\"": s.append("\"")
                        case "\\": s.append("\\")
                        default: s.append(chars[pos])
                        }
                        pos += 1
                    }
                } else { s.append(chars[pos]); pos += 1 }
            }
            pos += 1
            tokens.append(Token(kind: .str(s), line: line))
            continue
        }
        if c.isLetter || c == "_" {
            var s = ""
            while pos < n && (chars[pos].isLetter || chars[pos].isNumber || chars[pos] == "_") {
                s.append(chars[pos]); pos += 1
            }
            if keywordsSet.contains(s) {
                tokens.append(Token(kind: .keyword(s), line: line))
            } else {
                tokens.append(Token(kind: .ident(s), line: line))
            }
            continue
        }
        if pos + 1 < n {
            let two = String([chars[pos], chars[pos+1]])
            if two == "==" || two == "!=" || two == "<=" || two == ">=" {
                tokens.append(Token(kind: .op(two), line: line)); pos += 2; continue
            }
        }
        switch c {
        case "<": tokens.append(Token(kind: .op("<"), line: line)); pos += 1
        case ">": tokens.append(Token(kind: .op(">"), line: line)); pos += 1
        case "=": tokens.append(Token(kind: .op("="), line: line)); pos += 1
        case "+": tokens.append(Token(kind: .op("+"), line: line)); pos += 1
        case "-": tokens.append(Token(kind: .op("-"), line: line)); pos += 1
        case "*": tokens.append(Token(kind: .op("*"), line: line)); pos += 1
        case "/": tokens.append(Token(kind: .op("/"), line: line)); pos += 1
        case "%": tokens.append(Token(kind: .op("%"), line: line)); pos += 1
        case "(": tokens.append(Token(kind: .lparen, line: line)); pos += 1
        case ")": tokens.append(Token(kind: .rparen, line: line)); pos += 1
        case "[": tokens.append(Token(kind: .lbracket, line: line)); pos += 1
        case "]": tokens.append(Token(kind: .rbracket, line: line)); pos += 1
        case "{": tokens.append(Token(kind: .lbrace, line: line)); pos += 1
        case "}": tokens.append(Token(kind: .rbrace, line: line)); pos += 1
        case ",": tokens.append(Token(kind: .comma, line: line)); pos += 1
        case ";": tokens.append(Token(kind: .semicolon, line: line)); pos += 1
        default: pos += 1
        }
    }
    tokens.append(Token(kind: .eof, line: line))
    return tokens
}

// MARK: - Parser

final class Parser {
    var tokens: [Token]
    var pos: Int
    init(_ tokens: [Token]) { self.tokens = tokens; self.pos = 0 }
    var cur: Token { tokens[pos] }
    var curKind: TokenKind { tokens[pos].kind }
    var curLine: Int { tokens[pos].line }
    func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    func isKw(_ s: String) -> Bool { if case .keyword(s) = curKind { return true }; return false }
    func isOp(_ s: String) -> Bool { if case .op(s) = curKind { return true }; return false }
    func isIdent() -> Bool { if case .ident = curKind { return true }; return false }
    func getIdent() -> String { if case .ident(let s) = curKind { return s }; return "" }
    func isLP() -> Bool { curKind == .lparen }
    func isRP() -> Bool { curKind == .rparen }
    func isLB() -> Bool { curKind == .lbracket }
    func isRB() -> Bool { curKind == .rbracket }
    func isLBr() -> Bool { curKind == .lbrace }
    func isRBr() -> Bool { curKind == .rbrace }
    func isComma() -> Bool { curKind == .comma }
    func isSemi() -> Bool { curKind == .semicolon }
    func isEOF() -> Bool { curKind == .eof }
    func curOpStr() -> String { if case .op(let s) = curKind { return s }; return "" }

    func parseProgram() -> [Stmt] {
        var stmts: [Stmt] = []
        while !isEOF() { stmts.append(parseStmt()) }
        return stmts
    }

    func parseBlock() -> [Stmt] {
        advance() // {
        var stmts: [Stmt] = []
        while !isRBr() && !isEOF() { stmts.append(parseStmt()) }
        advance() // }
        return stmts
    }

    func parseParams() -> [String] {
        var params: [String] = []
        if isIdent() {
            params.append(getIdent()); advance()
            while isComma() { advance(); params.append(getIdent()); advance() }
        }
        return params
    }

    func parseStmt() -> Stmt {
        let line = curLine
        if isKw("let") {
            advance(); let name = getIdent(); advance()
            advance() // =
            let val = parseExpr(); advance() // ;
            return .letStmt(name, val, line)
        }
        if isKw("fn") {
            advance(); let name = getIdent(); advance()
            advance() // (
            let params = parseParams()
            advance() // )
            let body = parseBlock()
            return .fnDef(name, params, body, line)
        }
        if isKw("if") { return parseIf() }
        if isKw("while") {
            advance(); let cond = parseExpr(); let body = parseBlock()
            return .whileStmt(cond, body, line)
        }
        if isKw("for") {
            advance(); let vn = getIdent(); advance()
            advance() // in
            let iter = parseExpr(); let body = parseBlock()
            return .forStmt(vn, iter, body, line)
        }
        if isKw("return") {
            advance()
            if isSemi() { advance(); return .returnStmt(nil, line) }
            let val = parseExpr(); advance() // ;
            return .returnStmt(val, line)
        }
        if isKw("break") { advance(); advance(); return .breakStmt(line) }
        if isKw("continue") { advance(); advance(); return .continueStmt(line) }
        let expr = parseExpr()
        if isOp("=") {
            advance()
            let val = parseExpr(); advance() // ;
            if case .ident(let name, _) = expr {
                return .assign(name, val, line)
            }
            if case .index(let obj, let idx, _) = expr {
                return .indexAssign(obj, idx, val, line)
            }
            return .exprStmt(expr, line)
        }
        advance() // ;
        return .exprStmt(expr, line)
    }

    func parseIf() -> Stmt {
        let line = curLine
        advance() // if
        let cond = parseExpr()
        let body = parseBlock()
        var elseBody: [Stmt]? = nil
        if isKw("else") {
            advance()
            if isKw("if") { elseBody = [parseIf()] }
            else { elseBody = parseBlock() }
        }
        return .ifStmt(cond, body, elseBody, line)
    }

    func parseExpr() -> Expr { parseOr() }

    func parseOr() -> Expr {
        var left = parseAnd()
        while isKw("or") { let l = curLine; advance(); left = .binOp("or", left, parseAnd(), l) }
        return left
    }
    func parseAnd() -> Expr {
        var left = parseNot()
        while isKw("and") { let l = curLine; advance(); left = .binOp("and", left, parseNot(), l) }
        return left
    }
    func parseNot() -> Expr {
        if isKw("not") { let l = curLine; advance(); return .notExpr(parseNot(), l) }
        return parseComp()
    }
    func parseComp() -> Expr {
        var left = parseAdd()
        while isOp("==") || isOp("!=") || isOp("<") || isOp("<=") || isOp(">") || isOp(">=") {
            let op = curOpStr(); let l = curLine; advance()
            left = .binOp(op, left, parseAdd(), l)
        }
        return left
    }
    func parseAdd() -> Expr {
        var left = parseMul()
        while isOp("+") || isOp("-") {
            let op = curOpStr(); let l = curLine; advance()
            left = .binOp(op, left, parseMul(), l)
        }
        return left
    }
    func parseMul() -> Expr {
        var left = parseUnary()
        while isOp("*") || isOp("/") || isOp("%") {
            let op = curOpStr(); let l = curLine; advance()
            left = .binOp(op, left, parseUnary(), l)
        }
        return left
    }
    func parseUnary() -> Expr {
        if isOp("-") { let l = curLine; advance(); return .negExpr(parseUnary(), l) }
        return parsePostfix()
    }
    func parsePostfix() -> Expr {
        var expr = parsePrimary()
        while true {
            if isLP() {
                let l = curLine; advance()
                var args: [Expr] = []
                if !isRP() {
                    args.append(parseExpr())
                    while isComma() { advance(); args.append(parseExpr()) }
                }
                advance() // )
                expr = .call(expr, args, l)
            } else if isLB() {
                let l = curLine; advance()
                let idx = parseExpr(); advance() // ]
                expr = .index(expr, idx, l)
            } else { break }
        }
        return expr
    }
    func parsePrimary() -> Expr {
        let l = curLine
        switch curKind {
        case .int(let v): advance(); return .intLit(v, l)
        case .str(let s): advance(); return .stringLit(s, l)
        case .keyword("true"): advance(); return .boolLit(true, l)
        case .keyword("false"): advance(); return .boolLit(false, l)
        case .keyword("nil"): advance(); return .nilLit(l)
        case .ident(let s): advance(); return .ident(s, l)
        case .lparen:
            advance(); let e = parseExpr(); advance(); return e
        case .lbracket:
            advance()
            var elems: [Expr] = []
            if !isRB() {
                elems.append(parseExpr())
                while isComma() { advance(); if isRB() { break }; elems.append(parseExpr()) }
            }
            advance() // ]
            return .listLit(elems, l)
        case .keyword("fn"):
            advance(); advance() // (
            let params = parseParams(); advance() // )
            let body = parseBlock()
            return .fnLit(params, body, l)
        default:
            advance(); return .nilLit(l)
        }
    }
}

// MARK: - Interpreter

final class Interpreter {
    let builtinScope: Scope
    let globalScope: Scope
    var outputBuf: [String]

    init() {
        builtinScope = Scope(parent: nil)
        globalScope = Scope(parent: builtinScope)
        outputBuf = []
        setupBuiltins()
    }

    func typeName(_ v: TernValue) -> String {
        switch v {
        case .int: return "int"
        case .bool: return "bool"
        case .string: return "string"
        case .list: return "list"
        case .function: return "function"
        case .nilValue: return "nil"
        }
    }

    func truthy(_ v: TernValue) -> Bool {
        switch v {
        case .bool(let b): return b
        case .nilValue: return false
        case .int(let n): return n != 0
        case .string(let s): return !s.isEmpty
        case .list(let l): return !l.elements.isEmpty
        case .function: return true
        }
    }

    func escapeStr(_ s: String) -> String {
        var r = ""
        for c in s {
            switch c {
            case "\\": r += "\\\\"
            case "\"": r += "\\\""
            case "\n": r += "\\n"
            case "\t": r += "\\t"
            default: r.append(c)
            }
        }
        return r
    }

    func display(_ v: TernValue, inList: Bool, anc: inout Set<Int>) -> String {
        switch v {
        case .int(let n): return String(n)
        case .bool(let b): return b ? "true" : "false"
        case .nilValue: return "nil"
        case .function: return "<fn>"
        case .string(let s):
            return inList ? "\"" + escapeStr(s) + "\"" : s
        case .list(let l):
            let id = ObjectIdentifier(l).hashValue
            if anc.contains(id) { return "[...]" }
            anc.insert(id)
            var parts: [String] = []
            parts.reserveCapacity(l.elements.count)
            for e in l.elements { parts.append(display(e, inList: true, anc: &anc)) }
            anc.remove(id)
            return "[" + parts.joined(separator: ", ") + "]"
        }
    }

    func displayTop(_ v: TernValue) -> String {
        var anc = Set<Int>()
        return display(v, inList: false, anc: &anc)
    }

    func valuesEqual(_ a: TernValue, _ b: TernValue) -> Bool {
        switch (a, b) {
        case (.int(let x), .int(let y)): return x == y
        case (.bool(let x), .bool(let y)): return x == y
        case (.string(let x), .string(let y)): return x == y
        case (.nilValue, .nilValue): return true
        case (.list(let x), .list(let y)):
            if x === y { return true }
            if x.elements.count != y.elements.count { return false }
            for i in 0..<x.elements.count {
                if !valuesEqual(x.elements[i], y.elements[i]) { return false }
            }
            return true
        case (.function(let x), .function(let y)): return x === y
        default: return false
        }
    }

    func setupBuiltins() {
        let printFn = FunctionVal(builtinName: "print", arity: -1)
        let strFn = FunctionVal(builtinName: "str", arity: 1)
        let typeFn = FunctionVal(builtinName: "type", arity: 1)
        let lenFn = FunctionVal(builtinName: "len", arity: 1)
        let pushFn = FunctionVal(builtinName: "push", arity: 2)
        let popFn = FunctionVal(builtinName: "pop", arity: 1)
        let rangeFn = FunctionVal(builtinName: "range", arity: 2)
        let sliceFn = FunctionVal(builtinName: "slice", arity: 3)
        builtinScope.vars["print"] = .function(printFn)
        builtinScope.vars["str"] = .function(strFn)
        builtinScope.vars["type"] = .function(typeFn)
        builtinScope.vars["len"] = .function(lenFn)
        builtinScope.vars["push"] = .function(pushFn)
        builtinScope.vars["pop"] = .function(popFn)
        builtinScope.vars["range"] = .function(rangeFn)
        builtinScope.vars["slice"] = .function(sliceFn)
    }

    func run(_ stmts: [Stmt]) {
        do {
            try execBlock(stmts, scope: globalScope)
        } catch let TernError.runtime(msg, line) {
            flushOutput()
            print("error at line \(line): \(msg)")
        } catch {
            flushOutput()
        }
    }

    func flushOutput() {
        // output already flushed via print
    }

    func execBlock(_ stmts: [Stmt], scope: Scope) throws {
        for s in stmts { try exec(s, scope: scope) }
    }

    func exec(_ stmt: Stmt, scope: Scope) throws {
        switch stmt {
        case .letStmt(let name, let val, _):
            let v = try eval(val, scope: scope)
            scope.vars[name] = v
        case .fnDef(let name, let params, let body, _):
            let fv = FunctionVal(params: params, body: body, capturedScope: scope)
            scope.vars[name] = .function(fv)
        case .ifStmt(let cond, let body, let elseBody, _):
            let cv = try eval(cond, scope: scope)
            if truthy(cv) {
                let s = Scope(parent: scope)
                try execBlock(body, scope: s)
            } else if let eb = elseBody {
                let s = Scope(parent: scope)
                try execBlock(eb, scope: s)
            }
        case .whileStmt(let cond, let body, _):
            while true {
                let cv = try eval(cond, scope: scope)
                if !truthy(cv) { break }
                let s = Scope(parent: scope)
                do { try execBlock(body, scope: s) }
                catch TernError.breakLoop { break }
                catch TernError.continueLoop { continue }
            }
        case .forStmt(let varName, let iterExpr, let body, let line):
            let iterVal = try eval(iterExpr, scope: scope)
            guard case .list(let list) = iterVal else {
                throw TernError.runtime("cannot iterate \(typeName(iterVal))", line)
            }
            var i: Int = 0
            while i < list.elements.count {
                let s = Scope(parent: scope)
                s.vars[varName] = list.elements[i]
                do { try execBlock(body, scope: s) }
                catch TernError.breakLoop { break }
                catch TernError.continueLoop { /* fall through */ }
                i += 1
            }
        case .returnStmt(let val, _):
            if let v = val { throw TernError.returnValue(try eval(v, scope: scope)) }
            else { throw TernError.returnValue(.nilValue) }
        case .breakStmt: throw TernError.breakLoop
        case .continueStmt: throw TernError.continueLoop
        case .assign(let name, let val, let line):
            let v = try eval(val, scope: scope)
            if !scope.assign(name, v) {
                throw TernError.runtime("undefined variable \(name)", line)
            }
        case .indexAssign(let objExpr, let idxExpr, let valExpr, let line):
            let obj = try eval(objExpr, scope: scope)
            let idx = try eval(idxExpr, scope: scope)
            let val = try eval(valExpr, scope: scope)
            guard case .list(let list) = obj else {
                throw TernError.runtime("cannot assign into \(typeName(obj))", line)
            }
            guard case .int(let i) = idx else {
                throw TernError.runtime("cannot index list with \(typeName(idx))", line)
            }
            if i < 0 || i >= Int64(list.elements.count) {
                throw TernError.runtime("index \(i) out of range for length \(list.elements.count)", line)
            }
            list.elements[Int(i)] = val
        case .exprStmt(let e, _):
            _ = try eval(e, scope: scope)
        }
    }

    func eval(_ expr: Expr, scope: Scope) throws -> TernValue {
        switch expr {
        case .intLit(let v, _): return .int(v)
        case .stringLit(let s, _): return .string(s)
        case .boolLit(let b, _): return .bool(b)
        case .nilLit: return .nilValue
        case .ident(let name, let line):
            if let v = scope.lookup(name) { return v }
            throw TernError.runtime("undefined variable \(name)", line)
        case .listLit(let elems, _):
            var vals: [TernValue] = []
            vals.reserveCapacity(elems.count)
            for e in elems { vals.append(try eval(e, scope: scope)) }
            return .list(TernList(vals))
        case .fnLit(let params, let body, _):
            return .function(FunctionVal(params: params, body: body, capturedScope: scope))
        case .notExpr(let e, _):
            let v = try eval(e, scope: scope)
            return .bool(!truthy(v))
        case .negExpr(let e, let line):
            let v = try eval(e, scope: scope)
            guard case .int(let n) = v else {
                throw TernError.runtime("cannot apply - to \(typeName(v))", line)
            }
            if n == Int64.min { throw TernError.runtime("integer overflow", line) }
            return .int(-n)
        case .binOp(let op, let left, let right, let line):
            if op == "and" {
                let lv = try eval(left, scope: scope)
                if !truthy(lv) { return lv }
                return try eval(right, scope: scope)
            }
            if op == "or" {
                let lv = try eval(left, scope: scope)
                if truthy(lv) { return lv }
                return try eval(right, scope: scope)
            }
            let lv = try eval(left, scope: scope)
            let rv = try eval(right, scope: scope)
            return try applyBinOp(op, lv, rv, line)
        case .call(let calleeExpr, let argExprs, let line):
            let callee = try eval(calleeExpr, scope: scope)
            var args: [TernValue] = []
            args.reserveCapacity(argExprs.count)
            for ae in argExprs { args.append(try eval(ae, scope: scope)) }
            guard case .function(let fv) = callee else {
                throw TernError.runtime("cannot call \(typeName(callee))", line)
            }
            return try callFunction(fv, args, line)
        case .index(let objExpr, let idxExpr, let line):
            let obj = try eval(objExpr, scope: scope)
            let idx = try eval(idxExpr, scope: scope)
            return try indexValue(obj, idx, line)
        }
    }

    func applyBinOp(_ op: String, _ lv: TernValue, _ rv: TernValue, _ line: Int) throws -> TernValue {
        switch op {
        case "+":
            switch (lv, rv) {
            case (.int(let a), .int(let b)):
                let (r, ov) = a.addingReportingOverflow(b)
                if ov { throw TernError.runtime("integer overflow", line) }
                return .int(r)
            case (.string(let a), .string(let b)): return .string(a + b)
            case (.list(let a), .list(let b)):
                var elems = a.elements
                elems.append(contentsOf: b.elements)
                return .list(TernList(elems))
            default:
                throw TernError.runtime("cannot apply + to \(typeName(lv)) and \(typeName(rv))", line)
            }
        case "-":
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError.runtime("cannot apply - to \(typeName(lv)) and \(typeName(rv))", line)
            }
            let (r, ov) = a.subtractingReportingOverflow(b)
            if ov { throw TernError.runtime("integer overflow", line) }
            return .int(r)
        case "*":
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError.runtime("cannot apply * to \(typeName(lv)) and \(typeName(rv))", line)
            }
            let (r, ov) = a.multipliedReportingOverflow(by: b)
            if ov { throw TernError.runtime("integer overflow", line) }
            return .int(r)
        case "/":
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError.runtime("cannot apply / to \(typeName(lv)) and \(typeName(rv))", line)
            }
            if b == 0 { throw TernError.runtime("division by zero", line) }
            if b == -1 {
                if a == Int64.min { throw TernError.runtime("integer overflow", line) }
                return .int(-a)
            }
            let r = a / b
            return .int(r)
        case "%":
            guard case (.int(let a), .int(let b)) = (lv, rv) else {
                throw TernError.runtime("cannot apply % to \(typeName(lv)) and \(typeName(rv))", line)
            }
            if b == 0 { throw TernError.runtime("division by zero", line) }
            if b == -1 { return .int(0) }
            let r = a % b
            return .int(r)
        case "<":
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a < b)
            case (.string(let a), .string(let b)): return .bool(a < b)
            default: throw TernError.runtime("cannot apply < to \(typeName(lv)) and \(typeName(rv))", line)
            }
        case "<=":
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a <= b)
            case (.string(let a), .string(let b)): return .bool(a <= b)
            default: throw TernError.runtime("cannot apply <= to \(typeName(lv)) and \(typeName(rv))", line)
            }
        case ">":
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a > b)
            case (.string(let a), .string(let b)): return .bool(a > b)
            default: throw TernError.runtime("cannot apply > to \(typeName(lv)) and \(typeName(rv))", line)
            }
        case ">=":
            switch (lv, rv) {
            case (.int(let a), .int(let b)): return .bool(a >= b)
            case (.string(let a), .string(let b)): return .bool(a >= b)
            default: throw TernError.runtime("cannot apply >= to \(typeName(lv)) and \(typeName(rv))", line)
            }
        case "==": return .bool(valuesEqual(lv, rv))
        case "!=": return .bool(!valuesEqual(lv, rv))
        default:
            throw TernError.runtime("cannot apply \(op) to \(typeName(lv)) and \(typeName(rv))", line)
        }
    }

    func indexValue(_ obj: TernValue, _ idx: TernValue, _ line: Int) throws -> TernValue {
        switch obj {
        case .list(let l):
            guard case .int(let i) = idx else {
                throw TernError.runtime("cannot index list with \(typeName(idx))", line)
            }
            if i < 0 || i >= Int64(l.elements.count) {
                throw TernError.runtime("index \(i) out of range for length \(l.elements.count)", line)
            }
            return l.elements[Int(i)]
        case .string(let s):
            guard case .int(let i) = idx else {
                throw TernError.runtime("cannot index string with \(typeName(idx))", line)
            }
            let arr = Array(s)
            if i < 0 || i >= Int64(arr.count) {
                throw TernError.runtime("index \(i) out of range for length \(arr.count)", line)
            }
            return .string(String(arr[Int(i)]))
        default:
            throw TernError.runtime("cannot index \(typeName(obj)) with \(typeName(idx))", line)
        }
    }

    func callFunction(_ fv: FunctionVal, _ args: [TernValue], _ line: Int) throws -> TernValue {
        if fv.isBuiltin {
            let name = fv.builtinName!
            let arity = fv.builtinArity
            if arity >= 0 && args.count != arity {
                throw TernError.runtime("expected \(arity) arguments, got \(args.count)", line)
            }
            return try callBuiltin(name, args, line)
        }
        // user function
        if args.count != fv.params.count {
            throw TernError.runtime("expected \(fv.params.count) arguments, got \(args.count)", line)
        }
        let callScope = Scope(parent: fv.capturedScope)
