            guard case .list(let list) = obj else {
                throw TernError.runtime("cannot assign into \(typeName(obj))", line)
            }
            guard case .int(let i) = idx else {
                throw TernError.runtime("cannot index list with \(typeName(idx))", line)
            }
            if i < 0 || i >= Int64(list.elements.count) {
                throw TernError.runtime("index \(i) out of range for length \(list.elements.count)", line)
            }
            list.elements[Int(i)] = val
