import Foundation

// CRC-32 (zlib/PNG)
func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320 }
            else { crc >>= 1 }
        }
