    for (name, val) in params {
        let ln = name.lowercased()
        if ln == a + "*" { singleVal = val }
        else if ln.hasPrefix(a + "*") {
            let suffix = String(ln.dropFirst(a.count + 1))
            if suffix.hasSuffix("*") {
                let numStr = String(suffix.dropLast())
                if let num = Int(numStr) { segs.append((num, true, val)) }
            } else if let num = Int(suffix) { segs.append((num, false, val)) }
