        while j < sv.count && sv[j] != 0x27 { csB.append(sv[j]); j += 1 }
        if j < sv.count { j += 1 }
        while j < sv.count && sv[j] != 0x27 { j += 1 }
        if j < sv.count { j += 1 }
        let charset = String(bytes: csB, encoding: .ascii)?.lowercased() ?? "us-ascii"
        return csdec(pctdec(Array(sv[j...])), charset)
    }
    if !segs.isEmpty {
        segs.sort { $0.idx < $1.idx }
        var charset = "us-ascii"
        var allBytes: [UInt8] = []
        for seg in segs {
            if seg.pct {
                if seg.idx == 0 {
                    var j = 0; var csB: [UInt8] = []
                    while j < seg.val.count && seg.val[j] != 0x27 { csB.append(seg.val[j]); j += 1 }
                    if j < seg.val.count { j += 1 }
                    while j < seg.val.count && seg.val[j] != 0x27 { j += 1 }
                    if j < seg.val.count { j += 1 }
