import Foundation

// CRC-32 (zlib/PNG)
func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320 }
            else { crc >>= 1 }
        }
    }
    return crc ^ 0xFFFFFFFF
}

func qstr(_ scalars: [Unicode.Scalar]) -> String {
    var r = "\""
    for s in scalars {
        let v = s.value
        if v == 0x5C { r += "\\\\" }
        else if v == 0x22 { r += "\\\"" }
        else if v == 0x0A { r += "\\n" }
        else if v == 0x09 { r += "\\t" }
        else if v < 0x20 || (v >= 0x7F && v <= 0x9F) { r += String(format: "\\u%04x", v) }
        else { r.append(Character(s)) }
