struct Entity {
    var headers: [(String, [UInt8])]
    var body: [UInt8]
    var lb: [UInt8]
    var ct: (type: String, subtype: String, params: [(String, [UInt8])])
    var cte: String
    var dispType: String?
    var dispParams: [(String, [UInt8])]
    var parts: [Entity]?
}

func getParam(_ params: [(String, [UInt8])], _ name: String) -> [UInt8]? {
    for (pn, pv) in params { if pn == name { return pv } }
    return nil
}

func getHeaderVal(_ entity: Entity, _ name: String) -> [UInt8]? {
    for (n, v) in entity.headers { if n == name { return v } }
    return nil
}

func parseEntity(_ content: [UInt8], _ lb: [UInt8], _ isTop: Bool) -> Entity {
    var lines: [(content: [UInt8], hasLB: Bool)] = []
    var cur: [UInt8] = []
    var i = 0
    while i < content.count {
        if i + lb.count <= content.count && Array(content[i..<i+lb.count]) == lb {
            lines.append((cur, true)); cur = []; i += lb.count
        } else { cur.append(content[i]); i += 1 }
    }
    lines.append((cur, false))

    var headerLines: [[UInt8]] = []
    var bodyStart = 0
    var li = 0
    while li < lines.count {
        if lines[li].content.isEmpty {
            li += 1; bodyStart = li; break
        } else if lines[li].content[0] == 0x20 || lines[li].content[0] == 0x09 {
            if !headerLines.isEmpty { headerLines[headerLines.count-1].append(contentsOf: lines[li].content) }
            li += 1
        } else {
            headerLines.append(lines[li].content); li += 1
        }
    }

    var headers: [(String, [UInt8])] = []
    for hl in headerLines {
        var j = 0; var nameB: [UInt8] = []
        while j < hl.count && hl[j] != 0x3A { nameB.append(hl[j]); j += 1 }
        if j < hl.count { j += 1 }
        while j < hl.count && (hl[j] == 0x20 || hl[j] == 0x09) { j += 1 }
        var valB = Array(hl[j...])
        while let last = valB.last, last == 0x20 || last == 0x09 { valB.removeLast() }
        let name = String(bytes: nameB, encoding: .ascii)?.lowercased() ?? ""
        headers.append((name, valB))
    }

    var body: [UInt8] = []
    if bodyStart < lines.count {
        for (idx, line) in lines[bodyStart...].enumerated() {
            body.append(contentsOf: line.content)
            if idx < lines.count - bodyStart - 1 { body.append(contentsOf: lb) }
            else if isTop && line.hasLB { body.append(contentsOf: lb) }
        }
    }

    let ctVal = getHeaderVal(Entity(headers: headers, body: [], lb: lb, ct: ("text","plain",[]), cte: "7bit", dispType: nil, dispParams: [], parts: nil), "content-type")
    let ct: (type: String, subtype: String, params: [(String, [UInt8])])
    if let cv = ctVal { ct = parseCT(cv) } else { ct = ("text", "plain", []) }

    let cteVal = getHeaderVal(Entity(headers: headers, body: [], lb: lb, ct: ct, cte: "7bit", dispType: nil, dispParams: [], parts: nil), "content-transfer-encoding")
    let cte: String
    if let cv = cteVal {
        let s = String(bytes: cv, encoding: .ascii)?.trimmingCharacters(in: CharacterSet(charactersIn: " \t")).lowercased() ?? "7bit"
        cte = s
    } else { cte = "7bit" }

    let cdVal = getHeaderVal(Entity(headers: headers, body: [], lb: lb, ct: ct, cte: cte, dispType: nil, dispParams: [], parts: nil), "content-disposition")
    let cd: (type: String?, params: [(String, [UInt8])])
    if let cv = cdVal { cd = parseCD(cv) } else { cd = (nil, []) }

    var parts: [Entity]? = nil
    if ct.type == "multipart" {
        var boundary: String? = nil
        for (pn, pv) in ct.params { if pn == "boundary" { boundary = String(bytes: pv, encoding: .ascii); break } }
        if let b = boundary { parts = parseMultipart(body, b, lb) }
    }

    return Entity(headers: headers, body: body, lb: lb, ct: ct, cte: cte, dispType: cd.type, dispParams: cd.params, parts: parts)
}

func parseMultipart(_ body: [UInt8], _ boundary: String, _ lb: [UInt8]) -> [Entity] {
    let delim = Array("--\(boundary)".utf8)
    let closeDelim = Array("--\(boundary)--".utf8)

    struct LPos { var start: Int; var content: [UInt8]; var hasLB: Bool }
    var lines: [LPos] = []
    var i = 0
    while i < body.count {
        var le = i
        while le < body.count {
            if le + lb.count <= body.count && Array(body[le..<le+lb.count]) == lb { break }
            le += 1
        }
        let hasLB = le + lb.count <= body.count
        lines.append(LPos(start: i, content: Array(body[i..<le]), hasLB: hasLB))
        i = hasLB ? le + lb.count : le
    }

    var delimIdx: [Int] = []
    var closeIdx = -1
    for (li, line) in lines.enumerated() {
        var sc = line.content
        while let last = sc.last, last == 0x20 || last == 0x09 { sc.removeLast() }
        if sc == closeDelim { closeIdx = li; break }
        if sc == delim { delimIdx.append(li) }
    }

    var allD = delimIdx
    if closeIdx >= 0 { allD.append(closeIdx) }

    var parts: [Entity] = []
    for k in 0..<allD.count-1 {
        let sl = allD[k]; let el = allD[k+1]
        var partBytes: [UInt8] = []
        var li = sl + 1
        while li <= el - 1 {
            partBytes.append(contentsOf: lines[li].content)
            if li < el - 1 { partBytes.append(contentsOf: lb) }
            li += 1
        }
        parts.append(parseEntity(partBytes, lb, false))
    }
    return parts
}

func decodeBodyBytes(_ entity: Entity) -> [UInt8] {
    switch entity.cte {
    case "base64": return b64dec(entity.body)
    case "quoted-printable": return qpdec(entity.body, entity.lb)
    default: return entity.body
    }
}

func getCharset(_ entity: Entity) -> String {
    if let cv = getParam(entity.ct.params, "charset") {
        return String(bytes: cv, encoding: .ascii)?.lowercased() ?? "us-ascii"
    }
    return "us-ascii"
}

func decodeTextBody(_ entity: Entity) -> [Unicode.Scalar] {
    let raw = decodeBodyBytes(entity)
    let charset = getCharset(entity)
    var scalars = csdec(raw, charset)
    var result: [Unicode.Scalar] = []
    var i = 0
    while i < scalars.count {
        if scalars[i].value == 0x0D {
            if i + 1 < scalars.count && scalars[i+1].value == 0x0A { result.append(Unicode.Scalar(0x0A)); i += 2 }
            else { result.append(Unicode.Scalar(0x0A)); i += 1 }
        } else { result.append(scalars[i]); i += 1 }
    }
    return result
}

func getFileName(_ entity: Entity) -> String {
    if let n = rfc2231Get(entity.dispParams, "filename") { return qstr(n) }
    if let v = getParam(entity.dispParams, "filename") { return qstr(rfc2047dec(v)) }
    if let n = rfc2231Get(entity.ct.params, "name") { return qstr(n) }
    if let v = getParam(entity.ct.params, "name") { return qstr(rfc2047dec(v)) }
    return "-"
}

func printTree(_ entity: Entity, _ indent: Int) {
    let pad = String(repeating: "  ", count: indent)
    if entity.ct.type == "multipart" && entity.parts != nil {
        print("\(pad)multipart/\(entity.ct.subtype) parts=\(entity.parts!.count)")
        for part in entity.parts! { printTree(part, indent + 1) }
    } else if entity.ct.type == "text" && entity.dispType != "attachment" {
        let charset = getCharset(entity)
        let text = decodeTextBody(entity)
        let n = text.count
        print("\(pad)text/\(entity.ct.subtype) charset=\(charset) cte=\(entity.cte) chars=\(n)")
        print("\(pad)  \(qstr(text))")
    } else {
        let raw = decodeBodyBytes(entity)
        let size = raw.count
        let crc = crc32(raw)
        let name = getFileName(entity)
        let disp = entity.dispType ?? "-"
        print("\(pad)\(entity.ct.type)/\(entity.ct.subtype) cte=\(entity.cte) disposition=\(disp) name=\(name) size=\(size) crc32=\(String(format: "%08x", crc))")
    }
}

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { exit(0) }
