    lines.append((cur, false))

    var headerLines: [[UInt8]] = []
    var bodyStart = 0
    var li = 0
    while li < lines.count {
        if lines[li].content.isEmpty {
            li += 1; bodyStart = li; break
        } else if lines[li].content[0] == 0x20 || lines[li].content[0] == 0x09 {
            if !headerLines.isEmpty { headerLines[headerLines.count-1].append(contentsOf: lines[li].content) }
            li += 1
        } else {
            headerLines.append(lines[li].content); li += 1
        }
    }

    var headers: [(String, [UInt8])] = []
    for hl in headerLines {
        var j = 0; var nameB: [UInt8] = []
        while j < hl.count && hl[j] != 0x3A { nameB.append(hl[j]); j += 1 }
        if j < hl.count { j += 1 }
        while j < hl.count && (hl[j] == 0x20 || hl[j] == 0x09) { j += 1 }
        var valB = Array(hl[j...])
        while let last = valB.last, last == 0x20 || last == 0x09 { valB.removeLast() }
        let name = String(bytes: nameB, encoding: .ascii)?.lowercased() ?? ""
        headers.append((name, valB))
    }

    var body: [UInt8] = []
    if bodyStart < lines.count {
        for (idx, line) in lines[bodyStart...].enumerated() {
            body.append(contentsOf: line.content)
            if idx < lines.count - bodyStart - 1 { body.append(contentsOf: lb) }
            else if isTop && line.hasLB { body.append(contentsOf: lb) }
        }
    }

    let ctVal = getHeaderVal(headers, "content-type")
    let ct: (type: String, subtype: String, params: [(String, [UInt8])])
    if let cv = ctVal { ct = parseCT(cv) } else { ct = ("text", "plain", []) }

    let cteVal = getHeaderVal(headers, "content-transfer-encoding")
    let cte: String
    if let cv = cteVal {
        let s = String(bytes: cv, encoding: .ascii)?.trimmingCharacters(in: CharacterSet(charactersIn: " \t")).lowercased() ?? "7bit"
        cte = s
    } else { cte = "7bit" }

