    }

    return Entity(headers: headers, body: body, lb: lb, ct: ct, cte: cte, dispType: cd.type, dispParams: cd.params, parts: parts)
}

func parseMultipart(_ body: [UInt8], _ boundary: String, _ lb: [UInt8]) -> [Entity] {
    let delim = Array("--\(boundary)".utf8)
    let closeDelim = Array("--\(boundary)--".utf8)

    struct LPos { var start: Int; var content: [UInt8]; var hasLB: Bool }
    var lines: [LPos] = []
    var i = 0
    while i < body.count {
        var le = i
        while le < body.count {
            if le + lb.count <= body.count && Array(body[le..<le+lb.count]) == lb { break }
            le += 1
        }
        let hasLB = le + lb.count <= body.count
        lines.append(LPos(start: i, content: Array(body[i..<le]), hasLB: hasLB))
        i = hasLB ? le + lb.count : le
    }

    var delimIdx: [Int] = []
    var closeIdx = -1
    for (li, line) in lines.enumerated() {
        var sc = line.content
        while let last = sc.last, last == 0x20 || last == 0x09 { sc.removeLast() }
        if sc == closeDelim { closeIdx = li; break }
        if sc == delim { delimIdx.append(li) }
    }

    var allD = delimIdx
    if closeIdx >= 0 { allD.append(closeIdx) }

    var parts: [Entity] = []
    for k in 0..<allD.count-1 {
        let sl = allD[k]; let el = allD[k+1]
        var partBytes: [UInt8] = []
        var li = sl + 1
        while li <= el - 1 {
            partBytes.append(contentsOf: lines[li].content)
            if li < el - 1 { partBytes.append(contentsOf: lb) }
            li += 1
        }
        parts.append(parseEntity(partBytes, lb, false))
    }
    return parts
}

func decodeBodyBytes(_ entity: Entity) -> [UInt8] {
    switch entity.cte {
    case "base64": return b64dec(entity.body)
    case "quoted-printable": return qpdec(entity.body, entity.lb)
    default: return entity.body
    }
}

func getCharset(_ entity: Entity) -> String {
    if let cv = getParam(entity.ct.params, "charset") {
