        self.params = params
        self.body = body
        self.scope = scope
        self.name = name

class BuiltinFunction:
    __slots__ = ('fn', 'name', 'arity')
    def __init__(self, fn, name, arity):
        self.fn = fn
        self.name = name
        self.arity = arity

class Scope:
    __slots__ = ('vars', 'parent')
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def lookup(self, name):
        s = self
        while s is not None:
            v = s.vars.get(name)
            if v is not None or name in s.vars:
                return v
            s = s.parent
        return None

    def assign(self, name, val):
        s = self
        while s is not None:
            if name in s.vars:
                s.vars[name] = val
                return True
            s = s.parent
        return False

    def declare(self, name, val):
        self.vars[name] = val


KEYWORDS = frozenset(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil'])


def lex(source):
    tokens = []
    i = 0
    line = 1
    n = len(source)
    while i < n:
        c = source[i]
        if c == ' ' or c == '\t' or c == '\r':
            i += 1
            continue
        if c == '\n':
            line += 1
            i += 1
            continue
        if c == '#':
            while i < n and source[i] != '\n':
                i += 1
            continue
        if c == '"':
            i += 1
            parts = []
            while i < n and source[i] != '"':
                if source[i] == '\\':
                    i += 1
                    ec = source[i]
                    if ec == 'n': parts.append('\n')
                    elif ec == 't': parts.append('\t')
                    elif ec == '"': parts.append('"')
                    else: parts.append('\\')
                    i += 1
                else:
                    parts.append(source[i])
                    i += 1
            i += 1
            tokens.append(('STRING', ''.join(parts), line))
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= source[j] <= '9':
                j += 1
            tokens.append(('INT', int(source[i:j]), line))
            i = j
            continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (source[j].isalnum() or source[j] == '_'):
                j += 1
            word = source[i:j]
            if word in KEYWORDS:
                tokens.append((word, word, line))
            else:
                tokens.append(('IDENT', word, line))
            i = j
            continue
        if c == '=' and i+1 < n and source[i+1] == '=':
            tokens.append(('==', '==', line)); i += 2; continue
        if c == '!' and i+1 < n and source[i+1] == '=':
            tokens.append(('!=', '!=', line)); i += 2; continue
        if c == '<' and i+1 < n and source[i+1] == '=':
            tokens.append(('<=', '<=', line)); i += 2; continue
        if c == '>' and i+1 < n and source[i+1] == '=':
            tokens.append(('>=', '>=', line)); i += 2; continue
        if c in '+-*/%()[]{},;=':
            tokens.append((c, c, line)); i += 1; continue
        i += 1
    tokens.append(('EOF', None, line))
    return tokens


class Parser:
    __slots__ = ('tokens', 'pos')
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def expect(self, tt):
        self.pos += 1

    def parse_program(self):
        stmts = []
        while self.tokens[self.pos][0] != 'EOF':
            stmts.append(self.parse_stmt())
        return stmts

    def parse_block(self):
        self.pos += 1  # {
        stmts = []
        while self.tokens[self.pos][0] != '}':
            stmts.append(self.parse_stmt())
        self.pos += 1  # }
        return stmts

    def parse_stmt(self):
        t = self.tokens[self.pos]
        tt = t[0]
        if tt == 'let':
            self.pos += 1
            name = self.tokens[self.pos][1]; self.pos += 1
            self.pos += 1  # =
            val = self.parse_expr()
            self.pos += 1  # ;
            return ('let', name, val, t[2])
        elif tt == 'fn':
            self.pos += 1
            name = self.tokens[self.pos][1]; self.pos += 1
            self.pos += 1  # (
            params = self.parse_params()
            self.pos += 1  # )
            body = self.parse_block()
            return ('fn_decl', name, params, body, t[2])
        elif tt == 'if':
            return self.parse_if()
        elif tt == 'while':
            self.pos += 1
            cond = self.parse_expr()
            body = self.parse_block()
            return ('while', cond, body, t[2])
        elif tt == 'for':
            self.pos += 1
            var = self.tokens[self.pos][1]; self.pos += 1
            self.pos += 1  # in
            iterable = self.parse_expr()
            body = self.parse_block()
            return ('for', var, iterable, body, t[2])
        elif tt == 'return':
            self.pos += 1
            if self.tokens[self.pos][0] == ';':
                self.pos += 1
                return ('return', None, t[2])
            val = self.parse_expr()
            self.pos += 1  # ;
            return ('return', val, t[2])
        elif tt == 'break':
            self.pos += 2  # break ;
            return ('break', t[2])
        elif tt == 'continue':
            self.pos += 2  # continue ;
            return ('continue', t[2])
        else:
            expr = self.parse_expr()
            if self.tokens[self.pos][0] == '=':
                self.pos += 1  # =
                val = self.parse_expr()
                self.pos += 1  # ;
                if expr[0] == 'ident':
                    return ('assign', expr[1], val, expr[2])
                elif expr[0] == 'index':
                    return ('index_assign', expr[1], expr[2], val, expr[3])
            else:
                self.pos += 1  # ;
                return ('expr_stmt', expr, expr[2])

    def parse_params(self):
        params = []
        if self.tokens[self.pos][0] == ')':
            return params
        params.append(self.tokens[self.pos][1]); self.pos += 1
        while self.tokens[self.pos][0] == ',':
            self.pos += 1
            params.append(self.tokens[self.pos][1]); self.pos += 1
        return params

    def parse_if(self):
        t = self.advance()
        cond = self.parse_expr()
        then_block = self.parse_block()
        else_block = None
        if self.tokens[self.pos][0] == 'else':
            self.pos += 1
            if self.tokens[self.pos][0] == 'if':
                else_block = self.parse_if()
            else:
                else_block = self.parse_block()
        return ('if', cond, then_block, else_block, t[2])

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.tokens[self.pos][0] == 'or':
            t = self.advance()
            right = self.parse_and()
            left = ('or', left, right, t[2])
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.tokens[self.pos][0] == 'and':
            t = self.advance()
            right = self.parse_not()
            left = ('and', left, right, t[2])
        return left

    def parse_not(self):
        if self.tokens[self.pos][0] == 'not':
            t = self.advance()
            operand = self.parse_not()
            return ('not', operand, t[2])
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        while self.tokens[self.pos][0] in ('==','!=','<','<=','>','>='):
            t = self.advance()
            right = self.parse_additive()
            left = ('binary', t[0], left, right, t[2])
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.tokens[self.pos][0] in ('+','-'):
            t = self.advance()
            right = self.parse_multiplicative()
            left = ('binary', t[0], left, right, t[2])
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.tokens[self.pos][0] in ('*','/','%'):
            t = self.advance()
            right = self.parse_unary()
            left = ('binary', t[0], left, right, t[2])
        return left

    def parse_unary(self):
        if self.tokens[self.pos][0] == '-':
            t = self.advance()
            operand = self.parse_unary()
            return ('unary', '-', operand, t[2])
        return self.parse_postfix()

    def parse_postfix(self):
        expr = self.parse_primary()
        while True:
            tt = self.tokens[self.pos][0]
            if tt == '(':
                t = self.advance()
                args = []
                if self.tokens[self.pos][0] != ')':
                    args.append(self.parse_expr())
                    while self.tokens[self.pos][0] == ',':
                        self.pos += 1
                        args.append(self.parse_expr())
                self.pos += 1  # )
                expr = ('call', expr, args, t[2])
            elif tt == '[':
                t = self.advance()
                idx = self.parse_expr()
                self.pos += 1  # ]
                expr = ('index', expr, idx, t[2])
            else:
                break
        return expr

    def parse_primary(self):
        t = self.tokens[self.pos]
        tt = t[0]
        if tt == 'INT':
            self.pos += 1
            return ('int', t[1], t[2])
        elif tt == 'STRING':
            self.pos += 1
            return ('str', t[1], t[2])
        elif tt == 'true':
            self.pos += 1
            return ('bool', True, t[2])
        elif tt == 'false':
            self.pos += 1
            return ('bool', False, t[2])
        elif tt == 'nil':
            self.pos += 1
            return ('nil', t[2])
        elif tt == 'IDENT':
            self.pos += 1
            return ('ident', t[1], t[2])
        elif tt == '(':
            self.pos += 1
            expr = self.parse_expr()
            self.pos += 1  # )
            return expr
        elif tt == '[':
            self.pos += 1
            elems = []
            if self.tokens[self.pos][0] != ']':
                elems.append(self.parse_expr())
                while self.tokens[self.pos][0] == ',':
                    self.pos += 1
                    elems.append(self.parse_expr())
            self.pos += 1  # ]
            return ('list', elems, t[2])
        elif tt == 'fn':
            self.pos += 1
            self.pos += 1  # (
            params = self.parse_params()
            self.pos += 1  # )
            body = self.parse_block()
            return ('fn', params, body, t[2])
        else:
            self.pos += 1
            return ('nil', t[2])


def tern_type(v):
    if v is NIL: return "nil"
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "list"
    if isinstance(v, (TernFunction, BuiltinFunction)): return "function"
    return "nil"

def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


class Interpreter:
    __slots__ = ('global_scope',)

    def __init__(self):
        self.global_scope = Scope()
        builtin_scope = Scope()
        self.global_scope.parent = builtin_scope
        builtin_scope.declare('print', BuiltinFunction(self._print, 'print', -1))
        builtin_scope.declare('str', BuiltinFunction(self._str, 'str', 1))
        builtin_scope.declare('type', BuiltinFunction(self._type, 'type', 1))
        builtin_scope.declare('len', BuiltinFunction(self._len, 'len', 1))
        builtin_scope.declare('push', BuiltinFunction(self._push, 'push', 2))
        builtin_scope.declare('pop', BuiltinFunction(self._pop, 'pop', 1))
        builtin_scope.declare('range', BuiltinFunction(self._range, 'range', 2))
        builtin_scope.declare('slice', BuiltinFunction(self._slice, 'slice', 3))

    def _print(self, args, line):
        parts = [self.display(v) for v in args]
        sys.stdout.write(' '.join(parts) + '\n')
        return NIL

    def _str(self, args, line):
        return self.display(args[0])

    def _type(self, args, line):
        return tern_type(args[0])

    def _len(self, args, line):
        v = args[0]
        if isinstance(v, str) or isinstance(v, list):
            return len(v)
        raise TernError(line, "bad argument to len")

    def _push(self, args, line):
        lst, val = args
        if not isinstance(lst, list):
            raise TernError(line, "bad argument to push")
        lst.append(val)
        return NIL

    def _pop(self, args, line):
        lst = args[0]
        if not isinstance(lst, list) or len(lst) == 0:
            raise TernError(line, "bad argument to pop")
        return lst.pop()

    def _range(self, args, line):
        a, b = args
        if not is_int(a) or not is_int(b):
            raise TernError(line, "bad argument to range")
        return list(range(a, b))

    def _slice(self, args, line):
        x, a, b = args
        if not is_int(a) or not is_int(b):
            raise TernError(line, "bad argument to slice")
        if isinstance(x, str):
            if a < 0 or b > len(x) or a > b:
                raise TernError(line, "bad argument to slice")
            return x[a:b]
        elif isinstance(x, list):
            if a < 0 or b > len(x) or a > b:
                raise TernError(line, "bad argument to slice")
            return x[a:b]
        raise TernError(line, "bad argument to slice")

    def display(self, v, seen=None):
        if seen is None:
            seen = set()
        if v is NIL:
            return "nil"
        if isinstance(v, bool):
            return "true" if v else "false"
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            return v
        if isinstance(v, list):
            vid = id(v)
            if vid in seen:
                return "[...]"
            seen.add(vid)
            parts = [self._display_elem(e, seen) for e in v]
            seen.discard(vid)
            return "[" + ", ".join(parts) + "]"
        return "<fn>"

    def _display_elem(self, v, seen):
        if isinstance(v, str):
            s = v.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\t', '\\t')
            return '"' + s + '"'
        if isinstance(v, list):
            vid = id(v)
            if vid in seen:
                return "[...]"
            seen.add(vid)
            parts = [self._display_elem(e, seen) for e in v]
            seen.discard(vid)
            return "[" + ", ".join(parts) + "]"
        if v is NIL:
            return "nil"
        if isinstance(v, bool):
            return "true" if v else "false"
        if isinstance(v, int):
            return str(v)
        return "<fn>"

    def truthy(self, v):
        if v is NIL:
            return False
        if isinstance(v, bool):
            return v
        if isinstance(v, int):
            return v != 0
        if isinstance(v, str):
            return len(v) > 0
        if isinstance(v, list):
            return len(v) > 0
        return True

    def tern_eq(self, a, b):
        if a is NIL and b is NIL:
            return True
        if a is NIL or b is NIL:
            return False
        ab = isinstance(a, bool)
        bb = isinstance(b, bool)
        if ab and bb:
            return a == b
        if ab or bb:
            return False
        ai = isinstance(a, int)
        bi = isinstance(b, int)
        if ai and bi:
            return a == b
        if ai or bi:
            return False
        if isinstance(a, str) and isinstance(b, str):
            return a == b
        if isinstance(a, list) and isinstance(b, list):
            if len(a) != len(b):
                return False
            for x, y in zip(a, b):
                if not self.tern_eq(x, y):
                    return False
            return True
        if isinstance(a, (TernFunction, BuiltinFunction)) and isinstance(b, (TernFunction, BuiltinFunction)):
            return a is b
        return False

    def exec_program(self, stmts):
        for stmt in stmts:
            self.exec_stmt(stmt, self.global_scope)

    def exec_block(self, stmts, scope):
        for stmt in stmts:
            self.exec_stmt(stmt, scope)

    def exec_stmt(self, stmt, scope):
        tag = stmt[0]
        if tag == 'let':
            name = stmt[1]
            v = self.eval_expr(stmt[2], scope)
            scope.declare(name, v)
        elif tag == 'fn_decl':
            name = stmt[1]
            func = TernFunction(stmt[2], stmt[3], scope, name)
            scope.declare(name, func)
        elif tag == 'if':
            cond = stmt[1]
            v = self.eval_expr(cond, scope)
            if self.truthy(v):
                new_scope = Scope(scope)
                self.exec_block(stmt[2], new_scope)
            elif stmt[3] is not None:
                eb = stmt[3]
                if isinstance(eb, list):
                    new_scope = Scope(scope)
                    self.exec_block(eb, new_scope)
                else:
                    self.exec_stmt(eb, scope)
        elif tag == 'while':
            cond = stmt[1]
            body = stmt[2]
            while True:
                v = self.eval_expr(cond, scope)
                if not self.truthy(v):
                    break
                new_scope = Scope(scope)
                try:
                    self.exec_block(body, new_scope)
                except BreakSignal:
                    break
                except ContinueSignal:
                    continue
        elif tag == 'for':
            var = stmt[1]
            lst = self.eval_expr(stmt[2], scope)
            if not isinstance(lst, list):
                raise TernError(stmt[4], f"cannot iterate {tern_type(lst)}")
            body = stmt[3]
            i = 0
            while i < len(lst):
                new_scope = Scope(scope)
                new_scope.declare(var, lst[i])
                try:
                    self.exec_block(body, new_scope)
                except BreakSignal:
                    break
                except ContinueSignal:
                    pass
                i += 1
        elif tag == 'return':
            val = stmt[1]
            if val is not None:
                raise ReturnSignal(self.eval_expr(val, scope))
            else:
                raise ReturnSignal(NIL)
        elif tag == 'break':
            raise BreakSignal()
        elif tag == 'continue':
            raise ContinueSignal()
        elif tag == 'assign':
            name = stmt[1]
            v = self.eval_expr(stmt[2], scope)
            if not scope.assign(name, v):
                raise TernError(stmt[3], f"undefined variable {name}")
        elif tag == 'index_assign':
            obj_node = stmt[1]
            idx_node = stmt[2]
            val_node = stmt[3]
            line = stmt[4]
            obj_val = self.eval_expr(obj_node, scope)
            idx_val = self.eval_expr(idx_node, scope)
            v = self.eval_expr(val_node, scope)
            if not isinstance(obj_val, list):
                raise TernError(line, f"cannot assign into {tern_type(obj_val)}")
            if not is_int(idx_val):
                raise TernError(line, f"cannot index list with {tern_type(idx_val)}")
            if idx_val < 0 or idx_val >= len(obj_val):
                raise TernError(line, f"index {idx_val} out of range for length {len(obj_val)}")
            obj_val[idx_val] = v
        elif tag == 'expr_stmt':
            self.eval_expr(stmt[1], scope)

    def eval_expr(self, node, scope):
        tag = node[0]
        if tag == 'int':
            return node[1]
        elif tag == 'str':
            return node[1]
        elif tag == 'bool':
            return node[1]
        elif tag == 'nil':
            return NIL
        elif tag == 'ident':
            name = node[1]
            line = node[2]
            s = scope
            while s is not None:
                if name in s.vars:
                    return s.vars[name]
                s = s.parent
            raise TernError(line, f"undefined variable {name}")
        elif tag == 'list':
            elems = node[1]
            return [self.eval_expr(e, scope) for e in elems]
        elif tag == 'fn':
            return TernFunction(node[1], node[2], scope)
        elif tag == 'binary':
            op = node[1]
            lv = self.eval_expr(node[2], scope)
            rv = self.eval_expr(node[3], scope)
            return self.binary_op(op, lv, rv, node[4])
        elif tag == 'and':
            lv = self.eval_expr(node[1], scope)
            if not self.truthy(lv):
                return lv
            return self.eval_expr(node[2], scope)
        elif tag == 'or':
            lv = self.eval_expr(node[1], scope)
            if self.truthy(lv):
                return lv
            return self.eval_expr(node[2], scope)
        elif tag == 'not':
            v = self.eval_expr(node[1], scope)
            return not self.truthy(v)
        elif tag == 'unary':
            v = self.eval_expr(node[2], scope)
            if isinstance(v, bool) or not isinstance(v, int):
                raise TernError(node[3], f"cannot apply - to {tern_type(v)}")
            result = -v
            if result < INT_MIN or result > INT_MAX:
                raise TernError(node[3], "integer overflow")
            return result
        elif tag == 'call':
            func = self.eval_expr(node[1], scope)
            args = [self.eval_expr(a, scope) for a in node[2]]
            return self.call_func(func, args, node[3])
        elif tag == 'index':
            obj_val = self.eval_expr(node[1], scope)
            idx_val = self.eval_expr(node[2], scope)
            line = node[3]
            if isinstance(obj_val, list):
                if not is_int(idx_val):
                    raise TernError(line, f"cannot index list with {tern_type(idx_val)}")
                if idx_val < 0 or idx_val >= len(obj_val):
                    raise TernError(line, f"index {idx_val} out of range for length {len(obj_val)}")
                return obj_val[idx_val]
            elif isinstance(obj_val, str):
                if not is_int(idx_val):
                    raise TernError(line, f"cannot index string with {tern_type(idx_val)}")
                if idx_val < 0 or idx_val >= len(obj_val):
                    raise TernError(line, f"index {idx_val} out of range for length {len(obj_val)}")
                return obj_val[idx_val]
            else:
                raise TernError(line, f"cannot index {tern_type(obj_val)} with {tern_type(idx_val)}")
        return NIL

    def binary_op(self, op, lv, rv, line):
        if op == '+':
            if isinstance(lv, bool) or isinstance(rv, bool):
                raise TernError(line, f"cannot apply + to {tern_type(lv)} and {tern_type(rv)}")
            if isinstance(lv, int) and isinstance(rv, int):
                r = lv + rv
                if r < INT_MIN or r > INT_MAX:
                    raise TernError(line, "integer overflow")
                return r
            if isinstance(lv, str) and isinstance(rv, str):
                return lv + rv
            if isinstance(lv, list) and isinstance(rv, list):
                return lv + rv
            raise TernError(line, f"cannot apply + to {tern_type(lv)} and {tern_type(rv)}")
        elif op == '-':
            if isinstance(lv, bool) or isinstance(rv, bool):
                raise TernError(line, f"cannot apply - to {tern_type(lv)} and {tern_type(rv)}")
            if isinstance(lv, int) and isinstance(rv, int):
                r = lv - rv
                if r < INT_MIN or r > INT_MAX:
                    raise TernError(line, "integer overflow")
                return r
            raise TernError(line, f"cannot apply - to {tern_type(lv)} and {tern_type(rv)}")
        elif op == '*':
            if isinstance(lv, bool) or isinstance(rv, bool):
                raise TernError(line, f"cannot apply * to {tern_type(lv)} and {tern_type(rv)}")
            if isinstance(lv, int) and isinstance(rv, int):
                r = lv * rv
                if r < INT_MIN or r > INT_MAX:
                    raise TernError(line, "integer overflow")
                return r
            raise TernError(line, f"cannot apply * to {tern_type(lv)} and {tern_type(rv)}")
        elif op == '/':
            if isinstance(lv, bool) or isinstance(rv, bool):
                raise TernError(line, f"cannot apply / to {tern_type(lv)} and {tern_type(rv)}")
            if isinstance(lv, int) and isinstance(rv, int):
                if rv == 0:
                    raise TernError(line, "division by zero")
                q = lv // rv
                if (lv ^ rv) < 0 and lv % rv != 0:
                    q += 1
