import sys
import os

sys.setrecursionlimit(10000)

INT_MIN = -(2**63)
INT_MAX = 2**63 - 1

class NilType:
    __slots__ = ()
    def __repr__(self):
        return "nil"

NIL = NilType()

class TernError(Exception):
    __slots__ = ('line', 'message')
    def __init__(self, line, message):
        self.line = line
        self.message = message

class BreakSignal(Exception):
    __slots__ = ()

class ContinueSignal(Exception):
    __slots__ = ()

class ReturnSignal(Exception):
    __slots__ = ('value',)
    def __init__(self, value):
        self.value = value

class TernFunction:
    __slots__ = ('params', 'body', 'scope', 'name')
    def __init__(self, params, body, scope, name=None):
        self.params = params
        self.body = body
        self.scope = scope
        self.name = name

class BuiltinFunction:
    __slots__ = ('fn', 'name', 'arity')
    def __init__(self, fn, name, arity):
        self.fn = fn
        self.name = name
        self.arity = arity

class Scope:
    __slots__ = ('vars', 'parent')
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def lookup(self, name):
        s = self
        while s is not None:
            if name in s.vars:
                return s.vars[name]
            s = s.parent
        return None

    def assign(self, name, val):
        s = self
        while s is not None:
            if name in s.vars:
                s.vars[name] = val
                return True
            s = s.parent
        return False

    def declare(self, name, val):
        self.vars[name] = val


KEYWORDS = frozenset(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil'])


def lex(source):
    tokens = []
    i = 0
    line = 1
    n = len(source)
    while i < n:
        c = source[i]
        if c == ' ' or c == '\t' or c == '\r':
            i += 1
            continue
        if c == '\n':
            line += 1
            i += 1
            continue
        if c == '#':
            while i < n and source[i] != '\n':
                i += 1
            continue
        if c == '"':
            i += 1
            parts = []
            while i < n and source[i] != '"':
                if source[i] == '\\':
                    i += 1
                    ec = source[i]
                    if ec == 'n': parts.append('\n')
                    elif ec == 't': parts.append('\t')
                    elif ec == '"': parts.append('"')
                    else: parts.append('\\')
                    i += 1
                else:
                    parts.append(source[i])
                    i += 1
            i += 1
            tokens.append(('STRING', ''.join(parts), line))
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= source[j] <= '9':
                j += 1
            tokens.append(('INT', int(source[i:j]), line))
            i = j
            continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (source[j].isalnum() or source[j] == '_'):
                j += 1
            word = source[i:j]
            if word in KEYWORDS:
                tokens.append((word, word, line))
            else:
                tokens.append(('IDENT', word, line))
            i = j
            continue
        if c == '=' and i+1 < n and source[i+1] == '=':
            tokens.append(('==', '==', line)); i += 2; continue
        if c == '!' and i+1 < n and source[i+1] == '=':
            tokens.append(('!=', '!=', line)); i += 2; continue
        if c == '<' and i+1 < n and source[i+1] == '=':
            tokens.append(('<=', '<=', line)); i += 2; continue
        if c == '>' and i+1 < n and source[i+1] == '=':
            tokens.append(('>=', '>=', line)); i += 2; continue
        if c in '+-*/%()[]{},;=':
            tokens.append((c, c, line)); i += 1; continue
        i += 1
    tokens.append(('EOF', None, line))
    return tokens


