// ===== Tree node =====
interface TreeNode {
  kind: 'multipart' | 'text' | 'other';
  type: string;
  subtype: string;
  parts?: TreeNode[];
  charset?: string;
  cte?: string;
  text?: string;
  chars?: number;
  disposition?: string;
  name?: string;
  size?: number;
  crc?: number;
