function buildTree(entity: Entity): TreeNode {
  const ctVal = entity.headers.get('content-type');
  let ct: ParsedCT;
  if (ctVal) {
    ct = parseContentType(ctVal);
  } else {
    ct = { type: 'text', subtype: 'plain', params: new Map([['charset', 'us-ascii']]) };
  }

  const cteRaw = entity.headers.get('content-transfer-encoding');
  const cte = cteRaw ? cteRaw.toLowerCase() : '7bit';

  const dispRaw = entity.headers.get('content-disposition');
  let dispType: string | null = null;
  let dispParams: Map<string, string> = new Map();
  if (dispRaw) {
    const dp = parseContentType(dispRaw); // same syntax
    dispType = dp.type.toLowerCase(); // 'inline' or 'attachment'
    dispParams = dp.params;
  }

  if (ct.type === 'multipart') {
    const boundary = ct.params.get('boundary');
    let parts: TreeNode[] = [];
    if (boundary) {
      const bodyStr = entity.body.toString('latin1');
      const bodyLines = bodyStr.split(entity.lb);
      const partLines = extractMultipartParts(bodyLines, boundary);
      for (const pl of partLines) {
        const partRaw = Buffer.from(pl.join(entity.lb), 'latin1');
        const partEntity = parseEntity(partRaw, entity.lb);
        parts.push(buildTree(partEntity));
      }
    }
    return { kind: 'multipart', type: ct.type, subtype: ct.subtype, parts };
  }

  // Transfer decode
  const decoded = transferDecode(entity.body, cte, entity.lb);

  // Determine if text part
  const isText = ct.type === 'text' && dispType !== 'attachment';

  if (isText) {
    const charset = (ct.params.get('charset') || 'us-ascii').toLowerCase();
    let text = decodeCharset(decoded, charset);
    // Normalize line endings
    text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    const chars = [...text].length;
    return { kind: 'text', type: ct.type, subtype: ct.subtype, charset, cte, text, chars };
  }

  // Other part
  const name = getFileName(entity, ct, dispParams, dispRaw);
  return {
    kind: 'other',
    type: ct.type,
    subtype: ct.subtype,
    cte,
    disposition: dispType || '-',
    name,
    size: decoded.length,
    crc: crc32(decoded),
  };
}

function getFileName(entity: Entity, ct: ParsedCT, dispParams: Map<string, string>, dispRaw: string | null): string {
  // 1. Content-Disposition filename RFC 2231
  if (dispRaw) {
    const r = getRfc2231Name(dispParams, 'filename');
    if (r !== null) return r;
    // 2. Content-Disposition filename (plain)
    if (dispParams.has('filename')) {
      return decodeRfc2047(dispParams.get('filename')!);
    }
  }
  // 3. Content-Type name RFC 2231
  const r2 = getRfc2231Name(ct.params, 'name');
  if (r2 !== null) return r2;
  // 4. Content-Type name (plain)
  if (ct.params.has('name')) {
    return decodeRfc2047(ct.params.get('name')!);
  }
