// ===== Quoted string output =====
function quoteStr(s: string): string {
  let r = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (ch === '\\') r += '\\\\';
    else if (ch === '"') r += '\\"';
    else if (cp === 0x0A) r += '\\n';
    else if (cp === 0x09) r += '\\t';
    else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) r += '\\u' + cp.toString(16).padStart(4, '0');
    else r += ch;
  }
  r += '"';
  return r;
}

// ===== Print tree =====
function printTree(node: TreeNode, indent: number, out: string[]): void {
  const pad = '  '.repeat(indent);
  if (node.kind === 'multipart') {
    out.push(`${pad}multipart/${node.subtype} parts=${node.parts!.length}`);
    for (const p of node.parts!) printTree(p, indent + 1, out);
  } else if (node.kind === 'text') {
    out.push(`${pad}text/${node.subtype} charset=${node.charset} cte=${node.cte} chars=${node.chars}`);
    out.push(`${pad}  ${quoteStr(node.text!)}`);
  } else {
    const nameStr = node.name ? quoteStr(node.name) : '-';
    out.push(`${pad}${node.type}/${node.subtype} cte=${node.cte} disposition=${node.disposition} name=${nameStr} size=${node.size} crc32=${node.crc!.toString(16).padStart(8, '0')}`);
