}

// ===== Main =====
function main(): void {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir)
    .filter(f => f.endsWith('.eml'))
    .sort((a, b) => {
      const ab = Buffer.from(a, 'utf-8');
      const bb = Buffer.from(b, 'utf-8');
      return Buffer.compare(ab, bb);
    });

