    if (fi > 0) output.push('');
    const fname = files[fi];
    const raw = fs.readFileSync(path.join(dir, fname));
    // Detect line break
    const lb = raw.includes(0x0D) && raw.includes(0x0A) ? '\r\n' : '\n';
    // Check for \r\n specifically
    let hasCRLF = false;
    for (let i = 0; i < raw.length - 1; i++) {
      if (raw[i] === 0x0D && raw[i+1] === 0x0A) { hasCRLF = true; break; }
