    const entity = parseEntity(raw, lineBreak);
    output.push(`== ${fname}`);

    const fromRaw = entity.headers.get('from');
    const subjRaw = entity.headers.get('subject');
    const fromVal = fromRaw !== undefined ? quoteStr(decodeRfc2047(fromRaw)) : '-';
    const subjVal = subjRaw !== undefined ? quoteStr(decodeRfc2047(subjRaw)) : '-';
    output.push(`From: ${fromVal}`);
    output.push(`Subject: ${subjVal}`);

    const tree = buildTree(entity);
    printTree(tree, 0, output);
  }

  process.stdout.write(output.join('\n') + '\n');
}

