    static void writeChunk(ByteArrayOutputStream out, String type, byte[] data) throws IOException {
        int len = data.length;
        out.write((len >> 24) & 0xFF);
        out.write((len >> 16) & 0xFF);
        out.write((len >> 8) & 0xFF);
        out.write(len & 0xFF);
        byte[] typeBytes = type.getBytes("US-ASCII");
        out.write(typeBytes);
        out.write(data);
        byte[] crcInput = new byte[4 + len];
        System.arraycopy(typeBytes, 0, crcInput, 0, 4);
        System.arraycopy(data, 0, crcInput, 4, len);
        int crc = crc32(crcInput, 0, crcInput.length);
        out.write((crc >> 24) & 0xFF);
        out.write((crc >> 16) & 0xFF);
        out.write((crc >> 8) & 0xFF);
        out.write(crc & 0xFF);
    }
