fn find_ew(b: &[u8], start: usize) -> Option<(usize, usize, String, u8, Vec<u8>)> {
    let mut pos = start;
    while pos + 1 < b.len() {
        if b[pos] == b'=' && b[pos+1] == b'?' {
            let ws = pos;
            let mut p = pos + 2;
            let cs_s = p;
            while p < b.len() && b[p] != b'?' && b[p] != b' ' && b[p] != b'\t' { p += 1; }
            if p >= b.len() || b[p] != b'?' || p == cs_s { pos += 1; continue; }
            let cs_raw = String::from_utf8_lossy(&b[cs_s..p]).to_lowercase();
            p += 1;
            if p >= b.len() { pos += 1; continue; }
            let enc = b[p];
            if enc != b'B' && enc != b'b' && enc != b'Q' && enc != b'q' { pos += 1; continue; }
            p += 1;
            if p >= b.len() || b[p] != b'?' { pos += 1; continue; }
            p += 1;
            let et_s = p;
            while p < b.len() && b[p] != b'?' && b[p] != b' ' && b[p] != b'\t' { p += 1; }
            let et = b[et_s..p].to_vec();
            if p + 1 >= b.len() || b[p] != b'?' || b[p+1] != b'=' { pos += 1; continue; }
            p += 2;
            let cs = if let Some(i) = cs_raw.find('*') { cs_raw[..i].to_string() } else { cs_raw };
