fn get_filename(ct_params: &BTreeMap<String, String>, disp_params: &BTreeMap<String, String>) -> Option<String> {
    if let Some(v) = get_rfc2231(disp_params, "filename") { return Some(v); }
    if let Some(v) = disp_params.get("filename") { return Some(decode_rfc2047(v)); }
    if let Some(v) = get_rfc2231(ct_params, "name") { return Some(v); }
    if let Some(v) = ct_params.get("name") { return Some(decode_rfc2047(v)); }
    None
}

fn get_rfc2231(params: &BTreeMap<String, String>, attr: &str) -> Option<String> {
    let single = format!("{}*", attr);
    if let Some(val) = params.get(&single) {
        let (cs, enc) = split_cs_prefix(val);
        let bytes = pct_decode(enc.as_bytes());
        return Some(decode_charset(&bytes, &cs));
    }
    let prefix = format!("{}*", attr);
    let mut segs: BTreeMap<usize, (bool, String)> = BTreeMap::new();
    for (k, v) in params {
        if k.starts_with(&prefix) && k.len() > prefix.len() {
            let rest = &k[prefix.len()..];
            let (ns, pct) = if rest.ends_with('*') { (&rest[..rest.len()-1], true) } else { (rest, false) };
            if let Ok(n) = ns.parse::<usize>() { segs.insert(n, (pct, v.clone())); }
        }
    }
    if segs.is_empty() { return None; }
    let mut all = Vec::new();
    let mut cs = String::from("us-ascii");
    for (idx, (pct, val)) in &segs {
        if *idx == 0 && *pct {
            let (c, e) = split_cs_prefix(val);
            cs = c;
            all.extend_from_slice(&pct_decode(e.as_bytes()));
        } else if *pct {
            all.extend_from_slice(&pct_decode(val.as_bytes()));
        } else {
            all.extend_from_slice(val.as_bytes());
        }
    }
    Some(decode_charset(&all, &cs))
}

fn split_cs_prefix(s: &str) -> (String, &str) {
    if let Some(q1) = s.find('\'') {
        let cs = s[..q1].to_lowercase();
        let after = &s[q1+1..];
        if let Some(q2) = after.find('\'') { return (cs, &after[q2+1..]); }
        return (cs, after);
    }
    (String::from("us-ascii"), s)
}

fn pct_decode(s: &[u8]) -> Vec<u8> {
    let mut r = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'%' && i + 2 < s.len() && is_hex(s[i+1]) && is_hex(s[i+2]) {
            r.push(hex_val(s[i+1]) * 16 + hex_val(s[i+2])); i += 3;
        } else { r.push(s[i]); i += 1; }
    }
    r
}

fn print_entity(ent: &Entity, indent: usize) {
    let pad = "  ".repeat(indent);
    if ent.ct_type == "multipart" {
        println!("{}multipart/{} parts={}", pad, ent.ct_sub, ent.parts.len());
        for p in &ent.parts { print_entity(p, indent + 1); }
    } else if ent.ct_type == "text" && ent.disp_type.as_deref() != Some("attachment") {
        let decoded_bytes = decode_transfer(&ent.body, &ent.cte, b"\n");
        let mut text = decode_charset(&decoded_bytes, &ent.charset);
        text = text.replace("\r\n", "\n").replace('\r', "\n");
        let n = text.chars().count();
        println!("{}text/{} charset={} cte={} chars={}", pad, ent.ct_sub, ent.charset, ent.cte, n);
        println!("{}  {}", pad, quote_string(&text));
    } else {
