            return (&data[..pos], &data[pos+lb.len()..]);
        }
        let mut next = pos;
        while next < data.len() {
            if next + lb.len() <= data.len() && &data[next..next+lb.len()] == lb {
                next += lb.len(); break;
            }
            next += 1;
        }
        pos = next;
    }
    (data, &[])
