        if i + lb.len() <= data.len() && &data[i..i+lb.len()] == lb {
            lines.push(&data[start..i]);
            i += lb.len();
            start = i;
        } else { i += 1; }
    }
    if start < data.len() { lines.push(&data[start..]); }
