fn parse_multipart(body: &[u8], boundary: &str, lb: &[u8]) -> Vec<Vec<u8>> {
    let delim = format!("--{}", boundary);
    let close = format!("--{}--", boundary);
    let lines = split_lines(body, lb);
    let mut delims: Vec<(usize, bool)> = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let s = String::from_utf8_lossy(line).to_string();
        if s.starts_with(&close) {
            let rest = &s[close.len()..];
            if rest.chars().all(|c| c == ' ' || c == '\t') { delims.push((i, true)); continue; }
        }
        if s.starts_with(&delim) {
            let rest = &s[delim.len()..];
            if rest.chars().all(|c| c == ' ' || c == '\t') { delims.push((i, false)); }
        }
    }
    let mut parts = Vec::new();
    for w in delims.windows(2) {
        let si = w[0].0;
        let ei = w[1].0;
