        let mut pd = Vec::new();
        for (j, cl) in content_lines.iter().enumerate() {
            pd.extend_from_slice(cl);
            if j < content_lines.len() - 1 { pd.extend_from_slice(lb); }
        }
        parts.push(pd);
    }
    parts
