}

fn base64_decode(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut bits: u32 = 0;
    let mut nb: u32 = 0;
    for &b in data {
        if b == b'=' { break; }
        let v: u32 = match b {
            b'A'..=b'Z' => (b - b'A') as u32,
            b'a'..=b'z' => (b - b'a' + 26) as u32,
            b'0'..=b'9' => (b - b'0' + 52) as u32,
            b'+' => 62, b'/' => 63,
            _ => continue,
        };
        bits = (bits << 6) | v;
        nb += 6;
        if nb >= 8 { nb -= 8; result.push((bits >> nb) as u8); }
    }
    result
}

fn decode_qp(data: &[u8], lb: &[u8]) -> Vec<u8> {
    let lines = split_lines(data, lb);
