        strip_trailing_ws(&mut line);
        while !line.is_empty() && *line.last().unwrap() == b'=' {
            line.pop();
            i += 1;
            if i < lines.len() {
                line.extend_from_slice(lines[i]);
                strip_trailing_ws(&mut line);
            } else { break; }
        }
        let mut j = 0;
        while j < line.len() {
            if line[j] == b'=' && j + 2 < line.len() && is_hex(line[j+1]) && is_hex(line[j+2]) {
                result.push(hex_val(line[j+1]) * 16 + hex_val(line[j+2]));
                j += 3;
            } else {
                result.push(line[j]);
                j += 1;
            }
        }
        i += 1;
        if i < lines.len() { result.extend_from_slice(lb); }
    }
    result
}

fn strip_trailing_ws(v: &mut Vec<u8>) {
