    let mut pos = 0;
    while pos < b.len() {
        match find_ew(b, pos) {
            Some((ws, we, cs, enc, et)) => {
                result.push_str(&s[pos..ws]);
                let mut all = decode_ew(enc, &et);
                let mut ce = we;
                loop {
                    let mut np = ce;
                    while np < b.len() && (b[np] == b' ' || b[np] == b'\t') { np += 1; }
                    match find_ew(b, np) {
                        Some((s2, e2, cs2, enc2, t2)) if s2 == np && cs_eq(&cs, &cs2) => {
                            all.extend_from_slice(&decode_ew(enc2, &t2));
                            ce = e2;
                        }
                        _ => break,
                    }
                }
                result.push_str(&decode_charset(&all, &cs));
                pos = ce;
            }
            None => { result.push_str(&s[pos..]); break; }
        }
    }
    result
}

fn cs_eq(a: &str, b: &str) -> bool { a == b }

fn find_ew(b: &[u8], start: usize) -> Option<(usize, usize, String, u8, Vec<u8>)> {
    let mut pos = start;
    while pos + 1 < b.len() {
        if b[pos] == b'=' && b[pos+1] == b'?' {
            let ws = pos;
            let mut p = pos + 2;
            let cs_s = p;
            while p < b.len() && b[p] != b'?' && b[p] != b' ' && b[p] != b'\t' { p += 1; }
            if p >= b.len() || b[p] != b'?' || p == cs_s { pos += 1; continue; }
            let cs_raw = String::from_utf8_lossy(&b[cs_s..p]).to_lowercase();
            p += 1;
            if p >= b.len() { pos += 1; continue; }
            let enc = b[p];
            if enc != b'B' && enc != b'b' && enc != b'Q' && enc != b'q' { pos += 1; continue; }
            p += 1;
            if p >= b.len() || b[p] != b'?' { pos += 1; continue; }
            p += 1;
            let et_s = p;
            while p < b.len() && b[p] != b'?' && b[p] != b' ' && b[p] != b'\t' { p += 1; }
            let et = b[et_s..p].to_vec();
            if p + 1 >= b.len() || b[p] != b'?' || b[p+1] != b'=' { pos += 1; continue; }
            p += 2;
            let cs = if let Some(i) = cs_raw.find('*') { cs_raw[..i].to_string() } else { cs_raw };
            return Some((ws, p, cs, enc, et));
        }
        pos += 1;
    }
    None
}

fn decode_ew(enc: u8, text: &[u8]) -> Vec<u8> {
    match enc {
        b'B' | b'b' => base64_decode(text),
        b'Q' | b'q' => {
            let mut r = Vec::new();
            let mut i = 0;
            while i < text.len() {
                if text[i] == b'_' { r.push(0x20); i += 1; }
                else if text[i] == b'=' && i + 2 < text.len() && is_hex(text[i+1]) && is_hex(text[i+2]) {
                    r.push(hex_val(text[i+1]) * 16 + hex_val(text[i+2])); i += 3;
                } else { r.push(text[i]); i += 1; }
            }
            r
        }
        _ => text.to_vec(),
    }
