fn base64_decode(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut bits: u32 = 0;
    let mut nb: u32 = 0;
    for &b in data {
        if b == b'=' { break; }
        let v: u32 = match b {
