        let (cs, enc) = split_cs_prefix(val);
        let bytes = pct_decode(enc.as_bytes());
        return Some(decode_charset(&bytes, &cs));
    }
    let prefix = format!("{}*", attr);
    let mut segs: BTreeMap<usize, (bool, String)> = BTreeMap::new();
    for (k, v) in params {
        if k.starts_with(&prefix) && k.len() > prefix.len() {
            let rest = &k[prefix.len()..];
            let (ns, pct) = if rest.ends_with('*') { (&rest[..rest.len() - 1], true) } else { (rest, false) };
            if let Ok(n) = ns.parse::<usize>() { segs.insert(n, (pct, v.clone())); }
        }
    }
    if segs.is_empty() { return None; }
    let mut all = Vec::new();
    let mut cs = String::from("us-ascii");
    for (idx, (pct, val)) in &segs {
        if *idx == 0 && *pct {
            let (c, e) = split_cs_prefix(val);
            cs = c;
            all.extend_from_slice(&pct_decode(e.as_bytes()));
        } else if *pct {
            all.extend_from_slice(&pct_decode(val.as_bytes()));
        } else {
            all.extend_from_slice(val.as_bytes());
        }
    }
    Some(decode_charset(&all, &cs))
}

fn split_cs_prefix(s: &str) -> (String, &str) {
