        println!("{}multipart/{} parts={}", pad, ent.ct_sub, ent.parts.len());
        for p in &ent.parts { print_entity(p, indent + 1); }
    } else if ent.ct_type == "text" && ent.disp_type.as_deref() != Some("attachment") {
        let decoded_bytes = decode_transfer(&ent.body, &ent.cte, &ent.lb);
        let mut text = decode_charset(&decoded_bytes, &ent.charset);
