struct RtErr { line: usize, msg: String }

impl Interp {
    fn new() -> Self { Interp { out: String::new() } }

    fn resolve(&self, name: &str, scope: &Scope) -> Result<Val, RtErr> {
        let mut cur = scope.clone();
        loop {
            if let Some(v) = cur.borrow().get(name) { return Ok(v.clone()); }
            let parent = {
                let cur_b = cur.borrow();
                // We need parent pointer... let's store parent in scope
                // Actually let me redesign scope to include parent
                None::<Scope>
            };
            // Hmm, I need parent pointers. Let me use a different approach.
            break;
        }
        Err(RtErr { line: 0, msg: String::new() })
    }

    fn eval(&mut self, e: &Expr, scope: &Scope) -> Result<Val, RtErr> {
        match e {
            Expr::IntLit(n, _) => Ok(Val::Int(*n)),
            Expr::StrLit(s, _) => Ok(Val::Str(s.clone())),
            Expr::BoolLit(b, _) => Ok(Val::Bool(*b)),
            Expr::NilLit(_) => Ok(Val::Nil),
            Expr::Var(name, line) => {
                self.lookup(name, scope).ok_or_else(|| RtErr { line: *line, msg: format!("undefined variable {}", name) })
            }
            Expr::Bin { op, lhs, rhs, line } => {
                // and/or short-circuit
                if *op == BO::And {
                    let l = self.eval(lhs, scope)?;
                    if !truthy(&l) { return Ok(l); }
                    return self.eval(rhs, scope);
                }
                if *op == BO::Or {
                    let l = self.eval(lhs, scope)?;
                    if truthy(&l) { return Ok(l); }
                    return self.eval(rhs, scope);
                }
                let l = self.eval(lhs, scope)?;
                let r = self.eval(rhs, scope)?;
                self.binop(*op, &l, &r, *line)
            }
            Expr::Not(inner, line) => {
                let v = self.eval(inner, scope)?;
                Ok(Val::Bool(!truthy(&v)))
            }
            Expr::Neg(inner, line) => {
                let v = self.eval(inner, scope)?;
                match v {
                    Val::Int(n) => n.checked_neg().map(Val::Int).ok_or_else(|| RtErr { line: *line, msg: "integer overflow".to_string() }),
                    _ => Err(RtErr { line: *line, msg: format!("cannot apply - to {}", type_name(&v)) }),
                }
            }
            Expr::Call { callee, args, line } => {
                let cv = self.eval(callee, scope)?;
                let mut vals = Vec::with_capacity(args.len());
                for a in args { vals.push(self.eval(a, scope)?); }
                self.call(&cv, vals, *line)
            }
            Expr::Index { obj, idx, line } => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                self.index_read(&ov, &iv, *line)
            }
            Expr::ListLit(elems, _) => {
                let mut vs = Vec::with_capacity(elems.len());
                for e in elems { vs.push(self.eval(e, scope)?); }
                Ok(Val::List(Rc::new(RefCell::new(vs))))
            }
            Expr::FnExpr { params, body, .. } => {
                Ok(Val::Func(Rc::new(FuncData::User { params: params.clone(), body: body.clone(), captured: scope.clone() })))
            }
        }
    }

    fn lookup(&self, name: &str, scope: &Scope) -> Option<Val> {
        let mut cur = scope.clone();
        loop {
            if let Some(v) = cur.borrow().get(name) { return Some(v.clone()); }
            // Need parent... let me store parent differently
            // I'll use a separate parent map or include parent in scope
            break;
        }
        None
    }

    fn binop(&mut self, op: BO, l: &Val, r: &Val, line: usize) -> Result<Val, RtErr> {
        match op {
            BO::Add => match (l, r) {
                (Val::Int(a), Val::Int(b)) => a.checked_add(*b).map(Val::Int).ok_or_else(|| RtErr{line,msg:"integer overflow".into()}),
                (Val::Str(a), Val::Str(b)) => Ok(Val::Str(Rc::new(format!("{}{}", a, b)))),
                (Val::List(a), Val::List(b)) => {
                    let mut v = a.borrow().clone();
                    v.extend(b.borrow().iter().cloned());
                    Ok(Val::List(Rc::new(RefCell::new(v))))
                }
                _ => Err(RtErr{line,msg:format!("cannot apply + to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Sub => match (l, r) {
                (Val::Int(a), Val::Int(b)) => a.checked_sub(*b).map(Val::Int).ok_or_else(|| RtErr{line,msg:"integer overflow".into()}),
                _ => Err(RtErr{line,msg:format!("cannot apply - to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Mul => match (l, r) {
                (Val::Int(a), Val::Int(b)) => a.checked_mul(*b).map(Val::Int).ok_or_else(|| RtErr{line,msg:"integer overflow".into()}),
                _ => Err(RtErr{line,msg:format!("cannot apply * to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Div => match (l, r) {
                (Val::Int(a), Val::Int(b)) => {
                    if *b == 0 { return Err(RtErr{line,msg:"division by zero".into()}); }
                    if *a == i64::MIN && *b == -1 { return Err(RtErr{line,msg:"integer overflow".into()}); }
                    Ok(Val::Int(a / b))
                }
                _ => Err(RtErr{line,msg:format!("cannot apply / to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Mod => match (l, r) {
                (Val::Int(a), Val::Int(b)) => {
                    if *b == 0 { return Err(RtErr{line,msg:"division by zero".into()}); }
                    if *b == -1 { return Ok(Val::Int(0)); }
                    Ok(Val::Int(a % b))
                }
                _ => Err(RtErr{line,msg:format!("cannot apply % to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Eq => Ok(Val::Bool(val_eq(l, r))),
            BO::Ne => Ok(Val::Bool(!val_eq(l, r))),
            BO::Lt | BO::Le | BO::Gt | BO::Ge => match (l, r) {
                (Val::Int(a), Val::Int(b)) => Ok(Val::Bool(match op {
                    BO::Lt => a < b, BO::Le => a <= b, BO::Gt => a > b, _ => a >= b,
                })),
                (Val::Str(a), Val::Str(b)) => Ok(Val::Bool(match op {
                    BO::Lt => a.as_str() < b.as_str(), BO::Le => a.as_str() <= b.as_str(),
                    BO::Gt => a.as_str() > b.as_str(), _ => a.as_str() >= b.as_str(),
                })),
                _ => Err(RtErr{line,msg:format!("cannot apply {} to {} and {}",
                    match op { BO::Lt=>"<",BO::Le=>"<=",BO::Gt=>">",_=>">=" },type_name(l),type_name(r))}),
            },
            BO::And | BO::Or => unreachable!(),
        }
    }

    fn index_read(&mut self, obj: &Val, idx: &Val, line: usize) -> Result<Val, RtErr> {
        match (obj, idx) {
            (Val::List(l), Val::Int(i)) => {
                let l = l.borrow();
                if *i < 0 || *i >= l.len() as i64 {
                    Err(RtErr{line,msg:format!("index {} out of range for length {}",i,l.len())})
                } else {
                    Ok(l[*i as usize].clone())
                }
            }
            (Val::Str(s), Val::Int(i)) => {
                let chars: Vec<char> = s.chars().collect();
                if *i < 0 || *i >= chars.len() as i64 {
                    Err(RtErr{line,msg:format!("index {} out of range for length {}",i,chars.len())})
                } else {
                    Ok(Val::Str(Rc::new(chars[*i as usize].to_string())))
                }
            }
            (Val::List(_), _) => Err(RtErr{line,msg:format!("cannot index list with {}",type_name(idx))}),
            (Val::Str(_), _) => Err(RtErr{line,msg:format!("cannot index string with {}",type_name(idx))}),
            (x, i) => Err(RtErr{line,msg:format!("cannot index {} with {}",type_name(x),type_name(i))}),
        }
    }

    fn call(&mut self, cv: &Val, args: Vec<Val>, line: usize) -> Result<Val, RtErr> {
        match cv {
            Val::Func(fd) => {
                match &**fd {
                    FuncData::User { params, body, captured } => {
