    fn call_builtin(&mut self, bk: BK, args: Vec<Val>, line: usize) -> Result<Val, RtErr> {
        match bk {
            BK::Print => {
                let parts: Vec<String> = args.iter().map(|v| display_top(v)).collect();
                self.out.push_str(&parts.join(" "));
