fn kw(s: &str) -> Option<TK> {
    match s {
        "let" => Some(TK::Let), "fn" => Some(TK::Fn), "if" => Some(TK::If),
        "else" => Some(TK::Else), "while" => Some(TK::While), "for" => Some(TK::For),
        "in" => Some(TK::In), "return" => Some(TK::Ret), "break" => Some(TK::Brk),
        "continue" => Some(TK::Cont), "and" => Some(TK::And), "or" => Some(TK::Or),
        "not" => Some(TK::Not), "true" => Some(TK::True), "false" => Some(TK::False),
        "nil" => Some(TK::Nil), _ => None,
    }
}

fn lex(src: &str) -> Vec<Token> {
    let b = src.as_bytes();
    let n = b.len();
    let mut i = 0;
    let mut line = 1;
    let mut toks: Vec<Token> = Vec::new();
    while i < n {
        let c = b[i];
        if c == b' ' || c == b'\t' || c == b'\r' { i += 1; continue; }
        if c == b'\n' { line += 1; i += 1; continue; }
        if c == b'#' { while i < n && b[i] != b'\n' { i += 1; } continue; }
        if c.is_ascii_digit() {
            let start = i;
            while i < n && b[i].is_ascii_digit() { i += 1; }
            let s = &src[start..i];
            toks.push(Token { kind: TK::IntLit, line, text: s.to_string(), ival: s.parse::<i64>().unwrap(), sval: String::new() });
            continue;
        }
        if c == b'"' {
            i += 1;
            let mut s = String::new();
            while i < n && b[i] != b'"' {
                if b[i] == b'\\' {
                    i += 1;
                    if i < n {
                        match b[i] {
                            b'n' => s.push('\n'),
                            b't' => s.push('\t'),
                            b'"' => s.push('"'),
                            b'\\' => s.push('\\'),
                            _ => { s.push('\\'); s.push(b[i] as char); }
                        }
                        i += 1;
                    }
                } else {
                    s.push(b[i] as char);
                    i += 1;
                }
            }
            if i < n { i += 1; } // skip closing "
            toks.push(Token { kind: TK::StrLit, line, text: s.clone(), ival: 0, sval: s });
            continue;
        }
        if c.is_ascii_alphabetic() || c == b'_' {
            let start = i;
            while i < n && (b[i].is_ascii_alphanumeric() || b[i] == b'_') { i += 1; }
            let s = &src[start..i];
            let kind = kw(s).unwrap_or(TK::Ident);
            toks.push(Token { kind, line, text: s.to_string(), ival: 0, sval: String::new() });
            continue;
        }
        // operators
        let (kind, adv) = match c {
            b'=' => if i + 1 < n && b[i+1] == b'=' { (TK::Eq, 2) } else { (TK::Assign, 1) },
            b'!' => if i + 1 < n && b[i+1] == b'=' { (TK::Ne, 2) } else { (TK::Ne, 1) },
            b'<' => if i + 1 < n && b[i+1] == b'=' { (TK::Le, 2) } else { (TK::Lt, 1) },
            b'>' => if i + 1 < n && b[i+1] == b'=' { (TK::Ge, 2) } else { (TK::Gt, 1) },
            b'+' => (TK::Plus, 1),
            b'-' => (TK::Minus, 1),
            b'*' => (TK::Star, 1),
            b'/' => (TK::Slash, 1),
            b'%' => (TK::Pct, 1),
            b'(' => (TK::LP, 1),
            b')' => (TK::RP, 1),
            b'[' => (TK::LB, 1),
            b']' => (TK::RB, 1),
            b'{' => (TK::LC, 1),
            b'}' => (TK::RC, 1),
            b',' => (TK::Comma, 1),
            b';' => (TK::Semi, 1),
            _ => { i += 1; continue; }
        };
        toks.push(Token { kind, line, text: String::new(), ival: 0, sval: String::new() });
        i += adv;
    }
    toks.push(Token { kind: TK::Eof, line, text: String::new(), ival: 0, sval: String::new() });
    toks
}

// ============ AST ============
#[derive(Clone, Copy, PartialEq, Debug)]
enum BO { Add, Sub, Mul, Div, Mod, Eq, Ne, Lt, Le, Gt, Ge, And, Or }

#[derive(Debug)]
enum Expr {
    IntLit(i64, usize),
    StrLit(Rc<String>, usize),
    BoolLit(bool, usize),
    NilLit(usize),
    Var(String, usize),
    Bin { op: BO, lhs: Box<Expr>, rhs: Box<Expr>, line: usize },
    Not(Box<Expr>, usize),
    Neg(Box<Expr>, usize),
    Call { callee: Box<Expr>, args: Vec<Expr>, line: usize },
    Index { obj: Box<Expr>, idx: Box<Expr>, line: usize },
    ListLit(Vec<Expr>, usize),
    FnExpr { params: Vec<String>, body: Vec<Stmt>, line: usize },
}

#[derive(Debug)]
enum ElseB {
    If(Box<Stmt>),
    Block(Vec<Stmt>),
}

#[derive(Debug)]
enum Stmt {
    LetDecl(String, Expr, usize),
    FnDecl(String, Vec<String>, Vec<Stmt>, usize),
    If { cond: Expr, then_b: Vec<Stmt>, else_b: Option<ElseB>, line: usize },
    While { cond: Expr, body: Vec<Stmt>, line: usize },
    For { var: String, iter: Expr, body: Vec<Stmt>, line: usize },
    Ret(Option<Expr>, usize),
    Brk(usize),
    Cont(usize),
    Assign(String, Expr, usize),
    IdxAssign { obj: Box<Expr>, idx: Box<Expr>, val: Expr, line: usize },
