                let t = self.advance();
                self.advance(); // =
                let e = self.parse_expr();
                self.expect(TK::Semi);
                Stmt::Assign(t.text.clone(), e, line)
            }
            _ => {
                let e = self.parse_expr();
                if self.at(TK::Assign) {
                    self.advance();
                    let val = self.parse_expr();
                    self.expect(TK::Semi);
                    match e {
                        Expr::Index { obj, idx, line: il } => Stmt::IdxAssign { obj, idx, val, line: il },
                        _ => panic!("invalid assignment target"),
                    }
                } else {
                    self.expect(TK::Semi);
                    Stmt::ExprS(e, line)
                }
            }
        }
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut lhs = self.parse_and();
        while self.at(TK::Or) {
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_and();
            lhs = Expr::Bin { op: BO::Or, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_and(&mut self) -> Expr {
        let mut lhs = self.parse_not();
        while self.at(TK::And) {
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_not();
            lhs = Expr::Bin { op: BO::And, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_not(&mut self) -> Expr {
