            let line = self.peek().line;
            self.advance();
            let e = self.parse_not();
            Expr::Not(Box::new(e), line)
        } else {
            self.parse_cmp()
        }
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut lhs = self.parse_add();
        loop {
            let op = match self.peek_kind() {
                TK::Eq => BO::Eq, TK::Ne => BO::Ne, TK::Lt => BO::Lt,
                TK::Le => BO::Le, TK::Gt => BO::Gt, TK::Ge => BO::Ge,
                _ => break,
            };
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_add();
            lhs = Expr::Bin { op, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_add(&mut self) -> Expr {
        let mut lhs = self.parse_mul();
        loop {
            let op = match self.peek_kind() {
                TK::Plus => BO::Add, TK::Minus => BO::Sub,
                _ => break,
            };
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_mul();
            lhs = Expr::Bin { op, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_mul(&mut self) -> Expr {
        let mut lhs = self.parse_unary();
        loop {
            let op = match self.peek_kind() {
                TK::Star => BO::Mul, TK::Slash => BO::Div, TK::Pct => BO::Mod,
                _ => break,
            };
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_unary();
            lhs = Expr::Bin { op, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_unary(&mut self) -> Expr {
        if self.at(TK::Minus) {
            let line = self.peek().line;
            self.advance();
            let e = self.parse_unary();
            Expr::Neg(Box::new(e), line)
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
