            TK::True => Expr::BoolLit(true, t.line),
            TK::False => Expr::BoolLit(false, t.line),
            TK::Nil => Expr::NilLit(t.line),
            TK::Ident => Expr::Var(t.text.clone(), t.line),
            TK::LP => { let e = self.parse_expr(); self.expect(TK::RP); e }
            TK::LB => {
                let mut elems = Vec::new();
                if !self.at(TK::RB) {
