    fn expect(&mut self, k: TK) -> Token { let t = self.advance(); assert_eq!(t.kind, k); t }
    fn at(&self, k: TK) -> bool { self.toks[self.pos].kind == k }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while !self.at(TK::Eof) { stmts.push(self.parse_stmt()); }
        stmts
    }

    fn parse_block(&mut self) -> Rc<Vec<Stmt>> {
        self.expect(TK::LC);
        let mut stmts = Vec::new();
        while !self.at(TK::RC) && !self.at(TK::Eof) { stmts.push(self.parse_stmt()); }
        self.expect(TK::RC);
        Rc::new(stmts)
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut ps = Vec::new();
        if self.at(TK::RP) { return ps; }
        loop {
            let t = self.expect(TK::Ident);
            ps.push(t.text.clone());
            if self.at(TK::Comma) { self.advance(); } else { break; }
        }
        ps
    }

    fn parse_stmt(&mut self) -> Stmt {
        let line = self.peek().line;
        match self.pk() {
            TK::Let => {
                self.advance();
                let t = self.expect(TK::Ident);
                self.expect(TK::Assign);
                let e = self.parse_expr();
                self.expect(TK::Semi);
                Stmt::LetDecl(Rc::new(t.text), e, line)
            }
            TK::Fn => {
                self.advance();
                let t = self.expect(TK::Ident);
                self.expect(TK::LP);
                let params = Rc::new(self.parse_params());
                self.expect(TK::RP);
                let body = self.parse_block();
                Stmt::FnDecl(Rc::new(t.text), params, body, line)
            }
            TK::If => {
                self.advance();
                let cond = self.parse_expr();
                let then_b = self.parse_block();
                let else_b = if self.at(TK::Else) {
                    self.advance();
                    if self.at(TK::If) { Some(ElseB::If(Box::new(self.parse_stmt()))) }
                    else { Some(ElseB::Block(self.parse_block())) }
                } else { None };
                Stmt::If { cond, then_b, else_b, line }
            }
            TK::While => {
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While { cond, body, line }
            }
            TK::For => {
                self.advance();
                let t = self.expect(TK::Ident);
                self.expect(TK::In);
                let iter = self.parse_expr();
                let body = self.parse_block();
                Stmt::For { var: Rc::new(t.text), iter, body, line }
            }
            TK::Ret => {
                self.advance();
                let e = if self.at(TK::Semi) { None } else { Some(self.parse_expr()) };
                self.expect(TK::Semi);
                Stmt::Ret(e, line)
            }
            TK::Brk => { self.advance(); self.expect(TK::Semi); Stmt::Brk(line) }
            TK::Cont => { self.advance(); self.expect(TK::Semi); Stmt::Cont(line) }
            TK::Ident if self.pk_at(1) == TK::Assign => {
                let t = self.advance();
                self.advance();
                let e = self.parse_expr();
                self.expect(TK::Semi);
                Stmt::Assign(Rc::new(t.text), e, line)
            }
            _ => {
                let e = self.parse_expr();
                if self.at(TK::Assign) {
                    self.advance();
                    let val = self.parse_expr();
                    self.expect(TK::Semi);
                    match e {
                        Expr::Index { obj, idx, line: il } => Stmt::IdxAssign { obj, idx, val: Box::new(val), line: il },
                        _ => panic!("invalid assignment target"),
                    }
                } else {
                    self.expect(TK::Semi);
                    Stmt::ExprS(e, line)
                }
            }
        }
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut lhs = self.parse_and();
        while self.at(TK::Or) {
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_and();
            lhs = Expr::Bin { op: BO::Or, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_and(&mut self) -> Expr {
        let mut lhs = self.parse_not();
        while self.at(TK::And) {
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_not();
            lhs = Expr::Bin { op: BO::And, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_not(&mut self) -> Expr {
        if self.at(TK::Not) {
            let line = self.peek().line;
            self.advance();
            let e = self.parse_not();
            Expr::Not(Box::new(e), line)
        } else {
            self.parse_cmp()
        }
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut lhs = self.parse_add();
        loop {
            let op = match self.pk() {
                TK::Eq => BO::Eq, TK::Ne => BO::Ne, TK::Lt => BO::Lt,
                TK::Le => BO::Le, TK::Gt => BO::Gt, TK::Ge => BO::Ge,
                _ => break,
            };
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_add();
            lhs = Expr::Bin { op, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_add(&mut self) -> Expr {
        let mut lhs = self.parse_mul();
        loop {
            let op = match self.pk() {
                TK::Plus => BO::Add, TK::Minus => BO::Sub,
                _ => break,
            };
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_mul();
            lhs = Expr::Bin { op, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_mul(&mut self) -> Expr {
        let mut lhs = self.parse_unary();
        loop {
            let op = match self.pk() {
                TK::Star => BO::Mul, TK::Slash => BO::Div, TK::Pct => BO::Mod,
                _ => break,
            };
            let line = self.peek().line;
            self.advance();
            let rhs = self.parse_unary();
            lhs = Expr::Bin { op, lhs: Box::new(lhs), rhs: Box::new(rhs), line };
        }
        lhs
    }

    fn parse_unary(&mut self) -> Expr {
        if self.at(TK::Minus) {
            let line = self.peek().line;
            self.advance();
            let e = self.parse_unary();
            Expr::Neg(Box::new(e), line)
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            if self.at(TK::LP) {
                let line = self.peek().line;
                self.advance();
                let mut args = Vec::new();
                if !self.at(TK::RP) {
                    loop {
                        args.push(self.parse_expr());
                        if self.at(TK::Comma) { self.advance(); } else { break; }
                    }
                }
                self.expect(TK::RP);
                e = Expr::Call { callee: Box::new(e), args: Rc::new(args), line };
            } else if self.at(TK::LB) {
                let line = self.peek().line;
                self.advance();
                let idx = self.parse_expr();
                self.expect(TK::RB);
                e = Expr::Index { obj: Box::new(e), idx: Box::new(idx), line };
            } else {
                break;
            }
        }
        e
    }

    fn parse_primary(&mut self) -> Expr {
        let t = self.advance();
        match t.kind {
            TK::IntLit => Expr::IntLit(t.ival, t.line),
            TK::StrLit => Expr::StrLit(Rc::new(t.sval.clone()), t.line),
            TK::True => Expr::BoolLit(true, t.line),
            TK::False => Expr::BoolLit(false, t.line),
            TK::Nil => Expr::NilLit(t.line),
            TK::Ident => Expr::Var(Rc::new(t.text.clone()), t.line),
            TK::LP => { let e = self.parse_expr(); self.expect(TK::RP); e }
            TK::LB => {
                let mut elems = Vec::new();
                if !self.at(TK::RB) {
                    loop {
                        elems.push(self.parse_expr());
                        if self.at(TK::Comma) { self.advance(); } else { break; }
                    }
                }
                self.expect(TK::RB);
                Expr::ListLit(Rc::new(elems), t.line)
            }
            TK::Fn => {
                self.expect(TK::LP);
                let params = Rc::new(self.parse_params());
                self.expect(TK::RP);
                let body = self.parse_block();
                Expr::FnExpr { params, body, line: t.line }
            }
            _ => panic!("unexpected token {:?}", t.kind),
        }
    }
}

// ============ VALUES ============
#[derive(Clone)]
enum Val {
    Int(i64),
    Bool(bool),
    Str(Rc<String>),
    List(Rc<RefCell<Vec<Val>>>),
    Func(Rc<FuncData>),
    Nil,
}

enum FuncData {
    User { params: Rc<Vec<String>>, body: Rc<Vec<Stmt>>, captured: Scope },
    Builtin(BK),
}

#[derive(Clone, Copy, PartialEq)]
enum BK { Print, Str, Type, Len, Push, Pop, Range, Slice }

struct ScopeNode {
    vars: HashMap<String, Val>,
    parent: Option<Rc<RefCell<ScopeNode>>>,
}
type Scope = Rc<RefCell<ScopeNode>>;

fn new_scope(parent: Option<Scope>) -> Scope {
    Rc::new(RefCell::new(ScopeNode { vars: HashMap::new(), parent }))
}

fn type_name(v: &Val) -> &'static str {
    match v {
        Val::Int(_) => "int",
        Val::Bool(_) => "bool",
        Val::Str(_) => "string",
        Val::List(_) => "list",
        Val::Func(_) => "function",
        Val::Nil => "nil",
    }
}

fn truthy(v: &Val) -> bool {
    match v {
        Val::Bool(b) => *b,
        Val::Nil => false,
        Val::Int(n) => *n != 0,
        Val::Str(s) => !s.is_empty(),
        Val::List(l) => !l.borrow().is_empty(),
        Val::Func(_) => true,
    }
}

fn val_eq(a: &Val, b: &Val) -> bool {
    match (a, b) {
        (Val::Int(x), Val::Int(y)) => x == y,
        (Val::Bool(x), Val::Bool(y)) => x == y,
        (Val::Str(x), Val::Str(y)) => x == y,
        (Val::Nil, Val::Nil) => true,
        (Val::Func(x), Val::Func(y)) => Rc::ptr_eq(x, y),
        (Val::List(x), Val::List(y)) => {
            if Rc::ptr_eq(x, y) { return true; }
            let xa = x.borrow();
            let yb = y.borrow();
            if xa.len() != yb.len() { return false; }
            xa.iter().zip(yb.iter()).all(|(a, b)| val_eq(a, b))
        }
        _ => false,
    }
}

fn esc_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 4);
    for c in s.chars() {
        match c {
            '\\' => r.push_str("\\\\"),
            '"' => r.push_str("\\\""),
            '\n' => r.push_str("\\n"),
            '\t' => r.push_str("\\t"),
            _ => r.push(c),
        }
    }
    r
}

fn display(v: &Val, in_list: bool, anc: &mut Vec<usize>) -> String {
    match v {
        Val::Int(n) => n.to_string(),
        Val::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Val::Nil => "nil".to_string(),
        Val::Func(_) => "<fn>".to_string(),
        Val::Str(s) => {
            if in_list { format!("\"{}\"", esc_str(s)) } else { s.to_string() }
        }
        Val::List(l) => {
            let ptr = Rc::as_ptr(l) as usize;
            if anc.contains(&ptr) {
                "[...]".to_string()
            } else {
                anc.push(ptr);
                let items: Vec<String> = l.borrow().iter().map(|e| display(e, true, anc)).collect();
                anc.pop();
                format!("[{}]", items.join(", "))
            }
        }
    }
}

fn display_top(v: &Val) -> String {
    let mut anc = Vec::new();
    display(v, false, &mut anc)
}

// ============ INTERPRETER ============
enum Flow { Normal, Break, Continue, Return(Val) }

struct RtErr { line: usize, msg: String }

struct Interp {
    out: String,
}

impl Interp {
    fn new() -> Self { Interp { out: String::new() } }

    fn lookup(&self, name: &str, scope: &Scope) -> Option<Val> {
        let mut cur: Option<Scope> = Some(scope.clone());
        while let Some(s) = cur {
            let sb = s.borrow();
            if let Some(v) = sb.vars.get(name) { return Some(v.clone()); }
            cur = sb.parent.clone();
        }
        None
    }

    fn assign_var(&self, name: &str, val: Val, scope: &Scope) -> Result<(), RtErr> {
        let mut cur: Option<Scope> = Some(scope.clone());
        while let Some(s) = cur {
            let mut sb = s.borrow_mut();
            if sb.vars.contains_key(name) {
                sb.vars.insert(name.to_string(), val);
                return Ok(());
            }
            cur = sb.parent.clone();
        }
        Err(RtErr { line: 0, msg: String::new() })
    }

    fn eval(&mut self, e: &Expr, scope: &Scope) -> Result<Val, RtErr> {
        match e {
            Expr::IntLit(n, _) => Ok(Val::Int(*n)),
            Expr::StrLit(s, _) => Ok(Val::Str(s.clone())),
            Expr::BoolLit(b, _) => Ok(Val::Bool(*b)),
            Expr::NilLit(_) => Ok(Val::Nil),
            Expr::Var(name, line) => {
                self.lookup(name, scope).ok_or_else(|| RtErr { line: *line, msg: format!("undefined variable {}", name) })
            }
            Expr::Bin { op, lhs, rhs, line } => {
                if *op == BO::And {
                    let l = self.eval(lhs, scope)?;
                    if !truthy(&l) { return Ok(l); }
                    return self.eval(rhs, scope);
                }
                if *op == BO::Or {
                    let l = self.eval(lhs, scope)?;
                    if truthy(&l) { return Ok(l); }
                    return self.eval(rhs, scope);
                }
                let l = self.eval(lhs, scope)?;
                let r = self.eval(rhs, scope)?;
                self.binop(*op, &l, &r, *line)
            }
            Expr::Not(inner, _line) => {
                let v = self.eval(inner, scope)?;
                Ok(Val::Bool(!truthy(&v)))
            }
            Expr::Neg(inner, line) => {
                let v = self.eval(inner, scope)?;
                match v {
                    Val::Int(n) => n.checked_neg().map(Val::Int).ok_or_else(|| RtErr { line: *line, msg: "integer overflow".to_string() }),
                    _ => Err(RtErr { line: *line, msg: format!("cannot apply - to {}", type_name(&v)) }),
                }
            }
            Expr::Call { callee, args, line } => {
                let cv = self.eval(callee, scope)?;
                let mut vals = Vec::with_capacity(args.len());
                for a in args.iter() { vals.push(self.eval(a, scope)?); }
                self.call(&cv, vals, *line)
            }
            Expr::Index { obj, idx, line } => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                self.index_read(&ov, &iv, *line)
            }
            Expr::ListLit(elems, _) => {
                let mut vs = Vec::with_capacity(elems.len());
                for e in elems.iter() { vs.push(self.eval(e, scope)?); }
                Ok(Val::List(Rc::new(RefCell::new(vs))))
            }
            Expr::FnExpr { params, body, .. } => {
                Ok(Val::Func(Rc::new(FuncData::User { params: params.clone(), body: body.clone(), captured: scope.clone() })))
            }
        }
    }

    fn binop(&mut self, op: BO, l: &Val, r: &Val, line: usize) -> Result<Val, RtErr> {
        match op {
            BO::Add => match (l, r) {
                (Val::Int(a), Val::Int(b)) => a.checked_add(*b).map(Val::Int).ok_or_else(|| RtErr{line,msg:"integer overflow".into()}),
                (Val::Str(a), Val::Str(b)) => Ok(Val::Str(Rc::new(format!("{}{}", a, b)))),
                (Val::List(a), Val::List(b)) => {
                    let mut v: Vec<Val> = Vec::with_capacity(a.borrow().len() + b.borrow().len());
                    v.extend(a.borrow().iter().cloned());
                    v.extend(b.borrow().iter().cloned());
                    Ok(Val::List(Rc::new(RefCell::new(v))))
                }
                _ => Err(RtErr{line,msg:format!("cannot apply + to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Sub => match (l, r) {
                (Val::Int(a), Val::Int(b)) => a.checked_sub(*b).map(Val::Int).ok_or_else(|| RtErr{line,msg:"integer overflow".into()}),
                _ => Err(RtErr{line,msg:format!("cannot apply - to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Mul => match (l, r) {
                (Val::Int(a), Val::Int(b)) => a.checked_mul(*b).map(Val::Int).ok_or_else(|| RtErr{line,msg:"integer overflow".into()}),
                _ => Err(RtErr{line,msg:format!("cannot apply * to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Div => match (l, r) {
                (Val::Int(a), Val::Int(b)) => {
                    if *b == 0 { return Err(RtErr{line,msg:"division by zero".into()}); }
                    if *a == i64::MIN && *b == -1 { return Err(RtErr{line,msg:"integer overflow".into()}); }
                    Ok(Val::Int(a / b))
                }
                _ => Err(RtErr{line,msg:format!("cannot apply / to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Mod => match (l, r) {
                (Val::Int(a), Val::Int(b)) => {
                    if *b == 0 { return Err(RtErr{line,msg:"division by zero".into()}); }
                    if *b == -1 { return Ok(Val::Int(0)); }
                    Ok(Val::Int(a % b))
                }
                _ => Err(RtErr{line,msg:format!("cannot apply % to {} and {}",type_name(l),type_name(r))}),
            },
            BO::Eq => Ok(Val::Bool(val_eq(l, r))),
            BO::Ne => Ok(Val::Bool(!val_eq(l, r))),
            BO::Lt | BO::Le | BO::Gt | BO::Ge => match (l, r) {
                (Val::Int(a), Val::Int(b)) => Ok(Val::Bool(match op {
                    BO::Lt => a < b, BO::Le => a <= b, BO::Gt => a > b, _ => a >= b,
                })),
                (Val::Str(a), Val::Str(b)) => Ok(Val::Bool(match op {
                    BO::Lt => a.as_str() < b.as_str(), BO::Le => a.as_str() <= b.as_str(),
                    BO::Gt => a.as_str() > b.as_str(), _ => a.as_str() >= b.as_str(),
                })),
                _ => Err(RtErr{line,msg:format!("cannot apply {} to {} and {}",
                    match op { BO::Lt=>"<",BO::Le=>"<=",BO::Gt=>">",_=>">=" },type_name(l),type_name(r))}),
            },
            BO::And | BO::Or => unreachable!(),
        }
    }

    fn index_read(&mut self, obj: &Val, idx: &Val, line: usize) -> Result<Val, RtErr> {
        match obj {
            Val::List(l) => {
                match idx {
                    Val::Int(i) => {
                        let lb = l.borrow();
                        let len = lb.len() as i64;
                        if *i < 0 || *i >= len {
                            Err(RtErr{line,msg:format!("index {} out of range for length {}",i,len)})
                        } else {
                            Ok(lb[*i as usize].clone())
                        }
                    }
                    _ => Err(RtErr{line,msg:format!("cannot index list with {}",type_name(idx))}),
                }
            }
            Val::Str(s) => {
                match idx {
                    Val::Int(i) => {
                        let len = s.len() as i64;
                        if *i < 0 || *i >= len {
                            Err(RtErr{line,msg:format!("index {} out of range for length {}",i,len)})
                        } else {
                            Ok(Val::Str(Rc::new(s[*i as usize..*i as usize+1].to_string())))
                        }
                    }
                    _ => Err(RtErr{line,msg:format!("cannot index string with {}",type_name(idx))}),
                }
            }
            _ => {
                Err(RtErr{line,msg:format!("cannot index {} with {}",type_name(obj),type_name(idx))})
            }
        }
    }

    fn call(&mut self, cv: &Val, args: Vec<Val>, line: usize) -> Result<Val, RtErr> {
        match cv {
            Val::Func(fd) => {
                match &**fd {
                    FuncData::User { params, body, captured } => {
                        if args.len() != params.len() {
                            return Err(RtErr{line,msg:format!("expected {} arguments, got {}",params.len(),args.len())});
                        }
                        let call_scope = new_scope(Some(captured.clone()));
                        {
                            let mut sb = call_scope.borrow_mut();
                            for (p, a) in params.iter().zip(args) {
                                sb.vars.insert(p.clone(), a);
                            }
                        }
                        match self.exec_block(body, &call_scope) {
                            Ok(Flow::Return(v)) => Ok(v),
                            Ok(_) => Ok(Val::Nil),
                            Err(e) => Err(e),
                        }
                    }
                    FuncData::Builtin(bk) => self.call_builtin(*bk, args, line),
                }
            }
            _ => Err(RtErr{line,msg:format!("cannot call {}",type_name(cv))}),
        }
    }

    fn exec_block(&mut self, stmts: &[Stmt], scope: &Scope) -> Result<Flow, RtErr> {
        for s in stmts {
            match self.exec_stmt(s, scope)? {
                Flow::Normal => {},
                f @ _ => return Ok(f),
            }
        }
        Ok(Flow::Normal)
    }

    fn exec_stmt(&mut self, s: &Stmt, scope: &Scope) -> Result<Flow, RtErr> {
        match s {
            Stmt::LetDecl(name, expr, _line) => {
                let v = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.to_string(), v);
                Ok(Flow::Normal)
            }
            Stmt::FnDecl(name, params, body, _line) => {
                let fv = Val::Func(Rc::new(FuncData::User { params: params.clone(), body: body.clone(), captured: scope.clone() }));
                scope.borrow_mut().vars.insert(name.to_string(), fv);
                Ok(Flow::Normal)
            }
            Stmt::If { cond, then_b, else_b, .. } => {
                let cv = self.eval(cond, scope)?;
                if truthy(&cv) {
                    let inner = new_scope(Some(scope.clone()));
                    self.exec_block(then_b, &inner)
                } else {
                    match else_b {
                        Some(ElseB::Block(b)) => {
                            let inner = new_scope(Some(scope.clone()));
                            self.exec_block(b, &inner)
                        }
                        Some(ElseB::If(st)) => self.exec_stmt(st, scope),
                        None => Ok(Flow::Normal),
                    }
                }
            }
            Stmt::While { cond, body, .. } => {
                loop {
                    let cv = self.eval(cond, scope)?;
                    if !truthy(&cv) { break; }
                    let inner = new_scope(Some(scope.clone()));
                    match self.exec_block(body, &inner)? {
                        Flow::Normal => {},
                        Flow::Break => break,
                        Flow::Continue => {},
                        Flow::Return(v) => return Ok(Flow::Return(v)),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::For { var, iter, body, line } => {
                let list_val = self.eval(iter, scope)?;
                let list = match &list_val {
                    Val::List(l) => l.clone(),
                    _ => return Err(RtErr{line:*line, msg:format!("cannot iterate {}", type_name(&list_val))}),
                };
                let mut i: i64 = 0;
                loop {
                    let len = list.borrow().len() as i64;
                    if i >= len { break; }
                    let elem = list.borrow()[i as usize].clone();
                    let inner = new_scope(Some(scope.clone()));
                    inner.borrow_mut().vars.insert(var.to_string(), elem);
                    match self.exec_block(body, &inner)? {
                        Flow::Normal => {},
                        Flow::Break => break,
                        Flow::Continue => {},
