    }

    fn call_builtin(&mut self, bk: BK, args: Vec<Val>, line: usize) -> Result<Val, RtErr> {
        match bk {
            BK::Print => {
                let parts: Vec<String> = args.iter().map(|v| display_top(v)).collect();
                self.out.push_str(&parts.join(" "));
                self.out.push('\n');
                Ok(Val::Nil)
            }
            BK::Str => {
                if args.len() != 1 { return Err(RtErr{line,msg:format!("expected 1 arguments, got {}",args.len())}); }
                Ok(Val::Str(Rc::new(display_top(&args[0]))))
            }
            BK::Type => {
                if args.len() != 1 { return Err(RtErr{line,msg:format!("expected 1 arguments, got {}",args.len())}); }
                Ok(Val::Str(Rc::new(type_name(&args[0]).to_string())))
            }
            BK::Len => {
                if args.len() != 1 { return Err(RtErr{line,msg:format!("expected 1 arguments, got {}",args.len())}); }
                match &args[0] {
                    Val::Str(s) => Ok(Val::Int(s.len() as i64)),
                    Val::List(l) => Ok(Val::Int(l.borrow().len() as i64)),
                    _ => Err(RtErr{line,msg:"bad argument to len".into()}),
                }
            }
            BK::Push => {
                if args.len() != 2 { return Err(RtErr{line,msg:format!("expected 2 arguments, got {}",args.len())}); }
                match &args[0] {
                    Val::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Val::Nil) }
                    _ => Err(RtErr{line,msg:"bad argument to push".into()}),
                }
            }
            BK::Pop => {
                if args.len() != 1 { return Err(RtErr{line,msg:format!("expected 1 arguments, got {}",args.len())}); }
                match &args[0] {
                    Val::List(l) => {
                        let mut lb = l.borrow_mut();
                        if lb.is_empty() { return Err(RtErr{line,msg:"bad argument to pop".into()}); }
                        Ok(lb.pop().unwrap())
                    }
                    _ => Err(RtErr{line,msg:"bad argument to pop".into()}),
                }
            }
            BK::Range => {
                if args.len() != 2 { return Err(RtErr{line,msg:format!("expected 2 arguments, got {}",args.len())}); }
                match (&args[0], &args[1]) {
                    (Val::Int(a), Val::Int(b)) => {
                        let mut v = Vec::new();
                        let mut i = *a;
                        while i < *b { v.push(Val::Int(i)); i += 1; }
                        Ok(Val::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(RtErr{line,msg:"bad argument to range".into()}),
                }
            }
            BK::Slice => {
                if args.len() != 3 { return Err(RtErr{line,msg:format!("expected 3 arguments, got {}",args.len())}); }
                match (&args[0], &args[1], &args[2]) {
                    (Val::Str(s), Val::Int(a), Val::Int(b)) => {
                        let al = *a as usize; let bl = *b as usize;
                        if *a < 0 || *b < 0 || al > s.len() || bl > s.len() || al > bl {
                            return Err(RtErr{line,msg:"bad argument to slice".into()});
                        }
                        Ok(Val::Str(Rc::new(s[al..bl].to_string())))
                    }
                    (Val::List(l), Val::Int(a), Val::Int(b)) => {
                        let al = *a as usize; let bl = *b as usize;
                        let lb = l.borrow();
                        if *a < 0 || *b < 0 || al > lb.len() || bl > lb.len() || al > bl {
                            return Err(RtErr{line,msg:"bad argument to slice".into()});
                        }
                        Ok(Val::List(Rc::new(RefCell::new(lb[al..bl].to_vec()))))
                    }
                    _ => Err(RtErr{line,msg:"bad argument to slice".into()}),
                }
            }
        }
    }
}

// ============ MAIN ============
fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = std::fs::read_to_string(&path).expect("cannot read program");

    let toks = lex(&src);
