    Neg(Box<Expr>, usize),
    Call { callee: Box<Expr>, args: Rc<Vec<Expr>>, line: usize },
    Index { obj: Box<Expr>, idx: Box<Expr>, line: usize },
    ListLit(Rc<Vec<Expr>>, usize),
    FnExpr { params: Rc<Vec<String>>, body: Rc<Vec<Stmt>>, line: usize },
}

#[derive(Clone)]
enum ElseB {
    If(Box<Stmt>),
    Block(Rc<Vec<Stmt>>),
}

#[derive(Clone)]
enum Stmt {
    LetDecl(Rc<String>, Expr, usize),
    FnDecl(Rc<String>, Rc<Vec<String>>, Rc<Vec<Stmt>>, usize),
    If { cond: Expr, then_b: Rc<Vec<Stmt>>, else_b: Option<ElseB>, line: usize },
    While { cond: Expr, body: Rc<Vec<Stmt>>, line: usize },
    For { var: Rc<String>, iter: Expr, body: Rc<Vec<Stmt>>, line: usize },
    Ret(Option<Expr>, usize),
    Brk(usize),
    Cont(usize),
    Assign(Rc<String>, Expr, usize),
