    fn pk(&self) -> TK { self.toks[self.pos].kind }
    fn pk_at(&self, off: usize) -> TK { self.toks[self.pos + off].kind }
    fn advance(&mut self) -> Token { let t = self.toks[self.pos].clone(); self.pos += 1; t }
    fn expect(&mut self, k: TK) -> Token { let t = self.advance(); assert_eq!(t.kind, k); t }
    fn at(&self, k: TK) -> bool { self.toks[self.pos].kind == k }

