fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = std::fs::read_to_string(&path).expect("cannot read program");

    let toks = lex(&src);
    let mut parser = Parser::new(toks);
    let program = parser.parse_program();

    // Build builtins scope
    let builtins = new_scope(None);
    {
        let mut sb = builtins.borrow_mut();
        sb.vars.insert("print".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Print))));
        sb.vars.insert("str".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Str))));
        sb.vars.insert("type".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Type))));
        sb.vars.insert("len".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Len))));
        sb.vars.insert("push".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Push))));
        sb.vars.insert("pop".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Pop))));
        sb.vars.insert("range".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Range))));
        sb.vars.insert("slice".into(), Val::Func(Rc::new(FuncData::Builtin(BK::Slice))));
    }

    let global = new_scope(Some(builtins));
    let mut interp = Interp::new();

    match interp.exec_block(&program, &global) {
        Ok(_) => {},
        Err(e) => {
            // print everything so far, then the error
            print!("{}", interp.out);
            println!("error at line {}: {}", e.line, e.msg);
            let _ = std::io::stdout().flush();
            process::exit(0);
        }
    }

    print!("{}", interp.out);
    let _ = std::io::stdout().flush();
    process::exit(0);
}
