// Bit reader for DEFLATE (LSB first)
final class BitReader {
    let data: [UInt8]
    var pos: Int
    var bitPos: Int
    init(_ d: [UInt8]) { data = d; pos = 0; bitPos = 0 }
    @inline(__always) func readBit() -> Int {
        let b = Int((data[pos] >> bitPos) & 1)
        bitPos += 1
        if bitPos == 8 { bitPos = 0; pos += 1 }
        return b
    }
    func readBits(_ n: Int) -> Int {
        var v = 0
        for i in 0..<n { v |= readBit() << i }
        return v
    }
    func alignToByte() { if bitPos != 0 { bitPos = 0; pos += 1 } }
    @inline(__always) func readByte() -> UInt8 { let b = data[pos]; pos += 1; return b }
}

