func paeth(_ a: Int, _ b: Int, _ c: Int) -> Int {
    let p = a + b - c
    let pa = abs(p - a), pb = abs(p - b), pc = abs(p - c)
    if pa <= pb && pa <= pc { return a }
    if pb <= pc { return b }
    return c
}

func unfilter(_ data: [UInt8], width: Int, height: Int, channels: Int, bitDepth: Int) -> ([[UInt8]], [Int]) {
    let bpp = max(1, channels * bitDepth / 8)
    let rowBytes = (width * channels * bitDepth + 7) / 8
    var rows = [[UInt8]](repeating: [UInt8](repeating: 0, count: rowBytes), count: height)
    var fc = [Int](repeating: 0, count: 5)
    for y in 0..<height {
        let ft = Int(data[y * (rowBytes + 1)])
        fc[ft] += 1
        let off = y * (rowBytes + 1) + 1
        for x in 0..<rowBytes {
            let raw = Int(data[off + x])
            let a = x >= bpp ? Int(rows[y][x - bpp]) : 0
            let b = y > 0 ? Int(rows[y - 1][x]) : 0
            let c = (y > 0 && x >= bpp) ? Int(rows[y - 1][x - bpp]) : 0
            let v: Int
            switch ft {
            case 0: v = raw
            case 1: v = raw + a
            case 2: v = raw + b
            case 3: v = raw + (a + b) / 2
            case 4: v = raw + paeth(a, b, c)
            default: v = raw
            }
            rows[y][x] = UInt8(v & 0xFF)
        }
    }
    return (rows, fc)
}

func extractSample(_ row: [UInt8], x: Int, channels: Int, bitDepth: Int, si: Int) -> Int {
    if bitDepth >= 8 {
        let bps = bitDepth / 8
        let off = (x * channels + si) * bps
        if bps == 1 { return Int(row[off]) }
        return (Int(row[off]) << 8) | Int(row[off + 1])
    } else {
        let bp = x * bitDepth
        let bi = bp / 8
        let bo = 8 - bitDepth - (bp % 8)
        return (Int(row[bi]) >> bo) & ((1 << bitDepth) - 1)
    }
}

func to8(_ v: Int, _ depth: Int) -> Int {
    if depth == 8 { return v }
    if depth == 16 { return v >> 8 }
    return v * 255 / ((1 << depth) - 1)
}

