    static int getSample(byte[] data, int rowOff, int sampleIdx, int bitDepth) {
        if (bitDepth == 8) return data[rowOff + sampleIdx] & 0xFF;
        if (bitDepth == 16) return ((data[rowOff + sampleIdx * 2] & 0xFF) << 8) | (data[rowOff + sampleIdx * 2 + 1] & 0xFF);
        int spp = 8 / bitDepth;
        int byteIdx = sampleIdx / spp;
        int bitOff = (sampleIdx % spp) * bitDepth;
        int shift = 8 - bitDepth - bitOff;
        return (data[rowOff + byteIdx] >>> shift) & ((1 << bitDepth) - 1);
    }

    static int convert8bit(int v, int bitDepth) {
