        return v * 255 / ((1 << bitDepth) - 1);
    }

    static int convertGray(int v, int bitDepth) {
        if (bitDepth == 8) return v;
        if (bitDepth == 16) return v >> 8;
        return v * 255 / ((1 << bitDepth) - 1);
    }

    static void deflateDecode(byte[] data, byte[] output, int[] blockCounts) {
        BitReader br = new BitReader(data);
        int outPos = 0;

        while (true) {
            int last = br.readBit();
            int btype = br.readBits(2);

            if (btype == 0) {
                blockCounts[0]++;
                br.align();
                int len = (data[br.pos] & 0xFF) | ((data[br.pos + 1] & 0xFF) << 8);
                br.pos += 4; // skip LEN and NLEN
                System.arraycopy(data, br.pos, output, outPos, len);
                outPos += len;
                br.pos += len;
            } else if (btype == 1) {
                blockCounts[1]++;
                outPos = decodeBlock(br, output, outPos, FIXED_LIT_DEC, FIXED_DIST_DEC);
            } else {
                blockCounts[2]++;
                int hlit = br.readBits(5) + 257;
                int hdist = br.readBits(5) + 1;
                int hclen = br.readBits(4) + 4;

                int[] clenLengths = new int[19];
                for (int i = 0; i < hclen; i++) {
                    clenLengths[CLEN_ORDER[i]] = br.readBits(3);
                }

                HuffmanDecoder clenDec = new HuffmanDecoder();
                clenDec.build(clenLengths, 19);

                int[] allLengths = new int[hlit + hdist];
                int idx = 0;
                while (idx < hlit + hdist) {
                    int sym = clenDec.decode(br);
                    if (sym < 16) {
                        allLengths[idx++] = sym;
                    } else if (sym == 16) {
                        int prev = allLengths[idx - 1];
                        int count = br.readBits(2) + 3;
                        for (int k = 0; k < count; k++) allLengths[idx++] = prev;
                    } else if (sym == 17) {
                        int count = br.readBits(3) + 3;
                        for (int k = 0; k < count; k++) allLengths[idx++] = 0;
                    } else {
                        int count = br.readBits(7) + 11;
                        for (int k = 0; k < count; k++) allLengths[idx++] = 0;
                    }
                }

                int[] litLengths = Arrays.copyOfRange(allLengths, 0, hlit);
                int[] distLengths = Arrays.copyOfRange(allLengths, hlit, hlit + hdist);

                HuffmanDecoder litDec = new HuffmanDecoder();
                litDec.build(litLengths, hlit);
                HuffmanDecoder distDec = new HuffmanDecoder();
                distDec.build(distLengths, hdist);

                outPos = decodeBlock(br, output, outPos, litDec, distDec);
            }

            if (last == 1) break;
        }
    }

    static int decodeBlock(BitReader br, byte[] output, int outPos, HuffmanDecoder litDec, HuffmanDecoder distDec) {
        while (true) {
            int sym = litDec.decode(br);
            if (sym < 256) {
                output[outPos++] = (byte) sym;
            } else if (sym == 256) {
                break;
            } else {
                int lenIdx = sym - 257;
                int length = LEN_BASE[lenIdx] + br.readBits(LEN_EXTRA[lenIdx]);
                int distSym = distDec.decode(br);
                int distance = DIST_BASE[distSym] + br.readBits(DIST_EXTRA[distSym]);
                for (int i = 0; i < length; i++) {
                    output[outPos] = output[outPos - distance];
                    outPos++;
                }
            }
        }
        return outPos;
    }
