    }
    let mut tree: Vec<[i32; 2]> = vec![[-1, -1]];
    for (sym, &l) in lengths.iter().enumerate() {
        if l == 0 { continue; }
        let mut node = 0usize;
        for bit in (0..l).rev() {
            let b = ((codes[sym] >> bit) & 1) as usize;
