        tree[0][1] = tree[0][0];
    } else if tree.len() == 2 && tree[0][1] != -1 && tree[0][0] == -1 {
        tree[0][0] = tree[0][1];
    }
    tree
}

fn decode_sym(tree: &[[i32; 2]], br: &mut BitReader) -> u16 {
    let mut node = 0usize;
    loop {
        let bit = br.read_bit() as usize;
        let next = tree[node][bit];
        if next < 0 { return (-(next + 1)) as u16; }
        node = next as usize;
    }
