    for &l in lengths { if l > 0 { bl_count[l as usize] += 1; } }
    let mut next_code = vec![0u32; max_bits + 1];
    let mut code = 0u32;
    for bits in 1..=max_bits {
        code = (code + bl_count[bits - 1]) << 1;
        next_code[bits] = code;
    }
    let mut codes = vec![0u32; lengths.len()];
    for (i, &l) in lengths.iter().enumerate() {
