fn write_png(path: &str, width: usize, height: usize, pixels: &[u8]) {
    let row_size = 1 + width * 3;
    let raw_size = height * row_size;
    let mut raw = Vec::with_capacity(raw_size);
    for y in 0..height {
        raw.push(0u8); // filter None
        let row_start = y * width * 3;
        raw.extend_from_slice(&pixels[row_start..row_start + width * 3]);
    }

    // zlib stream
    let mut zlib = Vec::new();
    zlib.push(0x78u8); // CMF
    zlib.push(0x01u8); // FLG

    // stored deflate blocks
    let mut offset = 0usize;
    while offset < raw.len() {
        let remaining = raw.len() - offset;
        let block_size = if remaining > 65535 { 65535 } else { remaining };
        let is_last = (offset + block_size) >= raw.len();

        zlib.push(if is_last { 1u8 } else { 0u8 });
        zlib.push((block_size & 0xFF) as u8);
        zlib.push(((block_size >> 8) & 0xFF) as u8);
        let nlen = !(block_size as u16);
        zlib.push((nlen & 0xFF) as u8);
        zlib.push(((nlen >> 8) & 0xFF) as u8);
        zlib.extend_from_slice(&raw[offset..offset + block_size]);
        offset += block_size;
    }

    let adler = adler32(&raw);
    zlib.push((adler >> 24) as u8);
    zlib.push((adler >> 16) as u8);
    zlib.push((adler >> 8) as u8);
    zlib.push(adler as u8);

    let mut file = fs::File::create(path).unwrap();
    file.write_all(b"\x89PNG\r\n\x1a\n").unwrap();

    let mut ihdr = Vec::with_capacity(13);
    ihdr.extend_from_slice(&(width as u32).to_be_bytes());
    ihdr.extend_from_slice(&(height as u32).to_be_bytes());
    ihdr.push(8);  // bit depth
    ihdr.push(2);  // color type RGB
    ihdr.push(0);  // compression
    ihdr.push(0);  // filter
    ihdr.push(0);  // interlace
    write_chunk(&mut file, b"IHDR", &ihdr);

    write_chunk(&mut file, b"IDAT", &zlib);
    write_chunk(&mut file, b"IEND", &[]);
}

fn covers(shape: &Shape, x: i64, y: i64) -> bool {
    match shape {
        Shape::Rect { x: rx, y: ry, w, h, .. } => {
            *rx <= x && x < *rx + *w && *ry <= y && y < *ry + *h
        }
        Shape::Circle { cx, cy, r, .. } => {
            let dx = x - *cx;
            let dy = y - *cy;
            dx * dx + dy * dy <= *r * *r
        }
        Shape::Triangle { points, .. } => {
            let (x0, y0) = points[0];
            let (x1, y1) = points[1];
            let (x2, y2) = points[2];
            let e0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0);
            let e1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);
            let e2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2);
            (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
        }
        Shape::Line { x1, y1, x2, y2, r, .. } => {
            let dx = *x2 - *x1;
            let dy = *y2 - *y1;
            let l = dx * dx + dy * dy;
            let t = (x - *x1) * dx + (y - *y1) * dy;
            let r2 = *r * *r;
            if t <= 0 {
                let ddx = x - *x1;
                let ddy = y - *y1;
                ddx * ddx + ddy * ddy <= r2
            } else if t >= l {
                let ddx = x - *x2;
                let ddy = y - *y2;
                ddx * ddx + ddy * ddy <= r2
            } else {
                let c = (x - *x1) * dy - (y - *y1) * dx;
                c * c <= r2 * l
            }
        }
    }
}

fn blend(dst: &mut [u8], idx: usize, color: &[i64; 4]) {
    let a = color[3];
    if a == 0 { return; }
    let inv_a = 255 - a;
    for ch in 0..3 {
        let s = color[ch];
        let d = dst[idx + ch] as i64;
        dst[idx + ch] = ((s * a + d * inv_a + 127) / 255) as u8;
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let json_str = fs::read_to_string(format!("{}/scene.json", dir)).unwrap();
    let mut parser = JsonParser::new(&json_str);
    let scene = parser.parse();

    let obj = as_obj(&scene);
    let width = as_num(get_field(obj, "width")) as usize;
    let height = as_num(get_field(obj, "height")) as usize;
    let bg_arr = as_arr(get_field(obj, "background"));
    let bg = [as_num(&bg_arr[0]) as u8, as_num(&bg_arr[1]) as u8, as_num(&bg_arr[2]) as u8];
    let shapes_arr = as_arr(get_field(obj, "shapes"));

    let mut shapes: Vec<Shape> = Vec::new();
    let mut shape_types: Vec<&str> = Vec::new();

    for sv in shapes_arr {
        let so = as_obj(sv);
        let stype = as_str(get_field(so, "type"));
        match stype {
            "rect" => {
                let x = as_num(get_field(so, "x"));
                let y = as_num(get_field(so, "y"));
                let w = as_num(get_field(so, "w"));
                let h = as_num(get_field(so, "h"));
                let color = parse_color(get_field(so, "color"));
                shapes.push(Shape::Rect { x, y, w, h, color });
            }
            "circle" => {
                let cx = as_num(get_field(so, "cx"));
                let cy = as_num(get_field(so, "cy"));
                let r = as_num(get_field(so, "r"));
                let color = parse_color(get_field(so, "color"));
                shapes.push(Shape::Circle { cx, cy, r, color });
            }
            "triangle" => {
                let pts_arr = as_arr(get_field(so, "points"));
                let p0 = as_arr(&pts_arr[0]);
                let p1 = as_arr(&pts_arr[1]);
                let p2 = as_arr(&pts_arr[2]);
                let points = [
                    (as_num(&p0[0]), as_num(&p0[1])),
                    (as_num(&p1[0]), as_num(&p1[1])),
                    (as_num(&p2[0]), as_num(&p2[1])),
                ];
                let color = parse_color(get_field(so, "color"));
                shapes.push(Shape::Triangle { points, color });
            }
            "line" => {
                let x1 = as_num(get_field(so, "x1"));
                let y1 = as_num(get_field(so, "y1"));
                let x2 = as_num(get_field(so, "x2"));
                let y2 = as_num(get_field(so, "y2"));
                let r = as_num(get_field(so, "r"));
                let color = parse_color(get_field(so, "color"));
                shapes.push(Shape::Line { x1, y1, x2, y2, r, color });
            }
            _ => panic!("unknown shape type: {}", stype),
        }
        shape_types.push(stype);
    }

    // Initialize canvas
    let mut canvas = vec![0u8; width * height * 3];
    for y in 0..height {
        for x in 0..width {
            let idx = (y * width + x) * 3;
            canvas[idx] = bg[0];
            canvas[idx + 1] = bg[1];
            canvas[idx + 2] = bg[2];
        }
    }

    // Render shapes and count coverage
    let mut counts: Vec<usize> = Vec::new();
    for shape in &shapes {
        let mut count = 0usize;
        for y in 0..height as i64 {
            for x in 0..width as i64 {
                if covers(shape, x, y) {
                    count += 1;
                    let idx = (y as usize * width + x as usize) * 3;
                    let color = match shape {
                        Shape::Rect { color, .. } => color,
                        Shape::Circle { color, .. } => color,
                        Shape::Triangle { color, .. } => color,
                        Shape::Line { color, .. } => color,
                    };
                    blend(&mut canvas, idx, color);
                }
            }
        }
        counts.push(count);
    }

    // Count distinct colors
    let mut color_set: Vec<u32> = Vec::new();
    {
        let mut seen = std::collections::HashSet::new();
        for y in 0..height {
            for x in 0..width {
                let idx = (y * width + x) * 3;
                let key: u32 = (canvas[idx] as u32) << 16
                    | (canvas[idx + 1] as u32) << 8
                    | canvas[idx + 2] as u32;
                seen.insert(key);
            }
        }
        color_set = seen.into_iter().collect();
    }
    let num_colors = color_set.len();

    // Write PNG
    write_png("out.png", width, height, &canvas);

    // Print summary
    let mut out = String::new();
    for i in 0..shapes.len() {
        out.push_str(&format!("{} {} {}\n", i + 1, shape_types[i], counts[i]));
    }
    out.push_str(&format!("colors {}\n", num_colors));
    print!("{}", out);
}
