use std::env;
use std::fs;
use std::io::Write;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Num(i64),
    Str(String),
    Arr(Vec<JsonValue>),
    Obj(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn parse(&mut self) -> JsonValue {
        self.skip_ws();
        match self.input[self.pos] {
            b'{' => self.parse_obj(),
            b'[' => self.parse_arr(),
            b'"' => JsonValue::Str(self.parse_str()),
            b't' => { self.pos += 4; JsonValue::Bool(true) }
            b'f' => { self.pos += 5; JsonValue::Bool(false) }
            b'n' => { self.pos += 4; JsonValue::Null }
            _ => JsonValue::Num(self.parse_num()),
        }
    }
    fn parse_obj(&mut self) -> JsonValue {
        self.pos += 1;
        let mut entries = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
            return JsonValue::Obj(entries);
        }
        loop {
            self.skip_ws();
            let key = self.parse_str();
            self.skip_ws();
            self.pos += 1; // ':'
            let val = self.parse();
            entries.push((key, val));
            self.skip_ws();
            if self.pos < self.input.len() && self.input[self.pos] == b',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.skip_ws();
        self.pos += 1; // '}'
        JsonValue::Obj(entries)
    }
    fn parse_arr(&mut self) -> JsonValue {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
            return JsonValue::Arr(items);
        }
        loop {
            let val = self.parse();
            items.push(val);
            self.skip_ws();
            if self.pos < self.input.len() && self.input[self.pos] == b',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.skip_ws();
        self.pos += 1; // ']'
        JsonValue::Arr(items)
    }
    fn parse_str(&mut self) -> String {
        self.pos += 1; // '"'
        let mut s = Vec::new();
        while self.input[self.pos] != b'"' {
            if self.input[self.pos] == b'\\' {
                self.pos += 1;
                match self.input[self.pos] {
                    b'n' => s.push(b'\n'),
                    b't' => s.push(b'\t'),
                    b'r' => s.push(b'\r'),
                    b'\\' => s.push(b'\\'),
                    b'"' => s.push(b'"'),
                    b'/' => s.push(b'/'),
                    b'u' => { self.pos += 4; s.push(b'?'); }
                    c => s.push(c),
                }
            } else {
                s.push(self.input[self.pos]);
            }
            self.pos += 1;
        }
        self.pos += 1; // '"'
        String::from_utf8(s).unwrap()
    }
    fn parse_num(&mut self) -> i64 {
        let neg = self.input[self.pos] == b'-';
        if neg { self.pos += 1; }
        let mut n: i64 = 0;
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
            n = n * 10 + (self.input[self.pos] - b'0') as i64;
            self.pos += 1;
        }
        if neg { -n } else { n }
    }
}

