                else if (s === 17) { const r = reader.readBits(3) + 3; for (let i = 0; i < r; i++) allLens[idx++] = 0; }
                else { const r = reader.readBits(7) + 11; for (let i = 0; i < r; i++) allLens[idx++] = 0; }
            }
            const litTree = buildHuffmanTree(allLens.slice(0, hlit));
            let distLens = allLens.slice(hlit, hlit + hdist);
            // Handle case where all distance codes are 0 (single code tree)
            const hasDist = distLens.some(l => l > 0);
            let distTree: HNode;
            if (!hasDist) {
                // Build a dummy tree with one code
                const dummy = new Array(30).fill(0);
                dummy[0] = 1; dummy[1] = 1;
                distTree = buildHuffmanTree(dummy);
            } else {
                distTree = buildHuffmanTree(distLens);
            }
            inflateBlock(reader, litTree, distTree, output);
        }
    }
    reader.alignByte();
    const a3 = ((reader.readByte() << 24) | (reader.readByte() << 16) | (reader.readByte() << 8) | reader.readByte()) >>> 0;
    const outputBuf = Buffer.from(output);
    return { output: outputBuf, stored, fixed, dynamic, adlerOk: adler32(outputBuf) === a3 };
}

// Paeth predictor
function paeth(a: number, b: number, c: number): number {
    const p = a + b - c;
    const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
    if (pa <= pb && pa <= pc) return a;
    if (pb <= pc) return b;
    return c;
}

// Extract a sample from a scanline
function extractSample(scanline: Buffer, pixelX: number, ch: number, channels: number, bitDepth: number): number {
    if (bitDepth === 8) return scanline[pixelX * channels + ch];
    if (bitDepth === 16) { const o = pixelX * channels * 2 + ch * 2; return (scanline[o] << 8) | scanline[o + 1]; }
    // 1, 2, 4
    const bitOff = pixelX * channels * bitDepth + ch * bitDepth;
    const byteOff = bitOff >> 3;
    const bitPos = bitOff & 7; // from MSB
    return (scanline[byteOff] >> (8 - bitPos - bitDepth)) & ((1 << bitDepth) - 1);
}

function to8bit(v: number, bitDepth: number): number {
    if (bitDepth === 16) return v >> 8;
    if (bitDepth === 8) return v;
    // 1, 2, 4
    return (v * 255) / ((1 << bitDepth) - 1);
}

function main(): void {
    const dir = process.argv[2];
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.png')).sort((a, b) => {
        const ba = Buffer.from(a, 'binary');
        const bb = Buffer.from(b, 'binary');
        return ba.compare(bb);
    });

