            pos += 4;
            const type = data.subarray(pos, pos + 4).toString('ascii');
            pos += 4;
            const cdata = data.subarray(pos, pos + len);
            pos += len;
            const storedCrc = ((data[pos] << 24) | (data[pos + 1] << 16) | (data[pos + 2] << 8) | data[pos + 3]) >>> 0;
            pos += 4;

            if (crcError === -1) {
                const computed = crc32(Buffer.concat([Buffer.from(type, 'ascii'), cdata]));
                if (computed !== storedCrc) {
                    crcError = chunkNum;
                    crcErrorType = type;
                }
            }

            chunkTypes.push(type);
            chunkData.push(cdata);

            if (type === 'IEND') break;
        }

        if (crcError !== -1) {
            out.push(`error: CRC mismatch in chunk ${crcError} ${crcErrorType}`);
            continue;
        }

        // Parse IHDR
        const ihdr = chunkData[0];
        const width = (ihdr[0] << 24) | (ihdr[1] << 16) | (ihdr[2] << 8) | ihdr[3];
        const height = (ihdr[4] << 24) | (ihdr[5] << 16) | (ihdr[6] << 8) | ihdr[7];
        const bitDepth = ihdr[8];
        const colorType = ihdr[9];
