        if (trns && colorType === 2) {
            trnsR = (trns[0] << 8) | trns[1];
            trnsG = (trns[2] << 8) | trns[3];
            trnsB = (trns[4] << 8) | trns[5];
        }
        const trnsCount = trns ? trns.length : 0;

        for (let y = 0; y < height; y++) {
            const row = raw[y];
            for (let x = 0; x < width; x++) {
                let r = 0, g = 0, b = 0, a = 255;
                if (colorType === 0) {
                    const v = extractSample(row, x, 0, channels, bitDepth);
                    const gray = to8bit(v, bitDepth);
                    r = g = b = gray;
                    if (trns && v === trnsGray) a = 0;
                } else if (colorType === 2) {
                    const vr = extractSample(row, x, 0, channels, bitDepth);
                    const vg = extractSample(row, x, 1, channels, bitDepth);
                    const vb = extractSample(row, x, 2, channels, bitDepth);
                    r = to8bit(vr, bitDepth); g = to8bit(vg, bitDepth); b = to8bit(vb, bitDepth);
                    if (trns && vr === trnsR && vg === trnsG && vb === trnsB) a = 0;
