                    if (trns && idx < trnsCount) a = trns[idx];
                } else if (colorType === 4) {
                    const v = extractSample(row, x, 0, channels, bitDepth);
                    const va = extractSample(row, x, 1, channels, bitDepth);
                    r = g = b = to8bit(v, bitDepth);
                    a = to8bit(va, bitDepth);
                } else { // colorType === 6
                    r = to8bit(extractSample(row, x, 0, channels, bitDepth), bitDepth);
                    g = to8bit(extractSample(row, x, 1, channels, bitDepth), bitDepth);
                    b = to8bit(extractSample(row, x, 2, channels, bitDepth), bitDepth);
                    a = to8bit(extractSample(row, x, 3, channels, bitDepth), bitDepth);
                }
                rgba[rgbaIdx++] = r; rgba[rgbaIdx++] = g; rgba[rgbaIdx++] = b; rgba[rgbaIdx++] = a;
                sumR += r; sumG += g; sumB += b; sumA += a;
            }
        }

        // Format chunks line
        const chunkStrs: string[] = [];
        let ci = 0;
        while (ci < chunkTypes.length) {
            let run = 1;
            while (ci + run < chunkTypes.length && chunkTypes[ci + run] === chunkTypes[ci]) run++;
            if (run > 1) chunkStrs.push(`${chunkTypes[ci]}*${run}`);
            else chunkStrs.push(chunkTypes[ci]);
            ci += run;
        }

        const rgbaCrc = crc32(rgba).toString(16).padStart(8, '0');

        out.push(`IHDR ${width}x${height} depth=${bitDepth} color=${colorType}`);
        out.push(`chunks ${chunkStrs.join(' ')}`);
        out.push(`deflate stored=${inf.stored} fixed=${inf.fixed} dynamic=${inf.dynamic}`);
        out.push(`filters none=${filters[0]} sub=${filters[1]} up=${filters[2]} average=${filters[3]} paeth=${filters[4]}`);
        out.push(`rgba sum=${sumR},${sumG},${sumB},${sumA} crc32=${rgbaCrc}`);
    }

    process.stdout.write(out.join('\n') + '\n');
}

