#!/usr/bin/env python3
import sys
import json
import socket
import base64
import time
import urllib.parse


def form_urlencode(s):
    result = []
    for byte in s.encode('utf-8'):
        if (0x41 <= byte <= 0x5A) or (0x61 <= byte <= 0x7A) or (0x30 <= byte <= 0x39) or byte in (0x2D, 0x2E, 0x5F, 0x2A):
            result.append(chr(byte))
        elif byte == 0x20:
            result.append('+')
        else:
            result.append('%%%02X' % byte)
    return ''.join(result)


def read_line(sock):
    data = b''
    while True:
        b = sock.recv(1)
        if not b:
            break
        data += b
        if b == b'\n':
            break
    return data


def read_exact(sock, n):
    data = b''
    while len(data) < n:
        chunk = sock.recv(n - len(data))
        if not chunk:
            break
        data += chunk
    return data


def read_chunked_body(sock):
    body = b''
    while True:
        line = read_line(sock)
        size_str = line.strip().split(b';')[0]
        chunk_size = int(size_str, 16)
        if chunk_size == 0:
            while True:
                trailer = read_line(sock)
                if trailer == b'\r\n' or trailer == b'\n' or trailer == b'':
                    break
            break
        chunk_data = read_exact(sock, chunk_size)
        body += chunk_data
        read_exact(sock, 2)
    return body


def http_request(method, host, port, path, headers=None, body=None):
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((host, port))

    req = f"{method} {path} HTTP/1.1\r\n"
    req += f"Host: {host}:{port}\r\n"
    if headers:
        for k, v in headers.items():
            req += f"{k}: {v}\r\n"
    body_bytes = None
    if body is not None:
        body_bytes = body.encode('utf-8') if isinstance(body, str) else body
        req += f"Content-Length: {len(body_bytes)}\r\n"
    req += "\r\n"

    sock.sendall(req.encode('utf-8'))
    if body_bytes is not None:
        sock.sendall(body_bytes)

    status_line = read_line(sock).decode('ascii')
    parts = status_line.split(' ', 2)
    status_code = int(parts[1])

    resp_headers = {}
    while True:
        line = read_line(sock)
        if line == b'\r\n' or line == b'\n' or line == b'':
            break
        decoded = line.decode('ascii').rstrip('\r\n')
        key, value = decoded.split(':', 1)
        resp_headers[key.strip().lower()] = value.strip()

    te = resp_headers.get('transfer-encoding', '').lower()
    if 'chunked' in te:
        resp_body = read_chunked_body(sock)
    elif 'content-length' in resp_headers:
        resp_body = read_exact(sock, int(resp_headers['content-length']))
    else:
        resp_body = b''
        while True:
            chunk = sock.recv(65536)
            if not chunk:
                break
            resp_body += chunk

    sock.close()
    return status_code, resp_headers, resp_body


def get_token(host, port, path_prefix, client_id, client_secret, scope):
    encoded_id = form_urlencode(client_id)
    encoded_secret = form_urlencode(client_secret)
    credentials = f"{encoded_id}:{encoded_secret}"
    auth_b64 = base64.b64encode(credentials.encode('utf-8')).decode('ascii')

    path = f"{path_prefix}/oauth/token"
    headers = {
        "Content-Type": "application/x-www-form-urlencoded",
        "Authorization": f"Basic {auth_b64}",
    }
    body = f"grant_type=client_credentials&scope={form_urlencode(scope)}"

    status, resp_headers, resp_body = http_request('POST', host, port, path, headers, body)

    if status != 200:
        return None, f"ERROR {status} {resp_body.decode('utf-8')}"

    data = json.loads(resp_body.decode('utf-8'))
    return data['access_token'], None


def parse_amount_to_cents(amount_str):
    negative = False
    if amount_str.startswith('-'):
        negative = True
        amount_str = amount_str[1:]

    if '.' in amount_str:
        int_part, dec_part = amount_str.split('.')
    else:
        int_part = amount_str
        dec_part = ''

    if len(dec_part) == 1:
        cents = int(dec_part) * 10
    elif len(dec_part) == 2:
        cents = int(dec_part)
    else:
        cents = 0

    total = int(int_part) * 100 + cents
    if negative:
        total = -total
    return total


def format_cents(cents):
    if cents < 0:
        return '-' + format_cents(-cents)
    integer_part = cents // 100
    frac_part = cents % 100
    return f"{integer_part}.{frac_part:02d}"


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(f"{data_dir}/client.json") as f:
        client = json.load(f)

    client_id = client["client_id"]
    client_secret = client["client_secret"]
    scope = client["scope"]
    page_size = client["page_size"]

    parsed = urllib.parse.urlparse(base_url)
    host = parsed.hostname
    port = parsed.port or 80
    path_prefix = parsed.path.rstrip('/')

    # Step 1: get access token
    token, err = get_token(host, port, path_prefix, client_id, client_secret, scope)
    if err:
        print(err)
        return

    # Step 2: fetch pages
    orders = []
    pages = 0
    retries = 0
    reauths = 0
    cursor = None
    fresh_token = True

    while True:
        if cursor is None:
            path = f"{path_prefix}/orders?limit={page_size}"
        else:
            encoded_cursor = urllib.parse.quote(cursor, safe='')
            path = f"{path_prefix}/orders?limit={page_size}&cursor={encoded_cursor}"

        headers = {"Authorization": f"Bearer {token}"}
        status, resp_headers, resp_body = http_request('GET', host, port, path, headers)

        if status == 200:
            pages += 1
            fresh_token = False
            data = json.loads(resp_body.decode('utf-8'))
            page_orders = data.get('data', [])
            orders.extend(page_orders)
            next_cursor = data.get('next_cursor')
            if next_cursor is None:
                break
            cursor = next_cursor

        elif status == 429:
            retries += 1
            fresh_token = False
            retry_after = int(resp_headers.get('retry-after', '1'))
            time.sleep(retry_after)

        elif status == 503:
            retries += 1
            fresh_token = False
            time.sleep(0.5)

        elif status == 401:
            if fresh_token:
                print(f"ERROR {status} {resp_body.decode('utf-8')}")
                return
            reauths += 1
            token, err = get_token(host, port, path_prefix, client_id, client_secret, scope)
            if err:
                print(err)
                return
            fresh_token = True

        else:
            print(f"ERROR {status} {resp_body.decode('utf-8')}")
            return

    # Build report
    totals = {}
    status_counts = {}

    for order in orders:
        st = order.get('status', '')
        status_counts[st] = status_counts.get(st, 0) + 1

        if st != 'cancelled':
            customer = order.get('customer', {})
            name = customer.get('name', '')
            currency = order.get('currency', '')
            amount_str = order.get('amount', '0')
            cents = parse_amount_to_cents(amount_str)
            key = (name, currency)
            totals[key] = totals.get(key, 0) + cents

    sorted_keys = sorted(totals.keys(), key=lambda x: (x[0], x[1]))
    for name, currency in sorted_keys:
        cents = totals[(name, currency)]
        print(f"total {currency} {format_cents(cents)} {name}")

    for st in sorted(status_counts.keys()):
        print(f"status {st} {status_counts[st]}")

    print(f"orders {len(orders)} pages {pages} retries {retries} reauth {reauths}")


