        while (i < s.length() && s.charAt(i) != '.') {
            intPart = intPart * 10 + (s.charAt(i) - '0');
            i++;
        }
        long fracPart = 0;
        int fracDigits = 0;
        if (i < s.length() && s.charAt(i) == '.') {
            i++;
            while (i < s.length()) {
                fracPart = fracPart * 10 + (s.charAt(i) - '0');
                fracDigits++;
                i++;
            }
        }
        if (fracDigits == 1) fracPart *= 10;
        long cents = intPart * 100 + fracPart;
        return neg ? -cents : cents;
    }

    static String formatCents(long cents) {
        boolean neg = cents < 0;
        cents = Math.abs(cents);
        long whole = cents / 100;
        long frac = cents % 100;
        return (neg ? "-" : "") + whole + "." + (frac < 10 ? "0" : "") + frac;
    }

    // --- HTTP ---

    static String getToken(String host, int port, String pathPrefix,
                          String clientId, String clientSecret, String scope) throws Exception {
        String auth = basicAuth(clientId, clientSecret);
        String body = "grant_type=client_credentials&scope=" + formEncode(scope);
        HttpResponse resp = sendRequest(host, port, "POST", pathPrefix + "/oauth/token",
            new String[]{"Content-Type: application/x-www-form-urlencoded",
                        "Authorization: Basic " + auth}, body);
        if (resp.status != 200) {
            System.out.println("ERROR " + resp.status + " " + resp.body);
            System.exit(0);
        }
        @SuppressWarnings("unchecked")
        Map<String, Object> tok = (Map<String, Object>) parseJson(resp.body);
        return (String) tok.get("access_token");
    }

    static HttpResponse sendRequest(String host, int port, String method, String path,
                                   String[] extraHeaders, String body) throws Exception {
        Socket sock = new Socket(host, port);
        sock.setSoTimeout(30000);
        BufferedOutputStream out = new BufferedOutputStream(sock.getOutputStream());
        BufferedInputStream in = new BufferedInputStream(sock.getInputStream());

        StringBuilder req = new StringBuilder();
        req.append(method).append(" ").append(path).append(" HTTP/1.1\r\n");
        String hostHdr = (port == 80) ? host : host + ":" + port;
        req.append("Host: ").append(hostHdr).append("\r\n");
        for (String h : extraHeaders) {
            req.append(h).append("\r\n");
        }
        byte[] bodyBytes = null;
        if (body != null) {
            bodyBytes = body.getBytes(StandardCharsets.UTF_8);
            req.append("Content-Length: ").append(bodyBytes.length).append("\r\n");
        }
        req.append("\r\n");
        out.write(req.toString().getBytes(StandardCharsets.US_ASCII));
        if (bodyBytes != null) out.write(bodyBytes);
        out.flush();

        byte[] statusLineBytes = readLineBytes(in);
        String statusLine = new String(statusLineBytes, StandardCharsets.US_ASCII);
        int status = Integer.parseInt(statusLine.split(" ", 3)[1]);

        Map<String, String> headers = new HashMap<>();
        byte[] hLine;
        while ((hLine = readLineBytes(in)).length > 0) {
            String hs = new String(hLine, StandardCharsets.US_ASCII);
            int colon = hs.indexOf(':');
            if (colon > 0) {
                headers.put(hs.substring(0, colon).toLowerCase(), hs.substring(colon + 1).trim());
            }
        }

        byte[] respBodyBytes;
        String te = headers.get("transfer-encoding");
        if (te != null && te.toLowerCase().contains("chunked")) {
            respBodyBytes = readChunkedBody(in);
        } else if (headers.containsKey("content-length")) {
            int len = Integer.parseInt(headers.get("content-length"));
            respBodyBytes = new byte[len];
            int off = 0;
            while (off < len) {
                int r = in.read(respBodyBytes, off, len - off);
                if (r == -1) break;
                off += r;
            }
        } else {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            int c;
            while ((c = in.read()) != -1) bos.write(c);
            respBodyBytes = bos.toByteArray();
        }

        sock.close();
        return new HttpResponse(status, headers, new String(respBodyBytes, StandardCharsets.UTF_8));
    }

    static byte[] readLineBytes(InputStream in) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\n') break;
            if (c == '\r') {
                in.mark(1);
                int next = in.read();
                if (next != '\n' && next != -1) in.reset();
                break;
            }
            buf.write(c);
        }
        return buf.toByteArray();
    }

    static byte[] readChunkedBody(InputStream in) throws IOException {
        ByteArrayOutputStream body = new ByteArrayOutputStream();
        while (true) {
            byte[] sizeLine = readLineBytes(in);
            String sizeStr = new String(sizeLine, StandardCharsets.US_ASCII).trim();
            int semi = sizeStr.indexOf(';');
            if (semi >= 0) sizeStr = sizeStr.substring(0, semi);
            int chunkSize = Integer.parseInt(sizeStr, 16);
            if (chunkSize == 0) {
                byte[] trailer;
                while ((trailer = readLineBytes(in)).length > 0) { }
                break;
            }
            byte[] chunkData = new byte[chunkSize];
            int off = 0;
            while (off < chunkSize) {
                int r = in.read(chunkData, off, chunkSize - off);
                if (r == -1) break;
                off += r;
            }
            body.write(chunkData, 0, off);
            readLineBytes(in); // consume CRLF after chunk
        }
        return body.toByteArray();
    }

    // --- Encoding ---

    static String formEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                || c == '-' || c == '.' || c == '_' || c == '*') {
                sb.append((char) c);
            } else if (c == ' ') {
                sb.append('+');
            } else {
                sb.append('%').append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static String percentEncodeQuery(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                || c == '-' || c == '.' || c == '_' || c == '~') {
                sb.append((char) c);
            } else {
                sb.append('%').append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static String basicAuth(String clientId, String clientSecret) {
        String joined = formEncode(clientId) + ":" + formEncode(clientSecret);
        return Base64.getEncoder().encodeToString(joined.getBytes(StandardCharsets.UTF_8));
    }

    // --- JSON Parser ---

    static Object parseJson(String s) {
        int[] pos = {0};
        return parseValue(s, pos);
    }

    static void skipWs(String s, int[] pos) {
        while (pos[0] < s.length()) {
            char c = s.charAt(pos[0]);
            if (c == ' ' || c == '\t' || c == '\r' || c == '\n') pos[0]++;
            else break;
        }
    }

    static Object parseValue(String s, int[] pos) {
        skipWs(s, pos);
        char c = s.charAt(pos[0]);
        if (c == '{') return parseObject(s, pos);
        if (c == '[') return parseArray(s, pos);
        if (c == '"') return parseString(s, pos);
        if (c == 't') { pos[0] += 4; return Boolean.TRUE; }
        if (c == 'f') { pos[0] += 5; return Boolean.FALSE; }
        if (c == 'n') { pos[0] += 4; return null; }
        return parseNumber(s, pos);
    }

    static Map<String, Object> parseObject(String s, int[] pos) {
        Map<String, Object> map = new LinkedHashMap<>();
        pos[0]++; // {
        skipWs(s, pos);
        if (pos[0] < s.length() && s.charAt(pos[0]) == '}') { pos[0]++; return map; }
        while (true) {
            skipWs(s, pos);
            String key = parseString(s, pos);
            skipWs(s, pos);
            pos[0]++; // :
            Object val = parseValue(s, pos);
            map.put(key, val);
            skipWs(s, pos);
            if (pos[0] < s.length() && s.charAt(pos[0]) == ',') { pos[0]++; continue; }
            if (pos[0] < s.length() && s.charAt(pos[0]) == '}') { pos[0]++; break; }
        }
        return map;
    }

    static List<Object> parseArray(String s, int[] pos) {
        List<Object> list = new ArrayList<>();
        pos[0]++; // [
        skipWs(s, pos);
        if (pos[0] < s.length() && s.charAt(pos[0]) == ']') { pos[0]++; return list; }
        while (true) {
            Object val = parseValue(s, pos);
            list.add(val);
            skipWs(s, pos);
            if (pos[0] < s.length() && s.charAt(pos[0]) == ',') { pos[0]++; continue; }
            if (pos[0] < s.length() && s.charAt(pos[0]) == ']') { pos[0]++; break; }
        }
        return list;
    }

    static String parseString(String s, int[] pos) {
        pos[0]++; // opening "
        StringBuilder sb = new StringBuilder();
        while (pos[0] < s.length()) {
            char c = s.charAt(pos[0]);
            if (c == '"') { pos[0]++; break; }
            if (c == '\\') {
                pos[0]++;
                char esc = s.charAt(pos[0]);
                switch (esc) {
                    case '"': sb.append('"'); pos[0]++; break;
                    case '\\': sb.append('\\'); pos[0]++; break;
                    case '/': sb.append('/'); pos[0]++; break;
                    case 'b': sb.append('\b'); pos[0]++; break;
                    case 'f': sb.append('\f'); pos[0]++; break;
                    case 'n': sb.append('\n'); pos[0]++; break;
                    case 'r': sb.append('\r'); pos[0]++; break;
                    case 't': sb.append('\t'); pos[0]++; break;
                    case 'u': {
                        int cp = Integer.parseInt(s.substring(pos[0] + 1, pos[0] + 5), 16);
                        pos[0] += 5;
                        if (Character.isHighSurrogate((char) cp)) {
                            if (pos[0] + 5 < s.length() && s.charAt(pos[0]) == '\\' && s.charAt(pos[0] + 1) == 'u') {
                                int lo = Integer.parseInt(s.substring(pos[0] + 2, pos[0] + 6), 16);
                                pos[0] += 6;
                                sb.appendCodePoint(Character.toCodePoint((char) cp, (char) lo));
                            } else {
                                sb.append((char) cp);
                            }
                        } else {
                            sb.append((char) cp);
                        }
                        break;
                    }
                    default: pos[0]++; break;
                }
            } else {
                sb.append(c);
                pos[0]++;
            }
        }
        return sb.toString();
    }

    static Object parseNumber(String s, int[] pos) {
        int start = pos[0];
        if (pos[0] < s.length() && s.charAt(pos[0]) == '-') pos[0]++;
        while (pos[0] < s.length() && Character.isDigit(s.charAt(pos[0]))) pos[0]++;
        boolean isFloat = false;
        if (pos[0] < s.length() && s.charAt(pos[0]) == '.') {
            isFloat = true; pos[0]++;
            while (pos[0] < s.length() && Character.isDigit(s.charAt(pos[0]))) pos[0]++;
        }
        if (pos[0] < s.length() && (s.charAt(pos[0]) == 'e' || s.charAt(pos[0]) == 'E')) {
            isFloat = true; pos[0]++;
            if (pos[0] < s.length() && (s.charAt(pos[0]) == '+' || s.charAt(pos[0]) == '-')) pos[0]++;
            while (pos[0] < s.length() && Character.isDigit(s.charAt(pos[0]))) pos[0]++;
        }
        String numStr = s.substring(start, pos[0]);
        if (isFloat) return Double.parseDouble(numStr);
        return Long.parseLong(numStr);
    }

    // --- HTTP Response holder ---
    static class HttpResponse {
        int status;
        Map<String, String> headers;
        String body;
        HttpResponse(int status, Map<String, String> headers, String body) {
            this.status = status;
            this.headers = headers;
            this.body = body;
        }
    }
