func doHTTP(_ urlStr: String, method: String, headers: [String: String], body: Data?) -> HTTPResponse? {
    guard let url = URL(string: urlStr) else { return nil }
    var req = URLRequest(url: url)
    req.httpMethod = method
    req.timeoutInterval = 60
    for (k, v) in headers {
        req.setValue(v, forHTTPHeaderField: k)
    }
    req.httpBody = body

    let sem = DispatchSemaphore(value: 0)
    var result: HTTPResponse?
    let config = URLSessionConfiguration.default
    config.httpAdditionalHeaders = nil
    let session = URLSession(configuration: config)
    let task = session.dataTask(with: req) { data, response, _ in
        if let hr = response as? HTTPURLResponse {
            var hdrs: [String: String] = [:]
            for (k, v) in hr.allHeaderFields {
                hdrs["\(k)".lowercased()] = "\(v)"
            }
            result = HTTPResponse(status: hr.statusCode, headers: hdrs, body: data ?? Data())
        }
        sem.signal()
    }
    task.resume()
    sem.wait()
    session.invalidateAndCancel()
    return result
}

