def to_camel(name):
    result = []
    i = 0
    n = len(name)
    while i < n:
        if name[i] == '_':
            i += 1
            if i < n:
                c = name[i]
                if 'a' <= c <= 'z':
                    result.append(c.upper())
                else:
                    result.append(c)
                i += 1
        else:
            result.append(name[i])
            i += 1
    return ''.join(result)

def escape_json_str(s):
    parts = ['"']
    for ch in s:
        cp = ord(ch)
        if ch == '"':
            parts.append('\\"')
        elif ch == '\\':
            parts.append('\\\\')
        elif cp == 0x08:
            parts.append('\\b')
        elif cp == 0x09:
            parts.append('\\t')
        elif cp == 0x0A:
            parts.append('\\n')
        elif cp == 0x0C:
            parts.append('\\f')
        elif cp == 0x0D:
            parts.append('\\r')
        elif cp < 0x20:
            parts.append('\\u%04x' % cp)
        else:
            parts.append(ch)
    parts.append('"')
    return ''.join(parts)

