    if fi['label'] == 'optional':
        return True
    if fi['oneof'] is not None:
        return True
    return not is_default_value(msg['fields'][fn], fi['type'], schema)

def value_to_json(value, type_name, schema):
    if is_msg_type(type_name, schema):
        return message_to_json(value, type_name, schema)
    elif type_name == 'string':
        return escape_json_str(value)
    elif type_name == 'bytes':
