        if value in enum_info['values']:
            return escape_json_str(enum_info['values'][value])
        else:
            return str(value)
    elif type_name in ('int32', 'uint32', 'sint32', 'fixed32', 'sfixed32'):
        return str(value)
    elif type_name in ('int64', 'uint64', 'sint64', 'fixed64', 'sfixed64'):
        return '"' + str(value) + '"'
    else:
        return str(value)

def map_to_json(map_data, fi, schema):
    if fi['map_key_type'] == 'string':
        keys = sorted(map_data.keys(), key=lambda k: k.encode('utf-8'))
    else:
        keys = sorted(map_data.keys())
    parts = []
    for k in keys:
        v = map_data[k]
        if fi['map_key_type'] == 'string':
            json_key = escape_json_str(k)
        else:
            json_key = escape_json_str(str(k))
        json_val = value_to_json(v, fi['map_value_type'], schema)
        parts.append(json_key + ':' + json_val)
    return '{' + ','.join(parts) + '}'

def message_to_json(msg, msg_name, schema):
    msg_info = schema['messages'][msg_name]
    entries = []
    for fn in sorted(msg['fields'].keys()):
        fi = msg_info['fields'][fn]
        if should_print(fn, fi, msg, schema):
            json_name = to_camel(fi['name'])
            if fi['is_map']:
                json_val = map_to_json(msg['fields'][fn], fi, schema)
