                json_val = '[' + ','.join(value_to_json(v, fi['type'], schema) for v in msg['fields'][fn]) + ']'
            else:
                json_val = value_to_json(msg['fields'][fn], fi['type'], schema)
            entries.append(escape_json_str(json_name) + ':' + json_val)
    return '{' + ','.join(entries) + '}'

