        if (t.value === 'option') {
          this.skipToSemicolon();
        } else if (t.value === 'reserved') {
          this.skipToSemicolon();
        } else if (t.value === 'message' && this.isNestedDecl('message')) {
          this.parseMessage();
        } else if (t.value === 'enum' && this.isNestedDecl('enum')) {
          this.parseEnum();
        } else if (t.value === 'oneof') {
          this.parseOneof(msgDef);
        } else if (t.value === 'map') {
          this.parseMapField(msgDef);
        } else if (t.value === 'repeated' || t.value === 'optional') {
          this.parseField(msgDef, t.value);
        } else {
          this.parseField(msgDef, 'singular');
        }
      } else {
        this.next();
      }
    }
    this.expect('punct', '}');
  }

  parseField(msgDef: MessageDef, label: string): void {
    let labelStr: 'optional' | 'repeated' | 'singular' = 'singular';
    let isOptional = false;
    if (label === 'repeated') { labelStr = 'repeated'; this.next(); }
    else if (label === 'optional') { labelStr = 'optional'; isOptional = true; this.next(); }

    const type = this.expect('ident').value;
    const name = this.expect('ident').value;
    this.expect('punct', '=');
    const number = parseInt(this.expect('number').value);
    this.skipOptionList();
    this.expect('punct', ';');

    msgDef.fields.set(number, { number, name, type, label: labelStr, isOptional });
  }

  parseMapField(msgDef: MessageDef): void {
    this.next(); // consume 'map'
    this.expect('punct', '<');
    const keyType = this.expect('ident').value;
    this.expect('punct', ',');
    const valueType = this.expect('ident').value;
    this.expect('punct', '>');
    const name = this.expect('ident').value;
    this.expect('punct', '=');
    const number = parseInt(this.expect('number').value);
    this.skipOptionList();
    this.expect('punct', ';');

    msgDef.fields.set(number, { number, name, type: valueType, label: 'map', keyType, isOptional: false });
  }

  parseOneof(msgDef: MessageDef): void {
    this.next(); // consume 'oneof'
    const oneofName = this.expect('ident').value;
    this.expect('punct', '{');

    while (!this.match('punct', '}') && this.pos < this.tokens.length) {
      const t = this.peek();
      if (!t) break;
      if (t.type === 'ident') {
        if (t.value === 'option') {
          this.skipToSemicolon();
        } else {
          const type = this.expect('ident').value;
          const name = this.expect('ident').value;
          this.expect('punct', '=');
          const number = parseInt(this.expect('number').value);
          this.skipOptionList();
          this.expect('punct', ';');
          msgDef.fields.set(number, { number, name, type, label: 'singular', oneofName, isOptional: false });
        }
      } else {
        this.next();
      }
    }
    this.expect('punct', '}');
  }

  parseEnum(): void {
    this.next(); // consume 'enum'
    const name = this.expect('ident').value;
    this.expect('punct', '{');

    const enumDef: EnumDef = { name, values: new Map() };
    enums.set(name, enumDef);

    while (!this.match('punct', '}') && this.pos < this.tokens.length) {
      const t = this.peek();
      if (!t) break;
      if (t.type === 'ident') {
        if (t.value === 'option' || t.value === 'reserved') {
          this.skipToSemicolon();
        } else {
          const valueName = this.expect('ident').value;
          this.expect('punct', '=');
          const valueNum = parseInt(this.expect('number').value);
          this.skipOptionList();
          this.expect('punct', ';');
          enumDef.values.set(valueNum, valueName);
        }
      } else {
        this.next();
      }
    }
    this.expect('punct', '}');
  }
}

// ============ BINARY DECODING ============

function readVarint(buf: Buffer, pos: number): [bigint, number] {
  let result = 0n;
  let shift = 0;
  for (let i = 0; i < 10; i++) {
    if (pos >= buf.length) throw new Error("EOF in varint");
    const byte = buf[pos];
    result |= BigInt(byte & 0x7f) << BigInt(shift);
    pos++;
    if ((byte & 0x80) === 0) return [result, pos];
    shift += 7;
  }
  throw new Error("Varint too long");
}

function skipField(buf: Buffer, pos: number, wireType: number, fieldNumber: number): number {
  switch (wireType) {
    case 0: { const [, np] = readVarint(buf, pos); return np; }
    case 1: return pos + 8;
    case 2: { const [len, np] = readVarint(buf, pos); return np + Number(len); }
    case 5: return pos + 4;
    case 3: {
      while (pos < buf.length) {
        const [key, np] = readVarint(buf, pos);
        pos = np;
        const fn = Number(key >> 3n);
        const wt = Number(key & 7n);
        if (wt === 4 && fn === fieldNumber) return pos;
        pos = skipField(buf, pos, wt, fn);
      }
      throw new Error("Unterminated group");
    }
    case 4: return pos;
    default: throw new Error(`Unknown wire type ${wireType}`);
  }
}

function isNumericType(typeName: string): boolean {
  return ['int32','int64','uint32','uint64','sint32','sint64','bool','fixed32','fixed64','sfixed32','sfixed64'].includes(typeName) || enums.has(typeName);
}

function isFixed32Type(typeName: string): boolean {
  return typeName === 'fixed32' || typeName === 'sfixed32';
}

function isFixed64Type(typeName: string): boolean {
  return typeName === 'fixed64' || typeName === 'sfixed64';
}

function varintToInt32(v: bigint): number {
  let x = Number(v & 0xFFFFFFFFn);
  if (x >= 0x80000000) x -= 0x100000000;
  return x;
}

function varintToInt64(v: bigint): bigint {
  let x = v & 0xFFFFFFFFFFFFFFFFn;
  if (x >= (1n << 63n)) x -= (1n << 64n);
  return x;
}

function zigzagDecode32(v: bigint): number {
  const n = v & 0xFFFFFFFFn;
  const decoded = (n >> 1n) ^ (-(n & 1n));
  return Number(decoded);
}

function zigzagDecode64(v: bigint): bigint {
  const n = v & 0xFFFFFFFFFFFFFFFFn;
  return (n >> 1n) ^ (-(n & 1n));
}

function convertVarint(v: bigint, typeName: string): any {
  switch (typeName) {
    case 'int32': return varintToInt32(v);
    case 'int64': return varintToInt64(v);
    case 'uint32': return Number(v & 0xFFFFFFFFn);
    case 'uint64': return v & 0xFFFFFFFFFFFFFFFFn;
    case 'sint32': return zigzagDecode32(v);
    case 'sint64': return zigzagDecode64(v);
    case 'bool': return v !== 0n;
    default: return varintToInt32(v); // enum
  }
}

function decodeScalar(buf: Buffer, pos: number, wireType: number, typeName: string): { value: any; nextPos: number } {
  switch (typeName) {
    case 'int32': case 'int64': case 'uint32': case 'uint64':
    case 'sint32': case 'sint64': case 'bool': {
      const [v, np] = readVarint(buf, pos);
      return { value: convertVarint(v, typeName), nextPos: np };
    }
    case 'string': {
      const [len, np] = readVarint(buf, pos);
      const s = buf.subarray(np, np + Number(len)).toString('utf8');
      return { value: s, nextPos: np + Number(len) };
    }
    case 'bytes': {
      const [len, np] = readVarint(buf, pos);
      const b = buf.subarray(np, np + Number(len));
      return { value: b, nextPos: np + Number(len) };
    }
    case 'fixed32': return { value: buf.readUInt32LE(pos), nextPos: pos + 4 };
    case 'sfixed32': return { value: buf.readInt32LE(pos), nextPos: pos + 4 };
    case 'fixed64': return { value: buf.readBigUInt64LE(pos), nextPos: pos + 8 };
    case 'sfixed64': return { value: buf.readBigInt64LE(pos), nextPos: pos + 8 };
    default: { // enum
      const [v, np] = readVarint(buf, pos);
      return { value: varintToInt32(v), nextPos: np };
    }
  }
}

function decodePacked(payload: Buffer, typeName: string): any[] {
  const result: any[] = [];
  let pos = 0;
  while (pos < payload.length) {
    if (isFixed32Type(typeName)) {
      if (typeName === 'fixed32') result.push(payload.readUInt32LE(pos));
      else result.push(payload.readInt32LE(pos));
      pos += 4;
    } else if (isFixed64Type(typeName)) {
      if (typeName === 'fixed64') result.push(payload.readBigUInt64LE(pos));
      else result.push(payload.readBigInt64LE(pos));
      pos += 8;
    } else {
      const [v, np] = readVarint(payload, pos);
      result.push(convertVarint(v, typeName));
      pos = np;
    }
  }
  return result;
}

function decodeMessage(data: Buffer, msgDef: MessageDef): DecodedMsg {
  const result: DecodedMsg = {
    fields: new Map(),
    seen: new Set(),
    oneofSet: new Map(),
  };

  let pos = 0;
  while (pos < data.length) {
    const [key, newPos] = readVarint(data, pos);
    pos = newPos;
    const fieldNumber = Number(key >> 3n);
    const wireType = Number(key & 7n);

    const fieldDef = msgDef.fields.get(fieldNumber);
    if (!fieldDef) {
      pos = skipField(data, pos, wireType, fieldNumber);
      continue;
    }

    // oneof: clear other members
    if (fieldDef.oneofName) {
      const prevSet = result.oneofSet.get(fieldDef.oneofName);
      if (prevSet !== undefined && prevSet !== fieldNumber) {
        result.fields.delete(prevSet);
        result.seen.delete(prevSet);
      }
      result.oneofSet.set(fieldDef.oneofName, fieldNumber);
    }

    const isNumeric = isNumericType(fieldDef.type);
    const isMsg = messages.has(fieldDef.type);

    if (fieldDef.label === 'repeated') {
      if (isNumeric && wireType === 2) {
        const [len, np] = readVarint(data, pos);
        pos = np;
        const payload = data.subarray(pos, pos + Number(len));
        pos += Number(len);
        const elements = decodePacked(payload, fieldDef.type);
        if (!result.fields.has(fieldNumber)) result.fields.set(fieldNumber, []);
        (result.fields.get(fieldNumber) as any[]).push(...elements);
      } else {
        const val = decodeScalar(data, pos, wireType, fieldDef.type);
        pos = val.nextPos;
        if (!result.fields.has(fieldNumber)) result.fields.set(fieldNumber, []);
        (result.fields.get(fieldNumber) as any[]).push(val.value);
      }
      result.seen.add(fieldNumber);
    } else if (fieldDef.label === 'map') {
      const [len, np] = readVarint(data, pos);
      pos = np;
      const entryData = data.subarray(pos, pos + Number(len));
      pos += Number(len);
      const entry = decodeMapEntry(entryData, fieldDef.keyType!, fieldDef.type);
      if (!result.fields.has(fieldNumber)) result.fields.set(fieldNumber, new Map());
      result.fields.get(fieldNumber).set(entry.key, entry.value);
      result.seen.add(fieldNumber);
    } else {
      // singular (including optional and oneof members)
      if (isMsg) {
        const [len, np] = readVarint(data, pos);
        pos = np;
        const subData = data.subarray(pos, pos + Number(len));
        pos += Number(len);
        const subDef = messages.get(fieldDef.type)!;
        if (result.seen.has(fieldNumber) && result.fields.has(fieldNumber)) {
          mergeInto(result.fields.get(fieldNumber), subData, subDef);
        } else {
          result.fields.set(fieldNumber, decodeMessage(subData, subDef));
        }
        result.seen.add(fieldNumber);
      } else {
        const val = decodeScalar(data, pos, wireType, fieldDef.type);
        pos = val.nextPos;
        result.fields.set(fieldNumber, val.value);
        result.seen.add(fieldNumber);
      }
    }
  }

  return result;
}

function mergeInto(target: DecodedMsg, newData: Buffer, msgDef: MessageDef): void {
  const source = decodeMessage(newData, msgDef);
  for (const [fn, val] of source.fields) {
    const fdef = msgDef.fields.get(fn);
    if (!fdef) continue;
    if (fdef.label === 'repeated') {
      if (!target.fields.has(fn)) target.fields.set(fn, []);
      (target.fields.get(fn) as any[]).push(...(val as any[]));
    } else if (fdef.label === 'map') {
      if (!target.fields.has(fn)) target.fields.set(fn, new Map());
      for (const [k, v] of (val as Map<any, any>)) {
        target.fields.get(fn).set(k, v);
      }
    } else {
      if (messages.has(fdef.type)) {
        if (target.fields.has(fn) && target.seen.has(fn)) {
          mergeInto(target.fields.get(fn), encodeSub(val), messages.get(fdef.type)!);
        } else {
          target.fields.set(fn, val);
        }
      } else {
        target.fields.set(fn, val);
      }
      target.seen.add(fn);
    }
  }
  // merge oneof state from source
  for (const [name, fn] of source.oneofSet) {
    const prev = target.oneofSet.get(name);
    if (prev !== undefined && prev !== fn) {
      target.fields.delete(prev);
      target.seen.delete(prev);
    }
    target.oneofSet.set(name, fn);
  }
}

// We need to re-encode a DecodedMsg to merge nested messages.
// Actually, let's change approach: merge decoded messages directly.
function mergeDecoded(target: DecodedMsg, source: DecodedMsg, msgDef: MessageDef): void {
  for (const [fn, val] of source.fields) {
    const fdef = msgDef.fields.get(fn);
    if (!fdef) continue;
    if (fdef.label === 'repeated') {
      if (!target.fields.has(fn)) target.fields.set(fn, []);
      (target.fields.get(fn) as any[]).push(...(val as any[]));
    } else if (fdef.label === 'map') {
      if (!target.fields.has(fn)) target.fields.set(fn, new Map());
      for (const [k, v] of (val as Map<any, any>)) {
        target.fields.get(fn).set(k, v);
      }
    } else {
      if (messages.has(fdef.type)) {
        if (target.fields.has(fn) && target.seen.has(fn)) {
          mergeDecoded(target.fields.get(fn), val, messages.get(fdef.type)!);
        } else {
          target.fields.set(fn, val);
        }
      } else {
        target.fields.set(fn, val);
      }
      target.seen.add(fn);
    }
  }
  for (const [name, fn] of source.oneofSet) {
    const prev = target.oneofSet.get(name);
    if (prev !== undefined && prev !== fn) {
      target.fields.delete(prev);
      target.seen.delete(prev);
    }
    target.oneofSet.set(name, fn);
  }
}

function encodeSub(_val: DecodedMsg): Buffer {
  // Not needed with mergeDecoded approach
  throw new Error("not used");
}

function decodeMapEntry(data: Buffer, keyType: string, valType: string): { key: any; value: any } {
  let key: any = keyType === 'string' ? '' : 0;
  let value: any = getDefaultForType(valType);
  let pos = 0;
  while (pos < data.length) {
    const [keyVarint, np] = readVarint(data, pos);
    pos = np;
    const fn = Number(keyVarint >> 3n);
    const wt = Number(keyVarint & 7n);

    if (fn === 1) {
      const val = decodeScalar(data, pos, wt, keyType);
      key = val.value;
      pos = val.nextPos;
    } else if (fn === 2) {
      if (messages.has(valType)) {
        const [len, np2] = readVarint(data, pos);
        pos = np2;
        const subData = data.subarray(pos, pos + Number(len));
        pos += Number(len);
        value = decodeMessage(subData, messages.get(valType)!);
      } else {
        const val = decodeScalar(data, pos, wt, valType);
        value = val.value;
        pos = val.nextPos;
      }
    } else {
      pos = skipField(data, pos, wt, fn);
    }
  }
  return { key, value };
}

function getDefaultForType(typeName: string): any {
  switch (typeName) {
    case 'string': return '';
    case 'bytes': return Buffer.alloc(0);
    case 'bool': return false;
    case 'int64': case 'uint64': case 'sint64': case 'fixed64': case 'sfixed64': return 0n;
    default: return 0; // int32, uint32, sint32, fixed32, sfixed32, enum, message handled separately
  }
}

