function decodeMessageFixed(data: Buffer, msgDef: MessageDef): DecodedMsg {
  const result: DecodedMsg = {
    fields: new Map(),
    seen: new Set(),
    oneofSet: new Map(),
  };

  let pos = 0;
  while (pos < data.length) {
    const [key, newPos] = readVarint(data, pos);
    pos = newPos;
    const fieldNumber = Number(key >> 3n);
    const wireType = Number(key & 7n);

    const fieldDef = msgDef.fields.get(fieldNumber);
    if (!fieldDef) {
      pos = skipField(data, pos, wireType, fieldNumber);
      continue;
    }

    if (fieldDef.oneofName) {
      const prevSet = result.oneofSet.get(fieldDef.oneofName);
      if (prevSet !== undefined && prevSet !== fieldNumber) {
        result.fields.delete(prevSet);
        result.seen.delete(prevSet);
      }
      result.oneofSet.set(fieldDef.oneofName, fieldNumber);
    }

    const isNumeric = isNumericType(fieldDef.type);
    const isMsg = messages.has(fieldDef.type);

    if (fieldDef.label === 'repeated') {
      if (isNumeric && wireType === 2) {
        const [len, np] = readVarint(data, pos);
        pos = np;
        const payload = data.subarray(pos, pos + Number(len));
        pos += Number(len);
        const elements = decodePacked(payload, fieldDef.type);
        if (!result.fields.has(fieldNumber)) result.fields.set(fieldNumber, []);
        (result.fields.get(fieldNumber) as any[]).push(...elements);
      } else {
        const val = decodeScalar(data, pos, wireType, fieldDef.type);
        pos = val.nextPos;
        if (!result.fields.has(fieldNumber)) result.fields.set(fieldNumber, []);
        (result.fields.get(fieldNumber) as any[]).push(val.value);
      }
      result.seen.add(fieldNumber);
    } else if (fieldDef.label === 'map') {
      const [len, np] = readVarint(data, pos);
      pos = np;
      const entryData = data.subarray(pos, pos + Number(len));
      pos += Number(len);
      const entry = decodeMapEntry(entryData, fieldDef.keyType!, fieldDef.type);
      if (!result.fields.has(fieldNumber)) result.fields.set(fieldNumber, new Map());
      result.fields.get(fieldNumber).set(entry.key, entry.value);
      result.seen.add(fieldNumber);
    } else {
      // singular
      if (isMsg) {
        const [len, np] = readVarint(data, pos);
        pos = np;
        const subData = data.subarray(pos, pos + Number(len));
        pos += Number(len);
        const subDef = messages.get(fieldDef.type)!;
        if (result.seen.has(fieldNumber) && result.fields.has(fieldNumber)) {
          const newSub = decodeMessageFixed(subData, subDef);
          mergeDecoded(result.fields.get(fieldNumber), newSub, subDef);
        } else {
          result.fields.set(fieldNumber, decodeMessageFixed(subData, subDef));
        }
        result.seen.add(fieldNumber);
      } else {
        const val = decodeScalar(data, pos, wireType, fieldDef.type);
        pos = val.nextPos;
        result.fields.set(fieldNumber, val.value);
        result.seen.add(fieldNumber);
      }
    }
  }

  return result;
}

// ============ JSON SERIALIZATION ============

function toCamelCase(name: string): string {
  let result = '';
  let upper = false;
  for (const ch of name) {
    if (ch === '_') {
      upper = true;
    } else {
      if (upper && ch >= 'a' && ch <= 'z') {
        result += ch.toUpperCase();
      } else {
        result += ch;
      }
      upper = false;
    }
  }
  return result;
}

function escapeJsonStr(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code === 0x22) result += '\\"';
    else if (code === 0x5C) result += '\\\\';
    else if (code === 0x08) result += '\\b';
    else if (code === 0x09) result += '\\t';
    else if (code === 0x0A) result += '\\n';
    else if (code === 0x0C) result += '\\f';
    else if (code === 0x0D) result += '\\r';
    else if (code < 0x20) result += '\\u00' + code.toString(16).padStart(2, '0');
    else result += s[i];
  }
  return result;
}

function isDefaultValue(val: any, typeName: string): boolean {
  if (typeName === 'string') return val === '';
  if (typeName === 'bytes') return val.length === 0;
  if (typeName === 'bool') return val === false;
  if (typeName === 'int64' || typeName === 'uint64' || typeName === 'sint64' ||
      typeName === 'fixed64' || typeName === 'sfixed64') return val === 0n;
  // int32, uint32, sint32, fixed32, sfixed32, enum
  return val === 0;
}

function shouldPrintField(msg: DecodedMsg, fdef: FieldDef): boolean {
  if (fdef.label === 'repeated') {
    const arr = msg.fields.get(fdef.number);
    return arr !== undefined && (arr as any[]).length > 0;
  }
  if (fdef.label === 'map') {
    const m = msg.fields.get(fdef.number);
    return m !== undefined && (m as Map<any, any>).size > 0;
  }
  // singular
  if (!msg.seen.has(fdef.number)) return false;
  if (messages.has(fdef.type)) return true;
  if (fdef.isOptional) return true;
  if (fdef.oneofName) return true;
  return !isDefaultValue(msg.fields.get(fdef.number), fdef.type);
}

function valueToJson(val: any, typeName: string): string {
  if (typeName === 'string') return `"${escapeJsonStr(val)}"`;
  if (typeName === 'bytes') return `"${(val as Buffer).toString('base64')}"`;
  if (typeName === 'bool') return val ? 'true' : 'false';
  if (typeName === 'int64' || typeName === 'uint64' || typeName === 'sint64' ||
      typeName === 'fixed64' || typeName === 'sfixed64') return `"${(val as bigint).toString()}"`;
  if (typeName === 'int32' || typeName === 'uint32' || typeName === 'sint32' ||
      typeName === 'fixed32' || typeName === 'sfixed32') return String(val);
  // enum
  if (enums.has(typeName)) {
    const enumDef = enums.get(typeName)!;
    const name = enumDef.values.get(val as number);
    if (name !== undefined) return `"${name}"`;
    return String(val);
  }
  // message
  if (messages.has(typeName)) {
    return messageToJson(val as DecodedMsg, messages.get(typeName)!);
  }
  return String(val);
}

function mapValueToJson(val: any, typeName: string): string {
  // Map values are always printed, even if default
  if (messages.has(typeName)) {
    return messageToJson(val as DecodedMsg, messages.get(typeName)!);
  }
  return valueToJson(val, typeName);
}

