        }
      } else {
        target.fields.set(fn, val);
      }
      target.seen.add(fn);
    }
  }
  // merge oneof state from source
  for (const [name, fn] of source.oneofSet) {
    const prev = target.oneofSet.get(name);
    if (prev !== undefined && prev !== fn) {
      target.fields.delete(prev);
      target.seen.delete(prev);
    }
    target.oneofSet.set(name, fn);
  }
}

function decodeMapEntry(data: Buffer, keyType: string, valType: string): { key: any; value: any } {
  let key: any = keyType === 'string' ? '' : 0;
  let value: any;

  // Initialize value based on type
  if (messages.has(valType)) {
    value = makeEmptyMsg();
  } else {
    value = getDefaultScalar(valType);
  }

  let pos = 0;
  while (pos < data.length) {
    const [keyVarint, np] = readVarint(data, pos);
    pos = np;
    const fn = Number(keyVarint >> 3n);
    const wt = Number(keyVarint & 7n);

    if (fn === 1) {
      const val = decodeScalar(data, pos, wt, keyType);
      key = val.value;
      pos = val.nextPos;
    } else if (fn === 2) {
      if (messages.has(valType)) {
        const [len, np2] = readVarint(data, pos);
        pos = np2;
        const subData = data.subarray(pos, pos + Number(len));
        pos += Number(len);
        value = decodeMessage(subData, messages.get(valType)!);
      } else {
        const val = decodeScalar(data, pos, wt, valType);
        value = val.value;
        pos = val.nextPos;
      }
    } else {
      pos = skipField(data, pos, wt, fn);
    }
  }
  return { key, value };
}

function getDefaultScalar(typeName: string): any {
  switch (typeName) {
    case 'string': return '';
    case 'bytes': return Buffer.alloc(0);
    case 'bool': return false;
    case 'int64': case 'uint64': case 'sint64': case 'fixed64': case 'sfixed64': return 0n;
    default: return 0;
  }
}

// ============ JSON SERIALIZATION ============

function toCamelCase(name: string): string {
  let result = '';
  let upper = false;
  for (const ch of name) {
    if (ch === '_') {
      upper = true;
    } else {
      if (upper && ch >= 'a' && ch <= 'z') {
        result += ch.toUpperCase();
      } else {
        result += ch;
      }
      upper = false;
    }
  }
  return result;
}

function escapeJsonStr(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code === 0x22) result += '\\"';
    else if (code === 0x5C) result += '\\\\';
    else if (code === 0x08) result += '\\b';
    else if (code === 0x09) result += '\\t';
    else if (code === 0x0A) result += '\\n';
    else if (code === 0x0C) result += '\\f';
    else if (code === 0x0D) result += '\\r';
    else if (code < 0x20) result += '\\u00' + code.toString(16).padStart(2, '0');
    else result += s[i];
  }
  return result;
}

function isDefaultValue(val: any, typeName: string): boolean {
  if (typeName === 'string') return val === '';
  if (typeName === 'bytes') return val.length === 0;
  if (typeName === 'bool') return val === false;
  if (typeName === 'int64' || typeName === 'uint64' || typeName === 'sint64' ||
      typeName === 'fixed64' || typeName === 'sfixed64') return val === 0n;
  return val === 0;
}

function shouldPrintField(msg: DecodedMsg, fdef: FieldDef): boolean {
  if (fdef.label === 'repeated') {
    const arr = msg.fields.get(fdef.number);
    return arr !== undefined && (arr as any[]).length > 0;
  }
  if (fdef.label === 'map') {
    const m = msg.fields.get(fdef.number);
    return m !== undefined && (m as Map<any, any>).size > 0;
  }
  // singular
  if (!msg.seen.has(fdef.number)) return false;
  if (messages.has(fdef.type)) return true;
  if (fdef.isOptional) return true;
  if (fdef.oneofName) return true;
  return !isDefaultValue(msg.fields.get(fdef.number), fdef.type);
}

function valueToJson(val: any, typeName: string): string {
  if (typeName === 'string') return `"${escapeJsonStr(val)}"`;
  if (typeName === 'bytes') return `"${(val as Buffer).toString('base64')}"`;
  if (typeName === 'bool') return val ? 'true' : 'false';
  if (typeName === 'int64' || typeName === 'uint64' || typeName === 'sint64' ||
      typeName === 'fixed64' || typeName === 'sfixed64') return `"${(val as bigint).toString()}"`;
  if (typeName === 'int32' || typeName === 'uint32' || typeName === 'sint32' ||
      typeName === 'fixed32' || typeName === 'sfixed32') return String(val);
  // enum
  if (enums.has(typeName)) {
    const enumDef = enums.get(typeName)!;
    const name = enumDef.values.get(val as number);
    if (name !== undefined) return `"${name}"`;
    return String(val);
  }
  // message
  if (messages.has(typeName)) {
    return messageToJson(val as DecodedMsg, messages.get(typeName)!);
  }
  return String(val);
}

function mapValueToJson(val: any, typeName: string): string {
  if (messages.has(typeName)) {
    if (val === undefined || val === null) {
      return '{}';
    }
    return messageToJson(val as DecodedMsg, messages.get(typeName)!);
  }
  return valueToJson(val, typeName);
}

function mapToJson(map: Map<any, any>, keyType: string, valType: string): string {
  const rawEntries: { key: any; jsonKey: string; jsonVal: string }[] = [];
  for (const [k, v] of map) {
    let jsonKey: string;
    if (keyType === 'string') {
      jsonKey = `"${escapeJsonStr(k)}"`;
    } else {
      jsonKey = `"${k}"`;
    }
    rawEntries.push({ key: k, jsonKey, jsonVal: mapValueToJson(v, valType) });
  }

  if (keyType === 'string') {
    rawEntries.sort((a, b) => {
      const ba = Buffer.from(a.key, 'utf8');
      const bb = Buffer.from(b.key, 'utf8');
      const minLen = Math.min(ba.length, bb.length);
      for (let i = 0; i < minLen; i++) {
        if (ba[i] < bb[i]) return -1;
        if (ba[i] > bb[i]) return 1;
      }
      if (ba.length < bb.length) return -1;
      if (ba.length > bb.length) return 1;
      return 0;
    });
  } else {
    rawEntries.sort((a, b) => (a.key as number) - (b.key as number));
  }

  const parts = rawEntries.map(e => `${e.jsonKey}:${e.jsonVal}`);
  return `{${parts.join(',')}}`;
}

function messageToJson(msg: DecodedMsg, msgDef: MessageDef): string {
  const fieldNumbers = [...msgDef.fields.keys()].sort((a, b) => a - b);
  const parts: string[] = [];

  for (const fn of fieldNumbers) {
    const fdef = msgDef.fields.get(fn)!;
    if (!shouldPrintField(msg, fdef)) continue;

    const jsonName = toCamelCase(fdef.name);
    let jsonVal: string;

    if (fdef.label === 'repeated') {
      const arr = msg.fields.get(fn) as any[];
      const items = arr.map(item => valueToJson(item, fdef.type));
      jsonVal = `[${items.join(',')}]`;
    } else if (fdef.label === 'map') {
      jsonVal = mapToJson(msg.fields.get(fn) as Map<any, any>, fdef.keyType!, fdef.type);
    } else {
      jsonVal = valueToJson(msg.fields.get(fn), fdef.type);
    }

    parts.push(`"${jsonName}":${jsonVal}`);
  }

  return `{${parts.join(',')}}`;
}

// ============ MAIN ============

function main(): void {
  const dir = process.argv[2];
  if (!dir) { console.error("Usage: main.ts <directory>"); process.exit(1); }

  const schemaPath = path.join(dir, 'schema.proto');
  const messagesPath = path.join(dir, 'messages.bin');

  const schemaContent = fs.readFileSync(schemaPath, 'utf8');
  const stripped = stripComments(schemaContent);
  const tokens = tokenize(stripped);
  const parser = new ProtoParser(tokens);
  parser.parse();

  const binData = fs.readFileSync(messagesPath);

  const rootDef = messages.get(rootMessageName)!;
  let pos = 0;
  const outputLines: string[] = [];

  while (pos < binData.length) {
    const [recLen, newPos] = readVarint(binData, pos);
    pos = newPos;
    const recData = binData.subarray(pos, pos + Number(recLen));
    pos += Number(recLen);

    const decoded = decodeMessage(recData, rootDef);
    outputLines.push(messageToJson(decoded, rootDef));
  }

  process.stdout.write(outputLines.join('\n') + (outputLines.length > 0 ? '\n' : ''));
}

