struct BinReader {
    var bytes: [UInt8]
    var pos: Int = 0

    func readVarint() -> UInt64 {
        var r: UInt64 = 0; var s: UInt64 = 0
        while pos < bytes.count {
            let b = bytes[pos]; pos += 1
            r |= UInt64(b & 0x7F) << s
            if b & 0x80 == 0 { break }
            s += 7
        }
        return r
    }

    func readFixed32() -> UInt32 {
        let v = UInt32(bytes[pos]) | UInt32(bytes[pos+1]) << 8 | UInt32(bytes[pos+2]) << 16 | UInt32(bytes[pos+3]) << 24
        pos += 4; return v
    }

    func readFixed64() -> UInt64 {
        var v: UInt64 = 0
        for i in 0..<8 { v |= UInt64(bytes[pos+i]) << (8 * UInt64(i)) }
        pos += 8; return v
    }

    func readLenDelim() -> [UInt8] {
        let len = Int(readVarint())
        let d = Array(bytes[pos..<pos+len]); pos += len; return d
    }

    mutating func skipVal(_ wt: Int, _ fnum: Int) {
        switch wt {
        case 0: _ = readVarint()
        case 1: pos += 8
        case 2: let l = Int(readVarint()); pos += l
        case 5: pos += 4
        case 3: skipGroup(fnum)
        case 4: break
        default: break
        }
    }

    mutating func skipGroup(_ gf: Int) {
        while pos < bytes.count {
            let key = readVarint()
            let f = Int(key >> 3); let wt = Int(key & 7)
            if wt == 4 && f == gf { break }
            skipVal(wt, f)
        }
    }
}

