// ==================== SCHEMA PARSER ====================

class ProtoParser {
    var toks: [Tok]
    var p: Int = 0
    init(_ t: [Tok]) { toks = t }

    func peek() -> Tok? { p < toks.count ? toks[p] : nil }
    func adv() -> Tok { let t = toks[p]; p += 1; return t }
    func at(_ t: Tok) -> Bool { peek() == t }
    func expect(_ t: Tok) { assert(peek() == t, "expected \(t) got \(String(describing: peek()))"); p += 1 }
    func match(_ t: Tok) -> Bool { if peek() == t { p += 1; return true }; return false }

    func getId() -> String { if case .id(let s) = adv() { return s }; fatalError("id") }
    func getNum() -> Int64 { if case .num(let n) = adv() { return n }; fatalError("num") }
    func maybeNeg() -> Int64 { if match(.sym("-")) { return -getNum() }; return getNum() }

    func skipConst() {
        if match(.sym("-")) { _ = adv(); return }
        _ = adv()
    }

    func skipOptBrackets() {
        if !match(.sym("[")) { return }
        while !at(.sym("]")) && p < toks.count {
            _ = adv(); expect(.sym("=")); skipConst()
            if !match(.sym(",")) { break }
        }
        expect(.sym("]"))
    }

    func skipToSemi() {
        while p < toks.count && !at(.sym(";")) { p += 1 }
        if at(.sym(";")) { p += 1 }
    }

    func parseFile() -> Schema {
        var msgs: [String: MsgDef] = [:]
        var enums: [String: EnumDef] = [:]
        var root = ""
        while p < toks.count {
            if case .id(let s) = toks[p] {
                switch s {
                case "syntax": p += 1; expect(.sym("=")); _ = adv(); expect(.sym(";"))
                case "package": p += 1; skipToSemi()
                case "option": p += 1; _ = adv(); expect(.sym("=")); skipConst(); expect(.sym(";"))
                case "message":
                    let m = parseMsg(&msgs, &enums)
                    if root.isEmpty { root = m.name }
                    msgs[m.name] = m
                case "enum":
                    let e = parseEnum(&enums); enums[e.name] = e
                default: p += 1
                }
            } else { p += 1 }
        }
        return Schema(msgs: msgs, enums: enums, root: root)
    }

    func parseMsg(_ msgs: inout [String: MsgDef], _ enums: inout [String: EnumDef]) -> MsgDef {
        expect(.id("message")); let name = getId(); expect(.sym("{"))
        var fields: [Int: FieldDef] = [:]
        var oneofs: [String: [Int]] = [:]
        while !at(.sym("}")) && p < toks.count {
            if case .id(let s) = toks[p] {
                switch s {
                case "message": let n = parseMsg(&msgs, &enums); msgs[n.name] = n
                case "enum": let e = parseEnum(&enums); enums[e.name] = e
                case "option": p += 1; _ = adv(); expect(.sym("=")); skipConst(); expect(.sym(";"))
                case "reserved": p += 1; skipToSemi()
                case "oneof":
                    p += 1; let oname = getId(); expect(.sym("{"))
                    var nums: [Int] = []
                    while !at(.sym("}")) && p < toks.count {
                        let f = parseField(oneof: oname); fields[f.number] = f; nums.append(f.number)
                    }
                    expect(.sym("}")); oneofs[oname] = nums
                default:
                    let f = parseField(oneof: nil); fields[f.number] = f
                }
            } else { p += 1 }
        }
        expect(.sym("}"))
        return MsgDef(name: name, fields: fields, oneofs: oneofs)
    }

    func parseField(oneof: String?) -> FieldDef {
        var rep = false, opt = false
        if case .id(let s) = toks[p] {
