        skipOptBrackets(); expect(.sym(";"))
        return FieldDef(number: num, name: nm, type: t, isRepeated: rep, isOptional: opt, oneofName: oneof)
    }

    func parseType() -> PType {
        guard case .id(let s) = toks[p] else { fatalError("type") }
        p += 1
        switch s {
        case "int32": return .int32; case "int64": return .int64
        case "uint32": return .uint32; case "uint64": return .uint64
        case "sint32": return .sint32; case "sint64": return .sint64
        case "bool": return .bool; case "string": return .string; case "bytes": return .bytes
        case "fixed32": return .fixed32; case "fixed64": return .fixed64
        case "sfixed32": return .sfixed32; case "sfixed64": return .sfixed64
