func decodeScalar(_ r: inout BinReader, _ t: PType, _ wt: Int) -> DVal {
    switch t {
    case .int32:
        let v = r.readVarint(); return .i(Int64(Int32(truncatingIfNeeded: v)))
    case .int64:
        let v = r.readVarint(); return .i(Int64(bitPattern: v))
    case .uint32:
        let v = r.readVarint(); return .u(v & 0xFFFFFFFF)
    case .uint64:
        let v = r.readVarint(); return .u(v)
    case .sint32:
        let v = r.readVarint(); let z = Int64(bitPattern: (v >> 1) ^ (~(v & 1) &+ 1)); return .i(z)
    case .sint64:
        let v = r.readVarint(); let z = Int64(bitPattern: (v >> 1) ^ (~(v & 1) &+ 1)); return .i(z)
    case .bool:
        let v = r.readVarint(); return .b(v != 0)
    case .enumRef:
        let v = r.readVarint(); return .ev(Int32(truncatingIfNeeded: v))
    case .fixed32:
        return .u(UInt64(r.readFixed32()))
    case .sfixed32:
        return .i(Int64(Int32(bitPattern: r.readFixed32())))
    case .fixed64:
        return .u(r.readFixed64())
    case .sfixed64:
        return .i(Int64(bitPattern: r.readFixed64()))
    case .string:
        let b = r.readLenDelim(); return .s(String(decoding: b, as: UTF8.self))
    case .bytes:
        return .by(r.readLenDelim())
    default:
        fatalError("decodeScalar called with non-scalar")
    }
}

func decodeMsg(bytes: [UInt8], schema: Schema, msgName: String) -> DMsg {
    var msg = DMsg()
    let mdef = schema.msgs[msgName]!
    var r = BinReader(bytes: bytes)

    while r.pos < bytes.count {
        let key = r.readVarint()
        let fnum = Int(key >> 3)
        let wt = Int(key & 7)

        guard let fdef = mdef.fields[fnum] else {
            r.skipVal(wt, fnum)
            continue
        }

        // oneof: clear previous member if different
        if let oname = fdef.oneofName {
            if msg.oneofCur[oname] != fnum {
                if let prev = msg.oneofCur[oname] {
                    msg.fields.removeValue(forKey: prev)
                }
                msg.oneofCur[oname] = fnum
            }
        }

        if fdef.isRepeated {
            if wt == 2 && isPackable(fdef.type) {
                let payload = r.readLenDelim()
                var pr = BinReader(bytes: payload)
                var arr: [DVal] = []
                if case .rep(let a) = msg.fields[fnum] { arr = a }
                let ewt = wireTypeFor(fdef.type)
                while pr.pos < payload.count {
                    arr.append(decodeScalar(&pr, fdef.type, ewt))
                }
                msg.fields[fnum] = DVal.rep(arr)
            } else if case .msg(let subName) = fdef.type {
                let subBytes = r.readLenDelim()
                var arr: [DVal] = []
                if case .rep(let a) = msg.fields[fnum] { arr = a }
                arr.append(DVal.m(decodeMsg(bytes: subBytes, schema: schema, msgName: subName)))
                msg.fields[fnum] = DVal.rep(arr)
            } else {
                var arr: [DVal] = []
                if case .rep(let a) = msg.fields[fnum] { arr = a }
                arr.append(decodeScalar(&r, fdef.type, wt))
                msg.fields[fnum] = DVal.rep(arr)
            }
        } else if case .map(let kt, let vt) = fdef.type {
            let entryBytes = r.readLenDelim()
            var er = BinReader(bytes: entryBytes)
            var kv: DVal = .s("")
            var vv: DVal = defaultVal(vt, schema)
            while er.pos < entryBytes.count {
                let ek = er.readVarint()
                let ef = Int(ek >> 3); let ewt = Int(ek & 7)
                if ef == 1 { kv = decodeScalar(&er, kt, ewt) }
                else if ef == 2 {
                    if case .msg(let sn) = vt {
                        let sub = er.readLenDelim()
                        vv = DVal.m(decodeMsg(bytes: sub, schema: schema, msgName: sn))
                    } else {
                        vv = decodeScalar(&er, vt, ewt)
                    }
                } else { er.skipVal(ewt, ef) }
            }
            var entries: [(DVal, DVal)] = []
            if case .mapE(let a) = msg.fields[fnum] { entries = a }
            var replaced = false
            for i in 0..<entries.count {
                if dvalEq(entries[i].0, kv) { entries[i].1 = vv; replaced = true; break }
            }
            if !replaced { entries.append((kv, vv)) }
            msg.fields[fnum] = DVal.mapE(entries)
        } else if case .msg(let subName) = fdef.type {
            let subBytes = r.readLenDelim()
            let newSub = decodeMsg(bytes: subBytes, schema: schema, msgName: subName)
            if let existing = msg.fields[fnum], case DVal.msg(var em) = existing {
                let subdef = schema.msgs[subName]!
                mergeMsg(&em, newSub, subdef, schema)
                msg.fields[fnum] = DVal.msg(em)
            } else {
                msg.fields[fnum] = DVal.msg(newSub)
            }
        } else {
            msg.fields[fnum] = decodeScalar(&r, fdef.type, wt)
        }
    }
    return msg
}

func defaultVal(_ t: PType, _ schema: Schema) -> DVal {
    switch t {
    case .int32,.int64,.sint32,.sint64,.sfixed32,.sfixed64: return .i(0)
    case .uint32,.uint64,.fixed32,.fixed64: return .u(0)
    case .bool: return .b(false)
    case .string: return .s("")
    case .bytes: return .by([])
    case .enumRef: return .ev(0)
    case .msg(_): return .m(DMsg())
    default: fatalError()
    }
}

func mergeMsg(_ dst: inout DMsg, _ src: DMsg, _ mdef: MsgDef, _ schema: Schema) {
    for (fnum, sv) in src.fields {
        guard let fdef = mdef.fields[fnum] else { continue }
        if let oname = fdef.oneofName {
            if dst.oneofCur[oname] != fnum {
                if let prev = dst.oneofCur[oname] { dst.fields.removeValue(forKey: prev) }
                dst.oneofCur[oname] = fnum
            }
        }
        if fdef.isRepeated {
            var arr: [DVal] = []
            if case .rep(let a) = dst.fields[fnum] { arr = a }
            if case .rep(let a) = sv { arr.append(contentsOf: a) }
            dst.fields[fnum] = DVal.rep(arr)
        } else if case .map = fdef.type {
            var entries: [(DVal, DVal)] = []
            if case .mapE(let a) = dst.fields[fnum] { entries = a }
            if case .mapE(let a) = sv {
                for (k, v) in a {
                    var rep = false
                    for i in 0..<entries.count {
                        if dvalEq(entries[i].0, k) { entries[i].1 = v; rep = true; break }
                    }
                    if !rep { entries.append((k, v)) }
                }
            }
            dst.fields[fnum] = DVal.mapE(entries)
        } else if case .msg(let sn) = fdef.type {
            if let ex = dst.fields[fnum], case DVal.msg(var em) = ex {
                if case DVal.msg(let sm) = sv {
                    let sd = schema.msgs[sn]!
                    mergeMsg(&em, sm, sd, schema)
                    dst.fields[fnum] = DVal.msg(em)
                }
            } else {
                dst.fields[fnum] = sv
            }
        } else {
            dst.fields[fnum] = sv
        }
    }
}

// ==================== JSON OUTPUT ====================

func toCamel(_ name: String) -> String {
    var res = ""
    var up = false
    for c in name {
        if c == "_" { up = true }
        else {
            if up && c >= "a" && c <= "z" { res.append(Character(c.uppercased())) }
            else { res.append(c) }
            up = false
        }
    }
    return res
}

func jsonStr(_ s: String) -> String {
    var r = "\""
    for c in s.unicodeScalars {
        switch c {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{08}": r += "\\b"
        case "\t": r += "\\t"
        case "\n": r += "\\n"
        case "\u{0C}": r += "\\f"
        case "\r": r += "\\r"
        default:
            if c.value < 0x20 { r += String(format: "\\u%04x", c.value) }
            else { r.append(Character(c)) }
        }
    }
    r += "\""
    return r
}

func base64Enc(_ data: [UInt8]) -> String {
    return Data(data).base64EncodedString()
}

func isDefaultVal(_ v: DVal, _ t: PType) -> Bool {
    switch (v, t) {
    case (.i(let x), _): return x == 0
    case (.u(let x), _): return x == 0
    case (.b(let x), _): return !x
    case (.s(let x), _): return x.isEmpty
    case (.by(let x), _): return x.isEmpty
    case (.ev(let x), _): return x == 0
    default: return false
    }
}

func isMsgType(_ t: PType) -> Bool {
    if case .msg = t { return true }
    return false
}

func valToJSON(_ v: DVal, _ t: PType, _ schema: Schema) -> String {
    switch v {
    case .i(let x):
        switch t {
        case .int64,.uint64,.sint64,.fixed64,.sfixed64: return "\"\(x)\""
        default: return "\(x)"
        }
    case .u(let x):
        switch t {
        case .int64,.uint64,.sint64,.fixed64,.sfixed64: return "\"\(x)\""
        default: return "\(x)"
        }
    case .b(let x): return x ? "true" : "false"
    case .s(let x): return jsonStr(x)
    case .by(let x): return jsonStr(base64Enc(x))
    case .ev(let x):
        if case .enumRef(let en) = t {
            if let name = schema.enums[en]?.values[Int(x)] { return jsonStr(name) }
        }
        return "\(x)"
    case .m(let dm):
        if case .msg(let mn) = t { return msgToJSON(dm, schema.msgs[mn]!, schema) }
        return "{}"
    case .rep(let arr):
        var parts: [String] = []
        let elemType = t // for repeated fields, t IS the element type
        for e in arr { parts.append(valToJSON(e, elemType, schema)) }
        return "[" + parts.joined(separator: ",") + "]"
    case .mapE(let entries):
        var parts: [(String, String)] = []
        var keyType: PType = .string
        var valType: PType = .string
        if case .map(let k, let v) = t { keyType = k; valType = v }
        for (k, val) in entries {
            let ks: String
            switch k {
            case .s(let x): ks = x
            case .i(let x): ks = "\(x)"
            case .u(let x): ks = "\(x)"
            default: ks = ""
            }
            parts.append((ks, valToJSON(val, valType, schema)))
        }
        if case .int32 = keyType {
            parts.sort { Int($0.0) ?? 0 < Int($1.0) ?? 0 }
        } else {
            parts.sort { Array($0.0.utf8).lexicographicallyPrecedes(Array($1.0.utf8)) }
        }
        let members = parts.map { jsonStr($0.0) + ":" + $0.1 }
        return "{" + members.joined(separator: ",") + "}"
    }
}

func msgToJSON(_ msg: DMsg, _ mdef: MsgDef, _ schema: Schema) -> String {
    var parts: [String] = []
    let sortedNums = mdef.fields.keys.sorted()
    for num in sortedNums {
        guard let fdef = mdef.fields[num] else { continue }
        guard let val = msg.fields[num] else { continue }

        // For oneof: only print current member
        if let oname = fdef.oneofName {
            if msg.oneofCur[oname] != num { continue }
        }

        // Presence check
        if fdef.isRepeated {
            if case .rep(let arr) = val, arr.isEmpty { continue }
        } else if case .map = fdef.type {
            if case .mapE(let arr) = val, arr.isEmpty { continue }
        } else if isMsgType(fdef.type) {
            // always print if present
        } else {
            // singular scalar
            if !fdef.isOptional && fdef.oneofName == nil {
                if isDefaultVal(val, fdef.type) { continue }
            }
        }

        let jname = jsonStr(toCamel(fdef.name))
        let jval = valToJSON(val, fdef.type, schema)
        parts.append("\(jname):\(jval)")
    }
    return "{" + parts.joined(separator: ",") + "}"
}

