// ===== utilities =====

fn rvi(d: &[u8], p: &mut usize) -> u64 {
    let mut r: u64 = 0; let mut s = 0;
    loop { let b = d[*p]; *p += 1; r |= ((b & 0x7f) as u64) << s; if b & 0x80 == 0 { break; } s += 7; }
    r
}

fn b64(d: &[u8]) -> String {
    const C: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    for ch in d.chunks(3) {
        let b0 = ch[0] as u32;
        let b1 = if ch.len() > 1 { ch[1] as u32 } else { 0 };
        let b2 = if ch.len() > 2 { ch[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        r.push(C[((n >> 18) & 0x3f) as usize] as char);
        r.push(C[((n >> 12) & 0x3f) as usize] as char);
        if ch.len() > 1 { r.push(C[((n >> 6) & 0x3f) as usize] as char); } else { r.push('='); }
        if ch.len() > 2 { r.push(C[(n & 0x3f) as usize] as char); } else { r.push('='); }
    }
    r
}

fn jesc(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{08}' => r.push_str("\\b"),
            '\u{09}' => r.push_str("\\t"),
            '\u{0A}' => r.push_str("\\n"),
            '\u{0C}' => r.push_str("\\f"),
            '\u{0D}' => r.push_str("\\r"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            c => r.push(c),
        }
    }
    r
}

fn camel(s: &str) -> String {
    let mut r = String::new(); let mut up = false;
    for c in s.chars() {
        if c == '_' { up = true; }
        else { if up && c.is_ascii_lowercase() { r.push(c.to_ascii_uppercase()); } else { r.push(c); } up = false; }
    }
    r
}

