struct PP<'a> {
    d: &'a [u8], p: usize,
    msgs: HashMap<String, MDef>, enums: HashMap<String, EDef>,
    root: Option<String>,
}

impl<'a> PP<'a> {
    fn skip_ws(&mut self) {
        loop {
            while self.p < self.d.len() && matches!(self.d[self.p], b' '|b'\t'|b'\r'|b'\n') { self.p += 1; }
            if self.p + 1 < self.d.len() && self.d[self.p] == b'/' && self.d[self.p+1] == b'/' {
                while self.p < self.d.len() && self.d[self.p] != b'\n' { self.p += 1; }
            } else if self.p + 1 < self.d.len() && self.d[self.p] == b'/' && self.d[self.p+1] == b'*' {
                self.p += 2;
                while self.p + 1 < self.d.len() && !(self.d[self.p] == b'*' && self.d[self.p+1] == b'/') { self.p += 1; }
                if self.p + 1 < self.d.len() { self.p += 2; }
            } else { break; }
        }
    }

    fn pk(&mut self) -> Option<u8> { self.skip_ws(); if self.p < self.d.len() { Some(self.d[self.p]) } else { None } }
    fn eat(&mut self, b: u8) -> bool { self.skip_ws(); if self.p < self.d.len() && self.d[self.p] == b { self.p += 1; true } else { false } }
    fn exp(&mut self, b: u8) { assert!(self.eat(b)); }

    fn rword(&mut self) -> String {
        self.skip_ws(); let s = self.p;
        while self.p < self.d.len() && (self.d[self.p].is_ascii_alphanumeric() || self.d[self.p] == b'_') { self.p += 1; }
        String::from_utf8_lossy(&self.d[s..self.p]).to_string()
    }

    fn pkword(&mut self) -> String { let s = self.p; let w = self.rword(); self.p = s; w }

    fn rslit(&mut self) -> String {
        self.exp(b'"'); let s = self.p;
        while self.p < self.d.len() && self.d[self.p] != b'"' { self.p += 1; }
        let r = String::from_utf8_lossy(&self.d[s..self.p]).to_string();
        self.exp(b'"'); r
    }

    fn rint(&mut self) -> i64 {
        self.skip_ws(); let neg = if self.p < self.d.len() && self.d[self.p] == b'-' { self.p += 1; true } else { false };
        let s = self.p;
        while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        let n: i64 = String::from_utf8_lossy(&self.d[s..self.p]).parse().unwrap_or(0);
        if neg { -n } else { n }
    }

    fn skip_semi(&mut self) {
        loop { self.skip_ws(); if self.p >= self.d.len() { break; }
            if self.d[self.p] == b';' { self.p += 1; break; }
            if self.d[self.p] == b'"' { self.p += 1; while self.p < self.d.len() && self.d[self.p] != b'"' { self.p += 1; } self.p += 1; }
            else { self.p += 1; }
        }
    }

    fn skip_brk(&mut self) {
        loop { self.skip_ws(); if self.p >= self.d.len() { break; }
            if self.d[self.p] == b']' { self.p += 1; break; }
            if self.d[self.p] == b'"' { self.p += 1; while self.p < self.d.len() && self.d[self.p] != b'"' { self.p += 1; } self.p += 1; }
            else { self.p += 1; }
        }
    }

    fn rtype(&self, n: &str) -> FT {
        match n {
            "int32" => FT::I32, "int64" => FT::I64, "uint32" => FT::U32, "uint64" => FT::U64,
            "sint32" => FT::S32, "sint64" => FT::S64, "bool" => FT::Bool,
            "string" => FT::Str, "bytes" => FT::Bytes,
            "fixed32" => FT::F32, "fixed64" => FT::F64, "sfixed32" => FT::SF32, "sfixed64" => FT::SF64,
            _ => FT::Named(n.to_string()),
        }
    }

    fn parse_all(&mut self) {
        loop {
            self.skip_ws(); if self.p >= self.d.len() { break; }
            let w = self.pkword();
            match w.as_str() {
                "syntax"|"package" => { self.rword(); self.skip_semi(); }
                "option" => { self.rword(); self.skip_semi(); }
                "message" => { self.rword(); self.parse_msg(); }
                "enum" => { self.rword(); self.parse_enum(); }
                _ => break,
            }
        }
    }

    fn parse_msg(&mut self) {
        let name = self.rword(); self.exp(b'{');
        let mut fields: Vec<FDef> = Vec::new();
        let mut oneofs: HashMap<String, Vec<u32>> = HashMap::new();
        loop {
            self.skip_ws(); if self.p >= self.d.len() { break; }
            if self.d[self.p] == b'}' { break; }
            let w = self.pkword();
            match w.as_str() {
                "message" => { self.rword(); self.parse_msg(); }
                "enum" => { self.rword(); self.parse_enum(); }
                "oneof" => { self.rword(); self.parse_oneof(&mut fields, &mut oneofs); }
                "reserved" => { self.rword(); self.skip_semi(); }
                "option" => { self.rword(); self.skip_semi(); }
                "map" => { self.parse_map(&mut fields); }
                _ => { let fd = self.parse_fld(None); fields.push(fd); }
            }
        }
        self.exp(b'}');
        self.msgs.insert(name.clone(), MDef { fields, oneofs });
        if self.root.is_none() { self.root = Some(name); }
    }

    fn parse_oneof(&mut self, fields: &mut Vec<FDef>, oneofs: &mut HashMap<String, Vec<u32>>) {
        let oname = self.rword(); self.exp(b'{');
        let mut nums: Vec<u32> = Vec::new();
        loop {
            self.skip_ws(); if self.p >= self.d.len() { break; }
            if self.d[self.p] == b'}' { break; }
            let w = self.pkword();
            match w.as_str() {
                "option" => { self.rword(); self.skip_semi(); }
                "reserved" => { self.rword(); self.skip_semi(); }
                _ => {
                    let tn = self.rword(); let nm = self.rword();
                    self.exp(b'='); let num = self.rint() as u32;
                    if self.pk() == Some(b'[') { self.exp(b'['); self.skip_brk(); }
                    self.exp(b';');
                    nums.push(num);
                    fields.push(FDef { name: nm, num, ft: self.rtype(&tn), lbl: Lbl::Sing, oneof: Some(oname.clone()), is_map: false, mk: None, mv: None });
                }
            }
        }
        self.exp(b'}');
        oneofs.insert(oname, nums);
    }

    fn parse_fld(&mut self, _ctx: Option<&str>) -> FDef {
        let w = self.pkword();
        let lbl = match w.as_str() {
            "repeated" => { self.rword(); Lbl::Rep }
            "optional" => { self.rword(); Lbl::Opt }
            _ => Lbl::Sing,
        };
        let tn = self.rword(); let nm = self.rword();
        self.exp(b'='); let num = self.rint() as u32;
        if self.pk() == Some(b'[') { self.exp(b'['); self.skip_brk(); }
        self.exp(b';');
        FDef { name: nm, num, ft: self.rtype(&tn), lbl, oneof: None, is_map: false, mk: None, mv: None }
    }

    fn parse_map(&mut self, fields: &mut Vec<FDef>) {
        self.rword(); // map
        self.exp(b'<');
        let kn = self.rword(); self.exp(b',');
        let vn = self.rword(); self.exp(b'>');
        let nm = self.rword(); self.exp(b'='); let num = self.rint() as u32;
        if self.pk() == Some(b'[') { self.exp(b'['); self.skip_brk(); }
        self.exp(b';');
        fields.push(FDef { name: nm, num, ft: FT::Named("_map".into()), lbl: Lbl::Rep, oneof: None, is_map: true, mk: Some(self.rtype(&kn)), mv: Some(self.rtype(&vn)) });
    }

    fn parse_enum(&mut self) {
        let name = self.rword(); self.exp(b'{');
        let mut values: HashMap<i64, String> = HashMap::new();
        loop {
            self.skip_ws(); if self.p >= self.d.len() { break; }
            if self.d[self.p] == b'}' { break; }
            let w = self.pkword();
            match w.as_str() {
                "option" => { self.rword(); self.skip_semi(); }
                "reserved" => { self.rword(); self.skip_semi(); }
                _ => {
                    let vn = self.rword(); self.exp(b'='); let vi = self.rint();
                    if self.pk() == Some(b'[') { self.exp(b'['); self.skip_brk(); }
                    self.exp(b';');
                    values.insert(vi, vn);
                }
            }
        }
        self.exp(b'}');
        self.enums.insert(name, EDef { values });
    }
}

// ===== protobuf decoder =====

fn skip_fld(d: &[u8], p: &mut usize, wt: u8, fnum: u32) {
    match wt {
        0 => { rvi(d, p); }
        1 => { *p += 8; }
        2 => { let l = rvi(d, p) as usize; *p += l; }
        3 => { loop { let k = rvi(d, p); let fn_ = (k >> 3) as u32; let w = (k & 7) as u8; if w == 4 && fn_ == fnum { break; } skip_fld(d, p, w, fn_); } }
        4 => {}
        5 => { *p += 4; }
        _ => {}
    }
}

fn rscalar(d: &[u8], p: &mut usize, _wt: u8, ft: &FT, sc: &Schema) -> JV {
    match ft {
        FT::I32 => { let v = rvi(d, p); JV::Num(v as u32 as i32 as i64) }
        FT::I64 => { let v = rvi(d, p); JV::Str(format!("{}", v as i64)) }
        FT::U32 => { let v = rvi(d, p); JV::Num(v as u32 as i64) }
        FT::U64 => { let v = rvi(d, p); JV::Str(format!("{}", v)) }
        FT::S32 => { let v = rvi(d, p); let z = ((v as u32) >> 1) ^ ((v as u32) & 1).wrapping_neg(); JV::Num(z as i32 as i64) }
        FT::S64 => { let v = rvi(d, p); let z = (v >> 1) ^ (v & 1).wrapping_neg(); JV::Str(format!("{}", z as i64)) }
        FT::Bool => { let v = rvi(d, p); JV::Bool(v != 0) }
        FT::Str => { let l = rvi(d, p) as usize; let s = String::from_utf8_lossy(&d[*p..*p+l]).to_string(); *p += l; JV::Str(s) }
        FT::Bytes => { let l = rvi(d, p) as usize; let r = b64(&d[*p..*p+l]); *p += l; JV::Str(r) }
        FT::F32 => { let v = u32::from_le_bytes([d[*p],d[*p+1],d[*p+2],d[*p+3]]); *p += 4; JV::Num(v as i64) }
        FT::F64 => { let v = u64::from_le_bytes(d[*p..*p+8].try_into().unwrap()); *p += 8; JV::Str(format!("{}", v)) }
        FT::SF32 => { let v = i32::from_le_bytes([d[*p],d[*p+1],d[*p+2],d[*p+3]]); *p += 4; JV::Num(v as i64) }
        FT::SF64 => { let v = i64::from_le_bytes(d[*p..*p+8].try_into().unwrap()); *p += 8; JV::Str(format!("{}", v)) }
        FT::Named(n) => {
            let v = rvi(d, p); let iv = v as u32 as i32 as i64;
            if let Some(ed) = sc.enums.get(n) {
                match ed.values.get(&iv) { Some(nm) => JV::Str(nm.clone()), None => JV::Num(iv) }
            } else { JV::Num(iv) }
        }
    }
}

fn rfield(d: &[u8], p: &mut usize, wt: u8, ft: &FT, sc: &Schema) -> DV {
    if let FT::Named(n) = ft {
        if sc.msgs.contains_key(n) {
            let l = rvi(d, p) as usize;
            let sub = decode_msg(&d[*p..*p+l], &sc.msgs[n], sc);
            *p += l;
            return DV::Msg(Box::new(sub));
        }
    }
    DV::Sc(rscalar(d, p, wt, ft, sc))
}

fn default_dv(ft: &FT, sc: &Schema) -> DV {
    match ft {
        FT::Bool => DV::Sc(JV::Bool(false)),
        FT::Str => DV::Sc(JV::Str(String::new())),
        FT::Bytes => DV::Sc(JV::Str(String::new())),
        FT::I32|FT::U32|FT::S32|FT::F32|FT::SF32 => DV::Sc(JV::Num(0)),
        FT::I64|FT::U64|FT::S64|FT::F64|FT::SF64 => DV::Sc(JV::Str("0".into())),
        FT::Named(n) => {
            if sc.msgs.contains_key(n) {
                DV::Msg(Box::new(DM{fields:HashMap::new(),oa:HashMap::new()}))
            } else {
                let ename = sc.enums.get(n).and_then(|e| e.values.get(&0)).cloned().unwrap_or_default();
                DV::Sc(JV::Str(ename))
            }
        }
    }
}

fn decode_msg(data: &[u8], md: &MDef, sc: &Schema) -> DM {
    let mut p = 0usize;
    let mut fields: HashMap<u32, DF> = HashMap::new();
    let mut oa: HashMap<String, u32> = HashMap::new();

    while p < data.len() {
        let key = rvi(data, &mut p);
        let fnum = (key >> 3) as u32;
        let wt = (key & 7) as u8;

        let fd = match md.fields.iter().find(|f| f.num == fnum) {
            Some(fd) => fd,
            None => { skip_fld(data, &mut p, wt, fnum); continue; }
        };

        // oneof clearing
        if let Some(ref oname) = fd.oneof {
            if let Some(&old) = oa.get(oname) {
                if old != fnum { fields.remove(&old); }
            }
            oa.insert(oname.clone(), fnum);
        }

        if fd.is_map {
            let l = rvi(data, &mut p) as usize;
            let ed = &data[p..p+l]; p += l;
            let (k, v) = decode_map_entry(ed, fd.mk.as_ref().unwrap(), fd.mv.as_ref().unwrap(), sc);
            let map = fields.entry(fnum).or_insert_with(|| DF::Map(Vec::new()));
            if let DF::Map(ref mut entries) = map {
                let mut found = false;
                for e in entries.iter_mut() { if jv_eq(&e.0, &k) { e.1 = v.clone(); found = true; break; } }
                if !found { entries.push((k, v)); }
            }
        } else if fd.lbl == Lbl::Rep {
            let packable = is_pack(&fd.ft);
            if wt == 2 && packable && !is_msg_ft(&fd.ft, sc) {
                let l = rvi(data, &mut p) as usize;
                let pd = &data[p..p+l]; p += l;
                let mut pp = 0usize;
                let vec = fields.entry(fnum).or_insert_with(|| DF::Rep(Vec::new()));
                if let DF::Rep(ref mut elems) = vec {
                    while pp < pd.len() {
                        elems.push(DV::Sc(rscalar(pd, &mut pp, 0, &fd.ft, sc)));
                    }
                }
            } else {
                let v = rfield(data, &mut p, wt, &fd.ft, sc);
                let vec = fields.entry(fnum).or_insert_with(|| DF::Rep(Vec::new()));
                if let DF::Rep(ref mut elems) = vec { elems.push(v); }
            }
        } else {
            // singular (Sing or Opt)
            if is_msg_ft(&fd.ft, sc) {
                let l = rvi(data, &mut p) as usize;
                let sd = &data[p..p+l]; p += l;
                let n = if let FT::Named(ref n) = fd.ft { n.clone() } else { unreachable!() };
                let sub = decode_msg(sd, &sc.msgs[&n], sc);
                let subdef = &sc.msgs[&n];
                let existing = fields.get_mut(&fnum);
                if let Some(DF::Sing(DV::Msg(ref mut existing_box))) = existing {
                    merge_msg(existing_box, sub, subdef, sc);
                } else {
                    drop(existing);
                    fields.insert(fnum, DF::Sing(DV::Msg(Box::new(sub))));
                }
            } else {
                let v = rfield(data, &mut p, wt, &fd.ft, sc);
                fields.insert(fnum, DF::Sing(v));
            }
        }
    }

    DM { fields, oa }
}

fn decode_map_entry(data: &[u8], kt: &FT, vt: &FT, sc: &Schema) -> (JV, DV) {
    let mut p = 0usize;
    let mut key: Option<JV> = None;
    let mut val: Option<DV> = None;
    while p < data.len() {
        let k = rvi(data, &mut p);
        let fn_ = (k >> 3) as u32;
        let wt = (k & 7) as u8;
        if fn_ == 1 { key = Some(rscalar(data, &mut p, wt, kt, sc)); }
        else if fn_ == 2 { val = Some(rfield(data, &mut p, wt, vt, sc)); }
        else { skip_fld(data, &mut p, wt, fn_); }
    }
    let dk = match kt { FT::Str => JV::Str(String::new()), _ => JV::Num(0) };
    (key.unwrap_or(dk), val.unwrap_or_else(|| default_dv(vt, sc)))
}

fn merge_msg(t: &mut DM, s: DM, md: &MDef, sc: &Schema) {
    for (oname, sfnum) in s.oa {
        if let Some(&old) = t.oa.get(&oname) { if old != sfnum { t.fields.remove(&old); } }
        t.oa.insert(oname, sfnum);
    }
    for (fnum, sf) in s.fields {
        let fd = match md.fields.iter().find(|f| f.num == fnum) {
            Some(fd) => fd,
            None => { t.fields.insert(fnum, sf); continue; }
        };
        match t.fields.get_mut(&fnum) {
            Some(tf) => merge_field(tf, sf, fd, sc),
            None => { t.fields.insert(fnum, sf); }
        }
    }
}

fn merge_field(t: &mut DF, s: DF, fd: &FDef, sc: &Schema) {
    match (t, s) {
        (DF::Sing(DV::Sc(ref mut tv)), DF::Sing(DV::Sc(sv))) => { *tv = sv; }
        (DF::Sing(DV::Msg(ref mut tm)), DF::Sing(DV::Msg(sm))) => {
            let subdef = &sc.msgs[if let FT::Named(ref n) = fd.ft { n } else { unreachable!() }];
            merge_msg(tm, *sm, subdef, sc);
        }
        (DF::Rep(ref mut tv), DF::Rep(sv)) => { tv.extend(sv); }
        (DF::Map(ref mut tv), DF::Map(sm)) => {
            for (k, v) in sm {
                let mut found = false;
                for e in tv.iter_mut() { if jv_eq(&e.0, &k) { e.1 = v.clone(); found = true; break; } }
                if !found { tv.push((k, v)); }
            }
        }
        _ => {}
    }
}

fn jv_eq(a: &JV, b: &JV) -> bool {
    match (a, b) {
        (JV::Num(x), JV::Num(y)) => x == y,
        (JV::Str(x), JV::Str(y)) => x == y,
        (JV::Bool(x), JV::Bool(y)) => x == y,
        _ => false,
    }
}

// ===== JSON output =====

fn is_default(jv: &JV, ft: &FT, sc: &Schema) -> bool {
    match (jv, ft) {
        (JV::Num(0), FT::I32) => true,
        (JV::Num(0), FT::U32) => true,
        (JV::Num(0), FT::S32) => true,
        (JV::Num(0), FT::F32) => true,
        (JV::Num(0), FT::SF32) => true,
        (JV::Str(s), FT::I64) => s == "0",
        (JV::Str(s), FT::U64) => s == "0",
        (JV::Str(s), FT::S64) => s == "0",
        (JV::Str(s), FT::F64) => s == "0",
        (JV::Str(s), FT::SF64) => s == "0",
        (JV::Bool(false), FT::Bool) => true,
        (JV::Str(s), FT::Str) => s.is_empty(),
        (JV::Str(s), FT::Bytes) => s.is_empty(),
        (JV::Str(s), FT::Named(n)) if sc.enums.contains_key(n) => {
            sc.enums[n].values.get(&0).map_or(false, |n0| n0 == s)
        }
        (JV::Num(0), FT::Named(n)) if sc.enums.contains_key(n) => true,
        _ => false,
    }
}

fn msg_to_json(dm: &DM, md: &MDef, sc: &Schema) -> String {
    let mut sorted: Vec<&FDef> = md.fields.iter().collect();
    sorted.sort_by_key(|f| f.num);
    let mut parts: Vec<String> = Vec::new();

    for fd in &sorted {
        let df = match dm.fields.get(&fd.num) { Some(d) => d, None => continue };
        match df {
            DF::Sing(dv) => {
                let in_oneof = fd.oneof.is_some();
                let is_opt = fd.lbl == Lbl::Opt;
                match dv {
                    DV::Sc(jv) => {
                        if !in_oneof && !is_opt && is_default(jv, &fd.ft, sc) { continue; }
                        parts.push(format!("\"{}\":{}", jesc(&camel(&fd.name)), jv_str(jv)));
                    }
                    DV::Msg(m) => {
                        let subdef = &sc.msgs[if let FT::Named(ref n) = fd.ft { n } else { unreachable!() }];
                        parts.push(format!("\"{}\":{}", jesc(&camel(&fd.name)), msg_to_json(m, subdef, sc)));
                    }
                }
            }
            DF::Rep(elems) => {
                if elems.is_empty() { continue; }
                let items: Vec<String> = elems.iter().map(|dv| {
                    match dv {
                        DV::Sc(jv) => jv_str(jv),
                        DV::Msg(m) => {
                            let subdef = &sc.msgs[if let FT::Named(ref n) = fd.ft { n } else { unreachable!() }];
                            msg_to_json(m, subdef, sc)
                        }
                    }
                }).collect();
                parts.push(format!("\"{}\":{}", jesc(&camel(&fd.name)), format!("[{}]", items.join(","))));
            }
            DF::Map(entries) => {
                if entries.is_empty() { continue; }
                let mut sorted_entries: Vec<(String, String, i64)> = Vec::new();
                let key_is_int = matches!(fd.mk, Some(FT::I32));
                for (k, v) in entries {
                    let ks = match k {
                        JV::Str(s) => jesc(s),
                        JV::Num(n) => format!("{}", n),
                        _ => String::new(),
                    };
                    let kn = match k {
                        JV::Num(n) => *n,
                        _ => 0,
                    };
                    let vs = match v {
                        DV::Sc(jv) => jv_str(jv),
                        DV::Msg(m) => {
                            let subdef = &sc.msgs[if let FT::Named(ref n) = fd.mv.as_ref().unwrap() { n } else { unreachable!() }];
                            msg_to_json(m, subdef, sc)
                        }
                    };
                    sorted_entries.push((ks, vs, kn));
                }
                if key_is_int {
                    sorted_entries.sort_by_key(|(_, _, kn)| *kn);
                } else {
                    sorted_entries.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));
                }
                let members: Vec<String> = sorted_entries.iter().map(|(k, v, _)| format!("\"{}\":{}", k, v)).collect();
                parts.push(format!("\"{}\":{{{}}}", jesc(&camel(&fd.name)), members.join(",")));
            }
        }
    }
    format!("{{{}}}", parts.join(","))
}

fn jv_str(jv: &JV) -> String {
    match jv {
        JV::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JV::Num(n) => format!("{}", n),
        JV::Str(s) => format!("\"{}\"", jesc(s)),
    }
}

// ===== main =====

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let schema_text = fs::read_to_string(format!("{}/schema.proto", dir)).unwrap();
    let messages_bin = fs::read(format!("{}/messages.bin", dir)).unwrap();

