fn skip_fld(d: &[u8], p: &mut usize, wt: u8, fnum: u32) {
    match wt {
        0 => { rvi(d, p); }
        1 => { *p += 8; }
        2 => { let l = rvi(d, p) as usize; *p += l; }
        3 => { loop { let k = rvi(d, p); let fn_ = (k >> 3) as u32; let w = (k & 7) as u8; if w == 4 && fn_ == fnum { break; } skip_fld(d, p, w, fn_); } }
        4 => {}
        5 => { *p += 4; }
        _ => {}
    }
}

fn rscalar(d: &[u8], p: &mut usize, _wt: u8, ft: &FT, sc: &Schema) -> JV {
    match ft {
        FT::I32 => { let v = rvi(d, p); JV::Num(v as u32 as i32 as i64) }
        FT::I64 => { let v = rvi(d, p); JV::Str(format!("{}", v as i64)) }
        FT::U32 => { let v = rvi(d, p); JV::Num(v as u32 as i64) }
        FT::U64 => { let v = rvi(d, p); JV::Str(format!("{}", v)) }
        FT::S32 => { let v = rvi(d, p); let z = ((v as u32) >> 1) ^ ((v as u32) & 1).wrapping_neg(); JV::Num(z as i32 as i64) }
        FT::S64 => { let v = rvi(d, p); let z = (v >> 1) ^ (v & 1).wrapping_neg(); JV::Str(format!("{}", z as i64)) }
        FT::Bool => { let v = rvi(d, p); JV::Bool(v != 0) }
        FT::Str => { let l = rvi(d, p) as usize; let s = String::from_utf8_lossy(&d[*p..*p+l]).to_string(); *p += l; JV::Str(s) }
        FT::Bytes => { let l = rvi(d, p) as usize; let r = b64(&d[*p..*p+l]); *p += l; JV::Str(r) }
        FT::F32 => { let v = u32::from_le_bytes([d[*p],d[*p+1],d[*p+2],d[*p+3]]); *p += 4; JV::Num(v as i64) }
        FT::F64 => { let v = u64::from_le_bytes(d[*p..*p+8].try_into().unwrap()); *p += 8; JV::Str(format!("{}", v)) }
