struct HttpResp { status: u16, headers: Vec<(String, String)>, body: String }

fn http_req(host: &str, port: u16, method: &str, path: &str, hdrs: &[(&str, String)], body: Option<&str>) -> HttpResp {
    let mut stream = TcpStream::connect((host, port)).unwrap();
    let mut req = format!("{} {} HTTP/1.1\r\n", method, path);
    req.push_str(&format!("Host: {}\r\n", host));
    for (k, v) in hdrs {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("Connection: close\r\n\r\n");
    if let Some(b) = body { req.push_str(b); }
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();
    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).unwrap();
    let he = find_crlfcrlf(&raw);
    let hdr_str = std::str::from_utf8(&raw[..he]).unwrap();
    let body_raw = &raw[he+4..];
    let first_line = hdr_str.split("\r\n").next().unwrap();
    let status: u16 = first_line.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut headers = Vec::new();
    for line in hdr_str.split("\r\n").skip(1) {
        if let Some(i) = line.find(':') {
            headers.push((line[..i].trim().to_lowercase(), line[i+1..].trim().to_string()));
        }
    }
    let is_chunked = headers.iter().any(|(k,v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked"));
    let body_bytes = if is_chunked { decode_chunked(body_raw) } else { body_raw.to_vec() };
    HttpResp { status, headers, body: String::from_utf8_lossy(&body_bytes).to_string() }
}

