struct JP<'a> { d: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { d: s.as_bytes(), p: 0 } }
    fn ws(&mut self) { while self.p < self.d.len() && matches!(self.d[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn val(&mut self) -> JsonValue {
        self.ws();
        match self.d[self.p] {
            b'{' => self.obj(),
            b'[' => self.arr(),
            b'"' => JsonValue::Str(self.string()),
            b't' => { self.p += 4; JsonValue::Bool(true) },
            b'f' => { self.p += 5; JsonValue::Bool(false) },
            b'n' => { self.p += 4; JsonValue::Null },
            _ => self.num(),
        }
    }
    fn obj(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut kvs = Vec::new();
        if self.d[self.p] == b'}' { self.p += 1; return JsonValue::Obj(kvs); }
        loop {
            self.ws();
            let k = self.string();
            self.ws(); self.p += 1;
            let v = self.val();
            kvs.push((k, v));
            self.ws();
            if self.d[self.p] == b',' { self.p += 1; } else { break; }
        }
        self.p += 1;
        JsonValue::Obj(kvs)
    }
    fn arr(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut a = Vec::new();
        if self.d[self.p] == b']' { self.p += 1; return JsonValue::Arr(a); }
        loop {
            a.push(self.val());
            self.ws();
            if self.d[self.p] == b',' { self.p += 1; } else { break; }
        }
        self.p += 1;
        JsonValue::Arr(a)
    }
    fn string(&mut self) -> String {
        self.p += 1;
        let mut bytes: Vec<u8> = Vec::new();
        while self.p < self.d.len() && self.d[self.p] != b'"' {
            if self.d[self.p] == b'\\' {
                self.p += 1;
                match self.d[self.p] {
                    b'"' => { bytes.push(b'"'); self.p += 1; }
                    b'\\' => { bytes.push(b'\\'); self.p += 1; }
                    b'/' => { bytes.push(b'/'); self.p += 1; }
                    b'b' => { bytes.push(0x08); self.p += 1; }
                    b'f' => { bytes.push(0x0C); self.p += 1; }
                    b'n' => { bytes.push(b'\n'); self.p += 1; }
                    b'r' => { bytes.push(b'\r'); self.p += 1; }
                    b't' => { bytes.push(b'\t'); self.p += 1; }
                    b'u' => {
                        self.p += 1;
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            self.p += 1; // \
                            self.p += 1; // u
                            let cp2 = self.hex4();
                            let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                            let mut buf = [0u8; 4];
                            bytes.extend_from_slice(char::from_u32(combined).unwrap().encode_utf8(&mut buf).as_bytes());
                        } else {
                            let mut buf = [0u8; 4];
                            bytes.extend_from_slice(char::from_u32(cp).unwrap().encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => { bytes.push(self.d[self.p]); self.p += 1; }
                }
            } else {
                bytes.push(self.d[self.p]);
                self.p += 1;
            }
        }
        self.p += 1;
        String::from_utf8(bytes).unwrap()
    }
    fn hex4(&mut self) -> u32 {
        let mut v = 0u32;
        for _ in 0..4 {
            let c = self.d[self.p]; self.p += 1;
            v = v * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                _ => (c - b'A' + 10) as u32,
            };
        }
        v
    }
    fn num(&mut self) -> JsonValue {
        let s = self.p;
        if self.d[self.p] == b'-' { self.p += 1; }
        while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        if self.p < self.d.len() && self.d[self.p] == b'.' { self.p += 1; while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; } }
        if self.p < self.d.len() && (self.d[self.p] == b'e' || self.d[self.p] == b'E') {
            self.p += 1;
