fn base64_encode(data: &[u8]) -> String {
    const C: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() { data[i+1] as u32 } else { 0 };
        let b2 = if i + 2 < data.len() { data[i+2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        r.push(C[((n >> 18) & 63) as usize] as char);
        r.push(C[((n >> 12) & 63) as usize] as char);
        if i + 1 < data.len() { r.push(C[((n >> 6) & 63) as usize] as char); } else { r.push('='); }
        if i + 2 < data.len() { r.push(C[(n & 63) as usize] as char); } else { r.push('='); }
        i += 3;
    }
    r
}

fn form_enc(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if (b >= b'A' && b <= b'Z') || (b >= b'a' && b <= b'z') || (b >= b'0' && b <= b'9')
            || b == b'-' || b == b'.' || b == b'_' || b == b'*' {
            r.push(b as char);
        } else if b == b' ' {
            r.push('+');
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

fn pct_enc(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if (b >= b'A' && b <= b'Z') || (b >= b'a' && b <= b'z') || (b >= b'0' && b <= b'9')
            || b == b'-' || b == b'.' || b == b'_' || b == b'~' {
            r.push(b as char);
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

fn find_crlfcrlf(d: &[u8]) -> usize {
    for i in 0..d.len().saturating_sub(3) {
        if d[i] == b'\r' && d[i+1] == b'\n' && d[i+2] == b'\r' && d[i+3] == b'\n' { return i; }
    }
    0
}

fn find_crlf(d: &[u8], start: usize) -> usize {
    for i in start..d.len().saturating_sub(1) {
        if d[i] == b'\r' && d[i+1] == b'\n' { return i; }
    }
    d.len()
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut p = 0;
    loop {
        let le = find_crlf(data, p);
        let sz_str = std::str::from_utf8(&data[p..le]).unwrap();
        let sz = usize::from_str_radix(sz_str.trim(), 16).unwrap();
        if sz == 0 { break; }
        p = le + 2;
        out.extend_from_slice(&data[p..p+sz]);
        p += sz + 2;
    }
    out
}

struct HttpResp { status: u16, headers: Vec<(String, String)>, body: String }

fn http_req(host: &str, port: u16, method: &str, path: &str, hdrs: &[(&str, String)], body: Option<&str>) -> HttpResp {
    let mut stream = TcpStream::connect((host, port)).unwrap();
    let mut req = format!("{} {} HTTP/1.1\r\n", method, path);
    req.push_str(&format!("Host: {}\r\n", host));
    for (k, v) in hdrs {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("Connection: close\r\n\r\n");
    if let Some(b) = body { req.push_str(b); }
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();
    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).unwrap();
    let he = find_crlfcrlf(&raw);
    let hdr_str = std::str::from_utf8(&raw[..he]).unwrap();
    let body_raw = &raw[he+4..];
    let first_line = hdr_str.split("\r\n").next().unwrap();
    let status: u16 = first_line.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut headers = Vec::new();
    for line in hdr_str.split("\r\n").skip(1) {
        if let Some(i) = line.find(':') {
            headers.push((line[..i].trim().to_lowercase(), line[i+1..].trim().to_string()));
        }
    }
    let is_chunked = headers.iter().any(|(k,v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked"));
    let body_bytes = if is_chunked { decode_chunked(body_raw) } else { body_raw.to_vec() };
    HttpResp { status, headers, body: String::from_utf8_lossy(&body_bytes).to_string() }
}

fn parse_amount(s: &str) -> i64 {
    let neg = s.starts_with('-');
    let s2 = if neg { &s[1..] } else { s };
    let (int_part, frac_part) = match s2.find('.') {
        Some(i) => (&s2[..i], &s2[i+1..]),
        None => (s2, ""),
    };
    let mut cents: i64 = int_part.parse::<i64>().unwrap() * 100;
    if !frac_part.is_empty() {
        let f = if frac_part.len() == 1 { format!("{}0", frac_part) } else { frac_part.to_string() };
        cents += f.parse::<i64>().unwrap();
    }
    if neg { -cents } else { cents }
}

fn fmt_cents(c: i64) -> String {
    let neg = c < 0;
    let a = if neg { -(c as i128) as i64 } else { c };
    let int_part = a / 100;
    let frac_part = a % 100;
    if neg {
        format!("-{}.{:02}", int_part, frac_part)
    } else {
        format!("{}.{:02}", int_part, frac_part)
    }
}

