static void skip_ws(void){
    while(*g_pp){
        if(*g_pp==' '||*g_pp=='\t'||*g_pp=='\n'||*g_pp=='\r'){g_pp++;}
        else if(g_pp[0]=='/'&&g_pp[1]=='/'){g_pp+=2;while(*g_pp&&*g_pp!='\n')g_pp++;}
        else if(g_pp[0]=='/'&&g_pp[1]=='*'){g_pp+=2;while(*g_pp&&!(g_pp[0]=='*'&&g_pp[1]=='/'))g_pp++;if(*g_pp)g_pp+=2;}
        else break;
    }
}
static int ident_ch(char c){return isalnum((unsigned char)c)||c=='_';}
static int rd_ident(char *b,int mx){skip_ws();int i=0;while(*g_pp&&ident_ch(*g_pp)&&i<mx-1)b[i++]=*g_pp++;b[i]='\0';return i;}
static long long rd_num(void){skip_ws();int neg=0;if(*g_pp=='-'){neg=1;g_pp++;}else if(*g_pp=='+')g_pp++;long long v=0;while(*g_pp>='0'&&*g_pp<='9'){v=v*10+(*g_pp-'0');g_pp++;}return neg?-v:v;}
static void skip_str(void){g_pp++;while(*g_pp&&*g_pp!='"')g_pp++;if(*g_pp=='"')g_pp++;}
static void skip_semi(void){while(*g_pp&&*g_pp!=';'){if(*g_pp=='"')skip_str();else g_pp++;}if(*g_pp==';')g_pp++;}
static void skip_fopts(void){skip_ws();if(*g_pp=='['){g_pp++;int d=1;while(*g_pp&&d>0){if(*g_pp=='"')skip_str();else if(*g_pp=='['){d++;g_pp++;}else if(*g_pp==']'){d--;g_pp++;}else g_pp++;}}}
static int find_msg(const char*n){for(int i=0;i<g_nm;i++)if(!strcmp(g_msg[i].name,n))return i;return -1;}
static int find_en(const char*n){for(int i=0;i<g_ne;i++)if(!strcmp(g_en[i].name,n))return i;return -1;}
static int builtin_type(const char*n){
    if(!strcmp(n,"int32"))return TK_INT32;if(!strcmp(n,"int64"))return TK_INT64;
    if(!strcmp(n,"uint32"))return TK_UINT32;if(!strcmp(n,"uint64"))return TK_UINT64;
    if(!strcmp(n,"sint32"))return TK_SINT32;if(!strcmp(n,"sint64"))return TK_SINT64;
    if(!strcmp(n,"bool"))return TK_BOOL;if(!strcmp(n,"string"))return TK_STRING;
    if(!strcmp(n,"bytes"))return TK_BYTES;if(!strcmp(n,"fixed32"))return TK_FIXED32;
    if(!strcmp(n,"fixed64"))return TK_FIXED64;if(!strcmp(n,"sfixed32"))return TK_SFIXED32;
    if(!strcmp(n,"sfixed64"))return TK_SFIXED64;return -1;
}

static void parse_field_or_map(MsgDef*md,int oi){
    skip_ws();int label=0;char tok[MAXN];const char*sv=g_pp;
    rd_ident(tok,MAXN);
    if(!strcmp(tok,"repeated"))label=1;
    else if(!strcmp(tok,"optional"))label=2;
    else g_pp=sv;
    rd_ident(tok,MAXN);
    if(!strcmp(tok,"map")){
        skip_ws();g_pp++;/*<*/
        char kn[MAXN];rd_ident(kn,MAXN);skip_ws();g_pp++;/*,*/
        char vn[MAXN];rd_ident(vn,MAXN);skip_ws();g_pp++;/*>*/
        FieldDef*fd=&md->fields[md->nf];memset(fd,0,sizeof*fd);
        fd->is_map=1;fd->label=0;fd->oneof_idx=-1;
        fd->map_key_kind=(!strcmp(kn,"string"))?TK_STRING:TK_INT32;
        strcpy(fd->map_val_name,vn);
        rd_ident(fd->name,MAXN);skip_ws();g_pp++;/*=*/
        fd->field_number=(int)rd_num();skip_fopts();skip_ws();g_pp++;/*;*/
        md->nf++;return;
    }
    FieldDef*fd=&md->fields[md->nf];memset(fd,0,sizeof*fd);
    fd->label=label;fd->oneof_idx=oi;fd->is_map=0;
    strcpy(fd->type_name,tok);
    rd_ident(fd->name,MAXN);skip_ws();g_pp++;/*=*/
    fd->field_number=(int)rd_num();skip_fopts();skip_ws();g_pp++;/*;*/
    md->nf++;
}

static void parse_oneof(MsgDef*md){
    g_pp+=5;char nm[MAXN];rd_ident(nm,MAXN);
    int oi=md->n_oneofs++;md->oneof_nf[oi]=0;
    skip_ws();g_pp++;/*{*/
    while(1){skip_ws();if(*g_pp=='}'){g_pp++;break;}if(!*g_pp)break;
        const char*sv=g_pp;char tok[MAXN];rd_ident(tok,MAXN);
        if(!strcmp(tok,"option"))skip_semi();
        else{g_pp=sv;int fi=md->nf;parse_field_or_map(md,oi);md->oneof_fi[oi][md->oneof_nf[oi]++]=fi;}
    }
}

static void parse_enum(void){
    g_pp+=4;char nm[MAXN];rd_ident(nm,MAXN);
    EnumDef*ed=&g_en[g_ne];memset(ed,0,sizeof*ed);strcpy(ed->name,nm);ed->nv=0;g_ne++;
    skip_ws();g_pp++;/*{*/
    while(1){skip_ws();if(*g_pp=='}'){g_pp++;break;}if(!*g_pp)break;
        const char*sv=g_pp;char tok[MAXN];rd_ident(tok,MAXN);
        if(!strcmp(tok,"option"))skip_semi();
        else if(!strcmp(tok,"reserved"))skip_semi();
        else{strcpy(ed->vals[ed->nv].name,tok);skip_ws();g_pp++;/*=*/
            ed->vals[ed->nv].num=(int)rd_num();skip_fopts();skip_ws();g_pp++;/*;*/ed->nv++;}
    }
}

static void parse_message(int depth){
    g_pp+=7;char nm[MAXN];rd_ident(nm,MAXN);
    MsgDef*md=&g_msg[g_nm];memset(md,0,sizeof*md);strcpy(md->name,nm);
    for(int i=0;i<MAXO;i++)md->oneof_nf[i]=0;
    int mi=g_nm++;if(depth==0&&g_root<0)g_root=mi;
    skip_ws();g_pp++;/*{*/
    while(1){skip_ws();if(*g_pp=='}'){g_pp++;break;}if(!*g_pp)break;
        const char*sv=g_pp;char tok[MAXN];rd_ident(tok,MAXN);
        if(!strcmp(tok,"message")){g_pp=sv;parse_message(depth+1);}
        else if(!strcmp(tok,"enum")){g_pp=sv;parse_enum();}
        else if(!strcmp(tok,"oneof")){g_pp=sv;parse_oneof(md);}
        else if(!strcmp(tok,"reserved"))skip_semi();
        else if(!strcmp(tok,"option"))skip_semi();
        else{g_pp=sv;parse_field_or_map(md,-1);}
    }
}

static void resolve_types(void){
    for(int m=0;m<g_nm;m++)for(int f=0;f<g_msg[m].nf;f++){
        FieldDef*fd=&g_msg[m].fields[f];
        if(fd->is_map){
            int tk=builtin_type(fd->map_val_name);
            if(tk>=0)fd->map_val_kind=tk;
            else{int mi=find_msg(fd->map_val_name);if(mi>=0){fd->map_val_kind=TK_MESSAGE;fd->map_val_idx=mi;}
                else{fd->map_val_kind=TK_ENUM;fd->map_val_idx=find_en(fd->map_val_name);}}
        }else{
            int tk=builtin_type(fd->type_name);
            if(tk>=0)fd->type_kind=tk;
            else{int mi=find_msg(fd->type_name);if(mi>=0){fd->type_kind=TK_MESSAGE;fd->type_idx=mi;}
                else{fd->type_kind=TK_ENUM;fd->type_idx=find_en(fd->type_name);}}
        }
    }
}

/* ===== Decoded Message ===== */
typedef struct DecodedMsg DecodedMsg;
typedef struct{int64_t i;uint64_t u;char*s;int slen;DecodedMsg*msg;}Val;
typedef struct{Val key;Val val;}MapEntry;
typedef struct{
    int occurred;Val val;
    Val*rep;int rep_n,rep_cap;
    MapEntry*mp;int mp_n,mp_cap;
}FVal;
struct DecodedMsg{FVal fv[MAXF];int oneof_act[MAXO];};

/* ===== Binary helpers ===== */
static uint64_t rd_vint(const uint8_t**pp,const uint8_t*end){
    uint64_t v=0;int sh=0;
    while(*pp<end){uint8_t b=**pp;(*pp)++;v|=(uint64_t)(b&0x7F)<<sh;if(!(b&0x80))break;sh+=7;if(sh>=64)break;}
    return v;
}
static uint32_t rd_f32(const uint8_t**pp,const uint8_t*end){
    uint32_t v=0;if(*pp+4<=end){v=(uint32_t)(*pp)[0]|((uint32_t)(*pp)[1]<<8)|((uint32_t)(*pp)[2]<<16)|((uint32_t)(*pp)[3]<<24);*pp+=4;}return v;
}
static uint64_t rd_f64(const uint8_t**pp,const uint8_t*end){
    uint64_t v=0;if(*pp+8<=end){for(int i=0;i<8;i++)v|=(uint64_t)(*pp)[i]<<(i*8);*pp+=8;}return v;
}
static void skip_wv(const uint8_t**pp,const uint8_t*end,int wt,int fn);
static void skip_grp(const uint8_t**pp,const uint8_t*end,int fn){
    while(*pp<end){uint64_t k=rd_vint(pp,end);int kfn=(int)(k>>3),kwt=(int)(k&7);
        if(kwt==4&&kfn==fn)return;skip_wv(pp,end,kwt,kfn);}
}
static void skip_wv(const uint8_t**pp,const uint8_t*end,int wt,int fn){
    switch(wt){case 0:rd_vint(pp,end);break;case 1:*pp+=8;break;
    case 2:{uint64_t l=rd_vint(pp,end);*pp+=l;}break;case 5:*pp+=4;break;
    case 3:skip_grp(pp,end,fn);break;case 4:break;}
}

static Val decode_scalar(const uint8_t**pp,const uint8_t*end,int tk,int ti){
    Val v={0};
    switch(tk){
    case TK_INT32:case TK_ENUM:v.i=(int32_t)(uint32_t)rd_vint(pp,end);break;
    case TK_INT64:v.i=(int64_t)rd_vint(pp,end);break;
    case TK_UINT32:v.i=(int64_t)(uint32_t)rd_vint(pp,end);break;
    case TK_UINT64:v.u=rd_vint(pp,end);break;
    case TK_SINT32:{uint32_t n=(uint32_t)rd_vint(pp,end);v.i=(int32_t)((n>>1)^-(n&1));}break;
    case TK_SINT64:{uint64_t n=rd_vint(pp,end);v.i=(int64_t)((n>>1)^-(n&1));}break;
    case TK_BOOL:v.i=rd_vint(pp,end)!=0?1:0;break;
    case TK_FIXED32:v.i=(int64_t)rd_f32(pp,end);break;
    case TK_SFIXED32:v.i=(int32_t)rd_f32(pp,end);break;
    case TK_FIXED64:v.u=rd_f64(pp,end);break;
    case TK_SFIXED64:v.i=(int64_t)rd_f64(pp,end);break;
    default:break;
    }
    return v;
}

static void rep_append(FVal*fv,Val v){
    if(fv->rep_n>=fv->rep_cap){fv->rep_cap=fv->rep_cap?fv->rep_cap*2:8;fv->rep=realloc(fv->rep,fv->rep_cap*sizeof(Val));}
    fv->rep[fv->rep_n++]=v;
}
static int keys_eq(Val*a,Val*b,int kk){
    if(kk==TK_STRING)return a->slen==b->slen&&(a->slen==0||!memcmp(a->s,b->s,a->slen));
    return a->i==b->i;
}
static void map_upd(FVal*fv,Val k,Val val,FieldDef*fd){
    if(fv->mp_n>=fv->mp_cap){fv->mp_cap=fv->mp_cap?fv->mp_cap*2:8;fv->mp=realloc(fv->mp,fv->mp_cap*sizeof(MapEntry));}
    for(int i=0;i<fv->mp_n;i++)if(keys_eq(&fv->mp[i].key,&k,fd->map_key_kind)){fv->mp[i].val=val;return;}
    fv->mp[fv->mp_n].key=k;fv->mp[fv->mp_n].val=val;fv->mp_n++;
}

static void merge_dec(DecodedMsg*dst,DecodedMsg*src,int mi){
    MsgDef*md=&g_msg[mi];
    for(int i=0;i<md->nf;i++){
        FVal*sf=&src->fv[i],*df=&dst->fv[i];FieldDef*fd=&md->fields[i];
        if(!sf->occurred)continue;
        if(fd->is_map){for(int j=0;j<sf->mp_n;j++)map_upd(df,sf->mp[j].key,sf->mp[j].val,fd);}
        else if(fd->label==1){for(int j=0;j<sf->rep_n;j++)rep_append(df,sf->rep[j]);}
        else if(fd->type_kind==TK_MESSAGE){if(sf->val.msg){if(df->occurred&&df->val.msg)merge_dec(df->val.msg,sf->val.msg,fd->type_idx);else df->val.msg=sf->val.msg;}}
        else{df->val=sf->val;}
        df->occurred=1;
    }
    for(int i=0;i<md->n_oneofs;i++)if(src->oneof_act[i]>=0)dst->oneof_act[i]=src->oneof_act[i];
}

static DecodedMsg*decode_msg(const uint8_t*data,int len,int mi){
    DecodedMsg*dm=calloc(1,sizeof(DecodedMsg));
    for(int i=0;i<MAXO;i++)dm->oneof_act[i]=-1;
    MsgDef*md=&g_msg[mi];
    const uint8_t*p=data,*end=data+len;
    while(p<end){
        uint64_t key=rd_vint(&p,end);int fn=(int)(key>>3),wt=(int)(key&7);
        int fi=-1;for(int i=0;i<md->nf;i++)if(md->fields[i].field_number==fn){fi=i;break;}
        if(fi<0){skip_wv(&p,end,wt,fn);continue;}
        FieldDef*fd=&md->fields[fi];FVal*fv=&dm->fv[fi];
        if(fd->is_map){
            if(wt==2){uint64_t ml=rd_vint(&p,end);const uint8_t*me=p+ml;
                Val k={0},vl={0};
                while(p<me){uint64_t k2=rd_vint(&p,me);int kfn=(int)(k2>>3),kwt=(int)(k2&7);
                    if(kfn==1){if(fd->map_key_kind==TK_STRING){uint64_t sl=rd_vint(&p,me);k.s=(char*)p;k.slen=(int)sl;p+=sl;}else k.i=(int32_t)(uint32_t)rd_vint(&p,me);}
                    else if(kfn==2){if(fd->map_val_kind==TK_MESSAGE){uint64_t ml2=rd_vint(&p,me);vl.msg=decode_msg(p,(int)ml2,fd->map_val_idx);p+=ml2;}
                        else if(fd->map_val_kind==TK_STRING||fd->map_val_kind==TK_BYTES){uint64_t sl=rd_vint(&p,me);vl.s=(char*)p;vl.slen=(int)sl;p+=sl;}
                        else vl=decode_scalar(&p,me,fd->map_val_kind,fd->map_val_idx);}
                    else skip_wv(&p,me,kwt,kfn);}
                map_upd(fv,k,vl,fd);p=me;}
            fv->occurred=1;continue;
        }
        if(fd->oneof_idx>=0){
            int oi=fd->oneof_idx;int same=(dm->oneof_act[oi]==fi);
            if(!same){if(dm->oneof_act[oi]>=0){FVal*old=&dm->fv[dm->oneof_act[oi]];memset(old,0,sizeof(FVal));old->occurred=0;}dm->oneof_act[oi]=fi;}
            if(fd->type_kind==TK_MESSAGE){if(wt==2){uint64_t ml=rd_vint(&p,end);
                if(same&&fv->occurred&&fv->val.msg)merge_dec(fv->val.msg,decode_msg(p,(int)ml,fd->type_idx),fd->type_idx);
                else fv->val.msg=decode_msg(p,(int)ml,fd->type_idx);
                p+=ml;}}
            else{fv->val=decode_scalar(&p,end,fd->type_kind,fd->type_idx);}
            fv->occurred=1;continue;
        }
        if(fd->label==1){
            if(fd->type_kind==TK_MESSAGE){if(wt==2){uint64_t ml=rd_vint(&p,end);Val v={0};v.msg=decode_msg(p,(int)ml,fd->type_idx);p+=ml;rep_append(fv,v);}}
            else if(fd->type_kind==TK_STRING||fd->type_kind==TK_BYTES){if(wt==2){uint64_t sl=rd_vint(&p,end);Val v={0};v.s=(char*)p;v.slen=(int)sl;p+=sl;rep_append(fv,v);}}
            else{
                if(wt==2){uint64_t pl=rd_vint(&p,end);const uint8_t*pe=p+pl;while(p<pe){rep_append(fv,decode_scalar(&p,pe,fd->type_kind,fd->type_idx));}p=pe;}
                else rep_append(fv,decode_scalar(&p,end,fd->type_kind,fd->type_idx));
            }
            fv->occurred=1;continue;
        }
        /* singular scalar or message */
        if(fd->type_kind==TK_MESSAGE){
            if(wt==2){uint64_t ml=rd_vint(&p,end);
                if(fv->occurred&&fv->val.msg)merge_dec(fv->val.msg,decode_msg(p,(int)ml,fd->type_idx),fd->type_idx);
                else fv->val.msg=decode_msg(p,(int)ml,fd->type_idx);
                p+=ml;}
        }else{fv->val=decode_scalar(&p,end,fd->type_kind,fd->type_idx);}
        fv->occurred=1;
    }
    return dm;
}

/* ===== JSON Output ===== */
static void to_camel(const char*n,char*o){
    int j=0,u=0;
    for(int i=0;n[i];i++){if(n[i]=='_'){u=1;}else{if(u&&n[i]>='a'&&n[i]<='z')o[j++]=n[i]-32;else o[j++]=n[i];u=0;}}
    o[j]='\0';
}
static void pjson_str(const char*s,int len){
    putchar('"');
    for(int i=0;i<len;i++){unsigned char c=s[i];
        if(c=='"')printf("\\\"");else if(c=='\\')printf("\\\\");
        else if(c==8)printf("\\b");else if(c==9)printf("\\t");else if(c==10)printf("\\n");
        else if(c==12)printf("\\f");else if(c==13)printf("\\r");
        else if(c<0x20)printf("\\u%04x",c);
        else putchar(c);}
    putchar('"');
}
static const char b64c[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void pbase64(const char*d,int len){
    putchar('"');int i=0;
    while(i+2<len){uint32_t v=((uint8_t)d[i]<<16)|((uint8_t)d[i+1]<<8)|(uint8_t)d[i+2];
        putchar(b64c[(v>>18)&63]);putchar(b64c[(v>>12)&63]);putchar(b64c[(v>>6)&63]);putchar(b64c[v&63]);i+=3;}
    if(i<len){uint32_t v=(uint8_t)d[i]<<16;if(i+1<len)v|=(uint8_t)d[i+1]<<8;
        putchar(b64c[(v>>18)&63]);putchar(b64c[(v>>12)&63]);
        if(i+1<len){putchar(b64c[(v>>6)&63]);putchar('=');}else{putchar('=');putchar('=');}}
    putchar('"');
}
static int is_def(FieldDef*fd,FVal*fv){
    switch(fd->type_kind){
    case TK_BOOL:return fv->val.i==0;
    case TK_STRING:case TK_BYTES:return fv->val.slen==0;
    default:return fv->val.i==0&&fv->val.u==0;
    }
}
static int should_print(FieldDef*fd,FVal*fv,DecodedMsg*dm,int fi){
    if(fd->is_map)return fv->mp_n>0;
    if(fd->label==1)return fv->rep_n>0;
    if(fd->type_kind==TK_MESSAGE)return fv->occurred;
    if(!fv->occurred)return 0;
    if(fd->label==2)return 1;
    if(fd->oneof_idx>=0)return fv->occurred;
    return !is_def(fd,fv);
}
static void print_val(FieldDef*fd,Val*v,int tk,int ti){
    if(tk==TK_MESSAGE){if(v->msg)print_json_msg(v->msg,ti);else printf("{}");return;}
    if(tk==TK_STRING){pjson_str(v->s?v->s:"",v->slen);return;}
    if(tk==TK_BYTES){pbase64(v->s?v->s:"",v->slen);return;}
    if(tk==TK_BOOL){puts(v->i?"true":"false");return;}
    if(tk==TK_ENUM){EnumDef*ed=&g_en[ti];int found=0;
        for(int i=0;i<ed->nv;i++)if(ed->vals[i].num==(int)v->i){printf("\"%s\"",ed->vals[i].name);found=1;break;}
        if(!found)printf("%"PRId64,v->i);return;}
    if(tk==TK_INT64||tk==TK_SINT64||tk==TK_SFIXED64)printf("\"%"PRId64"\"",v->i);
    else if(tk==TK_UINT64||tk==TK_FIXED64)printf("\"%"PRIu64"\"",v->u);
    else if(tk==TK_UINT32||tk==TK_FIXED32)printf("%"PRId64,v->i);
    else printf("%"PRId64,v->i);
}
static void print_json_msg(DecodedMsg*dm,int mi){
    MsgDef*md=&g_msg[mi];
    int ord[MAXF],no=0;
    for(int i=0;i<md->nf;i++)ord[no++]=i;
    for(int i=0;i<no-1;i++)for(int j=i+1;j<no;j++)if(md->fields[ord[j]].field_number<md->fields[ord[i]].field_number){int t=ord[i];ord[i]=ord[j];ord[j]=t;}
    putchar('{');int first=1;
    for(int k=0;k<no;k++){int fi=ord[k];FieldDef*fd=&md->fields[fi];FVal*fv=&dm->fv[fi];
        if(!should_print(fd,fv,dm,fi))continue;
        if(!first)putchar(',');first=0;
        char jn[MAXN];to_camel(fd->name,jn);pjson_str(jn,strlen(jn));putchar(':');
        if(fd->is_map){
            /* sort map entries */
            if(fd->map_key_kind==TK_STRING){
                for(int i=1;i<fv->mp_n;i++){MapEntry tmp=fv->mp[i];int j=i-1;
                    while(j>=0){int ml=fv->mp[j].key.slen<tmp.key.slen?fv->mp[j].key.slen:tmp.key.slen;
                        int r=memcmp(fv->mp[j].key.s,tmp.key.s,ml);if(r>0||(r==0&&fv->mp[j].key.slen>tmp.key.slen)){fv->mp[j+1]=fv->mp[j];j--;}else break;}
                    fv->mp[j+1]=tmp;}
            }else{
                for(int i=1;i<fv->mp_n;i++){MapEntry tmp=fv->mp[i];int j=i-1;
                    while(j>=0&&fv->mp[j].key.i>tmp.key.i){fv->mp[j+1]=fv->mp[j];j--;}fv->mp[j+1]=tmp;}
            }
            putchar('{');int mf=1;
            for(int i=0;i<fv->mp_n;i++){
                if(!mf)putchar(',');mf=0;
                if(fd->map_key_kind==TK_STRING)pjson_str(fv->mp[i].key.s?fv->mp[i].key.s:"",fv->mp[i].key.slen);
                else printf("\"%"PRId64"\"",fv->mp[i].key.i);
                putchar(':');
                print_val(fd,&fv->mp[i].val,fd->map_val_kind,fd->map_val_idx);
            }
            putchar('}');
        }else if(fd->label==1){
            putchar('[');
            for(int i=0;i<fv->rep_n;i++){if(i)putchar(',');print_val(fd,&fv->rep[i],fd->type_kind,fd->type_idx);}
            putchar(']');
        }else{
            print_val(fd,&fv->val,fd->type_kind,fd->type_idx);
        }
    }
    putchar('}');
}

/* ===== Main ===== */
static char* read_file(const char*path,long*sz){
    FILE*f=fopen(path,"rb");if(!f){*sz=0;return NULL;}
    fseek(f,0,SEEK_END);*sz=ftell(f);fseek(f,0,SEEK_SET);
