function escapeStr(s: string): string {
  let r = '';
  for (const ch of s) {
    if (ch === '\\') r += '\\\\';
    else if (ch === '\n') r += '\\n';
    else if (ch === '\r') r += '\\r';
    else if (ch === '\t') r += '\\t';
    else r += ch;
  }
