function processStream(body: string): StreamResult {
  const events = parseSSE(body);
  const blockMap = new Map<number, ContentBlock>();
  let stopReason = '';
  let inputTokens = 0;
  let outputTokens = 0;
  let cacheReadTokens = 0;

  for (const { event, data } of events) {
    let json: any;
    try { json = JSON.parse(data); } catch { continue; }

    if (event === 'message_start') {
      const usage = json.message?.usage;
      if (usage) {
        inputTokens += usage.input_tokens ?? 0;
        cacheReadTokens += usage.cache_read_input_tokens ?? 0;
      }
    } else if (event === 'content_block_start') {
      const idx = json.index as number;
      const cb = json.content_block;
      if (cb.type === 'thinking') {
        blockMap.set(idx, { type: 'thinking', thinking: '', signature: '', text: '', id: '', name: '', rawInput: '', input: undefined });
      } else if (cb.type === 'text') {
        blockMap.set(idx, { type: 'text', thinking: '', signature: '', text: '', id: '', name: '', rawInput: '', input: undefined });
      } else if (cb.type === 'tool_use') {
        blockMap.set(idx, { type: 'tool_use', thinking: '', signature: '', text: '', id: cb.id, name: cb.name, rawInput: '', input: undefined });
      }
    } else if (event === 'content_block_delta') {
      const idx = json.index as number;
      const delta = json.delta;
      const block = blockMap.get(idx);
      if (!block) continue;
      if (delta.type === 'thinking_delta') {
        block.thinking += delta.thinking;
      } else if (delta.type === 'signature_delta') {
        block.signature += delta.signature;
      } else if (delta.type === 'text_delta') {
        block.text += delta.text;
      } else if (delta.type === 'input_json_delta') {
        block.rawInput += delta.partial_json;
      }
    } else if (event === 'content_block_stop') {
      const idx = json.index as number;
      const block = blockMap.get(idx);
      if (block && block.type === 'tool_use') {
        block.input = JSON.parse(block.rawInput || '{}');
      }
    } else if (event === 'message_delta') {
      if (json.delta?.stop_reason) stopReason = json.delta.stop_reason;
      outputTokens += json.usage?.output_tokens ?? 0;
    } else if (event === 'message_stop') {
      // end of reply
    }
    // ping and other events: ignore
  }

  const sortedIndices = [...blockMap.keys()].sort((a, b) => a - b);
  const blocks = sortedIndices.map(i => blockMap.get(i)!);

  return { blocks, stopReason, inputTokens, outputTokens, cacheReadTokens };
}

function executeTool(name: string, input: any): { result: string; isError: boolean } {
  if (name === 'measure') {
    const text = input.text as string;
    const unit = input.unit as string;
    if (unit === 'code_points') {
      return { result: String([...text].length), isError: false };
    } else if (unit === 'utf8_bytes') {
      return { result: String(Buffer.byteLength(text, 'utf8')), isError: false };
    } else if (unit === 'utf16_units') {
      return { result: String(text.length), isError: false };
    } else {
      return { result: `unsupported unit: ${unit}`, isError: true };
    }
  } else if (name === 'reverse') {
    const text = input.text as string;
    return { result: [...text].reverse().join(''), isError: false };
  } else {
    return { result: `unknown tool: ${name}`, isError: true };
  }
}

function makeRequest(bodyObj: object): Promise<{ statusCode: number; body: string }> {
  return new Promise((resolve, reject) => {
    const url = new URL(baseUrl + '/v1/messages');
    const bodyStr = JSON.stringify(bodyObj);
    const bodyBuf = Buffer.from(bodyStr, 'utf8');

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: url.port ? parseInt(url.port) : 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Content-Length': bodyBuf.length,
        'x-api-key': config.api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
    };

    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode ?? 0,
          body: Buffer.concat(chunks).toString('utf8'),
        });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    req.write(bodyBuf);
    req.end();
  });
}

function printBlocks(blocks: ContentBlock[]): string[] {
  const lines: string[] = [];
  for (const b of blocks) {
    if (b.type === 'thinking') {
