                if (next != '\n' && next >= 0) {
                    sb.append('\r');
                    // pushback not possible, but we handle CRLF: if next is \n we consumed both
                    // if next is not \n, we need to include it... but spec says lines end in LF or CRLF
                    // so CR without LF shouldn't happen in valid input
                    sb.append((char) next);
                }
                break;
            }
            sb.append((char) c);
        }
        return sb.toString();
