            }
        }
    }

    static String escape(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c); break;
            }
        }
        return sb.toString();
    }

    static String executeTool(String name, Map<String, Object> input) {
        if (name.equals("measure")) {
            String text = (String) input.get("text");
            String unit = (String) input.get("unit");
            switch (unit) {
                case "code_points":
                    return String.valueOf(text.codePointCount(0, text.length()));
                case "utf8_bytes":
                    return String.valueOf(text.getBytes(StandardCharsets.UTF_8).length);
                case "utf16_units":
                    return String.valueOf(text.length());
                default:
                    throw new RuntimeException("unsupported unit: " + unit);
            }
        } else if (name.equals("reverse")) {
            String text = (String) input.get("text");
            int[] cps = text.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return sb.toString();
        } else {
            throw new RuntimeException("unknown tool: " + name);
        }
    }

    // --- JSON Parser ---
    static int pos;
    static String jsonStr;

    static Object parseJson(String s) {
        jsonStr = s;
        pos = 0;
        skipWs();
        Object val = parseValue();
        skipWs();
        return val;
    }

    static void skipWs() {
        while (pos < jsonStr.length()) {
            char c = jsonStr.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
            else break;
        }
    }

    static Object parseValue() {
        skipWs();
        char c = jsonStr.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't') { pos += 4; return Boolean.TRUE; }
        if (c == 'f') { pos += 5; return Boolean.FALSE; }
        if (c == 'n') { pos += 4; return null; }
        return parseNumber();
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++;
        skipWs();
        if (jsonStr.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWs();
            String key = parseString();
            skipWs();
            pos++; // :
            skipWs();
            Object val = parseValue();
            map.put(key, val);
            skipWs();
            char c = jsonStr.charAt(pos);
            if (c == '}') { pos++; break; }
            pos++; // ,
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        if (jsonStr.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            skipWs();
            list.add(parseValue());
            skipWs();
            char c = jsonStr.charAt(pos);
            if (c == ']') { pos++; break; }
            pos++; // ,
        }
        return list;
    }

    static String parseString() {
        pos++;
        StringBuilder sb = new StringBuilder();
        while (pos < jsonStr.length()) {
            char c = jsonStr.charAt(pos);
            if (c == '"') { pos++; break; }
            if (c == '\\') {
                pos++;
                char e = jsonStr.charAt(pos);
                switch (e) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u': {
                        int cp = Integer.parseInt(jsonStr.substring(pos + 1, pos + 5), 16);
                        pos += 4;
                        if (Character.isHighSurrogate((char) cp)) {
                            pos++; // skip backslash
                            pos++; // skip 'u'
                            int lo = Integer.parseInt(jsonStr.substring(pos + 1, pos + 5), 16);
                            pos += 4;
                            cp = Character.toCodePoint((char) cp, (char) lo);
                        }
                        sb.appendCodePoint(cp);
                        break;
                    }
                    default: sb.append(e); break;
                }
            } else {
                sb.append(c);
            }
            pos++;
        }
        return sb.toString();
    }

    static Object parseNumber() {
        int start = pos;
        while (pos < jsonStr.length()) {
            char c = jsonStr.charAt(pos);
            if (c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || (c >= '0' && c <= '9')) pos++;
            else break;
        }
        String num = jsonStr.substring(start, pos);
        if (num.contains(".") || num.contains("e") || num.contains("E")) return Double.parseDouble(num);
        return Long.parseLong(num);
    }

    // --- JSON Serializer ---
    static String toJson(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof Number) {
            if (obj instanceof Long) return obj.toString();
            if (obj instanceof Double) {
                double d = (Double) obj;
                if (d == (long) d) return String.valueOf((long) d);
                return obj.toString();
            }
            return obj.toString();
        }
        if (obj instanceof String) return jsonString((String) obj);
        if (obj instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> map = (Map<String, Object>) obj;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : map.entrySet()) {
                if (!first) sb.append(",");
                sb.append(jsonString(e.getKey())).append(":").append(toJson(e.getValue()));
                first = false;
            }
            sb.append("}");
            return sb.toString();
        }
        if (obj instanceof List) {
            @SuppressWarnings("unchecked")
            List<Object> list = (List<Object>) obj;
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : list) {
                if (!first) sb.append(",");
                sb.append(toJson(item));
                first = false;
            }
            sb.append("]");
            return sb.toString();
        }
        return obj.toString();
    }

    static String jsonString(String s) {
