Looking at the timeout issue, the main problem is the HTTP response reading loop reads until EOF (`read()` returns 0), which can block for the full socket timeout (30s) even though the response is complete. The fix is to read headers first, then read exactly the body based on `Content-Length` or `Transfer-Encoding: chunked`. I also replaced `strcasestr` (not reliably available with `-std=c17` on macOS) and tightened the socket timeout.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>
#include <errno.h>
#include <ctype.h>

/* ── dynamic buffer ── */
typedef struct{char*d;size_t n,cap;}Buf;
static void bi(Buf*b){b->d=NULL;b->n=0;b->cap=0;}
static void bg(Buf*b,size_t x){if(b->n+x>b->cap){b->cap=(b->n+x)*2+256;b->d=realloc(b->d,b->cap);}}
static void ba(Buf*b,char c){bg(b,1);b->d[b->n++]=c;}
static void bp(Buf*b,const void*s,size_t n){bg(b,n);memcpy(b->d+b->n,s,n);b->n+=n;}

/* ── base64 ── */
static const char B64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static char*b64enc(const unsigned char*d,size_t n){
    size_t o=4*((n+2)/3);char*r=malloc(o+1);size_t j=0;
    for(size_t i=0;i<n;i+=3){
        uint32_t v=((uint32_t)d[i])<<16;
        if(i+1<n)v|=((uint32_t)d[i+1])<<8;
        if(i+2<n)v|=(uint32_t)d[i+2];
        r[j++]=B64[(v>>18)&63];r[j++]=B64[(v>>12)&63];
        r[j++]=(i+1<n)?B64[(v>>6)&63]:'=';
        r[j++]=(i+2<n)?B64[v&63]:'=';
    }
    r[j]=0;return r;
}

/* ── form-urlencoded (RFC 6749 §2.3.1) ── */
static char*formenc(const char*s){
    Buf b={0};
    for(const char*p=s;*p;p++){
        unsigned char c=(unsigned char)*p;
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='*')ba(&b,c);
        else if(c==' ')ba(&b,'+');
        else{ba(&b,'%');ba(&b,"0123456789ABCDEF"[c>>4]);ba(&b,"0123456789ABCDEF"[c&15]);}
    }
    ba(&b,0);return b.d;
}

/* ── percent-encode for query ── */
static char*qenc(const char*s){
    Buf b={0};
    for(const char*p=s;*p;p++){
        unsigned char c=(unsigned char)*p;
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='~')ba(&b,c);
        else{ba(&b,'%');ba(&b,"0123456789ABCDEF"[c>>4]);ba(&b,"0123456789ABCDEF"[c&15]);}
    }
    ba(&b,0);return b.d;
}

/* ── JSON parser ── */
typedef struct{const char*s;size_t p,len;}JC;
static void jsk(JC*c){while(c->p<c->len&&isspace((unsigned char)c->s[c->p]))c->p++;}
static char jpk(JC*c){jsk(c);return c->p<c->len?c->s[c->p]:0;}
static char jnx(JC*c){jsk(c);return c->p<c->len?c->s[c->p++]:0;}
static uint32_t hx4(JC*c){uint32_t v=0;for(int i=0;i<4;i++){char h=c->s[c->p++];v<<=4;if(h<='9')v|=h-'0';else if(h<='f')v|=h-'a'+10;else v|=h-'A'+10;}return v;}
static void u8(Buf*b,uint32_t cp){
    if(cp<0x80)ba(b,(char)cp);
    else if(cp<0x800){ba(b,(char)(0xC0|(cp>>6)));ba(b,(char)(0x80|(cp&0x3F)));}
    else if(cp<0x10000){ba(b,(char)(0xE0|(cp>>12)));ba(b,(char)(0x80|((cp>>6)&0x3F)));ba(b,(char)(0x80|(cp&0x3F)));}
    else{ba(b,(char)(0xF0|(cp>>18)));ba(b,(char)(0x80|((cp>>12)&0x3F)));ba(b,(char)(0x80|((cp>>6)&0x3F)));ba(b,(char)(0x80|(cp&0x3F)));}
}
static char*jstr(JC*c){
    Buf b={0};c->p++;
    while(c->p<c->len&&c->s[c->p]!='"'){
        if(c->s[c->p]=='\\'){
            c->p++;
            char e=c->s[c->p];
            switch(e){
                case'"':ba(&b,'"');c->p++;break;
                case'\\':ba(&b,'\\');c->p++;break;
                case'/':ba(&b,'/');c->p++;break;
                case'b':ba(&b,'\b');c->p++;break;
                case'f':ba(&b,'\f');c->p++;break;
                case'n':ba(&b,'\n');c->p++;break;
                case'r':ba(&b,'\r');c->p++;break;
                case't':ba(&b,'\t');c->p++;break;
                case'u':{c->p++;uint32_t cp=hx4(c);
                    if(cp>=0xD800&&cp<=0xDBFF&&c->p+1<c->len&&c->s[c->p]=='\\'&&c->s[c->p+1]=='u'){
                        c->p+=2;uint32_t lo=hx4(c);cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    u8(&b,cp);break;}
                default:ba(&b,e);c->p++;break;
            }
        }else{ba(&b,c->s[c->p]);c->p++;}
    }
    if(c->p<c->len)c->p++;
    ba(&b,0);return b.d;
}
static void jskipv(JC*c){
    char ch=jpk(c);
    if(ch=='"'){c->p++;while(c->p<c->len){if(c->s[c->p]=='\\')c->p+=2;else if(c->s[c->p]=='"'){c->p++;break;}else c->p++;}}
    else if(ch=='{'||ch=='['){int d=1;c->p++;while(c->p<c->len&&d>0){if(c->s[c->p]=='"'){c->p++;while(c->p<c->len){if(c->s[c->p]=='\\')c->p+=2;else if(c->s[c->p]=='"'){c->p++;break;}else c->p++;}}else if(c->s[c->p]=='{'||c->s[c->p]=='[')d++;else if(c->s[c->p]=='}'||c->s[c->p]==']')d--;else c->p++;}}
    else{while(c->p<c->len&&c->s[c->p]!=','&&c->s[c->p]!='}'&&c->s[c->p]!=']'&&!isspace((unsigned char)c->s[c->p]))c->p++;}
}
