/* ── URL parse ── */
static void purl(const char*url,char*host,size_t hsz,int*port,char*path,size_t psz){
    const char*p=strstr(url,"://");if(p)p+=3;else p=url;
    const char*sl=strchr(p,'/');const char*co=strchr(p,':');
    if(co&&(!sl||co<sl)){size_t hl=(size_t)(co-p);if(hl>=hsz)hl=hsz-1;memcpy(host,p,hl);host[hl]=0;*port=atoi(co+1);}
    else{size_t hl=sl?(size_t)(sl-p):strlen(p);if(hl>=hsz)hl=hsz-1;memcpy(host,p,hl);host[hl]=0;*port=80;}
    if(sl){size_t pl=strlen(sl);if(pl>=psz)pl=psz-1;memcpy(path,sl,pl);path[pl]=0;}
    else{path[0]='/';path[1]=0;}
}

/* ── buffered connection reader ── */
typedef struct{int fd;char buf[8192];size_t pos,len;}Conn;
static int conn_getc(Conn*c){
    if(c->pos>=c->len){
        ssize_t n=read(c->fd,c->buf,sizeof(c->buf));
        if(n<=0)return -1;
        c->pos=0;c->len=(size_t)n;
    }
    return (unsigned char)c->buf[c->pos++];
}
static int read_line_conn(Conn*c,Buf*out){
    int ch;
    while((ch=conn_getc(c))!=-1){
        if(ch=='\n')return 0;
        if(ch!='\r')ba(out,ch);
    }
    return -1;
}
static int read_exact_conn(Conn*c,char*dst,size_t n){
    size_t got=0;
    while(got<n){
        int ch=conn_getc(c);
        if(ch==-1)return -1;
        dst[got++]=(char)ch;
    }
    return 0;
}

