static int64_t parse_cents(const char*s){
    int neg=0;if(*s=='-'){neg=1;s++;}
    int64_t w=0;while(*s>='0'&&*s<='9'){w=w*10+(*s-'0');s++;}
    int64_t f=0;
    if(*s=='.'){s++;if(*s>='0'&&*s<='9'){f=*s-'0';s++;}if(*s>='0'&&*s<='9'){f=f*10+(*s-'0');s++;}}
    int64_t c=w*100+f;
    return neg?-c:c;
}
