Looking at the crash (exit status -5 = SIGTRAP), I identified several bugs:

1. **M formula**: Used `* 32` instead of `* 64` per the SQLite spec
2. **Overflow local size**: When K > X, should set local = M, not K - (U-4)
3. **`parseColumnDefs` crash**: `ta[idx...]` crashes when `idx >= ta.count` (column with no type/constraints)
4. **Bounds checking**: Missing guards in `parseRecord` when payload is shorter than expected

Here's the corrected program:

```swift
import Foundation

// MARK: - File reading and header parsing

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]
let filePath = dir + "/db.sqlite"
guard let data = FileManager.default.contents(atPath: filePath) else { exit(1) }
let bytes = [UInt8](data)

func u16(_ o: Int) -> Int { Int(bytes[o]) << 8 | Int(bytes[o+1]) }
func u32(_ o: Int) -> Int { Int(bytes[o]) << 24 | Int(bytes[o+1]) << 16 | Int(bytes[o+2]) << 8 | Int(bytes[o+3]) }

let pageSizeRaw = u16(16)
let pageSize = pageSizeRaw == 1 ? 65536 : pageSizeRaw
let reservedBytes = Int(bytes[20])
let usableSize = pageSize - reservedBytes

func pageOff(_ p: Int) -> Int { (p - 1) * pageSize }

// MARK: - Varint

func readVarint(_ buf: [UInt8], _ off: Int) -> (UInt64, Int) {
    var result: UInt64 = 0
    var pos = off
    for i in 0..<9 {
        let b = UInt64(buf[pos]); pos += 1
        if i == 8 { result = (result << 8) | b }
        else { result = (result << 7) | (b & 0x7F); if b & 0x80 == 0 { break } }
    }
    return (result, pos)
}

func readVarintFile(_ off: Int) -> (UInt64, Int) { readVarint(bytes, off) }

// MARK: - B-tree page header

func btreeHeader(_ pageNum: Int) -> (pageType: Int, numCells: Int, contentStart: Int, rightmost: Int) {
    let base = pageOff(pageNum)
    let ho = pageNum == 1 ? 100 : 0
    let pt = Int(bytes[base + ho])
    let nc = u16(base + ho + 3)
    var cs = u16(base + ho + 5)
    if cs == 0 { cs = 65536 }
    var rm = 0
    if pt == 5 || pt == 2 { rm = u32(base + ho + 8) }
    return (pt, nc, cs, rm)
}

// MARK: - Overflow payload

func readOverflow(_ pageNum: Int, _ length: Int) -> [UInt8] {
    var out = [UInt8]()
    out.reserveCapacity(length)
    var pg = pageNum
    var remaining = length
    while remaining > 0 && pg != 0 {
        let base = pageOff(pg)
        let avail = pageSize - 4
        let toRead = min(avail, remaining)
        for i in 0..<toRead { out.append(bytes[base + 4 + i]) }
        remaining -= toRead
        if remaining > 0 { pg = u32(base) } else { pg = 0 }
    }
    return out
}

// MARK: - Leaf table cell parsing

func parseLeafCell(_ pageNum: Int, _ cellOff: Int) -> (Int64, [UInt8]) {
    let base = pageOff(pageNum)
    var pos = base + cellOff
    let (payloadSize, p1) = readVarintFile(pos); pos = p1
    let (rowidU, p2) = readVarintFile(pos); pos = p2
    let rowid = Int64(bitPattern: rowidU)
    let ps = Int(payloadSize)

    let X = usableSize - 35
    let M = ((usableSize - 12) * 64 / 255) - 23

    var localSize: Int
    if ps <= X {
        localSize = ps
    } else {
        let K = M + ((ps - M) % (usableSize - 4))
        if K <= X {
            localSize = K
        } else {
            localSize = M
        }
    }

    var payload = [UInt8]()
    payload.reserveCapacity(ps)
    for i in 0..<localSize { payload.append(bytes[pos + i]) }

    if ps > X {
        pos += localSize
        let ovfPage = u32(pos)
        payload.append(contentsOf: readOverflow(ovfPage, ps - localSize))
    }

    return (rowid, payload)
}

// MARK: - B-tree walk (table b-trees only)

func walkBTree(_ pageNum: Int) -> [(Int64, [UInt8])] {
    var results = [(Int64, [UInt8])]()
    if pageNum <= 0 { return results }
    let (pt, nc, _, rm) = btreeHeader(pageNum)
    let base = pageOff(pageNum)

    if pt == 13 { // leaf table
        let ptrStart = base + (pageNum == 1 ? 100 + 8 : 8)
        for i in 0..<nc {
            let co = u16(ptrStart + i * 2)
            let (rowid, payload) = parseLeafCell(pageNum, co)
            results.append((rowid, payload))
        }
    } else if pt == 5 { // interior table
        let ptrStart = base + (pageNum == 1 ? 100 + 12 : 12)
        for i in 0..<nc {
            let co = u16(ptrStart + i * 2)
            let childPage = u32(base + co)
            results.append(contentsOf: walkBTree(childPage))
        }
        if rm != 0 { results.append(contentsOf: walkBTree(rm)) }
    }
    return results
}

// MARK: - Record parsing

func parseRecord(_ payload: [UInt8]) -> [(Int, [UInt8])] {
    if payload.isEmpty { return [] }
    var pos = 0
    let (hdrSize, p1) = readVarint(payload, pos); pos = p1
    var serialTypes = [Int]()
    while pos < Int(hdrSize) && pos < payload.count {
        let (st, np) = readVarint(payload, pos); pos = np
        serialTypes.append(Int(st))
    }
    var result = [(Int, [UInt8])]()
    for st in serialTypes {
        var d = [UInt8]()
        switch st {
        case 0: break
        case 1: if pos+1 <= payload.count { d = Array(payload[pos..<pos+1]) }; pos += 1
        case 2: if pos+2 <= payload.count { d = Array(payload[pos..<pos+2]) }; pos += 2
        case 3: if pos+3 <= payload.count { d = Array(payload[pos..<pos+3]) }; pos += 3
        case 4: if pos+4 <= payload.count { d = Array(payload[pos..<pos+4]) }; pos += 4
        case 5: if pos+6 <= payload.count { d = Array(payload[pos..<pos+6]) }; pos += 6
        case 6: if pos+8 <= payload.count { d = Array(payload[pos..<pos+8]) }; pos += 8
        case 7: if pos+8 <= payload.count { d = Array(payload[pos..<pos+8]) }; pos += 8
        case 8, 9: break
        default:
            if st >= 12 {
                let len = (st - 12) / 2
                if pos + len <= payload.count { d = Array(payload[pos..<pos+len]) }
                pos += len
            }
        }
        result.append((st, d))
    }
    return result
}

// MARK: - Signed integer extraction

func extractInt(_ st: Int, _ d: [UInt8]) -> Int64 {
    switch st {
    case 8: return 0
    case 9: return 1
    default: break
    }
    var v: Int64 = 0
    for b in d { v = (v << 8) | Int64(b) }
    let bits = d.count * 8
    if bits < 64 && !d.isEmpty && (d[0] & 0x80) != 0 { v -= (Int64(1) << bits) }
