// --- Compact JSON serializer for tool results ---
function serializeString(s: string): string {
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const cp = s.codePointAt(i)!;
    if (cp === 0x22) out += '\\"';
    else if (cp === 0x5C) out += '\\\\';
    else if (cp === 0x08) out += '\\b';
    else if (cp === 0x0C) out += '\\f';
    else if (cp === 0x0A) out += '\\n';
    else if (cp === 0x0D) out += '\\r';
    else if (cp === 0x09) out += '\\t';
    else if (cp < 0x20) out += '\\u' + cp.toString(16).padStart(4, '0');
    else {
      out += String.fromCodePoint(cp);
      if (cp > 0xFFFF) i++;
    }
  }
  return out + '"';
}

function serializeJSON(obj: any): string {
  if (obj === null) return 'null';
  if (typeof obj === 'number') return String(obj);
  if (typeof obj === 'boolean') return obj ? 'true' : 'false';
  if (typeof obj === 'string') return serializeString(obj);
  if (Array.isArray(obj)) {
    return '[' + obj.map(serializeJSON).join(',') + ']';
  }
  if (typeof obj === 'object') {
    const keys = Object.keys(obj);
    return '{' + keys.map(k => serializeString(k) + ':' + serializeJSON(obj[k])).join(',') + '}';
  }
  return 'null';
}

// --- HTTP request ---
function makeRequest(baseUrl: string, apiKey: string, body: object): Promise<{ status: number; body: any }> {
  return new Promise((resolve, reject) => {
    const url = new URL(baseUrl + '/chat/completions');
    const postData = JSON.stringify(body);
    const contentLength = Buffer.byteLength(postData, 'utf-8');

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: parseInt(url.port) || 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Authorization': 'Bearer ' + apiKey,
        'Content-Type': 'application/json',
        'Content-Length': String(contentLength),
        'Connection': 'close',
      },
    };

    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        const raw = Buffer.concat(chunks).toString('utf-8');
        let parsed: any;
        try {
          parsed = JSON.parse(raw);
        } catch (e) {
          parsed = null;
        }
        resolve({ status: res.statusCode || 0, body: parsed });
      });
    });

    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

