function executeTool(name: string, args: any, inventory: Map<string, string[]>, rates: { scale: number; rates: Record<string, number> }): string {
  if (name === 'inventory_lookup') {
    const sku: string = args.sku;
    const row = inventory.get(sku);
    if (!row) {
      return serializeJSON({ error: 'unknown sku: ' + sku });
    }
    return serializeJSON({
