    const from: string = args.from;
    const to: string = args.to;
    const rateFrom = BigInt(rates.rates[from]);
    const rateTo = BigInt(rates.rates[to]);
    const amount = BigInt(amountCents);
    // HALF_UP: (2 * amount * rateTo + rateFrom) / (2 * rateFrom)
    const numerator = 2n * amount * rateTo + rateFrom;
    const denominator = 2n * rateFrom;
    const converted = numerator / denominator;
    return serializeJSON({
      amount_cents: Number(converted),
      currency: to,
    });
  } else {
    return serializeJSON({ error: 'unknown tool: ' + name });
  }
}

