async function main() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    process.exit(1);
  }
  const dataDir = args[0];
  const baseUrl = args[1];

  // Read task.json
  const taskRaw = fs.readFileSync(path.join(dataDir, 'task.json'), 'utf-8');
  const task = JSON.parse(taskRaw);
  const apiKey: string = task.api_key;
  const model: string = task.model;
  const systemPrompt: string = task.system;
  const userPrompt: string = task.user;
  const tools: any[] = task.tools;

  // Read inventory.csv
  const csvRaw = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf-8');
  const csvRows = parseCSV(csvRaw);
  const inventory = new Map<string, string[]>();
  // Skip header row
  for (let r = 1; r < csvRows.length; r++) {
    const row = csvRows[r];
    if (row.length >= 5) {
      inventory.set(row[0], row);
    }
  }

  // Read rates.json
  const ratesRaw = fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf-8');
  const rates = JSON.parse(ratesRaw);

  // Conversation
  const messages: any[] = [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt },
  ];

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTotal = 0;
  let requestCount = 0;

  const outputLines: string[] = [];

  while (true) {
    const reqBody = {
      model: model,
      messages: messages,
      tools: tools,
      tool_choice: 'auto',
    };

    const resp = await makeRequest(baseUrl, apiKey, reqBody);
    requestCount++;

    if (resp.status !== 200) {
      // Error response
      for (const line of outputLines) {
        process.stdout.write(line + '\n');
      }
      const errMsg = resp.body && resp.body.error ? resp.body.error.message : '';
      process.stdout.write('ERROR ' + resp.status + ' ' + errMsg + '\n');
      process.exit(0);
    }

    const respBody = resp.body;

    // Accumulate usage
    if (respBody.usage) {
      totalPrompt += respBody.usage.prompt_tokens || 0;
      totalCompletion += respBody.usage.completion_tokens || 0;
      totalTotal += respBody.usage.total_tokens || 0;
    }

    const choice = respBody.choices[0];
    const finishReason: string = choice.finish_reason;
    const msg = choice.message;

    if (finishReason === 'tool_calls') {
      // Print SAY if content is a string
      if (typeof msg.content === 'string') {
        outputLines.push('SAY ' + msg.content);
      }

      // Build assistant message to append (keep role, content, tool_calls; drop refusal/annotations)
      const assistantMsg: any = {
        role: msg.role,
        content: msg.content !== undefined ? msg.content : null,
        tool_calls: msg.tool_calls,
      };
      messages.push(assistantMsg);

      // Execute tool calls
      const toolCalls = msg.tool_calls;
      for (const tc of toolCalls) {
        outputLines.push('CALL ' + tc.id + ' ' + tc.function.name);
      }

      for (const tc of toolCalls) {
        const parsedArgs = JSON.parse(tc.function.arguments);
        const result = executeTool(tc.function.name, parsedArgs, inventory, rates);
        outputLines.push('RESULT ' + tc.id + ' ' + result);
        messages.push({
          role: 'tool',
          tool_call_id: tc.id,
          content: result,
        });
      }
    } else {
      // finish_reason === 'stop'
      const finalContent: string = msg.content || '';
      outputLines.push('FINAL ' + finalContent);

      // Print all output
      for (const line of outputLines) {
        process.stdout.write(line + '\n');
      }
      process.stdout.write('USAGE prompt=' + totalPrompt + ' completion=' + totalCompletion + ' total=' + totalTotal + ' requests=' + requestCount + '\n');
      process.exit(0);
    }
  }
}

main().catch((e) => {
