// ─── HTTP ─────────────────────────────────────────────────────────────────────

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = if url.starts_with("http://") { &url[7..] } else { url };
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let hostport = &rest[..slash_pos];
    let path = if slash_pos < rest.len() { &rest[slash_pos..] } else { "/" };
    let (host, port) = if let Some(cp) = hostport.rfind(':') {
        (hostport[..cp].to_string(), hostport[cp+1..].parse::<u16>().unwrap_or(80))
    } else {
        (hostport.to_string(), 80)
    };
    (host, port, path.to_string())
}

fn read_all(mut stream: TcpStream) -> Vec<u8> {
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).unwrap();
    buf
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut p = 0;
    loop {
        // read hex size line
        let line_start = p;
        while p < data.len() && data[p] != b'\n' { p += 1; }
        if p >= data.len() { break; }
        p += 1; // skip LF
        let line = std::str::from_utf8(&data[line_start..p-1]).unwrap_or("").trim();
        // strip optional chunk extension
        let hex_str = if let Some(sc) = line.find(';') { &line[..sc] } else { line };
        let size = usize::from_str_radix(hex_str.trim(), 16).unwrap_or(0);
        if size == 0 { break; }
        // read size bytes
        if p + size <= data.len() {
            out.extend_from_slice(&data[p..p+size]);
            p += size;
        } else {
            out.extend_from_slice(&data[p..]);
            break;
        }
        // skip trailing CRLF
        if p < data.len() && data[p] == b'\r' { p += 1; }
        if p < data.len() && data[p] == b'\n' { p += 1; }
    }
    out
}

fn http_post(base_url: &str, body: &str, api_key: &str) -> (u16, Vec<u8>) {
    let (host, port, path) = parse_url(base_url);
    let endpoint = format!("{}{}", path, "/v1/messages");
    let body_bytes = body.as_bytes();
    let mut req = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n",
        endpoint, host, port, body_bytes.len(), api_key
    );
    req.push_str(body);

    let mut stream = TcpStream::connect((host.as_str(), port)).unwrap();
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let all = read_all(stream);

    // split headers and body
    let header_end = find_double_crlf(&all).unwrap_or(all.len());
    let header_str = std::str::from_utf8(&all[..header_end]).unwrap_or("");
    let body_bytes = if header_end < all.len() { &all[header_end+4..] } else { &[] };

    // parse status
    let first_line = header_str.lines().next().unwrap_or("");
    let status: u16 = first_line.split_whitespace().nth(1).unwrap_or("200").parse().unwrap_or(200);

    // check transfer-encoding
    let is_chunked = header_str.to_lowercase().contains("transfer-encoding: chunked");

    let decoded = if is_chunked {
        decode_chunked(body_bytes)
    } else {
        body_bytes.to_vec()
    };

    (status, decoded)
}

fn find_double_crlf(data: &[u8]) -> Option<usize> {
    for i in 0..data.len().saturating_sub(3) {
        if data[i] == b'\r' && data[i+1] == b'\n' && data[i+2] == b'\r' && data[i+3] == b'\n' {
            return Some(i);
        }
    }
    None
}

// ─── SSE Parsing ──────────────────────────────────────────────────────────────

struct SseEvent { event: String, data: String }

fn parse_sse(raw: &[u8]) -> Vec<SseEvent> {
    let text = String::from_utf8_lossy(raw);
    let mut events = Vec::new();
    let mut event_name = String::new();
    let mut data_lines: Vec<String> = Vec::new();
    let mut in_event = false;

    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        // read one line
        let line_start = i;
        while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
        let mut line_end = i;
        if i < bytes.len() { i += 1; } // skip LF
        // strip trailing CR
        if line_end > line_start && bytes[line_end - 1] == b'\r' { line_end -= 1; }
        let line = &text[line_start..line_end];

        if line.is_empty() {
            // blank line: end of event
            if in_event {
                events.push(SseEvent {
                    event: event_name.clone(),
                    data: data_lines.join("\n"),
                });
            }
            event_name.clear();
            data_lines.clear();
            in_event = false;
            continue;
        }

        if line.starts_with(':') { continue; } // comment

        if let Some(rest) = line.strip_prefix("event:") {
            event_name = rest.trim_start().to_string();
            in_event = true;
        } else if let Some(rest) = line.strip_prefix("data:") {
            let val = if rest.starts_with(' ') { &rest[1..] } else { rest };
            data_lines.push(val.to_string());
            in_event = true;
        }
    }
    // handle trailing event without blank line
    if in_event && !data_lines.is_empty() {
        events.push(SseEvent { event: event_name, data: data_lines.join("\n") });
    }
    events
}

