        let line_start = p;
        while p < data.len() && data[p] != b'\n' { p += 1; }
        if p >= data.len() { break; }
        p += 1;
        let line = std::str::from_utf8(&data[line_start..p-1]).unwrap_or("").trim();
        let hex_str = if let Some(sc) = line.find(';') { &line[..sc] } else { line };
        let size = usize::from_str_radix(hex_str.trim(), 16).unwrap_or(0);
        if size == 0 { break; }
        if p + size <= data.len() {
            out.extend_from_slice(&data[p..p+size]);
            p += size;
        } else {
            out.extend_from_slice(&data[p..]);
            break;
        }
        if p < data.len() && data[p] == b'\r' { p += 1; }
        if p < data.len() && data[p] == b'\n' { p += 1; }
    }
    out
}

fn http_post(base_url: &str, body: &str, api_key: &str) -> (u16, Vec<u8>) {
    let (host, port, path) = parse_url(base_url);
    let endpoint = format!("{}{}", path, "/v1/messages");
    let body_bytes = body.as_bytes();
    let mut req = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n",
        endpoint, host, port, body_bytes.len(), api_key
    );
    req.push_str(body);

    let mut stream = TcpStream::connect((host.as_str(), port)).unwrap();
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let all = read_all(stream);

    let header_end = find_double_crlf(&all).unwrap_or(all.len());
    let header_str = std::str::from_utf8(&all[..header_end]).unwrap_or("");
    let body_bytes = if header_end < all.len() { &all[header_end+4..] } else { &[] };

    let first_line = header_str.lines().next().unwrap_or("");
    let status: u16 = first_line.split_whitespace().nth(1).unwrap_or("200").parse().unwrap_or(200);

    let is_chunked = header_str.to_lowercase().contains("transfer-encoding: chunked");

    let decoded = if is_chunked {
        decode_chunked(body_bytes)
    } else {
        body_bytes.to_vec()
    };

    (status, decoded)
}

fn find_double_crlf(data: &[u8]) -> Option<usize> {
    for i in 0..data.len().saturating_sub(3) {
        if data[i] == b'\r' && data[i+1] == b'\n' && data[i+2] == b'\r' && data[i+3] == b'\n' {
            return Some(i);
        }
    }
    None
}

// ─── SSE Parsing ──────────────────────────────────────────────────────────────

struct SseEvent { event: String, data: String }

fn parse_sse(raw: &[u8]) -> Vec<SseEvent> {
    let text = String::from_utf8_lossy(raw);
    let mut events = Vec::new();
    let mut event_name = String::new();
    let mut data_lines: Vec<String> = Vec::new();
    let mut in_event = false;

    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let line_start = i;
        while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
        let mut line_end = i;
        if i < bytes.len() { i += 1; }
        if line_end > line_start && bytes[line_end - 1] == b'\r' { line_end -= 1; }
        let line = &text[line_start..line_end];

        if line.is_empty() {
            if in_event {
                events.push(SseEvent {
                    event: event_name.clone(),
                    data: data_lines.join("\n"),
                });
            }
            event_name.clear();
            data_lines.clear();
            in_event = false;
            continue;
        }

        if line.starts_with(':') { continue; }

        if let Some(rest) = line.strip_prefix("event:") {
            event_name = rest.trim_start().to_string();
            in_event = true;
        } else if let Some(rest) = line.strip_prefix("data:") {
            let val = if rest.starts_with(' ') { &rest[1..] } else { rest };
            data_lines.push(val.to_string());
            in_event = true;
        }
    }
    if in_event && !data_lines.is_empty() {
        events.push(SseEvent { event: event_name, data: data_lines.join("\n") });
    }
    events
}

// ─── Process SSE into blocks ──────────────────────────────────────────────────

struct ReplyInfo {
    blocks: Vec<CBlock>,
    stop_reason: String,
    input_tokens: i64,
    output_tokens: i64,
    cache_read: i64,
}

fn process_sse(raw: &[u8]) -> ReplyInfo {
    let events = parse_sse(raw);
    let mut blocks: Vec<Option<CBlock>> = Vec::new();
    let mut stop_reason = String::new();
    let mut input_tokens = 0i64;
    let mut output_tokens = 0i64;
    let mut cache_read = 0i64;

    for ev in &events {
        if ev.event == "ping" || ev.data.is_empty() { continue; }
        let mut jp = JP::new(&ev.data);
        let val = jp.parse();

        match ev.event.as_str() {
            "message_start" => {
                if let Some(msg) = val.get("message") {
                    if let Some(usage) = msg.get("usage") {
                        input_tokens += usage.get("input_tokens").map(|v| v.as_num() as i64).unwrap_or(0);
                        cache_read += usage.get("cache_read_input_tokens").map(|v| v.as_num() as i64).unwrap_or(0);
                    }
                }
            }
            "content_block_start" => {
                let idx = val.get("index").map(|v| v.as_num() as usize).unwrap_or(0);
                let cb = val.get("content_block").unwrap();
                let btype = cb.get("type").map(|v| v.as_str().to_string()).unwrap_or_default();
                let block = CBlock {
                    btype: btype.clone(),
                    thinking: String::new(),
                    signature: String::new(),
                    text: String::new(),
                    tool_id: cb.get("id").map(|v| v.as_str().to_string()).unwrap_or_default(),
                    tool_name: cb.get("name").map(|v| v.as_str().to_string()).unwrap_or_default(),
                    raw_input: String::new(),
                };
                while blocks.len() <= idx { blocks.push(None); }
                blocks[idx] = Some(block);
            }
            "content_block_delta" => {
                let idx = val.get("index").map(|v| v.as_num() as usize).unwrap_or(0);
                let delta = val.get("delta").unwrap();
                let dtype = delta.get("type").map(|v| v.as_str()).unwrap_or("");
                if let Some(Some(block)) = blocks.get_mut(idx) {
                    match dtype {
                        "thinking_delta" => block.thinking.push_str(delta.get("thinking").map(|v| v.as_str()).unwrap_or("")),
                        "signature_delta" => block.signature.push_str(delta.get("signature").map(|v| v.as_str()).unwrap_or("")),
                        "text_delta" => block.text.push_str(delta.get("text").map(|v| v.as_str()).unwrap_or("")),
                        "input_json_delta" => block.raw_input.push_str(delta.get("partial_json").map(|v| v.as_str()).unwrap_or("")),
                        _ => {}
                    }
                }
            }
            "content_block_stop" => {}
            "message_delta" => {
                if let Some(delta) = val.get("delta") {
                    if let Some(sr) = delta.get("stop_reason") {
                        stop_reason = sr.as_str().to_string();
                    }
                }
                if let Some(usage) = val.get("usage") {
                    output_tokens += usage.get("output_tokens").map(|v| v.as_num() as i64).unwrap_or(0);
                }
            }
            "message_stop" => {}
            _ => {}
        }
    }

    let blocks = blocks.into_iter().filter_map(|b| b).collect();
    ReplyInfo { blocks, stop_reason, input_tokens, output_tokens, cache_read }
}

// ─── Tool Execution ───────────────────────────────────────────────────────────

fn run_tool(name: &str, input_json: &str) -> (String, bool) {
    let mut jp = JP::new(input_json);
    let input = jp.parse();

    match name {
        "measure" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let unit = input.get("unit").map(|v| v.as_str().to_string()).unwrap_or_default();
            match unit.as_str() {
                "code_points" => (text.chars().count().to_string(), false),
                "utf8_bytes" => (text.len().to_string(), false),
                "utf16_units" => {
                    let count: usize = text.chars().map(|c| if (c as u32) > 0xFFFF { 2 } else { 1 }).sum();
                    (count.to_string(), false)
                }
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let reversed: String = text.chars().rev().collect();
            (reversed, false)
        }
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ─── Build Request Body ───────────────────────────────────────────────────────

fn build_request_body(model: &str, max_tokens: f64, thinking_budget: f64, system: &str, tools_json: &str, messages: &JVal) -> String {
    let mut body = String::new();
    body.push('{');
    body.push_str("\"model\":");
    body.push('"'); body.push_str(&json_escape(model)); body.push('"');
    body.push_str(",\"max_tokens\":");
    body.push_str(&format!("{}", max_tokens as i64));
    body.push_str(",\"stream\":true");
    body.push_str(",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    body.push_str(&format!("{}", thinking_budget as i64));
    body.push('}');
    body.push_str(",\"system\":");
    body.push('"'); body.push_str(&json_escape(system)); body.push('"');
    body.push_str(",\"tools\":");
    body.push_str(tools_json);
    body.push_str(",\"messages\":");
    ser_json(messages, &mut body);
    body.push('}');
    body
}

// ─── Print blocks ─────────────────────────────────────────────────────────────

fn print_blocks(blocks: &[CBlock]) {
    for b in blocks {
        match b.btype.as_str() {
            "thinking" => {
                println!("thinking {}", esc_out(&b.thinking));
                println!("signature {}", esc_out(&b.signature));
            }
            "text" => {
                println!("text {}", esc_out(&b.text));
            }
            "tool_use" => {
                println!("tool_use {} {} {}", esc_out(&b.tool_id), esc_out(&b.tool_name), esc_out(&b.raw_input));
            }
            _ => {}
        }
    }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        eprintln!("usage: main <data_dir> <base_url>");
        process::exit(1);
    }
    let data_dir = &args[1];
    let base_url = args[2].trim_end_matches('/');

    // Read request.json
    let req_path = format!("{}/request.json", data_dir);
    let req_content = std::fs::read_to_string(&req_path).unwrap();
    let mut jp = JP::new(&req_content);
    let req_json = jp.parse();

    let api_key = req_json.get("api_key").unwrap().as_str().to_string();
    let model = req_json.get("model").unwrap().as_str().to_string();
    let max_tokens = req_json.get("max_tokens").unwrap().as_num();
    let thinking_budget = req_json.get("thinking_budget").unwrap().as_num();
    let system = req_json.get("system").unwrap().as_str().to_string();
    let prompt = req_json.get("prompt").unwrap().as_str().to_string();

    // Serialize tools back to JSON
    let tools_val = req_json.get("tools").unwrap();
    let mut tools_str = String::new();
    ser_json(tools_val, &mut tools_str);

    // Build request 1
    let messages1 = JVal::Arr(vec![
        JVal::Obj(vec![
            ("role".to_string(), JVal::Str("user".to_string())),
            ("content".to_string(), JVal::Str(prompt.clone())),
        ])
    ]);
    let body1 = build_request_body(&model, max_tokens, thinking_budget, &system, &tools_str, &messages1);

    // Send request 1
    let (status1, body1_resp) = http_post(base_url, &body1, &api_key);

    if status1 != 200 {
        let mut jp2 = JP::new(std::str::from_utf8(&body1_resp).unwrap_or("{}"));
        let err_val = jp2.parse();
        let etype = err_val.get("error").and_then(|e| e.get("type")).map(|v| v.as_str()).unwrap_or("unknown");
        let emsg = err_val.get("error").and_then(|e| e.get("message")).map(|v| v.as_str()).unwrap_or("");
        println!("request 1");
        println!("ERROR {} {}: {}", status1, etype, emsg);
        process::exit(0);
    }

    // Process response 1
    let reply1 = process_sse(&body1_resp);

    // Print request 1
    println!("request 1");
    print_blocks(&reply1.blocks);
    println!("stop_reason {}", reply1.stop_reason);

    // Execute tools
    let mut tool_results: Vec<(String, String, bool)> = Vec::new();
    for b in &reply1.blocks {
        if b.btype == "tool_use" {
            let (result, is_err) = run_tool(&b.tool_name, &b.raw_input);
            tool_results.push((b.tool_id.clone(), result, is_err));
        }
    }

    // Print tool results
    for (id, result, is_err) in &tool_results {
        if *is_err {
            println!("error {} {}", esc_out(id), esc_out(result));
        } else {
            println!("result {} {}", esc_out(id), esc_out(result));
        }
    }

    // Build request 2
    let mut assistant_content: Vec<JVal> = Vec::new();
    for b in &reply1.blocks {
        match b.btype.as_str() {
            "thinking" => {
                assistant_content.push(JVal::Obj(vec![
                    ("type".to_string(), JVal::Str("thinking".to_string())),
                    ("thinking".to_string(), JVal::Str(b.thinking.clone())),
                    ("signature".to_string(), JVal::Str(b.signature.clone())),
                ]));
            }
            "text" => {
                assistant_content.push(JVal::Obj(vec![
                    ("type".to_string(), JVal::Str("text".to_string())),
                    ("text".to_string(), JVal::Str(b.text.clone())),
                ]));
            }
            "tool_use" => {
                let mut jp3 = JP::new(&b.raw_input);
                let input_val = jp3.parse();
                assistant_content.push(JVal::Obj(vec![
                    ("type".to_string(), JVal::Str("tool_use".to_string())),
                    ("id".to_string(), JVal::Str(b.tool_id.clone())),
                    ("name".to_string(), JVal::Str(b.tool_name.clone())),
                    ("input".to_string(), input_val),
                ]));
            }
            _ => {}
        }
    }

    let mut tool_result_content: Vec<JVal> = Vec::new();
    for (id, result, is_err) in &tool_results {
        let mut block = vec![
            ("type".to_string(), JVal::Str("tool_result".to_string())),
            ("tool_use_id".to_string(), JVal::Str(id.clone())),
            ("content".to_string(), JVal::Str(result.clone())),
        ];
        if *is_err {
            block.push(("is_error".to_string(), JVal::Bool(true)));
        }
        tool_result_content.push(JVal::Obj(block));
    }

    let messages2 = JVal::Arr(vec![
        JVal::Obj(vec![
            ("role".to_string(), JVal::Str("user".to_string())),
            ("content".to_string(), JVal::Str(prompt.clone())),
        ]),
        JVal::Obj(vec![
            ("role".to_string(), JVal::Str("assistant".to_string())),
            ("content".to_string(), JVal::Arr(assistant_content)),
        ]),
        JVal::Obj(vec![
            ("role".to_string(), JVal::Str("user".to_string())),
            ("content".to_string(), JVal::Arr(tool_result_content)),
        ]),
    ]);

    let body2 = build_request_body(&model, max_tokens, thinking_budget, &system, &tools_str, &messages2);

    // Send request 2
    let (status2, body2_resp) = http_post(base_url, &body2, &api_key);

    if status2 != 200 {
        let mut jp2 = JP::new(std::str::from_utf8(&body2_resp).unwrap_or("{}"));
        let err_val = jp2.parse();
        let etype = err_val.get("error").and_then(|e| e.get("type")).map(|v| v.as_str()).unwrap_or("unknown");
        let emsg = err_val.get("error").and_then(|e| e.get("message")).map(|v| v.as_str()).unwrap_or("");
        println!("request 2");
        println!("ERROR {} {}: {}", status2, etype, emsg);
        process::exit(0);
    }

    // Process response 2
    let reply2 = process_sse(&body2_resp);

    // Print request 2
    println!("request 2");
    print_blocks(&reply2.blocks);
    println!("stop_reason {}", reply2.stop_reason);

    // Usage
    let total_input = reply1.input_tokens + reply2.input_tokens;
    let total_output = reply1.output_tokens + reply2.output_tokens;
    let total_cache = reply1.cache_read + reply2.cache_read;
    println!("usage input={} output={} cache_read={}", total_input, total_output, total_cache);
}
