    static List<Row> readBTree(int pageNum, boolean isPage1) {
        List<Row> rows = new ArrayList<>();
        int pageBase = (pageNum - 1) * pageSize;
        int hdrOff = isPage1 ? 100 : 0;

        int pageType = data[pageBase + hdrOff] & 0xFF;
        int numCells = ((data[pageBase + hdrOff + 3] & 0xFF) << 8) | (data[pageBase + hdrOff + 4] & 0xFF);

