                rows.add(readLeafCell(cellOff));
            }
        } else if (pageType == 5) {
            int ptrStart = pageBase + hdrOff + 12;
            for (int i = 0; i < numCells; i++) {
                int cellOff = pageBase + (((data[ptrStart + i * 2] & 0xFF) << 8) | (data[ptrStart + i * 2 + 1] & 0xFF));
                int childPage = readInt32BE(cellOff);
                rows.addAll(readBTree(childPage, false));
