        int embedded;
        int overflowPage = 0;

        if (payloadSize <= M) {
            embedded = payloadSize;
        } else {
            long K = X + ((payloadSize - X) % (usableSize - 4));
            if (K >= payloadSize) {
                embedded = payloadSize;
            } else {
                embedded = (int) K;
                overflowPage = readInt32BE(pos + embedded);
