        long M = ((long) (usableSize - 12) * 64) / 255 - 23;

        int embedded;
        int overflowPage = 0;

        if (payloadSize <= M) {
            embedded = payloadSize;
        } else {
            long K = X + ((payloadSize - X) % (usableSize - 4));
            if (K >= payloadSize) {
