        if (overflowPage != 0) {
            int remaining = payloadSize - embedded;
            int op = overflowPage;
            int dest = embedded;
            while (remaining > 0 && op != 0) {
                int opBase = (op - 1) * pageSize;
                int chunk = Math.min(remaining, usableSize - 4);
                System.arraycopy(data, opBase + 4, payload, dest, chunk);
