    static int[] readVarint(byte[] buf, int pos) {
        int value = 0;
        for (int i = 0; i < 8; i++) {
            int b = buf[pos + i] & 0xFF;
            value = (value << 7) | (b & 0x7F);
            if ((b & 0x80) == 0) {
                return new int[]{value, pos + i + 1};
            }
        }
        value = (value << 8) | (buf[pos + 8] & 0xFF);
        return new int[]{value, pos + 9};
    }

    static long[] readVarint64(byte[] buf, int pos) {
        long value = 0;
        for (int i = 0; i < 8; i++) {
            int b = buf[pos + i] & 0xFF;
            value = (value << 7) | (b & 0x7F);
            if ((b & 0x80) == 0) {
                return new long[]{value, pos + i + 1};
            }
        }
        value = (value << 8) | (buf[pos + 8] & 0xFF);
        return new long[]{value, pos + 9};
