        StringBuilder cur = new StringBuilder();
        while (pos < sql.length()) {
            char c = sql.charAt(pos);
            if (c == '(') { depth++; cur.append(c); }
            else if (c == ')') {
                if (depth == 0) break;
                depth--; cur.append(c);
            } else if (c == ',' && depth == 0) {
