/* ===== JSON Serializer ===== */
static void enc_str(sbuf*sb,const char*s){
    sb_c(sb,'"');
    for(const unsigned char*p=(const unsigned char*)s;*p;p++){
        unsigned char c=*p;
        if(c=='"')sb_s(sb,"\\\"",2);
