static void ser_json(sbuf*sb,jval*v){
    if(!v){sb_str(sb,"null");return;}
    switch(v->type){
        case JNUL:sb_str(sb,"null");break;
        case JBOOL:sb_str(sb,v->bval?"true":"false");break;
        case JNUM:{long long ll=(long long)v->dval;if((double)ll==v->dval)sb_int(sb,ll);else{char t[64];snprintf(t,64,"%.17g",v->dval);sb_str(sb,t);}break;}
        case JSTR:enc_str(sb,v->sval);break;
        case JARR:sb_c(sb,'[');for(int i=0;i<v->arr.count;i++){if(i)sb_c(sb,',');ser_json(sb,v->arr.items[i]);}sb_c(sb,']');break;
