/* ===== CSV Parser ===== */
typedef struct{char*sku;char*name;long long price_cents;char*currency;long long stock;}inv_row;
static inv_row*inventory=NULL;static int inv_count=0;

static void parse_csv(const char*data,size_t len){
    const char*p=data,*end=data+len;
    /* skip BOM */
    if(len>=3&&(unsigned char)p[0]==0xEF&&(unsigned char)p[1]==0xBB&&(unsigned char)p[2]==0xBF)p+=3;
    /* skip header line */
    while(p<end&&!(p[0]=='\r'&&p+1<end&&p[1]=='\n'))p++;
    if(p<end)p+=2;
    int cap=64;inventory=malloc(cap*sizeof(inv_row));
    while(p<end){
        inv_row row={0};
        for(int fi=0;fi<5;fi++){
            sbuf fs;sb_init(&fs);
            if(p<end&&*p=='"'){
                p++;
                while(p<end){
                    if(*p=='"'){
                        if(p+1<end&&p[1]=='"'){sb_c(&fs,'"');p+=2;}
                        else{p++;break;}
                    }else{sb_c(&fs,*p);p++;}
                }
            }else{
                while(p<end&&*p!=','&&!(p[0]=='\r'&&p+1<end&&p[1]=='\n')){sb_c(&fs,*p);p++;}
            }
            char*val=fs.buf;
            if(fi==0)row.sku=val;
            else if(fi==1)row.name=val;
            else if(fi==2)row.price_cents=atoll(val);
            else if(fi==3)row.currency=val;
            else if(fi==4)row.stock=atoll(val);
            if(fi<4){if(p<end&&*p==',')p++;}
        }
        if(p<end&&p[0]=='\r'&&p+1<end&&p[1]=='\n')p+=2;
        else if(p<end&&p[0]=='\n')p+=1;
        if(inv_count>=cap){cap*=2;inventory=realloc(inventory,cap*sizeof(inv_row));}
        inventory[inv_count++]=row;
    }
}

