static void sb_ens(sbuf *s,size_t n){if(s->len+n+1>s->cap){while(s->len+n+1>s->cap)s->cap*=2;s->buf=realloc(s->buf,s->cap);}}
static void sb_c(sbuf *s,char c){sb_ens(s,1);s->buf[s->len++]=c;s->buf[s->len]=0;}
static void sb_s(sbuf *s,const char*p,size_t n){sb_ens(s,n);memcpy(s->buf+s->len,p,n);s->len+=n;s->buf[s->len]=0;}
static void sb_str(sbuf *s,const char*p){sb_s(s,p,strlen(p));}
static void sb_int(sbuf *s,long long v){char t[32];int n=snprintf(t,sizeof(t),"%lld",v);sb_s(s,t,(size_t)n);}
static void sb_free(sbuf *s){free(s->buf);}

/* ===== JSON Value ===== */
#define JNUL 0
#define JBOOL 1
#define JNUM 2
#define JSTR 3
#define JARR 4
#define JOBJ 5
typedef struct jval jval;
struct jval{int type;union{int bval;double dval;long long ival;char*sval;struct{jval**items;int count;}arr;struct{char**keys;jval**vals;int count;}obj;};};

static const char*skipws(const char*p){while(*p==' '||*p=='\t'||*p=='\n'||*p=='\r')p++;return p;}

static jval*parse_val(const char**pp);

static jval*parse_str(const char**pp){
    (*pp)++;sbuf sb;sb_init(&sb);
    while(**pp!='"'){
        if(**pp=='\\'){
            (*pp)++;
            char c=**pp;
            if(c=='"')sb_c(&sb,'"');
            else if(c=='\\')sb_c(&sb,'\\');
            else if(c=='/')sb_c(&sb,'/');
            else if(c=='b')sb_c(&sb,'\b');
            else if(c=='f')sb_c(&sb,'\f');
            else if(c=='n')sb_c(&sb,'\n');
            else if(c=='r')sb_c(&sb,'\r');
            else if(c=='t')sb_c(&sb,'\t');
            else if(c=='u'){
                (*pp)++;unsigned cp=0;
                for(int i=0;i<4;i++){cp<<=4;char h=**pp;cp+=(h<='9')?(h-'0'):((h|32)-'a'+10);(*pp)++;}
                if(cp>=0xD800&&cp<=0xDBFF){
                    if(**pp=='\\'&&*(*pp+1)=='u'){
                        (*pp)+=2;unsigned lo=0;
                        for(int i=0;i<4;i++){lo<<=4;char h=**pp;lo+=(h<='9')?(h-'0'):((h|32)-'a'+10);(*pp)++;}
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                }
                if(cp<0x80)sb_c(&sb,(char)cp);
                else if(cp<0x800){sb_c(&sb,(char)(0xC0|(cp>>6)));sb_c(&sb,(char)(0x80|(cp&0x3F)));}
                else if(cp<0x10000){sb_c(&sb,(char)(0xE0|(cp>>12)));sb_c(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_c(&sb,(char)(0x80|(cp&0x3F)));}
                else{sb_c(&sb,(char)(0xF0|(cp>>18)));sb_c(&sb,(char)(0x80|((cp>>12)&0x3F)));sb_c(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_c(&sb,(char)(0x80|(cp&0x3F)));}
                continue;
            }
            else sb_c(&sb,c);
        }else sb_c(&sb,**pp);
        (*pp)++;
    }
    (*pp)++;
    jval*v=malloc(sizeof(jval));v->type=JSTR;v->sval=sb.buf;return v;
}

static jval*parse_num(const char**pp){
    const char*st=*pp;char*end;double d=strtod(st,&end);*pp=end;
    jval*v=malloc(sizeof(jval));v->type=JNUM;v->dval=d;v->ival=(long long)d;return v;
}

static jval*parse_obj(const char**pp){
    (*pp)++;char**ks=NULL;jval**vs=NULL;int cnt=0,cap=8;
    ks=malloc(cap*sizeof(char*));vs=malloc(cap*sizeof(jval*));
    *pp=skipws(*pp);
    if(**pp=='}')(*pp)++;
    else{for(;;){
        *pp=skipws(*pp);jval*k=parse_str(pp);
        *pp=skipws(*pp);(*pp)++;*pp=skipws(*pp);jval*val=parse_val(pp);
        if(cnt>=cap){cap*=2;ks=realloc(ks,cap*sizeof(char*));vs=realloc(vs,cap*sizeof(jval*));}
        ks[cnt]=k->sval;free(k);vs[cnt]=val;cnt++;
        *pp=skipws(*pp);
        if(**pp==','){(*pp)++;continue;}
        if(**pp=='}'){(*pp)++;break;}
        break;
    }}
    jval*v=malloc(sizeof(jval));v->type=JOBJ;v->obj.keys=ks;v->obj.vals=vs;v->obj.count=cnt;return v;
}

static jval*parse_arr(const char**pp){
    (*pp)++;jval**items=NULL;int cnt=0,cap=8;items=malloc(cap*sizeof(jval*));
    *pp=skipws(*pp);
    if(**pp==']')(*pp)++;
    else{for(;;){
        *pp=skipws(*pp);jval*it=parse_val(pp);
        if(cnt>=cap){cap*=2;items=realloc(items,cap*sizeof(jval*));}
        items[cnt++]=it;
        *pp=skipws(*pp);
        if(**pp==','){(*pp)++;continue;}
        if(**pp==']'){(*pp)++;break;}
        break;
    }}
    jval*v=malloc(sizeof(jval));v->type=JARR;v->arr.items=items;v->arr.count=cnt;return v;
}

static jval*parse_val(const char**pp){
    *pp=skipws(*pp);char c=**pp;
    if(c=='"')return parse_str(pp);
    if(c=='{')return parse_obj(pp);
    if(c=='[')return parse_arr(pp);
    if(c=='t'){*pp+=4;jval*v=malloc(sizeof(jval));v->type=JBOOL;v->bval=1;return v;}
    if(c=='f'){*pp+=5;jval*v=malloc(sizeof(jval));v->type=JBOOL;v->bval=0;return v;}
    if(c=='n'){*pp+=4;jval*v=malloc(sizeof(jval));v->type=JNUL;return v;}
    return parse_num(pp);
}

static jval*jobj_get(jval*o,const char*k){
    if(!o||o->type!=JOBJ)return NULL;
    for(int i=0;i<o->obj.count;i++)if(strcmp(o->obj.keys[i],k)==0)return o->obj.vals[i];
    return NULL;
}
static const char*jstr(jval*v){return(v&&v->type==JSTR)?v->sval:NULL;}
static long long jint(jval*v){return(v&&v->type==JNUM)?v->ival:0;}

/* ===== JSON Serializer ===== */
static void enc_str(sbuf*sb,const char*s){
    sb_c(sb,'"');
    for(const unsigned char*p=(const unsigned char*)s;*p;p++){
        unsigned char c=*p;
        if(c=='"')sb_s(sb,"\\\"",2);
        else if(c=='\\')sb_s(sb,"\\\\",2);
        else if(c=='\b')sb_s(sb,"\\b",2);
        else if(c=='\f')sb_s(sb,"\\f",2);
        else if(c=='\n')sb_s(sb,"\\n",2);
        else if(c=='\r')sb_s(sb,"\\r",2);
        else if(c=='\t')sb_s(sb,"\\t",2);
        else if(c<0x20){char t[8];snprintf(t,8,"\\u%04x",c);sb_s(sb,t,6);}
        else sb_c(sb,(char)c);
    }
    sb_c(sb,'"');
}

static void ser_json(sbuf*sb,jval*v){
    if(!v){sb_str(sb,"null");return;}
    switch(v->type){
        case JNUL:sb_str(sb,"null");break;
        case JBOOL:sb_str(sb,v->bval?"true":"false");break;
        case JNUM:{long long ll=(long long)v->dval;if((double)ll==v->dval)sb_int(sb,ll);else{char t[64];snprintf(t,64,"%.17g",v->dval);sb_str(sb,t);}break;}
        case JSTR:enc_str(sb,v->sval);break;
        case JARR:sb_c(sb,'[');for(int i=0;i<v->arr.count;i++){if(i)sb_c(sb,',');ser_json(sb,v->arr.items[i]);}sb_c(sb,']');break;
        case JOBJ:sb_c(sb,'{');for(int i=0;i<v->obj.count;i++){if(i)sb_c(sb,',');enc_str(sb,v->obj.keys[i]);sb_c(sb,':');ser_json(sb,v->obj.vals[i]);}sb_c(sb,'}');break;
    }
}

/* ===== File Reading ===== */
static char*read_file(const char*path,size_t*len){
    FILE*f=fopen(path,"rb");if(!f)return NULL;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    char*buf=malloc(sz+1);size_t r=fread(buf,1,sz,f);buf[r]=0;fclose(f);
    if(len)*len=r;return buf;
}

/* ===== CSV Parser ===== */
typedef struct{char*sku;char*name;long long price_cents;char*currency;long long stock;}inv_row;
static inv_row*inventory=NULL;static int inv_count=0;

static void parse_csv(const char*data,size_t len){
    const char*p=data,*end=data+len;
    /* skip BOM */
    if(len>=3&&(unsigned char)p[0]==0xEF&&(unsigned char)p[1]==0xBB&&(unsigned char)p[2]==0xBF)p+=3;
    /* skip header line */
    while(p<end&&!(p[0]=='\r'&&p+1<end&&p[1]=='\n'))p++;
    if(p<end)p+=2;
    int cap=64;inventory=malloc(cap*sizeof(inv_row));
    while(p<end){
        inv_row row={0};
        for(int fi=0;fi<5;fi++){
            sbuf fs;sb_init(&fs);
            if(p<end&&*p=='"'){
                p++;
                while(p<end){
                    if(*p=='"'){
                        if(p+1<end&&p[1]=='"'){sb_c(&fs,'"');p+=2;}
                        else{p++;break;}
                    }else{sb_c(&fs,*p);p++;}
                }
            }else{
                while(p<end&&*p!=','&&!(p[0]=='\r'&&p+1<end&&p[1]=='\n')){sb_c(&fs,*p);p++;}
            }
            char*val=fs.buf;
            if(fi==0)row.sku=val;
            else if(fi==1)row.name=val;
            else if(fi==2)row.price_cents=atoll(val);
            else if(fi==3)row.currency=val;
            else if(fi==4)row.stock=atoll(val);
            if(fi<4){if(p<end&&*p==',')p++;}
        }
        if(p<end&&p[0]=='\r'&&p+1<end&&p[1]=='\n')p+=2;
        else if(p<end&&p[0]=='\n')p+=1;
        if(inv_count>=cap){cap*=2;inventory=realloc(inventory,cap*sizeof(inv_row));}
        inventory[inv_count++]=row;
    }
}

/* ===== Rates ===== */
typedef struct{char*code;long long rate;}rate_entry;
static rate_entry*rates=NULL;static int rate_count=0;

static long long get_rate(const char*code){
    for(int i=0;i<rate_count;i++)if(strcmp(rates[i].code,code)==0)return rates[i].rate;
    return 1000000;
}

/* ===== HTTP Client ===== */
typedef struct{int status;char*body;}http_resp;

static http_resp http_post(const char*url,const char*auth,const char*body){
    http_resp r={0,NULL};
    const char*p=url;
    if(strncmp(p,"http://",7)==0)p+=7;
    const char*slash=strchr(p,'/');
    char host[256]={0};int port=80;
    if(slash){
        size_t hlen=(size_t)(slash-p);
        const char*colon=memchr(p,':',hlen);
        if(colon){size_t hl=(size_t)(colon-p);memcpy(host,p,hl);host[hl]=0;port=atoi(colon+1);}
        else{memcpy(host,p,hlen);host[hlen]=0;}
    }else{
        const char*colon=strchr(p,':');
        if(colon){size_t hl=(size_t)(colon-p);memcpy(host,p,hl);host[hl]=0;port=atoi(colon+1);}
        else{strcpy(host,p);}
    }
    char path[512]={0};
    if(slash)snprintf(path,sizeof(path),"%s/chat/completions",slash);
    else snprintf(path,sizeof(path),"/chat/completions");

    int sock=socket(AF_INET,SOCK_STREAM,0);
    struct sockaddr_in addr={0};
    addr.sin_family=AF_INET;addr.sin_port=htons((unsigned short)port);
    inet_pton(AF_INET,host,&addr.sin_addr);
    if(connect(sock,(struct sockaddr*)&addr,sizeof(addr))<0){r.status=-1;close(sock);return r;}

    sbuf req;sb_init(&req);
    sb_str(&req,"POST ");sb_str(&req,path);sb_str(&req," HTTP/1.1\r\n");
    sb_str(&req,"Host: ");sb_str(&req,host);sb_c(&req,':');sb_int(&req,(long long)port);sb_str(&req,"\r\n");
    sb_str(&req,"Authorization: Bearer ");sb_str(&req,auth);sb_str(&req,"\r\n");
    sb_str(&req,"Content-Type: application/json\r\n");
    sb_str(&req,"Content-Length: ");sb_int(&req,(long long)strlen(body));sb_str(&req,"\r\n");
    sb_str(&req,"\r\n");
    sb_str(&req,body);

    size_t sent=0,total=req.len;
    while(sent<total){ssize_t w=write(sock,req.buf+sent,total-sent);if(w<=0)break;sent+=(size_t)w;}
    sb_free(&req);

    sbuf resp;sb_init(&resp);
    char tmp[8192];ssize_t n;
    while((n=read(sock,tmp,sizeof(tmp)))>0)sb_s(&resp,tmp,(size_t)n);
    close(sock);

    /* parse status line */
    resp.buf[resp.len]=0;
    if(strncmp(resp.buf,"HTTP/1.1 ",9)==0||strncmp(resp.buf,"HTTP/1.0 ",9)==0){
        r.status=atoi(resp.buf+9);
    }else r.status=-1;

    /* find body after \r\n\r\n */
    char*hdr_end=strstr(resp.buf,"\r\n\r\n");
    if(hdr_end)r.body=strdup(hdr_end+4);
    else r.body=strdup("");
    sb_free(&resp);
    return r;
}

/* ===== Conversation Messages ===== */
typedef struct{char*id;char*name;char*arguments;}tc_t;
typedef struct{char*role;char*content;tc_t*tcs;int n_tc;char*tc_id;}msg_t;

static msg_t*conv=NULL;static int conv_count=0,conv_cap=0;
static void conv_add(msg_t m){
    if(conv_count>=conv_cap){conv_cap=conv_cap?conv_cap*2:16;conv=realloc(conv,conv_cap*sizeof(msg_t));}
    conv[conv_count++]=m;
}

/* ===== Serialize Request ===== */
static void ser_msg(sbuf*sb,msg_t*m){
    sb_c(sb,'{');
    sb_str(sb,"\"role\":");enc_str(sb,m->role);
    if(strcmp(m->role,"tool")==0){
        sb_str(sb,",\"tool_call_id\":");enc_str(sb,m->tc_id);
        sb_str(sb,",\"content\":");enc_str(sb,m->content);
    }else if(strcmp(m->role,"assistant")==0){
        sb_str(sb,",\"content\":");
        if(m->content)enc_str(sb,m->content);else sb_str(sb,"null");
        if(m->n_tc>0){
            sb_str(sb,",\"tool_calls\":[");
            for(int i=0;i<m->n_tc;i++){
                if(i)sb_c(sb,',');
                sb_str(sb,"{\"id\":");enc_str(sb,m->tcs[i].id);
                sb_str(sb,",\"type\":\"function\",\"function\":{\"name\":");enc_str(sb,m->tcs[i].name);
                sb_str(sb,",\"arguments\":");enc_str(sb,m->tcs[i].arguments);
                sb_str(sb,"}}");
            }
            sb_c(sb,']');
        }
    }else{
        sb_str(sb,",\"content\":");enc_str(sb,m->content);
    }
    sb_c(sb,'}');
}

static char*build_body(const char*model,jval*tools){
    sbuf sb;sb_init(&sb);
    sb_str(&sb,"{\"model\":");enc_str(&sb,model);
    sb_str(&sb,",\"messages\":[");
    for(int i=0;i<conv_count;i++){if(i)sb_c(&sb,',');ser_msg(&sb,&conv[i]);}
    sb_str(&sb,"],\"tools\":");
    ser_json(&sb,tools);
    sb_str(&sb,",\"tool_choice\":\"auto\"}");
    return sb.buf;
}

/* ===== Tool Execution ===== */
static char*exec_tool(const char*name,const char*args_json){
    jval*args=NULL;
    if(args_json&&*args_json){const char*p=args_json;args=parse_val(&p);}
    if(strcmp(name,"inventory_lookup")==0){
        const char*sku=jstr(jobj_get(args,"sku"));
        if(!sku)sku="";
        for(int i=0;i<inv_count;i++){
            if(strcmp(inventory[i].sku,sku)==0){
                sbuf sb;sb_init(&sb);
                sb_str(&sb,"{\"sku\":");enc_str(&sb,inventory[i].sku);
                sb_str(&sb,",\"name\":");enc_str(&sb,inventory[i].name);
                sb_str(&sb,",\"price_cents\":");sb_int(&sb,inventory[i].price_cents);
                sb_str(&sb,",\"currency\":");enc_str(&sb,inventory[i].currency);
                sb_str(&sb,",\"stock\":");sb_int(&sb,inventory[i].stock);
                sb_c(&sb,'}');
                return sb.buf;
            }
        }
        sbuf sb;sb_init(&sb);
        sb_str(&sb,"{\"error\":\"unknown sku: ");enc_str(&sb,sku);sb_str(&sb,"\"}");
        return sb.buf;
    }else if(strcmp(name,"convert_currency")==0){
        long long amt=jint(jobj_get(args,"amount_cents"));
        const char*from=jstr(jobj_get(args,"from"));
        const char*to=jstr(jobj_get(args,"to"));
        if(!from)from="USD";if(!to)to="USD";
        long long rf=get_rate(from),rt=get_rate(to);
        /* HALF_UP: (2*amt*rt + rf) / (2*rf) */
        long long num=2*amt*rt+rf;
        long long den=2*rf;
        long long result=num/den;
        sbuf sb;sb_init(&sb);
        sb_str(&sb,"{\"amount_cents\":");sb_int(&sb,result);
        sb_str(&sb,",\"currency\":");enc_str(&sb,to);
        sb_c(&sb,'}');
        return sb.buf;
    }else{
        sbuf sb;sb_init(&sb);
        sb_str(&sb,"{\"error\":\"unknown tool: ");enc_str(&sb,name);sb_str(&sb,"\"}");
        return sb.buf;
    }
}

/* ===== Main ===== */
int main(int argc,char**argv){
    if(argc<3){fprintf(stderr,"Usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char*data_dir=argv[1];const char*base_url=argv[2];

    /* Read task.json */
    char tpath[4096];snprintf(tpath,sizeof(tpath),"%s/task.json",data_dir);
    char*tdata=read_file(tpath,NULL);
    const char*tp=tdata;jval*task=parse_val(&tp);
    const char*api_key=strdup(jstr(jobj_get(task,"api_key")));
    const char*model=strdup(jstr(jobj_get(task,"model")));
    const char*system=strdup(jstr(jobj_get(task,"system")));
    const char*user=strdup(jstr(jobj_get(task,"user")));
    jval*tools=jobj_get(task,"tools");

    /* Read inventory.csv */
    char cpath[4096];snprintf(cpath,sizeof(cpath),"%s/inventory.csv",data_dir);
    size_t clen=0;char*cdata=read_file(cpath,&clen);
    if(cdata)parse_csv(cdata,clen);

    /* Read rates.json */
    char rpath[4096];snprintf(rpath,sizeof(rpath),"%s/rates.json",data_dir);
    char*rdata=read_file(rpath,NULL);
    if(rdata){
        const char*rp=rdata;jval*rv=parse_val(&rp);
        jval*rates_obj=jobj_get(rv,"rates");
        if(rates_obj&&rates_obj->type==JOBJ){
            rate_count=rates_obj->obj.count;
            rates=malloc((size_t)rate_count*sizeof(rate_entry));
            for(int i=0;i<rate_count;i++){
                rates[i].code=rates_obj->obj.keys[i];
                rates[i].rate=jint(rates_obj->obj.vals[i]);
            }
        }
    }

    /* Init conversation */
    msg_t m1={strdup("system"),strdup(system),NULL,0,NULL};conv_add(m1);
    msg_t m2={strdup("user"),strdup(user),NULL,0,NULL};conv_add(m2);

    long long tot_prompt=0,tot_comp=0,tot_total=0;int n_req=0;

    for(;;){
        char*body=build_body(model,tools);
        http_resp resp=http_post(base_url,api_key,body);
        free(body);
        n_req++;

        if(resp.status!=200){
            /* try to extract error message */
            const char*em="";
            if(resp.body){
                const char*bp=resp.body;jval*ev=parse_val(&bp);
                jval*err=jobj_get(ev,"error");
                if(err)em=jstr(jobj_get(err,"message"));
                if(!em)em="";
            }
            printf("ERROR %d %s\n",resp.status,em);
            free(resp.body);
            printf("USAGE prompt=%lld completion=%lld total=%lld requests=%d\n",tot_prompt,tot_comp,tot_total,n_req);
            return 0;
        }

        /* Parse response */
        const char*bp=resp.body;jval*root=parse_val(&bp);
        jval*usage=jobj_get(root,"usage");
        if(usage){tot_prompt+=jint(jobj_get(usage,"prompt_tokens"));tot_comp+=jint(jobj_get(usage,"completion_tokens"));tot_total+=jint(jobj_get(usage,"total_tokens"));}

        jval*choices=jobj_get(root,"choices");
        jval*ch0=NULL;
        if(choices&&choices->type==JARR&&choices->arr.count>0)ch0=choices->arr.items[0];
        jval*msg=jobj_get(ch0,"message");
        const char*finish=jstr(jobj_get(ch0,"finish_reason"));

        if(finish&&strcmp(finish,"stop")==0){
            const char*content=jstr(jobj_get(msg,"content"));
            printf("FINAL %s\n",content?content:"");
            printf("USAGE prompt=%lld completion=%lld total=%lld requests=%d\n",tot_prompt,tot_comp,tot_total,n_req);
            free(resp.body);
            return 0;
        }

        /* tool_calls */
        jval*content_v=jobj_get(msg,"content");
        const char*content_str=(content_v&&content_v->type==JSTR)?content_v->sval:NULL;
        if(content_str)printf("SAY %s\n",content_str);

        jval*tcs=jobj_get(msg,"tool_calls");
        int ntc=0;tc_t*tcall=NULL;
        if(tcs&&tcs->type==JARR){
            ntc=tcs->arr.count;
            tcall=malloc((size_t)ntc*sizeof(tc_t));
            for(int i=0;i<ntc;i++){
                jval*tc=tcs->arr.items[i];
                tcall[i].id=strdup(jstr(jobj_get(tc,"id")));
                jval*fn=jobj_get(tc,"function");
                tcall[i].name=strdup(jstr(jobj_get(fn,"name")));
                tcall[i].arguments=strdup(jstr(jobj_get(fn,"arguments")));
            }
        }

        /* Print CALL lines */
        for(int i=0;i<ntc;i++)printf("CALL %s %s\n",tcall[i].id,tcall[i].name);

        /* Execute tools and print RESULT */
        char**results=malloc((size_t)ntc*sizeof(char*));
        for(int i=0;i<ntc;i++){
            results[i]=exec_tool(tcall[i].name,tcall[i].arguments);
            printf("RESULT %s %s\n",tcall[i].id,results[i]);
        }

        /* Append assistant message */
        msg_t am={strdup("assistant"),content_str?strdup(content_str):NULL,tcall,ntc,NULL};
        conv_add(am);

        /* Append tool messages */
        for(int i=0;i<ntc;i++){
