            5 => {
                let mut v: u64 = 0;
                for j in 0..6 { v = (v << 8) | payload[doff + j] as u64; }
                let sv = ((v << 16) as i64) >> 16;
                values.push(Value::Int(sv));
                doff += 6;
            }
            6 => { values.push(Value::Int(read_be_u64(payload, doff) as i64)); doff += 8; }
            7 => { values.push(Value::Real(f64::from_bits(read_be_u64(payload, doff)))); doff += 8; }
            8 => values.push(Value::Int(0)),
            9 => values.push(Value::Int(1)),
            n if n >= 12 && n % 2 == 0 => {
                let len = ((n - 12) / 2) as usize;
                values.push(Value::Blob(payload[doff..doff + len].to_vec()));
                doff += len;
            }
            n if n >= 13 => {
                let len = ((n - 13) / 2) as usize;
                values.push(Value::Text(payload[doff..doff + len].to_vec()));
                doff += len;
            }
            _ => values.push(Value::Null),
        }
    }
    values
}

fn parse_record(payload: &[u8], num_cols: usize, rowid: i64, int_pk: &[usize]) -> Vec<Value> {
    let mut values = parse_record_raw(payload);
    for &idx in int_pk {
        if idx < values.len() {
            values[idx] = Value::Int(rowid);
        }
    }
    while values.len() < num_cols {
        values.push(Value::Null);
    }
    values
}

fn collect_rows(data: &[u8], page_num: u32, page_size: usize, reserved: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
    if page_num == 0 { return; }
    let page_start = (page_num as usize - 1) * page_size;
    if page_start + page_size > data.len() { return; }
    let page = &data[page_start..page_start + page_size];
    let hdr_off = if page_num == 1 { 100 } else { 0 };
    let page_type = page[hdr_off];
    let num_cells = read_be_u16(page, hdr_off + 3) as usize;

    if page_type == 5 {
        // Interior table b-tree
        let right_child = read_be_u32(page, hdr_off + 8);
        let ptr_start = hdr_off + 12;
        for i in 0..num_cells {
            let cell_off = read_be_u16(page, ptr_start + i * 2) as usize;
            let child = read_be_u32(page, cell_off);
            collect_rows(data, child, page_size, reserved, rows);
        }
        collect_rows(data, right_child, page_size, reserved, rows);
    } else if page_type == 10 {
        // Leaf table b-tree
        let usable = page_size - reserved;
        let x_max = usable.saturating_sub(35);
        let m_val = ((usable.saturating_sub(12)) * 32) / 255;
        let m_val = m_val.saturating_sub(23);
        let ptr_start = hdr_off + 8;
        for i in 0..num_cells {
            let cell_off = read_be_u16(page, ptr_start + i * 2) as usize;
            let (payload_size, n1) = read_varint(page, cell_off);
            let (rowid_v, n2) = read_varint(page, cell_off + n1);
            let local_start = cell_off + n1 + n2;
            let p = payload_size as usize;

            let local_size = if p <= x_max {
                p
            } else {
                let k = m_val + ((p.wrapping_sub(m_val)) % (usable - 4));
                if k <= x_max { k } else { m_val }
            };

            let mut payload = page[local_start..local_start + local_size].to_vec();

            if local_size < p {
                let ovf_page = read_be_u32(page, local_start + local_size);
                let mut op = ovf_page;
                while op != 0 {
                    let os = (op as usize - 1) * page_size;
                    if os + page_size > data.len() { break; }
                    let next_op = read_be_u32(&data[os..os + page_size], 0);
                    let chunk = usable - 4;
                    payload.extend_from_slice(&data[os + 4..os + 4 + chunk]);
                    op = next_op;
                }
            }

            rows.push((rowid_v as i64, payload));
        }
    }
}

fn parse_create_table(sql: &str) -> (Vec<String>, Vec<usize>) {
    let mut col_names: Vec<String> = Vec::new();
    let mut int_pk: Vec<usize> = Vec::new();
    let bytes = sql.as_bytes();
    let len = bytes.len();
    let upper = sql.to_uppercase();
    let ct_pos = match upper.find("CREATE TABLE") {
        Some(p) => p,
        None => return (col_names, int_pk),
    };
    let mut pos = ct_pos + 12;

    // skip whitespace
    while pos < len && (bytes[pos] == b' ' || bytes[pos] == b'\t' || bytes[pos] == b'\n' || bytes[pos] == b'\r') { pos += 1; }

    // read table name
    if pos < len && bytes[pos] == b'"' {
        pos += 1;
        while pos < len && bytes[pos] != b'"' { pos += 1; }
        pos += 1;
    } else {
        while pos < len && !bytes[pos].is_ascii_whitespace() && bytes[pos] != b'(' { pos += 1; }
    }

    // skip whitespace
    while pos < len && (bytes[pos] == b' ' || bytes[pos] == b'\t' || bytes[pos] == b'\n' || bytes[pos] == b'\r') { pos += 1; }

    if pos >= len || bytes[pos] != b'(' { return (col_names, int_pk); }
    pos += 1;
    let defs_start = pos;
    let mut depth = 1i32;
    while pos < len && depth > 0 {
        match bytes[pos] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            _ => {}
        }
        if depth > 0 { pos += 1; }
    }
    let defs_str = &sql[defs_start..pos];

    // split by commas not inside parens
    let mut defs: Vec<&str> = Vec::new();
    let mut d2 = 0i32;
    let mut start = 0usize;
    let db = defs_str.as_bytes();
    for i in 0..db.len() {
        match db[i] {
            b'(' => d2 += 1,
            b')' => d2 -= 1,
            b',' if d2 == 0 => { defs.push(&defs_str[start..i]); start = i + 1; }
            _ => {}
        }
    }
    defs.push(&defs_str[start..]);

    for def in defs {
        let dt = def.trim();
        if dt.is_empty() { continue; }
        let dtb = dt.as_bytes();
        let mut p = 0usize;
        let col_name;
        if p < dtb.len() && dtb[p] == b'"' {
            p += 1;
            let qs = p;
            while p < dtb.len() && dtb[p] != b'"' { p += 1; }
            col_name = dt[qs..p].to_string();
            p += 1;
        } else {
            let qs = p;
            while p < dtb.len() && !dtb[p].is_ascii_whitespace() { p += 1; }
            col_name = dt[qs..p].to_string();
        }
        col_names.push(col_name);

        let rest = &dt[p..];
        let rest_norm: String = rest.split_whitespace().collect::<Vec<_>>().join(" ").to_uppercase();
        let rt = rest_norm.trim_start();
        let mut fwe = 0usize;
        let rtb = rt.as_bytes();
        while fwe < rtb.len() && (rtb[fwe].is_ascii_alphanumeric() || rtb[fwe] == b'_') { fwe += 1; }
        let fw = &rt[..fwe];
        if fw == "INTEGER" && rest_norm.contains("PRIMARY KEY") {
            int_pk.push(col_names.len() - 1);
        }
    }
    (col_names, int_pk)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
