import Foundation

// ===== URL Parsing =====
func parseURL(_ urlStr: String) -> (host: String, port: Int, path: String) {
    var rest = urlStr
    if rest.hasPrefix("http://") { rest.removeFirst(7) }
    let slashPos = rest.firstIndex(of: "/")
    let hostPort: Substring
    let path: String
    if let sp = slashPos {
        hostPort = rest[..<sp]
        path = String(rest[sp...])
    } else {
        hostPort = rest[...]
        path = "/"
    }
    let colonPos = hostPort.lastIndex(of: ":")
    let host: String
    let port: Int
    if let cp = colonPos {
        host = String(hostPort[..<cp])
        port = Int(hostPort[hostPort.index(after: cp)...]) ?? 80
    } else {
        host = String(hostPort)
        port = 80
    }
    return (host, port, path)
}

// ===== Socket I/O =====
func tcpConnect(host: String, port: Int) -> Int32 {
    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    guard fd >= 0 else { fatalError("socket failed") }
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = UInt16(port).bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)
    let r = withUnsafePointer(to: &addr) { p in
        p.withMemoryRebound(to: sockaddr.self, capacity: 1) { sp in
            Darwin.connect(fd, sp, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard r == 0 else { fatalError("connect failed") }
    return fd
}

func tcpSend(fd: Int32, data: Data) {
    data.withUnsafeBytes { raw in
        var off = 0
        while off < data.count {
            let n = Darwin.send(fd, raw.baseAddress!.advanced(by: off), data.count - off, 0)
            if n <= 0 { fatalError("send failed") }
            off += n
        }
    }
}

func tcpRecvAll(fd: Int32) -> Data {
    var result = Data()
    let cap = 65536
    let buf = UnsafeMutableRawPointer.allocate(byteCount: cap, alignment: 1)
    defer { buf.deallocate() }
    while true {
        let n = recv(fd, buf, cap, 0)
        if n <= 0 { break }
        result.append(buf.assumingMemoryBound(to: UInt8.self), count: n)
    }
    return result
}

// ===== HTTP =====
func buildHTTPRequest(host: String, port: Int, path: String, apiKey: String, body: Data) -> Data {
    var req = Data()
    let h = "POST \(path) HTTP/1.1\r\nHost: \(host):\(port)\r\nContent-Length: \(body.count)\r\nx-api-key: \(apiKey)\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n"
    req.append(h.data(using: .utf8)!)
    req.append(body)
    return req
}

func dechunk(_ data: Data) -> Data {
    var result = Data()
    var pos = 0
    while pos < data.count {
        var lineBytes: [UInt8] = []
        while pos < data.count {
            let b = data[data.startIndex + pos]
            pos += 1
            if b == 0x0A { break }
            lineBytes.append(b)
        }
        if lineBytes.last == 0x0D { lineBytes.removeLast() }
        let hexStr = String(bytes: lineBytes, encoding: .ascii) ?? ""
        let trimmed = hexStr.trimmingCharacters(in: .whitespaces)
        guard let chunkSize = Int(trimmed, radix: 16) else { break }
        if chunkSize == 0 { break }
        let end = pos + chunkSize
        if end <= data.count {
            result.append(data[data.startIndex + pos..<data.startIndex + end])
        }
        pos = end
        if pos < data.count && data[data.startIndex + pos] == 0x0D { pos += 1 }
        if pos < data.count && data[data.startIndex + pos] == 0x0A { pos += 1 }
    }
    return result
}

func parseHTTPResponse(_ raw: Data) -> (status: Int, headers: [String: String], body: Data) {
    let boundary = Data([0x0D, 0x0A, 0x0D, 0x0A])
    guard let range = raw.range(of: boundary) else { fatalError("bad HTTP") }
    let headerData = raw[raw.startIndex..<range.lowerBound]
    let rawBody = Data(raw[range.upperBound...])
    let headerStr = String(data: headerData, encoding: .utf8)!
    let lines = headerStr.components(separatedBy: "\r\n")
    let status = Int(lines[0].components(separatedBy: " ")[1]) ?? 0
    var headers: [String: String] = [:]
    for i in 1..<lines.count {
        let line = lines[i]
        if let ci = line.firstIndex(of: ":") {
            let key = String(line[..<ci]).lowercased()
            let val = String(line[line.index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            headers[key] = val
        }
    }
    var body: Data
    if headers["transfer-encoding"]?.lowercased().contains("chunked") == true {
        body = dechunk(rawBody)
    } else {
        body = rawBody
    }
    return (status, headers, body)
}

// ===== SSE Parsing =====
struct SSEEvent {
    var name: String = ""
    var dataLines: [String] = []
}

func parseSSE(_ data: Data) -> [SSEEvent] {
    guard let str = String(data: data, encoding: .utf8) else { return [] }
    var events: [SSEEvent] = []
    var cur = SSEEvent()
    var hasFields = false
    var lines: [String] = []
    var curLine = ""
    var idx = str.startIndex
    while idx < str.endIndex {
        let ch = str[idx]
        if ch == "\n" {
            lines.append(curLine); curLine = ""
            idx = str.index(after: idx)
        } else if ch == "\r" {
            let nxt = str.index(after: idx)
            if nxt < str.endIndex && str[nxt] == "\n" {
                lines.append(curLine); curLine = ""
                idx = str.index(nxt, offsetBy: 1)
            } else {
                lines.append(curLine); curLine = ""
                idx = nxt
            }
        } else {
            curLine.append(ch)
            idx = str.index(after: idx)
        }
    }
    if !curLine.isEmpty { lines.append(curLine) }

    for line in lines {
        if line.isEmpty {
            if hasFields { events.append(cur); cur = SSEEvent(); hasFields = false }
        } else if line.hasPrefix(":") {
            // comment
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            cur.name = v; hasFields = true
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            cur.dataLines.append(v); hasFields = true
        }
    }
    return events
}

