func processReply(_ events: [SSEEvent]) -> (blocks: [ContentBlock], stopReason: String, inputTokens: Int, outputTokens: Int, cacheReadTokens: Int) {
    var blocks: [Int: ContentBlock] = [:]
    var stopReason = ""
    var inTok = 0, outTok = 0, cacheTok = 0
    for ev in events {
        guard !ev.dataLines.isEmpty else { continue }
        let ds = ev.dataLines.joined(separator: "\n")
        guard let jd = ds.data(using: .utf8),
              let j = try? JSONSerialization.jsonObject(with: jd) as? [String: Any] else { continue }
        switch ev.name {
        case "message_start":
            if let msg = j["message"] as? [String: Any],
               let u = msg["usage"] as? [String: Any] {
                inTok += (u["input_tokens"] as? Int) ?? 0
                cacheTok += (u["cache_read_input_tokens"] as? Int) ?? 0
            }
        case "content_block_start":
            let i = (j["index"] as? Int) ?? 0
            if let cb = j["content_block"] as? [String: Any] {
                var b = ContentBlock(type: cb["type"] as? String ?? "", index: i)
                b.id = cb["id"] as? String ?? ""
                b.name = cb["name"] as? String ?? ""
                blocks[i] = b
            }
        case "content_block_delta":
            let i = (j["index"] as? Int) ?? 0
            guard var b = blocks[i], let d = j["delta"] as? [String: Any] else { continue }
            switch d["type"] as? String ?? "" {
            case "thinking_delta": b.thinking += (d["thinking"] as? String) ?? ""
            case "signature_delta": b.signature += (d["signature"] as? String) ?? ""
            case "text_delta": b.text += (d["text"] as? String) ?? ""
            case "input_json_delta": b.partialJson += (d["partial_json"] as? String) ?? ""
            default: break
            }
            blocks[i] = b
        case "content_block_stop":
            let i = (j["index"] as? Int) ?? 0
            if var b = blocks[i], b.type == "tool_use" {
                if let pd = b.partialJson.data(using: .utf8),
                   let parsed = try? JSONSerialization.jsonObject(with: pd) {
                    b.input = parsed
                }
                blocks[i] = b
            }
        case "message_delta":
            if let d = j["delta"] as? [String: Any] {
                stopReason = (d["stop_reason"] as? String) ?? ""
            }
            if let u = j["usage"] as? [String: Any] {
                outTok += (u["output_tokens"] as? Int) ?? 0
            }
        case "message_stop": break
        default: break
        }
    }
    let sorted = blocks.values.sorted { $0.index < $1.index }
    return (sorted, stopReason, inTok, outTok, cacheTok)
}

