func tcpRecvAll(fd: Int32) -> Data {
    var result = Data()
    let cap = 65536
    let buf = UnsafeMutableRawPointer.allocate(byteCount: cap, alignment: 1)
    defer { buf.deallocate() }
    while true {
        let n = recv(fd, buf, cap, 0)
        if n <= 0 { break }
        result.append(buf.assumingMemoryBound(to: UInt8.self), count: n)
