        let ch = str[idx]
        if ch == "\n" {
            lines.append(curLine); curLine = ""
            idx = str.index(after: idx)
        } else if ch == "\r" {
            let nxt = str.index(after: idx)
            if nxt < str.endIndex && str[nxt] == "\n" {
                lines.append(curLine); curLine = ""
                idx = str.index(nxt, offsetBy: 1)
            } else {
                lines.append(curLine); curLine = ""
                idx = nxt
            }
        } else {
            curLine.append(ch)
            idx = str.index(after: idx)
        }
    }
    if !curLine.isEmpty { lines.append(curLine) }

    for line in lines {
        if line.isEmpty {
            if hasFields { events.append(cur); cur = SSEEvent(); hasFields = false }
        } else if line.hasPrefix(":") {
            // comment
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            cur.name = v; hasFields = true
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
