func esc(_ s: String) -> String {
    var r = ""
    for c in s.unicodeScalars {
        switch c {
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(c)
        }
    }
    return r
}

func printBlock(_ b: ContentBlock) {
    switch b.type {
    case "thinking":
        print("thinking \(esc(b.thinking))")
        print("signature \(esc(b.signature))")
    case "text":
        print("text \(esc(b.text))")
    case "tool_use":
        print("tool_use \(esc(b.id)) \(esc(b.name)) \(esc(b.partialJson))")
    default: break
    }
}

// ===== Request Execution =====
func doRequest(host: String, port: Int, path: String, apiKey: String, body: Data) -> ([ContentBlock], String, Int, Int, Int) {
    let fd = tcpConnect(host: host, port: port)
    tcpSend(fd: fd, data: buildHTTPRequest(host: host, port: port, path: path, apiKey: apiKey, body: body))
    let raw = tcpRecvAll(fd: fd)
    Darwin.close(fd)
    let (status, _, respBody) = parseHTTPResponse(raw)
    if status != 200 {
        if let j = try? JSONSerialization.jsonObject(with: respBody) as? [String: Any],
           let err = j["error"] as? [String: Any] {
            print("ERROR \(status) \(err["type"] as? String ?? ""): \(err["message"] as? String ?? "")")
        }
        fflush(stdout)
        exit(0)
    }
    let events = parseSSE(respBody)
    return processReply(events)
}

