Looking at the failure, the core issue is that bytes are being lost during the chunked transfer decoding and SSE parsing pipeline. The garbled thinking text, truncated tool inputs, and missing `stop_reason` all point to data loss in the HTTP/SSE parsing. I'll rewrite the I/O and parsing layers to work with `[UInt8]` arrays throughout, handle `EINTR`, and be more careful about chunk boundaries and line endings.

```swift
import Foundation

// ===== URL Parsing =====
func parseURL(_ urlStr: String) -> (host: String, port: Int, path: String) {
    var rest = urlStr
    if rest.hasPrefix("http://") { rest.removeFirst(7) }
    let slashPos = rest.firstIndex(of: "/")
    let hostPort: Substring
    let path: String
    if let sp = slashPos {
        hostPort = rest[..<sp]
        path = String(rest[sp...])
    } else {
        hostPort = rest[...]
        path = "/"
    }
    let colonPos = hostPort.lastIndex(of: ":")
    let host: String
    let port: Int
    if let cp = colonPos {
        host = String(hostPort[..<cp])
        port = Int(hostPort[hostPort.index(after: cp)...]) ?? 80
    } else {
        host = String(hostPort)
        port = 80
    }
    return (host, port, path)
}

// ===== Socket I/O =====
func tcpConnect(host: String, port: Int) -> Int32 {
    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    guard fd >= 0 else { fatalError("socket failed") }
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = UInt16(port).bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)
    let r = withUnsafePointer(to: &addr) { p in
        p.withMemoryRebound(to: sockaddr.self, capacity: 1) { sp in
            Darwin.connect(fd, sp, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard r == 0 else { fatalError("connect failed") }
    return fd
}

func tcpSendAll(fd: Int32, bytes: [UInt8]) {
    bytes.withUnsafeBufferPointer { p in
        var off = 0
        while off < bytes.count {
            let n = Darwin.send(fd, p.baseAddress!.advanced(by: off), bytes.count - off, 0)
            if n <= 0 { fatalError("send failed") }
            off += n
        }
    }
}

func tcpRecvAll(fd: Int32) -> [UInt8] {
    var result: [UInt8] = []
    var buf = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = buf.withUnsafeMutableBufferPointer { p in
            recv(fd, p.baseAddress!, p.count, 0)
        }
        if n < 0 {
            if errno == EINTR { continue }
            break
        }
        if n == 0 { break }
        result.append(contentsOf: buf[0..<n])
    }
    return result
}

// ===== HTTP =====
func buildHTTPRequest(host: String, port: Int, path: String, apiKey: String, body: [UInt8]) -> [UInt8] {
    let h = "POST \(path) HTTP/1.1\r\nHost: \(host):\(port)\r\nContent-Length: \(body.count)\r\nx-api-key: \(apiKey)\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n"
    var req = Array(h.utf8)
    req.append(contentsOf: body)
    return req
}

func dechunk(_ data: [UInt8]) -> [UInt8] {
    var result: [UInt8] = []
    var pos = 0
    while pos < data.count {
        // Read chunk-size line (terminated by LF)
        var lineStart = pos
        while pos < data.count && data[pos] != 0x0A { pos += 1 }
        var lineEnd = pos // index of \n
        if pos < data.count { pos += 1 } // skip \n
        // Strip trailing \r
        if lineEnd > lineStart && data[lineEnd - 1] == 0x0D { lineEnd -= 1 }
        // Parse hex chunk size
        var sizeStr = ""
        for i in lineStart..<lineEnd {
            sizeStr.append(Character(UnicodeScalar(data[i])))
        }
        sizeStr = sizeStr.trimmingCharacters(in: .whitespaces)
        guard let chunkSize = Int(sizeStr, radix: 16) else { break }
        if chunkSize == 0 { break }
        // Read chunk data
        let end = pos + chunkSize
        if end > data.count { break }
        result.append(contentsOf: data[pos..<end])
        pos = end
        // Skip trailing CRLF after chunk data
        if pos < data.count && data[pos] == 0x0D { pos += 1 }
        if pos < data.count && data[pos] == 0x0A { pos += 1 }
    }
    return result
}

func parseHTTPResponse(_ raw: [UInt8]) -> (status: Int, headers: [String: String], body: [UInt8]) {
    // Find \r\n\r\n
    var boundaryPos = -1
    if raw.count >= 4 {
        for i in 0...(raw.count - 4) {
            if raw[i] == 0x0D && raw[i+1] == 0x0A && raw[i+2] == 0x0D && raw[i+3] == 0x0A {
                boundaryPos = i
                break
            }
        }
    }
    guard boundaryPos >= 0 else { fatalError("bad HTTP") }
    let headerBytes = Array(raw[0..<boundaryPos])
    let bodyStart = boundaryPos + 4
    let rawBody = Array(raw[bodyStart...])

    let headerStr = String(decoding: headerBytes, as: UTF8.self)
    let lines = headerStr.components(separatedBy: "\r\n")
    let status = Int(lines[0].components(separatedBy: " ")[1]) ?? 0
    var headers: [String: String] = [:]
    for i in 1..<lines.count {
        let line = lines[i]
        if let ci = line.firstIndex(of: ":") {
            let key = String(line[..<ci]).lowercased()
            let val = String(line[line.index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            headers[key] = val
        }
    }
    var body: [UInt8]
    if headers["transfer-encoding"]?.lowercased().contains("chunked") == true {
        body = dechunk(rawBody)
    } else {
        body = rawBody
    }
    return (status, headers, body)
}

