  return `${sign}${pad2(h)}:${pad2(m)}`;
}

function formatLocalTime(unixSec: number, utcOffset: number): string {
  const localSec = unixSec + utcOffset;
  const days = Math.floor(localSec / 86400);
  const rem = localSec - days * 86400;
  const { y, m, d } = civilFromDays(days);
  const h = Math.floor(rem / 3600);
  const mi = Math.floor((rem % 3600) / 60);
  const s = rem % 60;
  return `${pad4(y)}-${pad2(m)}-${pad2(d)}T${pad2(h)}:${pad2(mi)}:${pad2(s)}`;
