// === TZif structures ===

interface TZifType {
  offset: number;
  isdst: number;
  abbrIndex: number;
}

interface PosixRule {
  m: number;
  w: number;
  d: number;
  time: number;
}

interface PosixTZ {
  stdName: string;
  stdUtcOffset: number;
  dstName: string | null;
  dstUtcOffset: number | null;
  startRule: PosixRule | null;
  endRule: PosixRule | null;
}

interface TZifData {
  transitions: number[];
  typeIndices: number[];
  types: TZifType[];
  abbrs: string[];
  footer: PosixTZ | null;
}

// === TZif parsing ===

function parseTZif(buf: Buffer): TZifData {
  // Header layout: 4 magic + 1 version + 15 unused + 6*4 counts = 44 bytes
  // Counts at offsets: isutcnt=20, isstdcnt=24, leapcnt=28, timecnt=32, typecnt=36, charcnt=40
  const v1Isutcnt = buf.readInt32BE(20);
  const v1Isstdcnt = buf.readInt32BE(24);
  const v1Leapcnt = buf.readInt32BE(28);
  const v1Timecnt = buf.readInt32BE(32);
  const v1Typecnt = buf.readInt32BE(36);
  const v1Charcnt = buf.readInt32BE(40);
  const v1BlockSize = v1Timecnt * 4 + v1Timecnt + v1Typecnt * 6 + v1Charcnt + v1Leapcnt * 8 + v1Isstdcnt + v1Isutcnt;
  let pos = 44 + v1BlockSize;

  // v2 header
  const v2Isutcnt = buf.readInt32BE(pos + 20);
  const v2Isstdcnt = buf.readInt32BE(pos + 24);
  const v2Leapcnt = buf.readInt32BE(pos + 28);
  const v2Timecnt = buf.readInt32BE(pos + 32);
  const v2Typecnt = buf.readInt32BE(pos + 36);
  const v2Charcnt = buf.readInt32BE(pos + 40);
  pos += 44;

  const transitions: number[] = [];
  for (let i = 0; i < v2Timecnt; i++) {
    transitions.push(Number(buf.readBigInt64BE(pos)));
    pos += 8;
  }

  const typeIndices: number[] = [];
  for (let i = 0; i < v2Timecnt; i++) {
    typeIndices.push(buf[pos]);
    pos += 1;
  }

  const types: TZifType[] = [];
  for (let i = 0; i < v2Typecnt; i++) {
    types.push({
      offset: buf.readInt32BE(pos),
      isdst: buf[pos + 4],
      abbrIndex: buf[pos + 5],
    });
    pos += 6;
  }

  const abbrs: string[] = [];
  for (let i = 0; i < v2Typecnt; i++) {
    let end = pos + types[i].abbrIndex;
    while (buf[end] !== 0) end++;
    abbrs.push(buf.slice(pos + types[i].abbrIndex, end).toString('ascii'));
  }
  pos += v2Charcnt;

  pos += v2Leapcnt * 12;
  pos += v2Isstdcnt + v2Isutcnt;

  pos++; // skip \n
  let footerEnd = pos;
  while (footerEnd < buf.length && buf[footerEnd] !== 10) footerEnd++;
  const footerStr = buf.slice(pos, footerEnd).toString('ascii');

  let footer: PosixTZ | null = null;
  if (footerStr.length > 0) {
    footer = parsePosixTZ(footerStr);
  }

  return { transitions, typeIndices, types, abbrs, footer };
}

// === POSIX TZ string parsing ===

function parsePosixTZ(s: string): PosixTZ {
  let pos = 0;

  function parseName(): string {
    if (pos < s.length && s[pos] === '<') {
      let end = pos + 1;
      while (end < s.length && s[end] !== '>') end++;
      const name = s.slice(pos + 1, end);
      pos = end + 1;
      return name;
    } else {
      let end = pos;
      while (end < s.length && /[A-Za-z]/.test(s[end])) end++;
      const name = s.slice(pos, end);
      pos = end;
      return name;
    }
  }

  function parseOffset(): number {
    let sign = 1;
    if (pos < s.length && s[pos] === '+') { pos++; }
    else if (pos < s.length && s[pos] === '-') { sign = -1; pos++; }
    let hh = 0;
    while (pos < s.length && /\d/.test(s[pos])) { hh = hh * 10 + parseInt(s[pos]); pos++; }
    let mm = 0, ss = 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      while (pos < s.length && /\d/.test(s[pos])) { mm = mm * 10 + parseInt(s[pos]); pos++; }
      if (pos < s.length && s[pos] === ':') {
        pos++;
        while (pos < s.length && /\d/.test(s[pos])) { ss = ss * 10 + parseInt(s[pos]); pos++; }
      }
    }
    return -sign * (hh * 3600 + mm * 60 + ss);
  }

  function parseTime(): number {
    let sign = 1;
    if (pos < s.length && s[pos] === '+') { pos++; }
    else if (pos < s.length && s[pos] === '-') { sign = -1; pos++; }
    let hh = 0;
    while (pos < s.length && /\d/.test(s[pos])) { hh = hh * 10 + parseInt(s[pos]); pos++; }
    let mm = 0, ss = 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      while (pos < s.length && /\d/.test(s[pos])) { mm = mm * 10 + parseInt(s[pos]); pos++; }
      if (pos < s.length && s[pos] === ':') {
        pos++;
        while (pos < s.length && /\d/.test(s[pos])) { ss = ss * 10 + parseInt(s[pos]); pos++; }
      }
    }
    return sign * (hh * 3600 + mm * 60 + ss);
  }

  function parseMRule(): PosixRule {
    let m = 0;
    while (pos < s.length && /\d/.test(s[pos])) { m = m * 10 + parseInt(s[pos]); pos++; }
    pos++; // skip '.'
    let w = 0;
    while (pos < s.length && /\d/.test(s[pos])) { w = w * 10 + parseInt(s[pos]); pos++; }
    pos++; // skip '.'
    let d = 0;
    while (pos < s.length && /\d/.test(s[pos])) { d = d * 10 + parseInt(s[pos]); pos++; }
    let time = 2 * 3600;
    if (pos < s.length && s[pos] === '/') { pos++; time = parseTime(); }
    return { m, w, d, time };
  }

  const stdName = parseName();
  const stdUtcOffset = parseOffset();

  let dstName: string | null = null;
  let dstUtcOffset: number | null = null;
  let startRule: PosixRule | null = null;
  let endRule: PosixRule | null = null;

  if (pos < s.length && (s[pos] === '<' || /[A-Za-z]/.test(s[pos]))) {
    dstName = parseName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /\d/.test(s[pos]))) {
      dstUtcOffset = parseOffset();
    } else {
      dstUtcOffset = stdUtcOffset + 3600;
    }
    if (pos < s.length && s[pos] === ',') {
      pos++;
      if (pos < s.length && s[pos] === 'M') { pos++; startRule = parseMRule(); }
      if (pos < s.length && s[pos] === ',') {
        pos++;
        if (pos < s.length && s[pos] === 'M') { pos++; endRule = parseMRule(); }
      }
    }
  }

  return { stdName, stdUtcOffset, dstName, dstUtcOffset, startRule, endRule };
}

// === Offset at time ===

function computeFooterTransitionTime(year: number, rule: PosixRule, utcOffset: number): number {
  const day = nthWeekdayOfMonth(year, rule.m, rule.d, rule.w);
  const dayStart = daysFromCivil(year, rule.m, day) * 86400;
  return dayStart + rule.time - utcOffset;
}

function getOffsetAtTime(data: TZifData, t: number): { offset: number; abbr: string; isdst: number } {
  const { transitions, typeIndices, types, abbrs, footer } = data;

  if (transitions.length === 0) {
    return { offset: types[0].offset, abbr: abbrs[0], isdst: types[0].isdst };
  }

  if (t < transitions[0]) {
    return { offset: types[0].offset, abbr: abbrs[0], isdst: types[0].isdst };
  }

  if (t <= transitions[transitions.length - 1]) {
    let lo = 0, hi = transitions.length - 1;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (transitions[mid] <= t) lo = mid;
      else hi = mid - 1;
    }
    const ti = typeIndices[lo];
    return { offset: types[ti].offset, abbr: abbrs[ti], isdst: types[ti].isdst };
  }

  // After last transition: use footer
  if (!footer) {
    const ti = typeIndices[typeIndices.length - 1];
    return { offset: types[ti].offset, abbr: abbrs[ti], isdst: types[ti].isdst };
  }

  if (!footer.dstName || !footer.startRule || !footer.endRule) {
    return { offset: footer.stdUtcOffset, abbr: footer.stdName, isdst: 0 };
  }

  const utcYear = civilFromDays(Math.floor(t / 86400)).y;
  const startT = computeFooterTransitionTime(utcYear, footer.startRule, footer.stdUtcOffset);
  const endT = computeFooterTransitionTime(utcYear, footer.endRule, footer.dstUtcOffset!);

  let inDst: boolean;
  if (startT < endT) {
    inDst = t >= startT && t < endT;
  } else {
    inDst = t >= startT || t < endT;
  }

  if (inDst) {
    return { offset: footer.dstUtcOffset!, abbr: footer.dstName, isdst: 1 };
  } else {
    return { offset: footer.stdUtcOffset, abbr: footer.stdName, isdst: 0 };
  }
}

// === Query handlers ===

function handleUTC(data: TZifData, t: number): string {
  const info = getOffsetAtTime(data, t);
  const localStr = formatLocalTime(t, info.offset);
  const offsetStr = formatOffset(info.offset);
  return `${localStr}${offsetStr} ${info.abbr}`;
}

function handleLOCAL(data: TZifData, W: number): string {
  const offsets = new Set<number>();
  for (const type of data.types) offsets.add(type.offset);
  if (data.footer) {
    offsets.add(data.footer.stdUtcOffset);
    if (data.footer.dstUtcOffset !== null) offsets.add(data.footer.dstUtcOffset);
  }

  const candidates: number[] = [];
  for (const o of offsets) {
    const t = W - o;
    const info = getOffsetAtTime(data, t);
    if (info.offset === o) {
      candidates.push(t);
    }
  }

  candidates.sort((a, b) => a - b);

  if (candidates.length === 1) {
    const t = candidates[0];
    const info = getOffsetAtTime(data, t);
    return `${t} ${formatOffset(info.offset)} ${info.abbr}`;
  } else if (candidates.length >= 2) {
    const parts = candidates.map(t => {
      const info = getOffsetAtTime(data, t);
      return `${t} ${formatOffset(info.offset)} ${info.abbr}`;
    });
    return parts.join(' | ');
  }

  // Gap: find the transition
  const gapResult = findGapTransition(data, W);
  if (gapResult !== null) {
    const t = gapResult;
    const info = getOffsetAtTime(data, t);
    const localStr = formatLocalTime(t, info.offset);
    const offsetStr = formatOffset(info.offset);
    return `GAP ${t} ${localStr}${offsetStr} ${info.abbr}`;
  }

  return `GAP ERROR`;
}

function findGapTransition(data: TZifData, W: number): number | null {
  const { transitions, typeIndices, types, footer } = data;

  // Check explicit transitions
  for (let i = 0; i < transitions.length; i++) {
    const T = transitions[i];
    const offsetBefore = i === 0 ? types[0].offset : types[typeIndices[i - 1]].offset;
    const offsetAfter = types[typeIndices[i]].offset;
    if (offsetAfter > offsetBefore) {
      if (W >= T + offsetBefore && W < T + offsetAfter) {
        return W - offsetBefore;
      }
    }
  }

  // Check footer transitions
  if (footer && footer.dstName && footer.startRule && footer.endRule && footer.dstUtcOffset !== null) {
    const lastExplicit = transitions.length > 0 ? transitions[transitions.length - 1] : -Infinity;
    const utcYear = civilFromDays(Math.floor(W / 86400)).y;

    for (let year = utcYear - 1; year <= utcYear + 1; year++) {
      const startT = computeFooterTransitionTime(year, footer.startRule, footer.stdUtcOffset);
      const endT = computeFooterTransitionTime(year, footer.endRule, footer.dstUtcOffset);

      // Start: std → dst (gap if dst > std)
      if (footer.dstUtcOffset > footer.stdUtcOffset && startT > lastExplicit) {
        if (W >= startT + footer.stdUtcOffset && W < startT + footer.dstUtcOffset) {
          return W - footer.stdUtcOffset;
        }
      }

      // End: dst → std (gap if std > dst, unusual)
      if (footer.stdUtcOffset > footer.dstUtcOffset && endT > lastExplicit) {
        if (W >= endT + footer.dstUtcOffset && W < endT + footer.stdUtcOffset) {
          return W - footer.dstUtcOffset;
        }
      }
    }
  }

  return null;
}

// === Main ===

function main(): void {
  const dir = process.argv[2];
  const queriesPath = path.join(dir, 'queries.txt');
  const content = fs.readFileSync(queriesPath, 'utf-8');
  const lines = content.split('\n');

  const tzifCache: Map<string, TZifData> = new Map();
  function getTZif(filename: string): TZifData {
    if (!tzifCache.has(filename)) {
      const buf = fs.readFileSync(path.join(dir, filename));
      tzifCache.set(filename, parseTZif(buf));
    }
    return tzifCache.get(filename)!;
  }

  const outputLines: string[] = [];

  for (const line of lines) {
    if (line.trim() === '') continue;
    const parts = line.split(' ');
    const qType = parts[0];
    const filename = parts[1];
    const data = getTZif(filename);

    if (qType === 'UTC') {
      const t = parseInt(parts[2], 10);
      const result = handleUTC(data, t);
      outputLines.push(`${line} -> ${result}`);
    } else if (qType === 'LOCAL') {
      const wallStr = parts[2];
      const [datePart, timePart] = wallStr.split('T');
      const [yy, mm, dd] = datePart.split('-').map(Number);
      const [hh, mi, ss] = timePart.split(':').map(Number);
      const W = daysFromCivil(yy, mm, dd) * 86400 + hh * 3600 + mi * 60 + ss;
      const result = handleLOCAL(data, W);
      outputLines.push(`${line} -> ${result}`);
    }
  }

  process.stdout.write(outputLines.join('\n') + '\n');
}

