// MARK: - Buffered Socket

final class BSocket {
    let fd: Int32
    var buf: [UInt8] = []

    init?(host: String, port: Int) {
        fd = socket(AF_INET, SOCK_STREAM, 0)
        guard fd >= 0 else { return nil }
