                let line = String(decoding: buf[0..<end], as: UTF8.self)
                buf.removeFirst(nl + 1)
                return line
            }
            var tmp = [UInt8](repeating: 0, count: 4096)
            let n = tmp.withUnsafeMutableBufferPointer { Foundation.read(fd, $0.baseAddress, $0.count) }
            if n <= 0 { return nil }
            buf.append(contentsOf: tmp[0..<n])
        }
    }

    func readExactly(_ n: Int) -> Data? {
        if n == 0 { return Data() }
        var result = Data()
        if !buf.isEmpty {
            let take = min(n, buf.count)
            result.append(contentsOf: buf[0..<take])
            buf.removeFirst(take)
        }
        while result.count < n {
            let rem = n - result.count
            var tmp = [UInt8](repeating: 0, count: rem)
            let got = tmp.withUnsafeMutableBufferPointer { Foundation.read(fd, $0.baseAddress, $0.count) }
            if got <= 0 { return nil }
            result.append(contentsOf: tmp[0..<got])
        }
        return result
    }

