    let b1 = h[h.startIndex + 1]
    let fin = (b0 & 0x80) != 0
    let opcode = b0 & 0x0F
    let len7 = Int(b1 & 0x7F)
    var payloadLen = len7
    if len7 == 126 {
        guard let e = s.readExactly(2) else { return nil }
        payloadLen = Int(e[e.startIndex]) << 8 | Int(e[e.startIndex + 1])
    } else if len7 == 127 {
        guard let e = s.readExactly(8) else { return nil }
        payloadLen = 0
        for i in 0..<8 { payloadLen = payloadLen << 8 | Int(e[e.startIndex + i]) }
    }
    guard let payload = s.readExactly(payloadLen) else { return nil }
    return WSFrame(fin: fin, opcode: opcode, payload: payload)
}

