        addr.sin_port = in_port_t(port).bigEndian
        inet_pton(AF_INET, host, &addr.sin_addr)
        let r = withUnsafePointer(to: &addr) { p in
            p.withMemoryRebound(to: sockaddr.self, capacity: 1) { sa in
                connect(fd, sa, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }
        guard r == 0 else { Darwin.close(fd); return nil }
    }

    func readLine() -> String? {
        while true {
            if let nl = buf.firstIndex(of: 0x0A) {
                var end = nl
                if nl > 0 && buf[nl - 1] == 0x0D { end = nl - 1 }
                let line = String(decoding: buf[0..<end], as: UTF8.self)
                buf.removeFirst(nl + 1)
                return line
            }
            var tmp = [UInt8](repeating: 0, count: 4096)
            let n = tmp.withUnsafeMutableBufferPointer { Darwin.read(fd, $0.baseAddress, $0.count) }
            if n <= 0 { return nil }
            buf.append(contentsOf: tmp[0..<n])
        }
    }

    func readExactly(_ n: Int) -> Data? {
        if n == 0 { return Data() }
        var result = Data()
        if !buf.isEmpty {
            let take = min(n, buf.count)
            result.append(contentsOf: buf[0..<take])
            buf.removeFirst(take)
        }
        while result.count < n {
            let rem = n - result.count
            var tmp = [UInt8](repeating: 0, count: rem)
            let got = tmp.withUnsafeMutableBufferPointer { Darwin.read(fd, $0.baseAddress, $0.count) }
            if got <= 0 { return nil }
            result.append(contentsOf: tmp[0..<got])
        }
        return result
    }

    func writeAll(_ data: Data) {
        var off = 0
        data.withUnsafeBytes { ptr in
            while off < data.count {
                let n = Darwin.write(fd, ptr.baseAddress!.advanced(by: off), data.count - off)
                if n <= 0 { break }
                off += n
            }
        }
    }

    func closeSocket() { Darwin.close(fd) }
}

// MARK: - Frame I/O

struct WSFrame {
    let fin: Bool
    let opcode: UInt8
    let payload: Data
}

func readFrame(_ s: BSocket) -> WSFrame? {
    guard let h = s.readExactly(2) else { return nil }
    let b0 = h[h.startIndex]
    let b1 = h[h.startIndex + 1]
    let fin = (b0 & 0x80) != 0
    let opcode = b0 & 0x0F
    let len7 = Int(b1 & 0x7F)
    var payloadLen = len7
    if len7 == 126 {
        guard let e = s.readExactly(2) else { return nil }
        payloadLen = Int(e[e.startIndex]) << 8 | Int(e[e.startIndex + 1])
    } else if len7 == 127 {
        guard let e = s.readExactly(8) else { return nil }
        payloadLen = 0
        for i in 0..<8 { payloadLen = payloadLen << 8 | Int(e[e.startIndex + i]) }
    }
    guard let payload = s.readExactly(payloadLen) else { return nil }
    return WSFrame(fin: fin, opcode: opcode, payload: payload)
}

func sendFrame(_ s: BSocket, opcode: UInt8, payload: Data) {
    var frame = [UInt8]()
    frame.append(0x80 | opcode) // FIN=1, RSV=0
    let mask = randomMaskKey()
    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8(len >> 8))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in stride(from: 7, through: 0, by: -1) {
            frame.append(UInt8((len >> (i * 8)) & 0xFF))
        }
    }
    frame.append(contentsOf: mask)
    for i in 0..<len {
        frame.append(payload[payload.startIndex + i] ^ mask[i % 4])
    }
    s.writeAll(Data(frame))
}

// MARK: - Session

func runSession(url: String) {
    guard let (host, port, target) = parseWSURL(url) else { return }
    guard let sock = BSocket(host: host, port: port) else { return }

    // Handshake
    let keyBytes = randomBytes(16)
    let wsKey = Data(keyBytes).base64EncodedString()
    var req = "GET \(target) HTTP/1.1\r\n"
    req += "Host: \(host):\(port)\r\n"
    req += "Upgrade: websocket\r\n"
    req += "Connection: Upgrade\r\n"
    req += "Sec-WebSocket-Version: 13\r\n"
    req += "Sec-WebSocket-Key: \(wsKey)\r\n"
    req += "\r\n"
    sock.writeAll(req.data(using: .ascii)!)

    // Read response headers
    var statusLine = ""
    var headers: [String: String] = [:]
    var first = true
    var headerOK = true
    while true {
        guard let line = sock.readLine() else { headerOK = false; break }
        if first { statusLine = line; first = false; continue }
        if line.isEmpty { break }
        if let ci = line.firstIndex(of: ":") {
            let name = String(line[line.startIndex..<ci]).lowercased()
            let val = String(line[line.index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            headers[name] = val
        }
    }

    if !headerOK { sock.closeSocket(); return }

    // Check status
    let statusParts = statusLine.split(separator: " ", maxSplits: 2, omittingEmptySubsequences: false)
    guard statusParts.count >= 2, let code = Int(statusParts[1]) else { sock.closeSocket(); return }
    if code != 101 {
        let reason = statusParts.count >= 3 ? String(statusParts[2]) : ""
        print("handshake failed: \(code) \(reason)")
        sock.closeSocket()
        return
    }

    // Check Sec-WebSocket-Accept
    let expectedAccept = computeAccept(wsKey)
    guard let accept = headers["sec-websocket-accept"], accept == expectedAccept else {
        print("handshake failed: bad Sec-WebSocket-Accept")
        sock.closeSocket()
        return
    }

    // Message loop
    var textBuf = Data()
    var binBuf = Data()
    var curOp: UInt8 = 0
    var inMsg = false
    var expectBin = false
    var closing = false
    var sentClose = false

    func handleCloseFrame(_ frame: WSFrame) {
        var code = 1005
        var reason = ""
        if frame.payload.count >= 2 {
            code = Int(frame.payload[frame.payload.startIndex]) << 8 | Int(frame.payload[frame.payload.startIndex + 1])
            if frame.payload.count > 2 {
                reason = String(decoding: frame.payload[(frame.payload.startIndex + 2)...], as: UTF8.self)
            }
        }
        if reason.isEmpty {
            print("closed \(code)")
        } else {
            print("closed \(code) \(reason)")
        }
        if !sentClose {
            var cp = Data(count: 2)
            cp[0] = UInt8(code >> 8)
            cp[1] = UInt8(code & 0xFF)
            sendFrame(sock, opcode: 8, payload: cp)
            sentClose = true
        }
        sock.closeSocket()
    }

    func processText(_ data: Data) {
        let msg = String(decoding: data, as: UTF8.self)
        if closing { return }

        if msg.hasPrefix("ADD ") {
            let rest = String(msg.dropFirst(4))
            let parts = rest.split(separator: " ", maxSplits: 1, omittingEmptySubsequences: false)
            guard parts.count == 2, let a = Int(parts[0]), let b = Int(parts[1]) else { return }
            let sum = a + b
            let reply = String(sum)
            sendFrame(sock, opcode: 1, payload: reply.data(using: .utf8)!)
            print("ADD \(parts[0]) \(parts[1]) -> \(sum)")
        } else if msg.hasPrefix("REV ") {
            let text = String(msg.dropFirst(4))
            let reversed = String(String.UnicodeScalarView(text.unicodeScalars.reversed()))
            sendFrame(sock, opcode: 1, payload: reversed.data(using: .utf8)!)
            print("REV \(text) -> \(reversed)")
        } else if msg == "SHA1" {
            expectBin = true
        } else if msg == "BYE" {
            var cp = Data(count: 2)
            cp[0] = 0x03
            cp[1] = 0xE8
            sendFrame(sock, opcode: 8, payload: cp)
            sentClose = true
            closing = true
        }
    }

    func processBinary(_ data: Data) {
        if !expectBin { return }
        expectBin = false
        let hex = sha1Hex(data)
        sendFrame(sock, opcode: 1, payload: hex.data(using: .utf8)!)
        print("SHA1 \(data.count) -> \(hex)")
    }

    while true {
        guard let frame = readFrame(sock) else { break }

        switch frame.opcode {
        case 9: // ping
            sendFrame(sock, opcode: 10, payload: frame.payload)
        case 10: // pong
            continue
        case 8: // close
            handleCloseFrame(frame)
            return
        case 1: // text start
            if closing { continue }
            textBuf = frame.payload
            curOp = 1
            inMsg = true
            if frame.fin { processText(textBuf); inMsg = false }
        case 2: // binary start
            if closing { continue }
            binBuf = frame.payload
            curOp = 2
            inMsg = true
            if frame.fin { processBinary(binBuf); inMsg = false }
        case 0: // continuation
            if !inMsg { continue }
            if curOp == 1 { textBuf.append(frame.payload) }
            else { binBuf.append(frame.payload) }
            if frame.fin {
                if curOp == 1 { processText(textBuf) }
                else { processBinary(binBuf) }
                inMsg = false
            }
        default:
            continue
        }
    }

    sock.closeSocket()
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count > 1 else { exit(0) }
for i in 1..<args.count {
    print("session \(i)")
    runSession(url: args[i])
}
exit(0)
