import Foundation

// --- JSON string encoding (custom rules) ---
func jsonStr(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{08}": r += "\\b"
        case "\u{0C}": r += "\\f"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if scalar.value < 0x20 {
                r += String(format: "\\u%04x", scalar.value)
            } else {
                r.unicodeScalars.append(scalar)
            }
        }
    }
    r += "\""
    return r
}

// --- RFC 4180 CSV parser ---
func parseCsv(_ data: Data) -> [[String]] {
    var bytes = [UInt8](data)
    var off = 0
    if bytes.count >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF {
        off = 3
    }
    guard let str = String(data: Data(bytes[off...]), encoding: .utf8) else {
        fatalError("CSV UTF-8 decode failed")
    }
    var rows: [[String]] = []
    var row: [String] = []
    var field = ""
    var inQ = false
    let ch = Array(str)
    var i = 0
    while i < ch.count {
        let c = ch[i]
        if inQ {
            if c == "\"" {
                if i + 1 < ch.count && ch[i + 1] == "\"" {
                    field.append("\"")
                    i += 2
                } else {
                    inQ = false
                    i += 1
                }
            } else {
                field.append(c)
                i += 1
            }
        } else {
            if c == "\"" {
                inQ = true
                i += 1
            } else if c == "," {
                row.append(field)
                field = ""
                i += 1
            } else if c == "\r" {
                if i + 1 < ch.count && ch[i + 1] == "\n" {
                    row.append(field)
                    field = ""
                    rows.append(row)
                    row = []
                    i += 2
                } else {
                    field.append(c)
                    i += 1
                }
            } else if c == "\n" {
                row.append(field)
                field = ""
                rows.append(row)
                row = []
                i += 1
            } else {
                field.append(c)
                i += 1
            }
        }
    }
    if !field.isEmpty || !row.isEmpty {
        row.append(field)
        rows.append(row)
    }
