    let name: String
    let arguments: String
}

struct ChatMsg {
    let role: String
    let content: String?
    let toolCalls: [ToolCallInfo]?
    let toolCallId: String?
}

// --- Serialize a message for the request body ---
func serializeMsg(_ m: ChatMsg) -> String {
    var s = "{"
    s += "\"role\":\(jsonStr(m.role))"
    if m.role == "tool" {
        s += ",\"tool_call_id\":\(jsonStr(m.toolCallId!))"
        s += ",\"content\":\(jsonStr(m.content!))"
    } else {
        if let c = m.content {
            s += ",\"content\":\(jsonStr(c))"
        } else {
            s += ",\"content\":null"
        }
        if let tcs = m.toolCalls {
            s += ",\"tool_calls\":["
            for (i, tc) in tcs.enumerated() {
                if i > 0 { s += "," }
                s += "{\"id\":\(jsonStr(tc.id)),\"type\":\(jsonStr(tc.type)),\"function\":{\"name\":\(jsonStr(tc.name)),\"arguments\":\(jsonStr(tc.arguments))}}"
            }
            s += "]"
        }
    }
    s += "}"
    return s
}

// --- Main program ---
let cmdArgs = CommandLine.arguments
guard cmdArgs.count >= 3 else {
    fputs("Usage: main <data_dir> <base_url>\n", stderr)
    exit(1)
}
let dataDir = cmdArgs[1]
let baseUrl = cmdArgs[2]

// Read task.json
let taskRaw = try! Data(contentsOf: URL(fileURLWithPath: "\(dataDir)/task.json"))
let task = try! JSONSerialization.jsonObject(with: taskRaw) as! [String: Any]
let apiKey = task["api_key"] as! String
let modelName = task["model"] as! String
let systemContent = task["system"] as! String
let userContent = task["user"] as! String
let toolsArray = task["tools"]!

// Serialize tools array once (compact)
let toolsRawData = try! JSONSerialization.data(withJSONObject: toolsArray, options: [])
let toolsJsonStr = String(data: toolsRawData, encoding: .utf8)!

// Read rates.json
let ratesRaw = try! Data(contentsOf: URL(fileURLWithPath: "\(dataDir)/rates.json"))
let ratesObj = try! JSONSerialization.jsonObject(with: ratesRaw) as! [String: Any]
let ratesMap = ratesObj["rates"] as! [String: Any]
func getRate(_ c: String) -> Int {
    return (ratesMap[c] as! NSNumber).intValue
}

// Read inventory.csv
let invRaw = try! Data(contentsOf: URL(fileURLWithPath: "\(dataDir)/inventory.csv"))
let csvRows = parseCsv(invRaw)

struct InvItem {
    let sku: String
    let name: String
    let priceCents: Int
    let currency: String
    let stock: Int
}
var inventory: [String: InvItem] = [:]
if csvRows.count > 1 {
    for row in csvRows[1...] {
        guard row.count >= 5 else { continue }
        let item = InvItem(
            sku: row[0],
            name: row[1],
            priceCents: Int(row[2])!,
            currency: row[3],
            stock: Int(row[4])!
        )
        inventory[item.sku] = item
    }
}

// --- Tool execution ---
func executeTool(name: String, arguments: String) -> String {
    if name == "inventory_lookup" {
        guard let obj = try? JSONSerialization.jsonObject(with: Data(arguments.utf8)) as? [String: Any] else {
            return "{\"error\":\(jsonStr("unknown tool: \(name)"))}"
        }
        let sku = obj["sku"] as! String
        if let item = inventory[sku] {
            return "{\"sku\":\(jsonStr(item.sku)),\"name\":\(jsonStr(item.name)),\"price_cents\":\(item.priceCents),\"currency\":\(jsonStr(item.currency)),\"stock\":\(item.stock)}"
        } else {
            return "{\"error\":\(jsonStr("unknown sku: \(sku)"))}"
        }
    } else if name == "convert_currency" {
        guard let obj = try? JSONSerialization.jsonObject(with: Data(arguments.utf8)) as? [String: Any] else {
            return "{\"error\":\(jsonStr("unknown tool: \(name)"))}"
        }
        let amountCents = (obj["amount_cents"] as! NSNumber).intValue
        let from = obj["from"] as! String
        let to = obj["to"] as! String
        let rFrom = getRate(from)
        let rTo = getRate(to)
        // HALF_UP rounding: (2*amount*rTo + rFrom) div (2*rFrom)
        let converted = (2 * amountCents * rTo + rFrom) / (2 * rFrom)
        return "{\"amount_cents\":\(converted),\"currency\":\(jsonStr(to))}"
    } else {
        return "{\"error\":\(jsonStr("unknown tool: \(name)"))}"
    }
}

// --- HTTP request ---
func doRequest(body: String) -> (Int, Data) {
    let url = URL(string: "\(baseUrl)/chat/completions")!
    var req = URLRequest(url: url)
    req.httpMethod = "POST"
    req.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
    req.setValue("application/json", forHTTPHeaderField: "Content-Type")
    req.httpBody = Data(body.utf8)

    let sem = DispatchSemaphore(value: 0)
    var code = 0
    var respData = Data()
    let session = URLSession(configuration: URLSessionConfiguration.default)
    let t = session.dataTask(with: req) { data, response, _ in
        if let hr = response as? HTTPURLResponse { code = hr.statusCode }
        if let d = data { respData = d }
        sem.signal()
    }
    t.resume()
    sem.wait()
    return (code, respData)
}

// --- Build initial conversation ---
var conversation: [ChatMsg] = [
    ChatMsg(role: "system", content: systemContent, toolCalls: nil, toolCallId: nil),
    ChatMsg(role: "user", content: userContent, toolCalls: nil, toolCallId: nil)
]

var outputLines: [String] = []
var sumPrompt = 0
var sumCompletion = 0
var sumTotal = 0
var numRequests = 0

// --- Main loop ---
var finished = false
while !finished {
    // Build request JSON body
    var body = "{"
    body += "\"model\":\(jsonStr(modelName)),"
    body += "\"messages\":["
    for (i, msg) in conversation.enumerated() {
        if i > 0 { body += "," }
        body += serializeMsg(msg)
    }
    body += "],"
    body += "\"tools\":\(toolsJsonStr),"
    body += "\"tool_choice\":\"auto\""
    body += "}"

    numRequests += 1
    let (status, respData) = doRequest(body: body)

    if status != 200 {
        for line in outputLines { print(line) }
        var errMsg = ""
        if let errObj = try? JSONSerialization.jsonObject(with: respData) as? [String: Any],
           let errDict = errObj["error"] as? [String: Any],
           let msg = errDict["message"] as? String {
            errMsg = msg
        }
        print("ERROR \(status) \(errMsg)")
        exit(0)
    }

    // Parse response JSON
    let resp = try! JSONSerialization.jsonObject(with: respData) as! [String: Any]

    // Accumulate usage
    if let usage = resp["usage"] as? [String: Any] {
        sumPrompt += (usage["prompt_tokens"] as! NSNumber).intValue
        sumCompletion += (usage["completion_tokens"] as! NSNumber).intValue
        sumTotal += (usage["total_tokens"] as! NSNumber).intValue
    }

    let choices = resp["choices"] as! [[String: Any]]
    let choice = choices[0]
    let finishReason = choice["finish_reason"] as! String
    let msgDict = choice["message"] as! [String: Any]
    let role = msgDict["role"] as! String

    // Extract content (string or null)
    let content: String?
    if let raw = msgDict["content"], !(raw is NSNull) {
        content = raw as? String
    } else {
        content = nil
    }

    if finishReason == "stop" {
        outputLines.append("FINAL \(content ?? "")")
        finished = true
    } else if finishReason == "tool_calls" {
        // SAY line if content is a string
        if let c = content {
            outputLines.append("SAY \(c)")
        }

        // Parse tool_calls
        let tcArr = msgDict["tool_calls"] as! [[String: Any]]
        var calls: [ToolCallInfo] = []
        for tc in tcArr {
            let id = tc["id"] as! String
            let type = tc["type"] as! String
            let fn = tc["function"] as! [String: Any]
            let name = fn["name"] as! String
            let args = fn["arguments"] as! String
            calls.append(ToolCallInfo(id: id, type: type, name: name, arguments: args))
        }

        // CALL lines
        for tc in calls {
            outputLines.append("CALL \(tc.id) \(tc.name)")
        }

        // Execute tools, collect results
        var results: [String] = []
        for tc in calls {
            let res = executeTool(name: tc.name, arguments: tc.arguments)
            results.append(res)
            outputLines.append("RESULT \(tc.id) \(res)")
        }

        // Append assistant message to conversation
        conversation.append(ChatMsg(role: role, content: content, toolCalls: calls, toolCallId: nil))

        // Append tool result messages
        for (i, tc) in calls.enumerated() {
            conversation.append(ChatMsg(role: "tool", content: results[i], toolCalls: nil, toolCallId: tc.id))
        }
    }
}

// Print all output lines
for line in outputLines { print(line) }
print("USAGE prompt=\(sumPrompt) completion=\(sumCompletion) total=\(sumTotal) requests=\(numRequests)")
exit(0)
