        let key_bytes = random_bytes(16);
        let key_b64 = base64_encode(&key_bytes);
        let handshake = format!(
            "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
            path, host, port, key_b64
        );
        if reader.stream.write_all(handshake.as_bytes()).is_err() { continue; }

        let status_line = match reader.read_line() { Some(l) => l, None => continue };
        let status_str = String::from_utf8_lossy(&status_line).to_string();
        let parts: Vec<&str> = status_str.splitn(3, ' ').collect();
        if parts.len() < 2 { continue; }
        let status_code: u16 = parts[1].parse().unwrap_or(0);
        let reason_phrase = if parts.len() >= 3 { parts[2] } else { "" };

        let mut accept_hdr: Option<String> = None;
        loop {
            match reader.read_line() {
                Some(l) if l.is_empty() => break,
                Some(l) => {
                    let s = String::from_utf8_lossy(&l).to_string();
                    if let Some(c) = s.find(':') {
                        let name = s[..c].trim().to_lowercase();
                        let val = s[c+1..].trim().to_string();
                        if name == "sec-websocket-accept" { accept_hdr = Some(val); }
                    }
                }
                None => break,
            }
        }

        if status_code != 101 {
            println!("handshake failed: {} {}", status_code, reason_phrase);
            continue;
        }

        let mut accept_input = key_b64.as_bytes().to_vec();
        accept_input.extend_from_slice(b"258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
        let expected_accept = base64_encode(&sha1(&accept_input));

        match &accept_hdr {
            Some(a) if a == &expected_accept => {},
            _ => { println!("handshake failed: bad Sec-WebSocket-Accept"); continue; }
        }

        // Frame processing
        let mut sent_close = false;
        let mut bye_mode = false;
        let mut pending_sha1 = false;
        let mut frag_op: Option<u8> = None;
        let mut frag_buf: Vec<u8> = Vec::new();

        loop {
            let b0 = match reader.read_byte() { Some(b) => b, None => break };
            let b1 = match reader.read_byte() { Some(b) => b, None => break };
