            let opcode = b0 & 0x0F;
            let len7 = (b1 & 0x7F) as u64;
            let payload_len: u64 = if len7 == 126 {
                match reader.read_exact(2) { Some(b) => u16::from_be_bytes([b[0],b[1]]) as u64, None => break }
            } else if len7 == 127 {
                match reader.read_exact(8) { Some(b) => u64::from_be_bytes([b[0],b[1],b[2],b[3],b[4],b[5],b[6],b[7]]), None => break }
            } else { len7 };
            let payload = if payload_len > 0 {
                match reader.read_exact(payload_len as usize) { Some(b) => b, None => break }
            } else { Vec::new() };

            match opcode {
                8 => {
                    let code = if payload.len() >= 2 { u16::from_be_bytes([payload[0], payload[1]]) } else { 1005 };
                    let reason = if payload.len() > 2 { String::from_utf8_lossy(&payload[2..]).to_string() } else { String::new() };
                    if !sent_close {
                        send_frame(&mut reader.stream, 8, &code.to_be_bytes());
                        sent_close = true;
                    }
                    if reason.is_empty() { println!("closed {}", code); }
                    else { println!("closed {} {}", code, reason); }
                    break;
                }
                9 => { send_frame(&mut reader.stream, 10, &payload); }
                10 => {}
                1 | 2 => {
                    if fin {
                        let data = if frag_op.is_some() || !frag_buf.is_empty() {
                            frag_buf.extend_from_slice(&payload);
                            let d = std::mem::take(&mut frag_buf);
                            let op = frag_op.take().unwrap_or(opcode);
                            (op, d)
                        } else {
                            (opcode, payload)
                        };
                        handle_msg(data.0, &data.1, &mut reader.stream, &mut sent_close, &mut bye_mode, &mut pending_sha1);
                    } else {
                        frag_op = Some(opcode);
                        frag_buf = payload;
                    }
                }
                0 => {
                    frag_buf.extend_from_slice(&payload);
                    if fin {
                        let op = frag_op.take().unwrap_or(1);
                        let data = std::mem::take(&mut frag_buf);
                        handle_msg(op, &data, &mut reader.stream, &mut sent_close, &mut bye_mode, &mut pending_sha1);
                    }
                }
                _ => {}
            }
        }
    }
}

fn handle_msg(opcode: u8, data: &[u8], stream: &mut TcpStream, sent_close: &mut bool, bye_mode: &mut bool, pending_sha1: &mut bool) {
    if *bye_mode { return; }

    if *pending_sha1 {
        let digest = sha1(data);
        let hex = bytes_to_hex(&digest);
        send_frame(stream, 1, hex.as_bytes());
        println!("SHA1 {} -> {}", data.len(), hex);
        *pending_sha1 = false;
        return;
    }

    if opcode == 1 {
        let text = String::from_utf8_lossy(data).to_string();
        if text == "BYE" {
            send_frame(stream, 8, &[0x03, 0xE8]);
            *sent_close = true;
            *bye_mode = true;
        } else if text.starts_with("ADD ") {
            let rest = &text[4..];
            let sp = rest.find(' ').unwrap();
            let a: i64 = rest[..sp].parse().unwrap();
            let b: i64 = rest[sp+1..].parse().unwrap();
            let sum = a + b;
            let reply = sum.to_string();
            send_frame(stream, 1, reply.as_bytes());
            println!("{} -> {}", text, reply);
        } else if text.starts_with("REV ") {
            let rest = &text[4..];
            let reversed: String = rest.chars().rev().collect();
            send_frame(stream, 1, reversed.as_bytes());
            println!("REV {} -> {}", rest, reversed);
        } else if text == "SHA1" {
            *pending_sha1 = true;
        }
    }
}
