fn http_post(host: &str, port: u16, host_hdr: &str, path: &str, api_key: &str, body: &str) -> (u16, String) {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connect failed");
    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        path, host_hdr, api_key, body.len(), body
    );
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut reader = BufReader::new(&stream);
    let mut line = String::new();
    reader.read_line(&mut line).unwrap();
    let status: u16 = line.split_whitespace().nth(1).unwrap().parse().unwrap();

    let mut clen: usize = 0;
    loop {
        line.clear();
        reader.read_line(&mut line).unwrap();
        if line == "\r\n" || line == "\n" || line.is_empty() { break; }
        let lower = line.to_lowercase();
        if lower.starts_with("content-length:") {
            clen = line[15..].trim().parse().unwrap();
        }
    }

    let mut body_buf = vec![0u8; clen];
    reader.read_exact(&mut body_buf).unwrap();
    (status, String::from_utf8(body_buf).unwrap())
}

fn parse_url(url: &str) -> (String, u16, String, String) {
    let after = url.strip_prefix("http://").unwrap();
    let (hp, path) = after.split_once('/').unwrap_or((after, ""));
    let (host, port) = if let Some((h, p)) = hp.split_once(':') {
        (h.to_string(), p.parse::<u16>().unwrap())
    } else {
        (hp.to_string(), 80u16)
    };
    (host, port, format!("/{}", path), hp.to_string())
}

