        match self {
            JV::Int(i) => Some(*i),
            JV::Float(f) => Some(*f as i64),
            _ => None,
        }
    }
}

struct JP<'a> { s: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { s: s.as_bytes(), p: 0 } }
    fn ws(&mut self) {
        while self.p < self.s.len() && (self.s[self.p] == b' ' || self.s[self.p] == b'\t' || self.s[self.p] == b'\n' || self.s[self.p] == b'\r') {
            self.p += 1;
        }
    }
    fn val(&mut self) -> JV {
        self.ws();
        match self.s[self.p] {
            b'n' => { self.p += 4; JV::Null }
            b't' => { self.p += 4; JV::Bool(true) }
            b'f' => { self.p += 5; JV::Bool(false) }
            b'"' => JV::Str(self.string()),
            b'[' => self.array(),
            b'{' => self.object(),
            _ => self.number(),
        }
    }
    fn string(&mut self) -> String {
        self.p += 1;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let c = self.s[self.p]; self.p += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.s[self.p]; self.p += 1;
                    match e {
                        b'"' => buf.push(b'"'),
                        b'\\' => buf.push(b'\\'),
                        b'/' => buf.push(b'/'),
                        b'b' => buf.push(8),
                        b'f' => buf.push(12),
                        b'n' => buf.push(b'\n'),
                        b'r' => buf.push(b'\r'),
                        b't' => buf.push(b'\t'),
                        b'u' => {
                            let hi = self.hex4();
                            if hi >= 0xD800 && hi <= 0xDBFF {
                                self.p += 2;
                                let lo = self.hex4();
                                let cp = 0x10000u32 + ((hi as u32 - 0xD800) << 10) + (lo as u32 - 0xDC00);
                                let mut tmp = [0u8; 4];
                                let enc = char::from_u32(cp).unwrap().encode_utf8(&mut tmp);
                                buf.extend_from_slice(enc.as_bytes());
                            } else {
                                let mut tmp = [0u8; 4];
                                let enc = char::from_u32(hi as u32).unwrap().encode_utf8(&mut tmp);
                                buf.extend_from_slice(enc.as_bytes());
                            }
                        }
                        _ => unreachable!(),
                    }
                }
                _ => buf.push(c),
            }
        }
        String::from_utf8(buf).unwrap()
    }
    fn hex4(&mut self) -> u16 {
        let mut v = 0u16;
        for _ in 0..4 {
            let c = self.s[self.p] as char; self.p += 1;
            v = v * 16 + c.to_digit(16).unwrap() as u16;
        }
        v
    }
    fn number(&mut self) -> JV {
        let st = self.p;
        if self.s[self.p] == b'-' { self.p += 1; }
        while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        let mut fl = false;
        if self.p < self.s.len() && self.s[self.p] == b'.' {
            fl = true; self.p += 1;
            while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        }
        if self.p < self.s.len() && (self.s[self.p] == b'e' || self.s[self.p] == b'E') {
            fl = true; self.p += 1;
            if self.p < self.s.len() && (self.s[self.p] == b'+' || self.s[self.p] == b'-') { self.p += 1; }
            while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        }
        let ns = std::str::from_utf8(&self.s[st..self.p]).unwrap();
        if fl { JV::Float(ns.parse().unwrap()) } else { JV::Int(ns.parse().unwrap()) }
    }
    fn array(&mut self) -> JV {
        self.p += 1;
        self.ws();
        let mut items = Vec::new();
        if self.p < self.s.len() && self.s[self.p] == b']' { self.p += 1; return JV::Arr(items); }
        loop {
            items.push(self.val());
            self.ws();
            if self.s[self.p] == b']' { self.p += 1; break; }
            self.p += 1;
        }
        JV::Arr(items)
    }
    fn object(&mut self) -> JV {
        self.p += 1;
        self.ws();
        let mut pairs = Vec::new();
        if self.p < self.s.len() && self.s[self.p] == b'}' { self.p += 1; return JV::Obj(pairs); }
        loop {
            self.ws();
            let key = self.string();
            self.ws();
            self.p += 1;
            let v = self.val();
            pairs.push((key, v));
            self.ws();
            if self.s[self.p] == b'}' { self.p += 1; break; }
            self.p += 1;
        }
        JV::Obj(pairs)
    }
}

fn parse_json(s: &str) -> JV {
    let mut jp = JP::new(s);
    jp.val()
}

fn json_esc(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{0008}' => r.push_str("\\b"),
            '\u{000C}' => r.push_str("\\f"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            _ => r.push(c),
        }
    }
    r
}

fn ser(v: &JV) -> String {
    match v {
        JV::Null => "null".into(),
        JV::Bool(b) => if *b { "true".into() } else { "false".into() },
        JV::Int(i) => format!("{}", i),
        JV::Float(f) => {
            if *f == f.floor() && f.abs() < 1e15 { format!("{}", *f as i64) }
            else { format!("{}", f) }
        }
        JV::Str(s) => format!("\"{}\"", json_esc(s)),
        JV::Arr(items) => format!("[{}]", items.iter().map(ser).collect::<Vec<_>>().join(",")),
        JV::Obj(pairs) => format!("{{{}}}", pairs.iter().map(|(k, v)| format!("\"{}\":{}", json_esc(k), ser(v))).collect::<Vec<_>>().join(",")),
    }
}

fn parse_csv(data: &[u8]) -> Vec<Vec<String>> {
    let mut start = 0;
    if data.len() >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF { start = 3; }
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut rec: Vec<String> = Vec::new();
    let mut fb: Vec<u8> = Vec::new();
    let mut q = false;
    let mut i = start;
    while i < data.len() {
        let c = data[i];
        if q {
            if c == b'"' {
                if i + 1 < data.len() && data[i + 1] == b'"' { fb.push(b'"'); i += 2; }
                else { q = false; i += 1; }
            } else { fb.push(c); i += 1; }
        } else {
            match c {
                b'"' => { q = true; i += 1; }
                b',' => { rec.push(String::from_utf8(fb.clone()).unwrap()); fb.clear(); i += 1; }
                b'\r' => {
                    if i + 1 < data.len() && data[i + 1] == b'\n' {
                        rec.push(String::from_utf8(fb.clone()).unwrap()); fb.clear();
                        records.push(rec.clone()); rec.clear(); i += 2;
                    } else { fb.push(c); i += 1; }
                }
                b'\n' => {
                    rec.push(String::from_utf8(fb.clone()).unwrap()); fb.clear();
                    records.push(rec.clone()); rec.clear(); i += 1;
                }
                _ => { fb.push(c); i += 1; }
            }
        }
    }
    if !fb.is_empty() || !rec.is_empty() {
        rec.push(String::from_utf8(fb).unwrap());
        records.push(rec);
    }
    records
}

fn http_post(host: &str, port: u16, host_hdr: &str, path: &str, api_key: &str, body: &str) -> (u16, String) {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connect failed");
    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        path, host_hdr, api_key, body.len(), body
    );
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut reader = BufReader::new(&stream);
    let mut line = String::new();
    reader.read_line(&mut line).unwrap();
    let status: u16 = line.split_whitespace().nth(1).unwrap().parse().unwrap();

    let mut clen: usize = 0;
    loop {
        line.clear();
        reader.read_line(&mut line).unwrap();
        if line == "\r\n" || line == "\n" || line.is_empty() { break; }
        let lower = line.to_lowercase();
        if lower.starts_with("content-length:") {
            clen = line[15..].trim().parse().unwrap();
        }
    }

    let mut body_buf = vec![0u8; clen];
    reader.read_exact(&mut body_buf).unwrap();
    (status, String::from_utf8(body_buf).unwrap())
}

fn parse_url(url: &str) -> (String, u16, String, String) {
    let after = url.strip_prefix("http://").unwrap();
    let (hp, path) = after.split_once('/').unwrap_or((after, ""));
    let (host, port) = if let Some((h, p)) = hp.split_once(':') {
        (h.to_string(), p.parse::<u16>().unwrap())
    } else {
        (hp.to_string(), 80u16)
    };
    (host, port, format!("/{}", path), hp.to_string())
}

fn execute_tool(name: &str, args_str: &str, inventory: &HashMap<String, (String, i64, String, i64)>, rates: &JV) -> String {
    match name {
        "inventory_lookup" => {
            let args = parse_json(args_str);
            let sku = args.get("sku").unwrap().as_str().unwrap();
            match inventory.get(sku) {
                Some((n, price, currency, stock)) => {
                    format!("{{\"sku\":\"{}\",\"name\":\"{}\",\"price_cents\":{},\"currency\":\"{}\",\"stock\":{}}}",
                        json_esc(sku), json_esc(n), price, json_esc(currency), stock)
                }
                None => {
                    format!("{{\"error\":\"unknown sku: {}\"}}", json_esc(sku))
                }
            }
        }
        "convert_currency" => {
            let args = parse_json(args_str);
            let amount = args.get("amount_cents").unwrap().as_int().unwrap();
            let from = args.get("from").unwrap().as_str().unwrap();
            let to = args.get("to").unwrap().as_str().unwrap();
            let rate_from = rates.get(from).unwrap().as_int().unwrap();
            let rate_to = rates.get(to).unwrap().as_int().unwrap();
            let converted = (2 * amount * rate_to + rate_from) / (2 * rate_from);
            format!("{{\"amount_cents\":{},\"currency\":\"{}\"}}", converted, json_esc(to))
        }
        _ => {
            format!("{{\"error\":\"unknown tool: {}\"}}", json_esc(name))
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
