    let inv_records = parse_csv(&inv_data);
    let mut inventory: HashMap<String, (String, i64, String, i64)> = HashMap::new();
    for r in &inv_records[1..] {
        inventory.insert(r[0].clone(), (r[1].clone(), r[2].parse().unwrap(), r[3].clone(), r[4].parse().unwrap()));
    }

    let rates_str = fs::read_to_string(format!("{}/rates.json", data_dir)).unwrap();
