            println!("FINAL {}", content);
            break;
        }

        // finish_reason == "tool_calls"
        let content_val = msg.get("content").unwrap();
        if let Some(cs) = content_val.as_str() {
            println!("SAY {}", cs);
        }

        let tool_calls = msg.get("tool_calls").unwrap();
        let tc_items = if let JV::Arr(items) = tool_calls { items } else { unreachable!() };

        for tci in tc_items.iter() {
            let id = tci.get("id").unwrap().as_str().unwrap();
