            let args_str = tci.get("function").unwrap().get("arguments").unwrap().as_str().unwrap();
            let result = execute_tool(&fname, args_str, &inventory, &rates_obj);
            println!("RESULT {} {}", id, result);
            tool_responses.push(JV::Obj(vec![
                ("role".into(), JV::Str("tool".into())),
                ("tool_call_id".into(), JV::Str(id)),
                ("content".into(), JV::Str(result)),
            ]));
        }

        // Append assistant message
        let mut assistant_fields: Vec<(String, JV)> = Vec::new();
        assistant_fields.push(("role".into(), JV::Str("assistant".into())));
        assistant_fields.push(("content".into(), content_val.clone()));
        assistant_fields.push(("tool_calls".into(), tool_calls.clone()));
        conv.push(JV::Obj(assistant_fields));

        for tr in tool_responses {
            conv.push(tr);
        }
    }

    println!("USAGE prompt={} completion={} total={} requests={}", tp, tc, tt, nreq);
}
