func formatOffset(_ offset: Int) -> String {
    let sign = offset < 0 ? "-" : "+"
    let a = abs(offset)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return "\(sign)\(String(format: "%02d", h)):\(String(format: "%02d", m)):\(String(format: "%02d", s))"
    }
    return "\(sign)\(String(format: "%02d", h)):\(String(format: "%02d", m))"
}

func formatLocal(_ t: Int64, _ utcOff: Int, _ abbr: String) -> String {
    let local = t + Int64(utcOff)
    let (y, m, d, h, mi, s) = epochToDate(local)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", y, m, d, h, mi, s) + formatOffset(utcOff) + " " + abbr
