    var transTypeIdx: [Int]
    var types: [TzType]
    var abbrs: [UInt8]
    var footerTZ: String
}

struct PosixRule {
    var hasDst: Bool
    var stdName: String
    var stdOff: Int
    var dstName: String
    var dstOff: Int
    var startM: Int, startW: Int, startD: Int, startT: Int
    var endM: Int, endW: Int, endD: Int, endT: Int
}

func parseTzFile(_ data: [UInt8]) -> TzFile {
    let isutcnt1 = Int(readBE32(data, 20))
    let isstdcnt1 = Int(readBE32(data, 24))
    let leapcnt1 = Int(readBE32(data, 28))
    let timecnt1 = Int(readBE32(data, 32))
    let typecnt1 = Int(readBE32(data, 36))
    let charcnt1 = Int(readBE32(data, 40))
    let block1Size = timecnt1*4 + timecnt1 + typecnt1*6 + charcnt1 + leapcnt1*8 + isstdcnt1 + isutcnt1
    let h2 = 44 + block1Size

    let isutcnt = Int(readBE32(data, h2 + 20))
    let isstdcnt = Int(readBE32(data, h2 + 24))
    let leapcnt = Int(readBE32(data, h2 + 28))
    let timecnt = Int(readBE32(data, h2 + 32))
    let typecnt = Int(readBE32(data, h2 + 36))
    let charcnt = Int(readBE32(data, h2 + 40))

    var pos = h2 + 44
    var transTimes = [Int64]()
    for _ in 0..<timecnt { transTimes.append(readBE64(data, pos)); pos += 8 }
    var transTypeIdx = [Int]()
    for _ in 0..<timecnt { transTypeIdx.append(Int(data[pos])); pos += 1 }
    var types = [TzType]()
    for _ in 0..<typecnt {
        types.append(TzType(gmtoff: readBE32(data, pos), isdst: data[pos+4], abbrIdx: data[pos+5]))
        pos += 6
    }
    let abbrs = Array(data[pos..<pos+charcnt])
    pos += charcnt
    pos += leapcnt * 12 + isstdcnt + isutcnt

    var footer = ""
    if pos < data.count && data[pos] == 0x0A {
        pos += 1
        while pos < data.count && data[pos] != 0x0A {
            footer.append(Character(UnicodeScalar(data[pos])))
            pos += 1
        }
    }
    return TzFile(transTimes: transTimes, transTypeIdx: transTypeIdx, types: types, abbrs: abbrs, footerTZ: footer)
}

func getAbbr(_ abbrs: [UInt8], _ idx: UInt8) -> String {
    var s = ""
    var i = Int(idx)
    while i < abbrs.count && abbrs[i] != 0 { s.append(Character(UnicodeScalar(abbrs[i]))); i += 1 }
    return s
}

func parsePosixTZ(_ s: String) -> PosixRule? {
    if s.isEmpty { return nil }
    let chars = Array(s)
    var pos = 0

    func parseName() -> String {
        if pos < chars.count && chars[pos] == "<" {
            pos += 1
            var name = ""
            while pos < chars.count && chars[pos] != ">" { name.append(chars[pos]); pos += 1 }
            pos += 1
            return name
        } else {
            var name = ""
            while pos < chars.count && chars[pos].isLetter { name.append(chars[pos]); pos += 1 }
            return name
        }
    }

    func parseOffset() -> Int {
        var sign = 1
        if pos < chars.count && chars[pos] == "-" { sign = -1; pos += 1 }
        else if pos < chars.count && chars[pos] == "+" { pos += 1 }
        var h = 0
        while pos < chars.count && chars[pos].isNumber { h = h*10 + Int(String(chars[pos]))!; pos += 1 }
        var m = 0, sec = 0
        if pos < chars.count && chars[pos] == ":" {
            pos += 1
            while pos < chars.count && chars[pos].isNumber { m = m*10 + Int(String(chars[pos]))!; pos += 1 }
        }
        if pos < chars.count && chars[pos] == ":" {
            pos += 1
            while pos < chars.count && chars[pos].isNumber { sec = sec*10 + Int(String(chars[pos]))!; pos += 1 }
        }
        return sign * (h*3600 + m*60 + sec)
    }

    func parseTime() -> Int {
        var sign = 1
        if pos < chars.count && chars[pos] == "-" { sign = -1; pos += 1 }
        else if pos < chars.count && chars[pos] == "+" { pos += 1 }
        var h = 0
        while pos < chars.count && chars[pos].isNumber { h = h*10 + Int(String(chars[pos]))!; pos += 1 }
        var m = 0, sec = 0
        if pos < chars.count && chars[pos] == ":" {
            pos += 1
            while pos < chars.count && chars[pos].isNumber { m = m*10 + Int(String(chars[pos]))!; pos += 1 }
        }
        if pos < chars.count && chars[pos] == ":" {
            pos += 1
            while pos < chars.count && chars[pos].isNumber { sec = sec*10 + Int(String(chars[pos]))!; pos += 1 }
        }
        return sign * (h*3600 + m*60 + sec)
    }

    func parseMWD() -> (Int, Int, Int) {
        pos += 1 // skip 'M'
        var m = 0
        while pos < chars.count && chars[pos].isNumber { m = m*10 + Int(String(chars[pos]))!; pos += 1 }
        pos += 1 // skip '.'
        var w = 0
        while pos < chars.count && chars[pos].isNumber { w = w*10 + Int(String(chars[pos]))!; pos += 1 }
        pos += 1 // skip '.'
        var d = 0
        while pos < chars.count && chars[pos].isNumber { d = d*10 + Int(String(chars[pos]))!; pos += 1 }
        return (m, w, d)
    }

    var rule = PosixRule(hasDst: false, stdName: "", stdOff: 0, dstName: "", dstOff: 0,
                         startM: 3, startW: 2, startD: 0, startT: 2*3600,
                         endM: 11, endW: 1, endD: 0, endT: 2*3600)
    rule.stdName = parseName()
    rule.stdOff = parseOffset()

    if pos < chars.count && (chars[pos].isLetter || chars[pos] == "<") {
        rule.dstName = parseName()
        if pos < chars.count && (chars[pos] == "+" || chars[pos] == "-" || chars[pos].isNumber) {
            rule.dstOff = parseOffset()
        } else {
            rule.dstOff = rule.stdOff - 3600
        }
        rule.hasDst = true
        if pos < chars.count && chars[pos] == "," {
            pos += 1
            let (sm, sw, sd) = parseMWD()
            rule.startM = sm; rule.startW = sw; rule.startD = sd
            if pos < chars.count && chars[pos] == "/" { pos += 1; rule.startT = parseTime() }
            pos += 1 // skip ','
            let (em, ew, ed) = parseMWD()
            rule.endM = em; rule.endW = ew; rule.endD = ed
            if pos < chars.count && chars[pos] == "/" { pos += 1; rule.endT = parseTime() }
        }
    }
