}

func nthDayOfMonth(_ y: Int, _ m: Int, _ w: Int, _ d: Int) -> Int {
    let firstDow = dayOfWeek(y, m, 1)
    var first: Int
    if d >= firstDow { first = 1 + (d - firstDow) }
    else { first = 1 + (7 - firstDow + d) }
    if w <= 4 { return first + (w-1)*7 }
    let dim = daysInMonth(y, m)
    let lastDow = dayOfWeek(y, m, dim)
    return dim - ((lastDow - d + 7) % 7)
}

func footerOffset(_ t: Int64, _ r: PosixRule) -> (utcOff: Int, abbr: String, isdst: Bool) {
    let stdU = -r.stdOff
    let dstU = -r.dstOff
    if !r.hasDst { return (stdU, r.stdName, false) }
    let localStd = t + Int64(stdU)
    let (y, _, _, _, _, _) = epochToDate(localStd)
    let sd = nthDayOfMonth(y, r.startM, r.startW, r.startD)
    let sw = dateToEpoch(y, r.startM, sd, r.startT/3600, (r.startT%3600)/60, r.startT%60)
    let startUTC = sw + Int64(r.stdOff)
    let ed = nthDayOfMonth(y, r.endM, r.endW, r.endD)
    let ew = dateToEpoch(y, r.endM, ed, r.endT/3600, (r.endT%3600)/60, r.endT%60)
    let endUTC = ew + Int64(r.dstOff)
    var inDst: Bool
    if startUTC <= endUTC { inDst = (t >= startUTC && t < endUTC) }
    else { inDst = (t >= startUTC || t < endUTC) }
    if inDst { return (dstU, r.dstName, true) }
    else { return (stdU, r.stdName, false) }
}

func getOffsetAtTime(_ t: Int64, _ tz: TzFile, _ rule: PosixRule?) -> (utcOff: Int, abbr: String, isdst: Bool) {
    if tz.transTimes.isEmpty {
        let tp = tz.types[0]
        return (Int(tp.gmtoff), getAbbr(tz.abbrs, tp.abbrIdx), tp.isdst != 0)
    }
    if t < tz.transTimes[0] {
        let tp = tz.types[0]
        return (Int(tp.gmtoff), getAbbr(tz.abbrs, tp.abbrIdx), tp.isdst != 0)
    }
    if t > tz.transTimes[tz.transTimes.count - 1] {
        if let r = rule { return footerOffset(t, r) }
        let tp = tz.types[tz.transTypeIdx[tz.transTypeIdx.count-1]]
        return (Int(tp.gmtoff), getAbbr(tz.abbrs, tp.abbrIdx), tp.isdst != 0)
    }
    var lo = 0, hi = tz.transTimes.count - 1, idx = 0
    while lo <= hi {
        let mid = (lo + hi) / 2
        if tz.transTimes[mid] <= t { idx = mid; lo = mid + 1 }
        else { hi = mid - 1 }
    }
    let tp = tz.types[tz.transTypeIdx[idx]]
    return (Int(tp.gmtoff), getAbbr(tz.abbrs, tp.abbrIdx), tp.isdst != 0)
}

func formatOffset(_ offset: Int) -> String {
    let sign = offset < 0 ? "-" : "+"
    let a = abs(offset)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return "\(sign)\(String(format: "%02d", h)):\(String(format: "%02d", m)):\(String(format: "%02d", s))"
    }
    return "\(sign)\(String(format: "%02d", h)):\(String(format: "%02d", m))"
}

func formatLocal(_ t: Int64, _ utcOff: Int, _ abbr: String) -> String {
    let local = t + Int64(utcOff)
    let (y, m, d, h, mi, s) = epochToDate(local)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", y, m, d, h, mi, s) + formatOffset(utcOff) + " " + abbr
}

