def parse_tzif(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    # First block header (44 bytes) - skip
    isutcnt1, isstdcnt1, leapcnt1, timecnt1, typecnt1, charcnt1 = struct.unpack('>6I', data[20:44])
    block1_size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1
    offset = 44 + block1_size

    # Second block header (44 bytes)
    isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt = struct.unpack('>6I', data[offset + 20:offset + 44])
    offset += 44

    # Transition times (64-bit signed big-endian)
    trans_times = []
    if timecnt > 0:
        trans_times = list(struct.unpack('>%dq' % timecnt, data[offset:offset + timecnt * 8]))
    offset += timecnt * 8

    # Type indices
    trans_types = []
    if timecnt > 0:
        trans_types = list(data[offset:offset + timecnt])
    offset += timecnt

    # Type records
    types = []
    for i in range(typecnt):
        gmtoff, isdst, abbrind = struct.unpack('>lBB', data[offset:offset + 6])
        types.append((gmtoff, isdst, abbrind))
        offset += 6

    # Abbreviations
    abbrs_raw = data[offset:offset + charcnt]
    offset += charcnt

    abbrs = []
    for i in range(typecnt):
        start = types[i][2]
        end = abbrs_raw.index(b'\x00', start)
        abbrs.append(abbrs_raw[start:end].decode('ascii'))

    # Skip leap seconds, isstd, isut
    offset += leapcnt * 12 + isstdcnt + isutcnt

    # Footer
