    return int(dt.timestamp())


def compute_transition_utc(year, rule, time_secs, utc_offset):
    month, week, day = rule
    dt_first = datetime(year, month, 1)
    dow_first = (dt_first.weekday() + 1) % 7  # Sun=0, Mon=1, ..., Sat=6
    days_until = (day - dow_first) % 7
    first_day = 1 + days_until

