        days_back = (dow_last - day) % 7
        target_day = last_dom - days_back
    else:
        target_day = first_day + (week - 1) * 7

    local_epoch = date_to_epoch_utc(year, month, target_day) + time_secs
    utc_epoch = local_epoch - utc_offset
    return utc_epoch


