fn handle_local(tz: &TzData, wall: i64, line: &str, out: &mut String) {
    let mut results: Vec<i64> = Vec::new();
    let mut offsets_seen: Vec<i32> = Vec::new();

    for tr in &tz.types {
        if !offsets_seen.contains(&tr.utc_offset) { offsets_seen.push(tr.utc_offset); }
    }
    if let Some(ref p) = tz.footer {
        let so = -p.std_offset_val;
        if !offsets_seen.contains(&so) { offsets_seen.push(so); }
        if p.dst_name.is_some() {
            let doff = match p.dst_offset_val { Some(v) => -v, None => so + 3600 };
            if !offsets_seen.contains(&doff) { offsets_seen.push(doff); }
        }
    }

    for &off in &offsets_seen {
        let t = wall - off as i64;
        let (ao, _, _) = get_info(tz, t);
        if ao == off { results.push(t); }
    }
    results.sort();
    results.dedup();

    match results.len() {
        1 => {
            let t = results[0];
            let (off, _, abbr) = get_info(tz, t);
            out.push_str(&format!("{} -> {} {} {}\n", line, t, fmt_off(off), abbr));
        }
        2 => {
            let (t1, t2) = (results[0], results[1]);
            let (o1, _, a1) = get_info(tz, t1);
            let (o2, _, a2) = get_info(tz, t2);
            out.push_str(&format!("{} -> {} {} {} | {} {} {}\n", line, t1, fmt_off(o1), a1, t2, fmt_off(o2), a2));
        }
        _ => {
            let mut gap_t = wall;
            // Collect all transition times near wall
            let mut evts: Vec<i64> = Vec::new();
            let lo = wall - 15*3600 - 86400;
            let hi = wall + 15*3600 + 86400;
            for &t in &tz.transitions {
                if t >= lo && t <= hi { evts.push(t); }
            }
            if let Some(ref p) = tz.footer {
                if p.dst_name.is_some() && p.start.is_some() && p.end.is_some() {
                    let so = -p.std_offset_val;
                    let doff = match p.dst_offset_val { Some(v) => -v, None => so+3600 };
                    let days = wall.div_euclid(86400);
                    let (yr, _, _) = civil_from_days(days);
                    for y in (yr-1)..=(yr+1) {
                        let s = rule_to_utc(p.start.as_ref().unwrap(), y, so);
                        let e = rule_to_utc(p.end.as_ref().unwrap(), y, doff);
                        if s >= lo && s <= hi { evts.push(s); }
                        if e >= lo && e <= hi { evts.push(e); }
                    }
                }
            }
            evts.sort();
            evts.dedup();
            for &t in &evts {
                let ob = get_info(tz, t - 1).0;
                let oa = get_info(tz, t).0;
                if oa > ob && wall >= t + ob as i64 && wall < t + oa as i64 {
                    gap_t = wall - ob as i64;
                    break;
                }
            }
            let (local, off, abbr) = utc_to_local(tz, gap_t);
            out.push_str(&format!("{} -> GAP {} {}{} {}\n", line, gap_t, fmt_dt(local), fmt_off(off), abbr));
        }
    }
}

fn fmt_dt(secs: i64) -> String {
    let days = secs.div_euclid(86400);
    let tod = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let h = tod / 3600;
    let mi = (tod % 3600) / 60;
    let s = tod % 60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, m, d, h, mi, s)
}

fn fmt_off(off: i32) -> String {
    let sign = if off >= 0 { '+' } else { '-' };
    let a = if off >= 0 { off } else { -off };
    let h = a / 3600;
    let m = (a % 3600) / 60;
    let s = a % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn parse_dt(s: &str) -> i64 {
    let y: i64 = s[0..4].parse().unwrap();
    let m: i64 = s[5..7].parse().unwrap();
    let d: i64 = s[8..10].parse().unwrap();
    let h: i64 = s[11..13].parse().unwrap();
    let mi: i64 = s[14..16].parse().unwrap();
    let sec: i64 = s[17..19].parse().unwrap();
    days_from_civil(y, m, d) * 86400 + h*3600 + mi*60 + sec
}

