            let (local, off, abbr) = utc_to_local(tz, gap_t);
            out.push_str(&format!("{} -> GAP {} {}{} {}\n", line, gap_t, fmt_dt(local), fmt_off(off), abbr));
        }
    }
}

fn fmt_dt(secs: i64) -> String {
    let days = secs.div_euclid(86400);
    let tod = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let h = tod / 3600;
    let mi = (tod % 3600) / 60;
    let s = tod % 60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, m, d, h, mi, s)
}

fn fmt_off(off: i32) -> String {
    let sign = if off >= 0 { '+' } else { '-' };
    let a = if off >= 0 { off } else { -off };
    let h = a / 3600;
    let m = (a % 3600) / 60;
    let s = a % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

