    let h2s = 44 + block1_sz;
    let h2 = &data[h2s..h2s+44];
    let isutcnt = read_i32_be(h2, 20) as usize;
    let isstdcnt = read_i32_be(h2, 24) as usize;
    let leapcnt = read_i32_be(h2, 28) as usize;
    let timecnt = read_i32_be(h2, 32) as usize;
    let typecnt = read_i32_be(h2, 36) as usize;
    let charcnt = read_i32_be(h2, 40) as usize;

